INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('marcusgoll/Spec-Flow/task-status-sync', 'community', 'marcusgoll', 'Spec-Flow', 'marcusgoll/Spec-Flow', 'task-status-sync', 0, 0, 45, '2026-03-08T01:57:15.376Z', '2026-03-08T02:04:38.683Z', 'a42c515692d6e5eb842a9cc7ef5a7e2a4600fed8b9442c6e233246a0d57b5c2c', '{"id":"marcusgoll/Spec-Flow/task-status-sync","name":"task-status-sync","description":{"en":"The task-status-sync skill maintains atomic synchronization between tasks.md checkboxes and NOTES.md completion markers, benefiting developers and teams using Spec-Driven Development","zh":"task-status-sync 是一种 Spec-Driven Development 工作流，实现任务状态的自动化同步","ja":"task-status-sync はタスク状態を同期させる AI エージェント機能です","ko":"task-status-sync는 작업 상태를 자동으로 동기화하는 클라우드 기반 서비스입니다","es":"Task-status-sync es una habilidad que permite mantener la sincronización atómica entre tareas y notas mediante el uso de comandos de seguimiento de tareas y la prevención de ediciones manuales","fr":"Task-status-sync est une compétence qui permet de maintenir la synchronisation atomique entre tâches et notes en utilisant des commandes de suivi de tâches et en empêchant les éditions manuelles","de":"Task-status-sync ist eine Fähigkeit, die die atomare Synchronisation zwischen Aufgaben und Notizen durch den Einsatz von Aufgaben-Tracking-Befehlen und die Verhinderung von manuellen Bearbeitungen ermöglicht","pt":"O task-status-sync é uma ferramenta que mantém a sincronização atômica entre tarefas e marcas de conclusão, garantindo a consistência dos dados","ru":"Task-status-sync — это инструмент, который поддерживает атомарную синхронизацию между задачами и маркерами завершения, обеспечивая согласованность данных","ar":"أداة task-status-sync هي أداة تحافظ على التزامن الذري بين المهام و علامات الإكمال، مما يضمن سلامة البيانات"},"seo":{"title":{"en":"task-status-sync: Atomic Synchronization Setup Guide | AI...","zh":"task-status-sync Setup Guide: Spec-Driven Development 工作流","ja":"task-status-sync 導入ガイド: AIエージェントによるタスク同期","ko":"task-status-sync 설정 가이드: 클라우드 기반 작업 상태 동기화","es":"Guía de configuración de task-status-sync para sincroniza...","fr":"Guide de mise en place de task-status-sync pour la synchr...","de":"Einrichtungsleitfaden für task-status-sync zur Aufgabensy...","pt":"Guia de Configuração do task-status-sync para Desenvolved...","ru":"ИИ Агенты: Руководство по Настройке task-status-sync","ar":"دليل إعداد أداة task-status-sync للبرمجة"},"description":{"en":"Automate task tracking with task-status-sync. Learn how to intercept manual edits and convert them to task-tracker commands for seamless workflow","zh":"使用 task-status-sync 实现 Spec-Driven Development，自动化任务状态同步，提高开发效率","ja":"task-status-sync を使用してタスク状態を同期させ、開発プロセスを自動化する","ko":"task-status-sync를 사용하여 작업 상태를 동기화하고 개발 프로세스를 자동화하여 효율성을 높입니다","es":"Aprende a implementar task-status-sync para mantener la sincronización atómica entre tareas y notas con Spec-Driven Development","fr":"Découvrez comment mettre en place task-status-sync pour maintenir la synchronisation atomique entre tâches et notes avec Spec-Driven Development","de":"Erfahren Sie, wie Sie task-status-sync implementieren, um die atomare Synchronisation zwischen Aufgaben und Notizen mit Spec-Driven Development aufrechtzuerh...","pt":"Aprenda a sincronizar tarefas com o task-status-sync, uma ferramenta de desenvolvimento baseada em especificações","ru":"Синхронизируйте задачи с помощью task-status-sync, инструмента разработки на основе спецификаций","ar":"تعرف على كيفية مزامنة المهام باستخدام أداة task-status-sync، وهي أداة تطوير قائمة على المواصفات"},"definition":{"en":"task-status-sync is a skill that enforces task-tracker command usage and prevents manual file edits, ensuring data consistency across tasks.md and NOTES.md files","zh":"task-status-sync 是一种自动化任务状态同步的技术，用于 Spec-Driven Development","ja":"task-status-sync はタスク状態を同期させる技術です","ko":"task-status-sync는 작업 상태를 자동으로 동기화하는 기술을 의미합니다","es":"Task-status-sync es una habilidad que proporciona sincronización atómica entre tareas y notas","fr":"Task-status-sync est une compétence qui offre une synchronisation atomique entre tâches et notes","de":"Task-status-sync ist eine Fähigkeit, die eine atomare Synchronisation zwischen Aufgaben und Notizen bietet","pt":"O task-status-sync é uma ferramenta de desenvolvimento que sincroniza tarefas e marcas de conclusão","ru":"Task-status-sync — это инструмент разработки, который синхронизирует задачи и маркеры завершения","ar":"أداة task-status-sync هي أداة تطوير تزامن المهام و علامات الإكمال"},"features":{"en":["Intercepts and converts manual edits to task-tracker commands","Detects Edit/Write tool usage on NOTES.md or tasks.md files","Extracts intent from user or Claude changes","Converts changes to task-tracker commands for auditable artifacts","Enforces quality gates and token budgets for repeatable workflows","Supports Spec-Driven Development with Claude Code workflows"],"zh":["自动化任务状态同步","支持 Spec-Driven Development 工作流","使用 token budgets 和 auditable artifacts","防止手动文件编辑导致的数据不一致","支持 Repeatable Claude Code 工作流"],"ja":["タスク状態の自動同期","AIエージェントによるタスク管理","トークン予算と監査可能な成果物の使用","手動ファイル編集によるデータ不一致の防止","リピータブルな Claude Code ワークフローのサポート"],"ko":["작업 상태 자동 동기화","클라우드 기반 작업 상태 관리","토큰 예산과 감사 가능한成果物 사용","수동 파일 편집으로 인한 데이터 불일치 방지","리피터블한 Claude Code 작업 흐름 지원"],"es":["Interceptación y conversión de ediciones manuales en comandos de seguimiento de tareas","Detección de intentos de edición en notas y tareas","Uso de comandos de seguimiento de tareas para mantener la sincronización","Prevención de ediciones manuales que causan inconsistencias de datos","Integración con Spec-Driven Development para lanzamientos de producción","Uso de token budgets y artefactos auditables"],"fr":["Interception et conversion des éditions manuelles en commandes de suivi de tâches","Détection des tentatives d''édition dans les notes et les tâches","Utilisation de commandes de suivi de tâches pour maintenir la synchronisation","Empêchement des éditions manuelles qui causent des incohérences de données","Intégration avec Spec-Driven Development pour les lancements de production","Utilisation de budgets de jetons et d''artefacts auditable"],"de":["Abfangen und Umwandeln manueller Bearbeitungen in Aufgaben-Tracking-Befehle","Erkennung von Bearbeitungsversuchen in Notizen und Aufgaben","Verwendung von Aufgaben-Tracking-Befehlen zur Aufrechterhaltung der Synchronisation","Verhinderung von manuellen Bearbeitungen, die Dateninkonsistenzen verursachen","Integration mit Spec-Driven Development für Produktionsstarts","Verwendung von Token-Budgets und überprüfbaren Artefakten"],"pt":["Sincronização atômica entre tarefas e marcas de conclusão","Prevenção de edições manuais que causam inconsistências de dados","Uso de comandos de acompanhamento de tarefas para garantir a consistência","Extração de intenção de alterações feitas pelo usuário","Conversão de edições manuais em comandos de acompanhamento de tarefas"],"ru":["Атомарная синхронизация между задачами и маркерами завершения","Предотвращение ручных редактирований, которые вызывают несоответствия данных","Использование команд отслеживания задач для обеспечения согласованности","Извлечение намерения изменений, сделанных пользователем","Преобразование ручных редактирований в команды отслеживания задач"],"ar":["التزامن الذري بين المهام و علامات الإكمال","منع التعديلات اليدوية التي تسبب عدم تطابق في البيانات","استخدام أوامر تتبع المهام لضمان التطابق","استخراج نیة التعديلات التي يقوم بها المستخدم","تحويل التعديلات اليدوية إلى أوامر تتبع المهام"]},"keywords":{"en":["how to use task-status-sync","task-status-sync alternative","task-status-sync setup guide","what is task-status-sync","task-status-sync vs manual tracking","task-status-sync install for AI agents","Spec-Driven Development with task-status-sync","task-status-sync for atomic synchronization","task-status-sync and Claude Code workflows"],"zh":["task-status-sync","Spec-Driven Development","自动化任务状态同步","token budgets","auditable artifacts","Repeatable Claude Code","AI 工具","工作流自动化"],"ja":["task-status-sync","AIエージェント","タスク状態同期","トークン予算","監査可能な成果物","リピータブルな Claude Code","開発プロセス自動化","AIツール"],"ko":["task-status-sync","클라우드 기반 작업 상태 동기화","작업 상태 자동 동기화","토큰 예산","감사 가능한成果物","리피터블한 Claude Code","개발 프로세스 자동화","AI 도구"],"es":["task-status-sync","sincronización de tareas","Spec-Driven Development","segimiento de tareas","edición manual","inconsistencias de datos","token budgets","artefactos auditable","lanzamientos de producción"],"fr":["task-status-sync","synchronisation des tâches","Spec-Driven Development","suivi de tâches","édition manuelle","incohérences de données","budgets de jetons","artefacts auditable","lancements de production"],"de":["task-status-sync","Aufgabensynchronisation","Spec-Driven Development","Aufgaben-Tracking","manuelle Bearbeitung","Dateninkonsistenzen","Token-Budgets","überprüfbare Artefakte","Produktionsstarts"],"pt":["task-status-sync","desenvolvimento baseado em especificações","sincronização de tarefas","ferramentas de desenvolvimento","consistência de dados","comandos de acompanhamento de tarefas","edições manuais","intenção de alterações"],"ru":["task-status-sync","разработка на основе спецификаций","синхронизация задач","инструменты разработки","согласованность данных","команды отслеживания задач","ручные редактирования","намерение изменений"],"ar":["task-status-sync","تطوير قائمة على المواصفات","تزامن المهام","أدوات التطوير","التطابق البيانات","أوامر تتبع المهام","التعديلات اليدوية","نية التعديلات"]}},"owner":"marcusgoll","repo":"Spec-Flow","repoPath":"marcusgoll/Spec-Flow","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.376Z","topics":[],"category":"community","skillMd":{"name":"task-status-sync","description":"Enforce atomic task status updates through task-tracker commands only. Prevent manual edits to NOTES.md and tasks.md that break synchronization. Auto-trigger when detecting Edit/Write attempts to task files, task completion mentions, or status update discussions. Auto-convert manual edit attempts to equivalent task-tracker commands. Validate task-tracker usage and auto-fix common mistakes.","bodyPreview":"<objective>\nMaintain atomic synchronization between tasks.md checkboxes and NOTES.md completion markers by enforcing task-tracker command usage and preventing manual file edits that cause data inconsistencies.\n</objective>\n\n<quick_start>\n<enforcement_model>\n**Intercept and convert manual edits to task-tracker commands:**\n\n1. **Detect attempt**: Monitor for Edit/Write tool usage on NOTES.md or tasks.md\n2. **Extract intent**: Parse what change the user/Claude wants to make\n3. **Convert to command*","body":"<objective>\nMaintain atomic synchronization between tasks.md checkboxes and NOTES.md completion markers by enforcing task-tracker command usage and preventing manual file edits that cause data inconsistencies.\n</objective>\n\n<quick_start>\n<enforcement_model>\n**Intercept and convert manual edits to task-tracker commands:**\n\n1. **Detect attempt**: Monitor for Edit/Write tool usage on NOTES.md or tasks.md\n2. **Extract intent**: Parse what change the user/Claude wants to make\n3. **Convert to command**: Generate equivalent task-tracker command\n4. **Execute atomically**: Run task-tracker to update both files simultaneously\n5. **Provide feedback**: Explain the conversion and show the result\n\n**Example workflow:**\n```\nUser: \"Mark T001 as completed\"\n\n❌ BLOCKED: Direct edit to tasks.md\n✅ AUTO-CONVERTED: .spec-flow/scripts/bash/task-tracker.sh mark-done-with-notes -TaskId T001\n\nResult:\n- tasks.md: - [X] T001 Create database schema\n- NOTES.md: ✅ T001: Create database schema - est (2025-11-19 10:30)\n```\n</enforcement_model>\n\n<allowed_operations>\n**✅ Permitted (read-only):**\n- Read NOTES.md to understand progress\n- Read tasks.md to see task list\n- Read error-log.md to diagnose failures\n\n**✅ Permitted (through task-tracker):**\n- Mark tasks complete: `mark-done-with-notes`\n- Mark tasks in progress: `mark-in-progress`\n- Mark tasks failed: `mark-failed`\n- Sync status: `sync-status`\n- Get next task: `next`\n- Get summary: `summary`\n- Validate: `validate`\n\n**❌ Blocked (auto-converted):**\n- Direct Edit/Write to tasks.md\n- Direct Edit/Write to NOTES.md\n- Manual checkbox changes ([ ] → [X])\n- Manual completion markers (✅ T001)\n</allowed_operations>\n\n<task_tracker_commands>\n**Available task-tracker.sh / task-tracker.ps1 actions:**\n\n```bash\n# Get current status\n.spec-flow/scripts/bash/task-tracker.sh status -Json\n\n# Mark task completed with full details\n.spec-flow/scripts/bash/task-tracker.sh mark-done-with-notes \\\n  -TaskId T001 \\\n  -Notes \"Created Message model with validation\" \\\n  -Evidence \"pytest: 25/25 passing\" \\\n  -Coverage \"92% (+8%)\" \\\n  -CommitHash \"abc123\" \\\n  -Duration \"15min\"\n\n# Mark task in progress\n.spec-flow/scripts/bash/task-tracker.sh mark-in-progress -TaskId T002\n\n# Mark task failed\n.spec-flow/scripts/bash/task-tracker.sh mark-failed \\\n  -TaskId T003 \\\n  -ErrorMessage \"Tests failing: ImportError on MessageService\"\n\n# Sync tasks.md to NOTES.md (migration utility)\n.spec-flow/scripts/bash/task-tracker.sh sync-status\n\n# Get next available task\n.spec-flow/scripts/bash/task-tracker.sh next -Json\n\n# Get phase-wise summary\n.spec-flow/scripts/bash/task-tracker.sh summary -Json\n\n# Validate task file structure\n.spec-flow/scripts/bash/task-tracker.sh validate -Json\n```\n\nSee [references/task-tracker-api.md](references/task-tracker-api.md) for complete API reference.\n</task_tracker_commands>\n</quick_start>\n\n<workflow>\n<detection_phase>\n**1. Monitor Tool Usage**\n\nWatch for these patterns that indicate task status updates:\n\n**Direct file edits:**\n- `Edit(file_path: \"*/tasks.md\", ...)`\n- `Edit(file_path: \"*/NOTES.md\", ...)`\n- `Write(file_path: \"*/tasks.md\", ...)`\n- `Write(file_path: \"*/NOTES.md\", ...)`\n\n**Verbal indicators:**\n- \"Mark T001 as complete\"\n- \"Update task status for T002\"\n- \"Task T003 is done\"\n- \"Completed T004\"\n- \"T005 failed\"\n\n**Checkbox change patterns:**\n- `old_string: \"- [ ] T001\"` → `new_string: \"- [X] T001\"`\n- Adding ✅ markers to NOTES.md manually\n</detection_phase>\n\n<interception_phase>\n**2. Intercept and Block Manual Edits**\n\nWhen Edit/Write detected on tasks.md or NOTES.md:\n\n```\n⛔ MANUAL EDIT BLOCKED\n\nFile: specs/001-feature/tasks.md\nAttempted change: Mark T001 as [X] completed\n\n❌ Reason: Manual edits break atomic sync between tasks.md and NOTES.md\n\n✅ Solution: Use task-tracker command instead\n\nAuto-converting to:\n  .spec-flow/scripts/bash/task-tracker.sh mark-done-with-notes -TaskId T001\n\nThis atomically updates:\n  - tasks.md checkbox: - [X] T001\n  - NOTES.md marker: ✅ T001: ... - est (2025-11-19 10:30)\n  - Progress summary in tasks.md (if update-tasks-summary.ps1 exists)\n```\n\nDo NOT execute the manual edit. Instead, proceed to conversion phase.\n</interception_phase>\n\n<conversion_phase>\n**3. Convert Manual Edit to Task-Tracker Command**\n\n**Parse the intended change:**\n\nExtract from Edit/Write tool parameters:\n- `TaskId`: T### from checkbox pattern or ✅ marker\n- `NewStatus`: Infer from checkbox ([X] = completed, [~] = in-progress, [ ] = pending)\n- `Notes`: Extract from NOTES.md addition or Edit context\n- `ErrorMessage`: Extract if marking failed\n\n**Generate equivalent command:**\n\n```javascript\n// Pseudo-logic\nif (newStatus === ''X'' || intent === ''mark complete'') {\n  command = ''mark-done-with-notes''\n  params = {\n    TaskId: extractedTaskId,\n    Notes: extractedNotes || \"\",\n    Duration: \"est\"  // Default if not specified\n  }\n}\nelse if (newStatus === ''~'' || intent === ''mark in progress'') {\n  command = ''mark-in-progress''\n  params = { TaskId: extractedTaskId }\n}\nelse if (intent === ''mark failed'' || errorMessage present) {\n  command = ''mark-failed''\n  params = {\n    TaskId: extractedTaskId,\n    ErrorMessage: extractedErrorMessage\n  }\n}\n```\n\n**Validation before execution:**\n\nCheck that:\n- TaskId exists in tasks.md\n- Status transition is valid (pending → in-progress → completed)\n- Required fields present (e.g., ErrorMessage for mark-failed)\n\nIf validation fails, auto-fix where possible:\n- Missing TaskId → Extract from context or ask user\n- Invalid transition → Warn and suggest correct flow\n- Missing ErrorMessage → Prompt for details\n\nSee [references/conversion-logic.md](references/conversion-logic.md) for detailed conversion rules.\n</conversion_phase>\n\n<execution_phase>\n**4. Execute Task-Tracker Command**\n\n```bash\n# Platform detection\nif (platform === ''win32'') {\n  script = ''.spec-flow/scripts/bash/task-tracker.sh''  # Uses WSL or delegates to PS\n} else if (platform === ''linux'' || platform === ''darwin'') {\n  script = ''.spec-flow/scripts/bash/task-tracker.sh''\n}\n\n# Execute with Bash tool\nBash(`${script} ${command} -TaskId ${TaskId} [additional params] -Json`)\n```\n\n**Parse JSON output:**\n\n```json\n{\n  \"Success\": true,\n  \"TaskId\": \"T001\",\n  \"Message\": \"Task T001 marked complete in both tasks.md and NOTES.md\",\n  \"TasksFile\": \"specs/001-feature/tasks.md\",\n  \"NotesFile\": \"specs/001-feature/NOTES.md\",\n  \"PhaseMarker\": \"[RED]\"\n}\n```\n\n**Provide feedback:**\n\n```\n✅ TASK STATUS UPDATED ATOMICALLY\n\nTask T001 marked complete:\n  - tasks.md: Updated checkbox to [X]\n  - NOTES.md: Added completion marker\n  - Phase: [RED] (TDD red phase)\n\nFiles synchronized:\n  - specs/001-feature/tasks.md\n  - specs/001-feature/NOTES.md\n\nNext steps:\n  - Run: task-tracker.sh next\n  - Continue with T002\n```\n</execution_phase>\n\n<validation_phase>\n**5. Validate Task-Tracker Usage**\n\n**Common mistakes to auto-fix:**\n\n| Mistake | Detection | Auto-fix |\n|---------|-----------|----------|\n| Wrong TaskId format (T1 instead of T001) | Regex: `^T\\d{1,2}$` | Pad with zeros: T001 |\n| Invalid status transition (pending → completed) | Check current status | Insert mark-in-progress first |\n| Missing duration | Duration field empty | Default to \"est\" |\n| Missing notes on completion | Notes empty for mark-done-with-notes | Prompt: \"Add implementation summary\" |\n| TaskId doesn''t exist | Not found in Parse-TasksFile | List available task IDs |\n| Marking already-completed task | IsCompleted = true | Warn: \"Already complete, skip or force?\" |\n\n**TDD validation:**\n\nCheck if test task completed before implementation:\n- If marking T002 (implement) complete but T001 (test) is pending → warn\n- Recommendation: \"Complete T001 (test) before T002 (implement) for TDD\"\n\n**Parallel safety:**\n\n- If more than 2 tasks in-progress → warn: \"Exceeds parallel limit (2)\"\n- If file path conflicts detected → block: \"T002 and T003 both modify `app.py`\"\n\nSee [references/validation-rules.md](references/validation-rules.md) for complete validation logic.\n</validation_phase>\n</workflow>\n\n<anti_patterns>\n**Avoid these mistakes that break sync:**\n\n**1. Manual checkbox edits**\n```markdown\n❌ BAD (manual edit to tasks.md):\n- [X] T001 Create database schema\n\n✅ GOOD (task-tracker command):\ntask-tracker.sh mark-done-with-notes -TaskId T001 -Notes \"Created schema\"\n```\n\n**2. Adding NOTES.md markers manually**\n```markdown\n❌ BAD (manual edit to NOTES.md):\n✅ T001: Created database schema\n\n✅ GOOD (task-tracker handles NOTES.md):\ntask-tracker.sh mark-done-with-notes -TaskId T001\n# Atomically updates both files\n```\n\n**3. Inconsistent states**\n```markdown\n❌ BAD (tasks.md says pending, NOTES.md says complete):\ntasks.md: - [ ] T001 Create schema\nNOTES.md: ✅ T001: Created schema\n\n✅ GOOD (atomic update ensures consistency):\nBoth files updated simultaneously via task-tracker\n```\n\n**4. Skipping in-progress marker**\n```markdown\n❌ BAD (pending → completed without in-progress):\nCan lose tracking of what''s actively being worked on\n\n✅ GOOD (mark in-progress first):\n1. task-tracker.sh mark-in-progress -TaskId T001\n2. [implement task]\n3. task-tracker.sh mark-done-with-notes -TaskId T001\n```\n\n**5. Missing task completion evidence**\n```markdown\n❌ BAD (no evidence of completion):\n✅ T001 - est (timestamp)\n\n✅ GOOD (include evidence, coverage, commit):\n✅ T001: Created Message model - 15min (2025-11-19 10:30)\n  - Evidence: pytest: 25/25 passing\n  - Coverage: 92% (+8%)\n  - Committed: abc123\n```\n</anti_patterns>\n\n<success_criteria>\n**Task status sync is working correctly when:**\n\n- ✓ All task completions use task-tracker commands\n- ✓ tasks.md checkboxes and NOTES.md markers are always synchronized\n- ✓ No manual edits to tasks.md or NOTES.md occur\n- ✓ Attempted manual edits are auto-converted to task-tracker commands\n- ✓ Task-tracker validation catches and fixes common mistakes\n- ✓ TDD flow is enforced (tests before implementation)\n- ✓ Parallel task limit (2) is respected\n- ✓ File path conflicts are detected and prevented\n- ✓ Error log entries are created for failed tasks\n- ✓ Progress summary stays updated with velocity metrics\n\n**Detection working when:**\n- Edit/Write attempts to tasks.md are intercepted\n- Verbal task completion mentions are recognized\n- Checkbox change patterns are detected\n- Auto-conversion generates correct task-tracker commands\n\n**Validation working when:**\n- Invalid task IDs are caught and corrected\n- Invalid status transitions are prevented or guided\n- TDD violations are warned\n- Parallel safety limits are enforced\n</success_criteria>\n\n<reference_guides>\nFor detailed implementation and troubleshooting:\n\n- **[references/task-tracker-api.md](references/task-tracker-api.md)** - Complete task-tracker command reference with examples\n- **[references/conversion-logic.md](references/conversion-logic.md)** - Manual edit → task-tracker command conversion rules\n- **[references/validation-rules.md](references/validation-rules.md)** - Task status validation and auto-fix logic\n- **[references/file-formats.md](references/file-formats.md)** - tasks.md and NOTES.md structure and patterns\n</reference_guides>\n"},"lastSynced":"2026-03-08T02:04:38.683Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing precise task management and Spec-Driven Development synchronization.","zh":"非常适合需要精确任务管理和规范驱动开发同步的开发代理。","ja":"開発エージェントが正確なタスク管理と仕様駆動開発の同期を必要とする場合に最適です。","ko":"개발 에이전트가 정확한 작업 관리와 구체적으로 주도된 개발 동기화를 필요로 할 때 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión de tareas precisa y sincronización de desarrollo basado en especificaciones.","fr":"Parfait pour les agents de développement nécessitant une gestion de tâches précise et une synchronisation de développement basée sur des spécifications.","de":"Perfekt für Entwicklungssagenten, die eine präzise Aufgabenverwaltung und eine spezifikationsgesteuerte Entwicklungssynchronisierung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de tarefas preciso e sincronização de Desenvolvimento Orientado por Especificações.","ru":"Идеально подходит для агентов разработки, которым необходим точный менеджмент задач и синхронизация разработки, основанной на спецификациях.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى إدارة مهمة دقيقة وتزامن تطوير مدفوع بالمواصفات."},"recommendation":{"en":"Empowers agents to maintain atomic synchronization between tasks.md checkboxes and NOTES.md completion markers by enforcing task-tracker command usage and preventing manual file edits, utilizing protocols like edit detection and intent parsing to ensure data consistency.","zh":"赋予代理维持任务.md 复选框和 NOTES.md 完成标记之间的原子同步，通过强制任务跟踪器命令使用并防止手动文件编辑，利用编辑检测和意图解析等协议以确保数据一致性。","ja":"タスク.md のチェックボックスと NOTES.md の完了マーカー間の原子同期をエージェントが維持できるようにし、タスク追跡コマンドの使用を強制し、手動ファイル編集を防止することで、編集検出と意図解析などのプロトコルを使用してデータの一貫性を確保します。","ko":"에이전트가 작업.md 체크박스와 NOTES.md 완료 표시기 사이의 원자적 동기화를 유지할 수 있도록 하며, 작업 추적기 명령의 사용을 강제하고 수동 파일 편집을 방지하여 편집 감지 및 의도 파싱 등의 프로토콜을 사용하여 데이터 일관성을 보장합니다.","es":"Habilita a los agentes a mantener la sincronización atómica entre las casillas de tareas.md y los marcadores de finalización de NOTES.md, al obligar a utilizar comandos de seguimiento de tareas y prevenir ediciones manuales de archivos, utilizando protocolos como la detección de ediciones y el análisis de intención para garantizar la consistencia de los datos, utilizando frameworks como React, Python, CLI y API.","fr":"Permet aux agents de maintenir une synchronisation atomique entre les cases à cocher de tasks.md et les marqueurs de fin de NOTES.md, en imposant l''utilisation de commandes de suivi de tâches et en empêchant les éditions manuelles de fichiers, en utilisant des protocoles tels que la détection d''éditions et l''analyse d''intention pour assurer la cohérence des données, en utilisant des frameworks comme React, Python, CLI et API.","de":"Ermächtigt die Agenten, eine atomare Synchronisation zwischen den Aufgaben.md-Checkboxes und den NOTES.md-Abschlussmarkern aufrechtzuerhalten, indem sie die Verwendung von Aufgaben-Tracker-Befehlen erzwingen und manuelle Dateibearbeitungen verhindern, unter Verwendung von Protokollen wie Editierverfolgung und Intentionserkennung, um die Datenkonsistenz sicherzustellen, unter Verwendung von Frameworks wie React, Python, CLI und API.","pt":"Habilita os agentes a manter a sincronização atômica entre as caixas de seleção do arquivo tasks.md e os marcadores de conclusão do arquivo NOTES.md, aplicando o uso de comandos de rastreador de tarefas e impedindo edições manuais de arquivos, utilizando protocolos como detecção de edições e análise de intenções para garantir a consistência dos dados.","ru":"Предоставляет агентам возможность поддерживать атомарную синхронизацию между флажками файла tasks.md и маркерами завершения файла NOTES.md, обеспечивая использование команд отслеживания задач и предотвращая ручные редактирования файлов, используя протоколы, такие как обнаружение изменений и анализ намерений, для обеспечения согласованности данных.","ar":"يمنح العملاء القدرة على الحفاظ على التزامن الذري بين مربعات الاختيار في ملف tasks.md وعلامات الإكمال في ملف NOTES.md ، من خلال تطبيق استخدام أوامر تتبع المهام ومنع تحرير الملفات يدويًا ، باستخدام بروتوكولات مثل الكشف عن التعديلات وتحليل النوايا لضمان συνέافة البيانات."},"useCases":{"en":["Automating task status updates in tasks.md and NOTES.md files","Enforcing task-tracker command usage for Spec-Driven Development","Preventing manual file edits that cause data inconsistencies"],"zh":["自动更新 tasks.md 和 NOTES.md 文件中的任务状态","强制使用任务跟踪器命令进行规范驱动开发","防止手动文件编辑导致的数据不一致"],"ja":["tasks.md と NOTES.md ファイル内のタスクの状態を自動的に更新する","タスク追跡コマンドの使用を強制して仕様駆動開発を行う","手動ファイル編集によるデータの不一致を防止する"],"ko":["작업.md 및 NOTES.md 파일 내의 작업 상태를 자동으로 업데이트하는 것","작업 추적기 명령의 사용을 강제하여 구체적으로 주도된 개발을 수행하는 것","수동 파일 편집으로 인한 데이터 불일치를 방지하는 것"],"es":["Automatización de actualizaciones de estado de tarea en archivos tasks.md y NOTES.md","Implantación del uso de comandos de seguimiento de tareas para el desarrollo basado en especificaciones","Prevención de ediciones manuales de archivos que causan inconsistencias de datos"],"fr":["Automatisation des mises à jour de l''état des tâches dans les fichiers tasks.md et NOTES.md","Mise en œuvre de l''utilisation de commandes de suivi de tâches pour le développement basé sur des spécifications","Prévention des éditions manuelles de fichiers qui provoquent des incohérences de données"],"de":["Automatisierung von Aufgabenstatus-Aktualisierungen in tasks.md- und NOTES.md-Dateien","Durchsetzung der Verwendung von Aufgaben-Tracker-Befehlen für die spezifikationsgesteuerte Entwicklung","Verhinderung von manuellen Dateibearbeitungen, die Dateninkonsistenzen verursachen"],"pt":["Automatizar atualizações de status de tarefas nos arquivos tasks.md e NOTES.md","Impor o uso de comandos de rastreador de tarefas para Desenvolvimento Orientado por Especificações","Prevenir edições manuais de arquivos que causem inconsistências de dados"],"ru":["Автоматизировать обновления статуса задач в файлах tasks.md и NOTES.md","Обеспечить использование команд отслеживания задач для разработки, основанной на спецификациях","Предотвратить ручные редактирования файлов, которые вызывают несоответствия данных"],"ar":["تأتمتة تحديث حالة المهام في ملفات tasks.md و NOTES.md","تطبيق استخدام أوامر تتبع المهام لتطوير مدفوع بالمواصفات","منع تحرير الملفات يدويًا الذي يسبب عدم تطابق البيانات"]},"limitations":{"en":["Requires task-tracker command integration","Limited to tasks.md and NOTES.md file formats","Needs monitoring and parsing capabilities for edit detection and intent extraction"],"zh":["需要任务跟踪器命令集成","仅限 tasks.md 和 NOTES.md 文件格式","需要编辑检测和意图提取的监控和解析能力"],"ja":["タスク追跡コマンドの統合が必要","tasks.md と NOTES.md ファイル形式のみに限定される","編集検出と意図抽出のための監視と解析機能が必要"],"ko":["작업 추적기 명령 통합이 필요함","작업.md 및 NOTES.md 파일 형식만 지원함","편집 감지 및 의도 추출을 위한 모니터링 및 파싱 기능이 필요함"],"es":["Requiere la integración de comandos de seguimiento de tareas","Limitado a los formatos de archivo tasks.md y NOTES.md","Necesita capacidades de monitoreo y análisis para la detección de ediciones y la extracción de intención"],"fr":["Nécessite l''intégration de commandes de suivi de tâches","Limité aux formats de fichiers tasks.md et NOTES.md","Nécessite des capacités de surveillance et d''analyse pour la détection d''éditions et l''extraction d''intention"],"de":["Erfordert die Integration von Aufgaben-Tracker-Befehlen","Begrenzt auf die Dateiformate tasks.md und NOTES.md","Benötigt Überwachungs- und Analysefunktionen für die Editierverfolgung und die Intentionserkennung"],"pt":["Exige integração de comandos de rastreador de tarefas","Limitado a formatos de arquivos tasks.md e NOTES.md","Necessita de capacidades de monitoramento e análise para detecção de edições e extração de intenções"],"ru":["Требует интеграции команд отслеживания задач","Ограничен форматами файлов tasks.md и NOTES.md","Требует возможностей мониторинга и анализа для обнаружения изменений и извлечения намерений"],"ar":["يتطلب تكامل أوامر تتبع المهام","محدود بتنسيقات ملفات tasks.md و NOTES.md","يحتاج إلى قدرات مراقبة وتحليل للكشف عن التعديلات واستخراج النوايا"]},"version":4},"contentHash":"a42c515692d6e5eb842a9cc7ef5a7e2a4600fed8b9442c6e233246a0d57b5c2c","qualityScore":45}');
