INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('marcusgoll/Spec-Flow/task-status-sync', 'task-status-sync', 'marcusgoll', 'Spec-Flow', 'community', 'task-status-sync marcusgoll Spec-Flow community The task-status-sync skill maintains atomic synchronization between tasks.md checkboxes and NOTES.md completion markers, benefiting developers and teams using Spec-Driven Development task-status-sync 是一种 Spec-Driven Development 工作流，实现任务状态的自动化同步 task-status-sync はタスク状態を同期させる AI エージェント機能です task-status-sync는 작업 상태를 자동으로 동기화하는 클라우드 기반 서비스입니다 Task-status-sync es una habilidad que permite mantener la sincronización atómica entre tareas y notas mediante el uso de comandos de seguimiento de tareas y la prevención de ediciones manuales Task-status-sync est une compétence qui permet de maintenir la synchronisation atomique entre tâches et notes en utilisant des commandes de suivi de tâches et en empêchant les éditions manuelles Task-status-sync ist eine Fähigkeit, die die atomare Synchronisation zwischen Aufgaben und Notizen durch den Einsatz von Aufgaben-Tracking-Befehlen und die Verhinderung von manuellen Bearbeitungen ermöglicht O task-status-sync é uma ferramenta que mantém a sincronização atômica entre tarefas e marcas de conclusão, garantindo a consistência dos dados Task-status-sync — это инструмент, который поддерживает атомарную синхронизацию между задачами и маркерами завершения, обеспечивая согласованность данных أداة task-status-sync هي أداة تحافظ على التزامن الذري بين المهام و علامات الإكمال، مما يضمن سلامة البيانات how to use task-status-sync task-status-sync alternative task-status-sync setup guide what is task-status-sync task-status-sync vs manual tracking task-status-sync install for AI agents Spec-Driven Development with task-status-sync task-status-sync for atomic synchronization task-status-sync and Claude Code workflows task-status-sync Spec-Driven Development 自动化任务状态同步 token budgets auditable artifacts Repeatable Claude Code AI 工具 工作流自动化 Intercepts and converts manual edits to task-tracker commands Detects Edit/Write tool usage on NOTES.md or tasks.md files Extracts intent from user or Claude changes Converts changes to task-tracker commands for auditable artifacts Enforces quality gates and token budgets for repeatable workflows Supports Spec-Driven Development with Claude Code workflows task-status-sync is a skill that enforces task-tracker command usage and prevents manual file edits, ensuring data consistency across tasks.md and NOTES.md files');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('regenrek/npm-trustme/release-npm-trustme', 'community', 'regenrek', 'npm-trustme', 'regenrek/npm-trustme', 'release-npm-trustme', 0, 0, 45, '2026-03-08T01:57:15.376Z', '2026-03-08T02:05:19.128Z', '791ea43dceba043365688697b2a7f08302efdd3938a291ed632dfd5e973c8b73', '{"id":"regenrek/npm-trustme/release-npm-trustme","name":"release-npm-trustme","description":{"en":"release-npm-trustme automates npm Trusted Publisher setup for developers, simplifying version management and release workflows.","zh":"release-npm-trustme 是一个自动化 npm Trusted Publisher 设置的工具，通过运行 scripts/release.ts 脚本来 bump 版本、构建、标签和推送发布","ja":"release-npm-trustme は npm Trusted Publisher の設定を自動化するツールで、scripts/release.ts スクリプトを実行してバージョンを bump し、ビルド、タグ付け、プッシュする","ko":"release-npm-trustme는 npm Trusted Publisher 설정을 자동화하는 도구로 scripts/release.ts 脚本을 실행하여 버전을 bump하고 빌드, 태그 및 푸시합니다","es":"Release-npm-trustme es una herramienta que automatiza la configuración de Trusted Publisher para npm. Permite ejecutar scripts y utilizar npm para una implementación eficiente","fr":"Release-npm-trustme est un outil qui automatise la configuration de Trusted Publisher pour npm. Il permet d''exécuter des scripts et d''utiliser npm pour une mise en œuvre efficace","de":"Release-npm-trustme ist ein Tool, das die Konfiguration von Trusted Publisher für npm automatisiert. Es ermöglicht die Ausführung von Skripten und die Verwendung von npm für eine effiziente Implementierung","pt":"O release-npm-trustme é uma ferramenta que automatiza a configuração do npm Trusted Publisher, permitindo que os desenvolvedores se concentrem em tarefas mais complexas.","ru":"ИИ Агент release-npm-trustme автоматизирует настройку npm Trusted Publisher, позволяя разработчикам сосредоточиться на более сложных задачах.","ar":"يدعم release-npm-trustme التحسين الآلي لإعدادات npm Trusted Publisher، مما يسمح للمطورين بالتركيز على مهام أكثر تعقيدا."},"seo":{"title":{"en":"release-npm-trustme: Automated npm Trusted Publisher Setu...","zh":"release-npm-trustme 设置指南：自动化 npm Trusted Publisher","ja":"release-npm-trustme セットアップガイド：npm Trusted Publisher の自動化","ko":"release-npm-trustme 설정 가이드: npm Trusted Publisher 자동화","es":"Guía de configuración de release-npm-trustme para automat...","fr":"Guide de mise en place de release-npm-trustme pour l''auto...","de":"Einrichtungsanleitung für release-npm-trustme zur Automat...","pt":"Guia de Configuração do release-npm-trustme para Automati...","ru":"ИИ Агент release-npm-trustme: Настройка Автоматизации npm...","ar":"إرشادات إعداد release-npm-trustme لتحسين آلي لمشترك موثوق..."},"description":{"en":"Streamline your npm Trusted Publisher setup with release-npm-trustme. Learn how to automate version bumps, builds, and GitHub Releases with this AI agent skill.","zh":"了解如何使用 release-npm-trustme 自动化 npm Trusted Publisher 设置，提高开发效率","ja":"release-npm-trustme を使用して npm Trusted Publisher の設定を自動化し、開発効率を向上させる方法について","ko":"release-npm-trustme를 사용하여 npm Trusted Publisher 설정을 자동화하고 개발 효율을 높이는 방법","es":"Automatice la configuración de Trusted Publisher con release-npm-trustme. Aprenda a ejecutar scripts y a utilizar npm para una implementación eficiente","fr":"Automatisez la configuration de Trusted Publisher avec release-npm-trustme. Découvrez comment exécuter des scripts et utiliser npm pour une mise en œuvre eff...","de":"Automatisieren Sie die Konfiguration von Trusted Publisher mit release-npm-trustme. Erfahren Sie, wie Sie Skripte ausführen und npm für eine effiziente Imple...","pt":"Aprenda a configurar o release-npm-trustme para automatizar a configuração do npm Trusted Publisher e melhorar a produtividade do seu time de desenvolvimento.","ru":"Узнайте, как настроить release-npm-trustme для автоматизации настройки npm Trusted Publisher и повысить производительность вашей команды разработчиков.","ar":"تعرف على كيفية إعداد release-npm-trustme لتحسين آلي لإعدادات npm Trusted Publisher وزيادة إنتاجية فريق التطوير الخاص بك."},"definition":{"en":"release-npm-trustme is a skill that automates npm Trusted Publisher setup, enabling developers to efficiently manage version bumps, builds, and releases.","zh":"release-npm-trustme 是一个用于自动化 npm Trusted Publisher 设置的 AI 工具","ja":"release-npm-trustme は npm Trusted Publisher の設定を自動化する AI エージェント","ko":"release-npm-trustme는 npm Trusted Publisher 설정을 자동화하는 AI 에이전트","es":"Release-npm-trustme es una herramienta de automatización para la configuración de Trusted Publisher en npm","fr":"Release-npm-trustme est un outil d''automatisation pour la configuration de Trusted Publisher dans npm","de":"Release-npm-trustme ist ein Automatisierungstool für die Konfiguration von Trusted Publisher in npm","pt":"O release-npm-trustme é uma ferramenta de automação que ajuda a configurar o npm Trusted Publisher de forma eficiente.","ru":"ИИ Агент release-npm-trustme - это инструмент автоматизации, помогающий настроить npm Trusted Publisher эффективно.","ar":"release-npm-trustme هو أداة تحسين آلي تساعد في إعداد إعدادات npm Trusted Publisher بفعالية."},"features":{"en":["Runs `scripts/release.ts` to bump version, build, tag, and push releases","Supports semver version bumps (patch, minor, major) via `pnpm tsx` command","Automates GitHub Release creation and updates using `gh` tool","Ensures clean working tree before running release script","Builds and commits changes before tagging and pushing releases"],"zh":["自动化 npm Trusted Publisher 设置","支持 bump 版本、构建、标签和推送发布","使用 scripts/release.ts 脚本","支持 patch、minor、major 和自定义 semver 版本","自动创建/更新 GitHub Release"],"ja":["npm Trusted Publisher の設定を自動化","バージョンの bump、ビルド、タグ付け、プッシュをサポート","scripts/release.ts スクリプトを使用","patch、minor、major とカスタム semver バージョンをサポート","GitHub Release の自動作成/更新"],"ko":["npm Trusted Publisher 설정 자동화","버전에 대한 bump, 빌드, 태그 및 푸시 지원","scripts/release.ts 스크립트 사용","patch, minor, major 및 사용자 지정 semver 버전 지원","GitHub Release 자동 생성/업데이트"],"es":["Automatización de la configuración de Trusted Publisher","Ejecución de scripts con npm","Uso de semver para control de versiones","Creación y actualización de lanzamientos en GitHub","Compatibilidad con pnpm y tsx"],"fr":["Automatisation de la configuration de Trusted Publisher","Exécution de scripts avec npm","Utilisation de semver pour le contrôle de version","Création et mise à jour de versions sur GitHub","Compatibilité avec pnpm et tsx"],"de":["Automatisierung der Konfiguration von Trusted Publisher","Ausführung von Skripten mit npm","Verwendung von semver für die Versionskontrolle","Erstellung und Aktualisierung von Releases auf GitHub","Kompatibilität mit pnpm und tsx"],"pt":["Executa scripts de release com `scripts/release.ts`","Suporta bump de versão com `patch`, `minor` ou `major`","Cria e atualiza releases no GitHub com `gh`","Permite a automação da configuração do npm Trusted Publisher","Utiliza `pnpm tsx` para executar scripts de release"],"ru":["Выполняет скрипты релиза с `scripts/release.ts`","Поддерживает bump версии с `patch`, `minor` или `major`","Создаёт и обновляет релизы на GitHub с `gh`","Позволяет автоматизировать настройку npm Trusted Publisher","Использует `pnpm tsx` для выполнения скриптов релиза"],"ar":["يعمل على تشغيل سكريبتات الإصدار مع `scripts/release.ts`","يدعم تحديث الإصدار مع `patch` أو `minor` أو `major`","يخلق ويعمل على تحديث الإصدارات على GitHub مع `gh`","يسمح بتحسين آلي لإعدادات npm Trusted Publisher","يستخدم `pnpm tsx` لتشغيل سكريبتات الإصدار"]},"keywords":{"en":["how to use release-npm-trustme","release-npm-trustme setup guide","npm Trusted Publisher automation","release-npm-trustme alternative","release-npm-trustme vs manual setup","automating npm version management"],"zh":["release-npm-trustme","npm Trusted Publisher","自动化设置","AI 工具","npm 版本管理","GitHub Release","semver","脚本自动化","开发效率"],"ja":["release-npm-trustme","npm Trusted Publisher","自動化設定","AI エージェント","npm バージョン管理","GitHub Release","semver","スクリプト自動化","開発効率"],"ko":["release-npm-trustme","npm Trusted Publisher","자동화 설정","AI 에이전트","npm 버전 관리","GitHub Release","semver","스크립트 자동화","개발 효율"],"es":["release-npm-trustme","Trusted Publisher","npm","automatización","scripts","semver","GitHub","pnpm","tsx","Herramientas de desarrollo"],"fr":["release-npm-trustme","Trusted Publisher","npm","automatisation","scripts","semver","GitHub","pnpm","tsx","Outils de développement"],"de":["release-npm-trustme","Trusted Publisher","npm","Automatisierung","Skripte","semver","GitHub","pnpm","tsx","Entwicklungstools"],"pt":["release-npm-trustme","automatizar npm Trusted Publisher","ferramenta de automação","configuração de release","bump de versão","GitHub release","pnpm tsx","scripts de release"],"ru":["release-npm-trustme","автоматизировать npm Trusted Publisher","инструмент автоматизации","настройка релиза","bump версии","GitHub релиз","pnpm tsx","скрипты релиза"],"ar":["release-npm-trustme","تحسين آلي لمشترك موثوق به في npm","أداة تحسين آلي","إعداد إصدار","تحديث إصدار","إصدار GitHub","pnpm tsx","سكريبتات الإصدار"]}},"owner":"regenrek","repo":"npm-trustme","repoPath":"regenrek/npm-trustme","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.376Z","topics":[],"category":"community","skillMd":{"name":"release-npm-trustme","description":"Release automation for npm-trustme. Use when asked to cut a new npm-trustme version, run the release script, or tag/publish a new release.","bodyPreview":"# release-npm-trustme\n\n## Overview\n\nRun `scripts/release.ts` to bump the version, build, tag, and push a release for npm-trustme.\n\n## Workflow\n\n- Open the repo: `cd ~/projects/npm-trustme`\n- Ensure the working tree is clean (the script will refuse to run otherwise).\n- Pick the version bump: `patch` | `minor` | `major` or a specific semver.\n- Run: `pnpm tsx scripts/release.ts <bump>`\n- The script builds, commits, tags, pushes, and (if `gh` is installed) creates/updates a GitHub Release.\n\n## Examp","body":"# release-npm-trustme\n\n## Overview\n\nRun `scripts/release.ts` to bump the version, build, tag, and push a release for npm-trustme.\n\n## Workflow\n\n- Open the repo: `cd ~/projects/npm-trustme`\n- Ensure the working tree is clean (the script will refuse to run otherwise).\n- Pick the version bump: `patch` | `minor` | `major` or a specific semver.\n- Run: `pnpm tsx scripts/release.ts <bump>`\n- The script builds, commits, tags, pushes, and (if `gh` is installed) creates/updates a GitHub Release.\n\n## Examples\n\n```\npnpm tsx scripts/release.ts patch\npnpm tsx scripts/release.ts minor\npnpm tsx scripts/release.ts 0.2.0\n```\n\n## Notes\n\n- The script pushes to the current branch and tags; confirm the branch before running.\n- Release notes use `CHANGELOG.md` if present. Set `GH_NOTES_REF` to override the changelog section.\n"},"lastSynced":"2026-03-08T02:05:19.128Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing automated npm Trusted Publisher setup and version management workflows.","zh":"非常适合需要自动化npm Trusted Publisher设置和版本管理工作流的开发人员代理。","ja":"npm Trusted Publisherの設定とバージョン管理ワークフローを自動化する必要がある開発者エージェントに最適です。","ko":"npm Trusted Publisher 설정 및 버전 관리 워크플ロー 자동화가 필요한 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan una configuración automatizada de npm Trusted Publisher y flujos de trabajo de administración de versiones.","fr":"Parfait pour les agents de développement nécessitant une configuration automatique de npm Trusted Publisher et des flux de travail de gestion de version.","de":"Perfekt für Entwickleragenten, die eine automatisierte npm Trusted Publisher-Konfiguration und Workflows für die Versionenverwaltung benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de configuração automatizada de Publicador Confiável do npm e fluxos de trabalho de gerenciamento de versão.","ru":"Идеально подходит для агентов разработчиков, которым необходима автоматизированная настройка доверенного издателя npm и рабочие процессы управления версиями.","ar":"مثالي لعميل المطور الذي يحتاج إلى إعداد ناشر موثوق به تلقائيًا وعمليات إدارة الإصدار ل npm."},"recommendation":{"en":"Empowers agents to automate version bumping, building, tagging, and pushing releases for npm packages using scripts like `release.ts` and tools such as `pnpm` and `gh` for GitHub Releases, streamlining the release workflow with semver versioning.","zh":"赋予代理自动化npm包的版本升级、构建、标记和发布版本的能力，使用诸如`release.ts`的脚本和`pnpm`、`gh`等工具实现GitHub Release，通过semver版本控制简化发布工作流。","ja":"エージェントに、npmパッケージのバージョンアップ、ビルド、タグ付け、リリースの自動化を可能にし、`release.ts`のようなスクリプトや`pnpm`、`gh`のようなツールを使用してGitHub Releaseを実現し、semverバージョニングでリリースワークフローを最適化します。","ko":"에이전트가 npm 패키지의 버전 업그레이드, 빌드, 태깅 및 릴리스 자동화를 가능하게 하며, `release.ts`와 같은 스크립트 및 `pnpm`, `gh`와 같은 도구를 사용하여 GitHub 릴리스를 구현하여 semver 버전 관리로 릴리스 워크플ロー 최적화합니다.","es":"Habilita a los agentes a automatizar el aumento de versión, la compilación, la etiquetado y la publicación de versiones para paquetes npm utilizando scripts como `release.ts` y herramientas como `pnpm` y `gh` para GitHub Releases, simplificando el flujo de trabajo de lanzamiento con versionado semver.","fr":"Permet aux agents d''automatiser la mise à jour de version, la construction, le tag et la publication de versions pour les packages npm en utilisant des scripts tels que `release.ts` et des outils tels que `pnpm` et `gh` pour GitHub Releases, en rationalisant le flux de travail de publication avec la version semver.","de":"Ermöglicht es Agenten, die Versionsnummern, das Erstellen, Tagging und Veröffentlichen von Releases für npm-Pakete mithilfe von Skripten wie `release.ts` und Tools wie `pnpm` und `gh` für GitHub Releases zu automatisieren, wodurch der Release-Workflow mit semver-Versionierung rationalisiert wird.","pt":"Permite que os agentes automatem o aumento de versão, compilação, marcação e envio de lançamentos para pacotes npm usando scripts como `release.ts` e ferramentas como `pnpm` e `gh` para Lançamentos do GitHub, simplificando o fluxo de trabalho de lançamento com controle de versão semver.","ru":"Наделяет агентов возможностью автоматизировать увеличение версии, сборку, маркировку и публикацию релизов для пакетов npm с помощью скриптов, таких как `release.ts`, и инструментов, таких как `pnpm` и `gh`, для GitHub-релизов, оптимизируя процесс релиза с управлением версиями semver.","ar":"تمكين الوكلاء من تلقين زيادة الإصدار وإنشاء وتغيير العلامات وإرسال الإصدارات لنماذج npm باستخدام سكريبتات مثل `release.ts` وأدوات مثل `pnpm` و `gh` من أجل إصدارات GitHub، وباستخدام التحكم في إصدار semver لتبسيط تدفق عمل الإصدار."},"useCases":{"en":["Automating npm package releases with version bumping and tagging","Streamlining GitHub Release creation and updates using `gh`","Simplifying version management with semver and `pnpm tsx` scripts"],"zh":["使用版本升级和标记自动化npm包发布","使用`gh`简化GitHub Release创建和更新","使用semver和`pnpm tsx`脚本简化版本管理"],"ja":["バージョンアップとタグ付けによるnpmパッケージの自動リリース","`gh`を使用したGitHub Releaseの作成と更新の簡素化","semverと`pnpm tsx`スクリプトを使用したバージョン管理の簡素化"],"ko":["버전 업그레이드 및 태깅을 통한 npm 패키지 자동 릴리스","`gh`를 사용한 GitHub 릴리스 생성 및 업데이트 간소화","semver 및 `pnpm tsx` 스크립트를 사용한 버전 관리 간소화"],"es":["Automatizar las versiones de paquetes npm con aumento y etiquetado de versiones","Racionalizar la creación y actualización de GitHub Release utilizando `gh`","Simplificar la administración de versiones con semver y scripts `pnpm tsx`"],"fr":["Automatiser les versions de packages npm avec la mise à jour et le tag de version","Rationaliser la création et la mise à jour de GitHub Release en utilisant `gh`","Simplifier la gestion des versions avec semver et des scripts `pnpm tsx`"],"de":["Automatisieren von npm-Paketversionen mit Versionsnummern und Tagging","Rationalisieren der Erstellung und Aktualisierung von GitHub Releases mit `gh`","Vereinfachen der Versionenverwaltung mit semver und `pnpm tsx`-Skripten"],"pt":["Automatizar lançamentos de pacotes npm com aumento de versão e marcação","Otimizar a criação e atualização de Lançamentos do GitHub usando `gh`","Simplificar o gerenciamento de versões com semver e scripts `pnpm tsx`"],"ru":["Автоматизировать релизы пакетов npm с увеличением версии и маркировкой","Оптимизировать создание и обновление GitHub-релизов с помощью `gh`","Упростить управление версиями с помощью semver и скриптов `pnpm tsx`"],"ar":["تلقين إصدارات حزمة npm مع زيادة الإصدار وتغيير العلامات","تبسيط إنشاء وتحديث إصدارات GitHub باستخدام `gh`","تبسيط إدارة الإصدار باستخدام semver و سكريبتات `pnpm tsx`"]},"limitations":{"en":["Requires a clean working tree to run the release script","Needs `gh` installed for GitHub Release automation","Specific to npm packages and GitHub Releases"],"zh":["需要干净的工作树来运行发布脚本","需要安装`gh`以实现GitHub Release自动化","仅限于npm包和GitHub Release"],"ja":["リリーススクリプトを実行するにはクリーンなワークツリーが必要","GitHub Releaseの自動化には`gh`のインストールが必要","npmパッケージとGitHub Releaseに限定"],"ko":["릴리스 스크립트를 실행하려면 깨끗한 워킹 트리가 필요함","GitHub 릴리스 자동화를 위해 `gh` 설치 필요","npm 패키지 및 GitHub 릴리스에 한정"],"es":["Requiere un árbol de trabajo limpio para ejecutar el script de lanzamiento","Necesita `gh` instalado para la automatización de GitHub Release","Específico para paquetes npm y GitHub Releases"],"fr":["Nécessite un arbre de travail propre pour exécuter le script de publication","Nécessite `gh` installé pour l''automatisation de GitHub Release","Spécifique aux packages npm et aux GitHub Releases"],"de":["Benötigt einen sauberen Arbeitsbereich, um das Release-Skript auszuführen","Benötigt `gh` installiert für die Automatisierung von GitHub Releases","Spezifisch für npm-Pakete und GitHub Releases"],"pt":["Exige uma árvore de trabalho limpa para executar o script de lançamento","Necessita de `gh` instalado para automação de Lançamento do GitHub","Específico para pacotes npm e Lançamentos do GitHub"],"ru":["Требует чистого рабочего дерева для запуска скрипта релиза","Требует установки `gh` для автоматизации GitHub-релизов","Специфичен для пакетов npm и GitHub-релизов"],"ar":["يتطلب شجرة عمل نظيفة لتشغيل سكريبت الإصدار","يحتاج إلى تثبيت `gh` لتلقين إصدار GitHub","محدد لحزم