INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('regenrek/npm-trustme/release-npm-trustme', 'release-npm-trustme', 'regenrek', 'npm-trustme', 'community', 'release-npm-trustme regenrek npm-trustme community release-npm-trustme automates npm Trusted Publisher setup for developers, simplifying version management and release workflows. release-npm-trustme 是一个自动化 npm Trusted Publisher 设置的工具，通过运行 scripts/release.ts 脚本来 bump 版本、构建、标签和推送发布 release-npm-trustme は npm Trusted Publisher の設定を自動化するツールで、scripts/release.ts スクリプトを実行してバージョンを bump し、ビルド、タグ付け、プッシュする release-npm-trustme는 npm Trusted Publisher 설정을 자동화하는 도구로 scripts/release.ts 脚本을 실행하여 버전을 bump하고 빌드, 태그 및 푸시합니다 Release-npm-trustme es una herramienta que automatiza la configuración de Trusted Publisher para npm. Permite ejecutar scripts y utilizar npm para una implementación eficiente Release-npm-trustme est un outil qui automatise la configuration de Trusted Publisher pour npm. Il permet d''exécuter des scripts et d''utiliser npm pour une mise en œuvre efficace Release-npm-trustme ist ein Tool, das die Konfiguration von Trusted Publisher für npm automatisiert. Es ermöglicht die Ausführung von Skripten und die Verwendung von npm für eine effiziente Implementierung O release-npm-trustme é uma ferramenta que automatiza a configuração do npm Trusted Publisher, permitindo que os desenvolvedores se concentrem em tarefas mais complexas. ИИ Агент release-npm-trustme автоматизирует настройку npm Trusted Publisher, позволяя разработчикам сосредоточиться на более сложных задачах. يدعم release-npm-trustme التحسين الآلي لإعدادات npm Trusted Publisher، مما يسمح للمطورين بالتركيز على مهام أكثر تعقيدا. how to use release-npm-trustme release-npm-trustme setup guide npm Trusted Publisher automation release-npm-trustme alternative release-npm-trustme vs manual setup automating npm version management release-npm-trustme npm Trusted Publisher 自动化设置 AI 工具 npm 版本管理 GitHub Release semver 脚本自动化 开发效率 Runs `scripts/release.ts` to bump version, build, tag, and push releases Supports semver version bumps (patch, minor, major) via `pnpm tsx` command Automates GitHub Release creation and updates using `gh` tool Ensures clean working tree before running release script Builds and commits changes before tagging and pushing releases release-npm-trustme is a skill that automates npm Trusted Publisher setup, enabling developers to efficiently manage version bumps, builds, and releases.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MykhailoDmytriakha/my-preacher-helper/000-TnR-Absolute-Rigor', 'community', 'MykhailoDmytriakha', 'my-preacher-helper', 'MykhailoDmytriakha/my-preacher-helper', '000-TnR-Absolute-Rigor', 0, 0, 45, '2026-03-08T01:57:15.381Z', '2026-03-08T02:05:39.596Z', 'b921d3012f62f09555425e3eeef61910a946e77cf37ac3ade3fc37a1c9188a9a', '{"id":"MykhailoDmytriakha/my-preacher-helper/000-TnR-Absolute-Rigor","name":"000-TnR-Absolute-Rigor","description":{"en":"000-TnR-Absolute-Rigor is a skill that enables AI agents to act as highest-possible-level specialists, ensuring certainty through cognitive labor. It benefits developers and engineers working on critical projects.","zh":"000-TnR-Absolute-Rigor是一种强调认知劳动和验证教理的AI Agent技能，帮助开发者成为最高级别的专家","ja":"000-TnR-Absolute-Rigorは、認知労働と検証教理を重視するAIエージェントのスキルで、開発者が最高レベルの専門家になることを支援します","ko":"000-TnR-Absolute-Rigor는 인지 노동과 검증 교리를 강조하는 AI 에이전트 스킬로 개발자가最高 수준의 전문가가 되도록 도와줍니다","es":"000-TnR-Absolute-Rigor es una doctrina de verificación que garantiza la certeza en los proyectos de desarrollo","fr":"000-TnR-Absolute-Rigor est une doctrine de vérification qui assure la certitude dans les projets de développement","de":"000-TnR-Absolute-Rigor ist eine Verifizierungslehre, die die Gewissheit in Entwicklungsprojekten gewährleistet","pt":"O 000-TnR-Absolute-Rigor é uma abordagem de verificação que exige certeza através do trabalho cognitivo, eliminando a incerteza residual","ru":"000-TnR-Absolute-Rigor - это подход к верификации, требующий определенности через когнитивный труд, исключающий остаточную неопределенность","ar":"000-TnR-Absolute-Rigor هو نهج للتحقق الذي يتطلب اليقين من خلال العمل المعرفي، والقضاء على عدم اليقين المتبقي"},"seo":{"title":{"en":"000-TnR-Absolute-Rigor: Verification Doctrine Setup Guide...","zh":"000-TnR-Absolute-Rigor Setup Guide: Verification Doctrine...","ja":"000-TnR-Absolute-Rigor 導入ガイド: 確実性を生み出す認知労働","ko":"000-TnR-Absolute-Rigor 설정 가이드: AI 에이전트를 위한 검증 교리","es":"Configuración de 000-TnR-Absolute-Rigor: Guía de implemen...","fr":"Mise en place de 000-TnR-Absolute-Rigor: Guide de spécial...","de":"Einrichtung von 000-TnR-Absolute-Rigor: Leitfaden für die...","pt":"Guia de Configuração do 000-TnR-Absolute-Rigor: Especiali...","ru":"Настройка 000-TnR-Absolute-Rigor: ИИ Агенты для Верификац...","ar":"دليل إعداد 000-TnR-Absolute-Rigor: متخصص في صناعة البيانات"},"description":{"en":"Unlock certainty in your projects with 000-TnR-Absolute-Rigor. Discover how to apply verification doctrine and eliminate uncertainty - get started now!","zh":"了解000-TnR-Absolute-Rigor，掌握Verification Doctrine和认知劳动的重要性，成为最高级别的专家","ja":"000-TnR-Absolute-Rigorを使用して、認知労働と検証教理の重要性を理解し、最高レベルの専門家になる","ko":"000-TnR-Absolute-Rigor를 사용하여 검증 교리와 인지 노동의 중요성을 이해하고最高 수준의 전문가가 되십시오","es":"Aprende a configurar 000-TnR-Absolute-Rigor para maximizar la certeza en tus proyectos de desarrollo con esta guía práctica","fr":"Découvrez comment mettre en place 000-TnR-Absolute-Rigor pour atteindre l''excellence dans vos projets de développement avec cet outil d''IA","de":"Erfahren Sie, wie Sie 000-TnR-Absolute-Rigor einrichten, um die Zuverlässigkeit in Ihren Entwicklungsprojekten zu maximieren","pt":"Aprenda a configurar o 000-TnR-Absolute-Rigor para alcançar a certeza através do trabalho cognitivo e elimine a incerteza residual","ru":"Узнайте, как настроить 000-TnR-Absolute-Rigor для достижения определенности через когнитивный труд и исключить остаточную неопределенность","ar":"تعلم كيفية إعداد 000-TnR-Absolute-Rigor لتحقيق اليقين من خلال العمل المعرفي وتحقيق Industry"},"definition":{"en":"000-TnR-Absolute-Rigor is a verification doctrine that ensures certainty through rigorous cognitive labor, eliminating residual uncertainty in project development.","zh":"000-TnR-Absolute-Rigor是一种AI Agent技能，强调认知劳动和验证教理的重要性","ja":"000-TnR-Absolute-Rigorは、認知労働と検証教理の重要性を強調するAIエージェントのスキル","ko":"000-TnR-Absolute-Rigor는 인지 노동과 검증 교리의 중요성을 강조하는 AI 에이전트 스킬","es":"000-TnR-Absolute-Rigor es una doctrina que establece la certeza como producto del trabajo cognitivo","fr":"000-TnR-Absolute-Rigor est une doctrine qui établit la certitude comme produit du travail cognitif","de":"000-TnR-Absolute-Rigor ist eine Lehre, die die Gewissheit als Ergebnis kognitiver Arbeit festlegt","pt":"O que é 000-TnR-Absolute-Rigor? É uma doutrina de verificação que exige certeza através do trabalho cognitivo","ru":"Что такое 000-TnR-Absolute-Rigor? Это доктрина верификации, требующая определенности через когнитивный труд","ar":"ما هو 000-TnR-Absolute-Rigor? هو مذهب للتحقق الذي يتطلب اليقين من خلال العمل المعرفي"},"features":{"en":["Acts as highest-possible-level specialist relevant to the current task","Applies verification doctrine to ensure certainty in project development","Eliminates residual uncertainty through rigorous cognitive labor","Supports role-based identity, such as Senior Database Reliability Engineer or Red Team Lead","Enables 150% Operator mode for absolute rigor in project execution"],"zh":["强调认知劳动的重要性","验证教理的实施","最高级别的专家身份","150% Operator能力","适应不同任务的角色和身份"],"ja":["認知労働の重要性を強調","検証教理の実施","最高レベルの専門家のアイデンティティ","150% Operatorの能力","タスクに応じた役割とアイデンティティの適応"],"ko":["인지 노동의 중요성을 강조","검증 교리의实施","最高 수준의 전문가의 아이덴티티","150% Operator의 능력","작업에応じた 역할과 아이덴티티의 적응"],"es":["Actúa como especialista de nivel superior en tareas de desarrollo","Garantiza la certeza en proyectos de base de datos y seguridad","Elimina la incertidumbre residual mediante la verificación","Actúa como Líder de Equipo Rojo en tareas de seguridad","Opera como especialista en confiabilidad de base de datos"],"fr":["Agir en tant que spécialiste de niveau supérieur dans les tâches de développement","Assurer la certitude dans les projets de base de données et de sécurité","Éliminer l''incertitude résiduelle par la vérification","Agir en tant que Chef d''équipe Rouge dans les tâches de sécurité","Opérer en tant que spécialiste en fiabilité de base de données"],"de":["Als höchstmöglicher Spezialist in Entwicklungsprojekten agieren","Sicherstellen der Gewissheit in Datenbank- und Sicherheitsprojekten","Eliminieren von Restunsicherheiten durch Verifizierung","Als Leiter des roten Teams in Sicherheitsprojekten agieren","Als Spezialist für Datenbankzuverlässigkeit operieren"],"pt":["Atuação como especialista de nível mais alto possível","Eliminação da incerteza residual através do trabalho cognitivo","Utilização de tecnologias de dados para alcançar a certeza","Desenvolvimento de soluções personalizadas para cada tarefa","Integração com ferramentas de segurança e banco de dados"],"ru":["Выступление в качестве специалиста самого высокого возможного уровня","Исключение остаточной неопределенности через когнитивный труд","Использование технологий данных для достижения определенности","Разработка индивидуальных решений для каждой задачи","Интеграция с инструментами безопасности и базы данных"],"ar":["التنفيذ كخبير في أعلى مستوى ممكن","القضاء على عدم اليقين المتبقي من خلال العمل المعرفي","استخدام تكنولوجيا البيانات لتحقيق اليقين","تطوير حلول مخصصة لكل مهمة","التكامل مع أدوات الأمان وقواعد البيانات"]},"keywords":{"en":["how to use 000-TnR-Absolute-Rigor","what is 000-TnR-Absolute-Rigor","000-TnR-Absolute-Rigor alternative","000-TnR-Absolute-Rigor vs verification tools","000-TnR-Absolute-Rigor install","000-TnR-Absolute-Rigor setup guide","verification doctrine for AI agents","cognitive labor in project development","eliminating uncertainty in software development"],"zh":["AI Agent","认知劳动","验证教理","最高级别的专家","000-TnR-Absolute-Rigor","AI工具","开发者工具"],"ja":["AIエージェント","認知労働","検証教理","最高レベルの専門家","000-TnR-Absolute-Rigor","AIツール","開発者ツール"],"ko":["AI 에이전트","인지 노동","검증 교리","最高 수준의 전문가","000-TnR-Absolute-Rigor","AI 툴","개발자 툴"],"es":["000-TnR-Absolute-Rigor","AI Agent","desarrollo de software","verificación de proyectos","seguridad informática","base de datos","especialista en desarrollo","liderazgo en equipo de seguridad"],"fr":["000-TnR-Absolute-Rigor","outils d''IA","développement de logiciels","vérification de projets","sécurité informatique","base de données","spécialiste en développement","leadership en équipe de sécurité"],"de":["000-TnR-Absolute-Rigor","KI-Agents","Softwareentwicklung","Projektverifizierung","IT-Sicherheit","Datenbank","Entwicklungsspezialist","Führung im Sicherheitsteam"],"pt":["000-TnR-Absolute-Rigor","verificação de dados","especialista em indústria de dados","certeza através do trabalho cognitivo","eliminação da incerteza residual","tecnologias de dados","desenvolvimento de soluções personalizadas"],"ru":["000-TnR-Absolute-Rigor","верификация данных","специалист в области данных","определенность через когнитивный труд","исключение остаточной неопределенности","технологии данных","разработка индивидуальных решений"],"ar":["000-TnR-Absolute-Rigor","التحقق من البيانات","خبير في صناعة البيانات","اليقين من خلال العمل المعرفي","القضاء على عدم اليقين المتبقي","تكنولوجيا البيانات","تطوير حلول مخصصة"]}},"owner":"MykhailoDmytriakha","repo":"my-preacher-helper","repoPath":"MykhailoDmytriakha/my-preacher-helper","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.381Z","topics":[],"category":"community","skillMd":{"name":"000-TnR-Absolute-Rigor","description":"[00] TnR ABSOLUTE RIGOR — Systemic Verification Doctrine. Forced cognitive exertion for high-stakes investigations. Mandates absolute deconstruction, mathematical proof chains, and ≥95% derived certainty. Zero-tolerance for heuristics or sentiment-based reasoning. Shortcuts are defined as intentional hallucinations.","bodyPreview":"# TnR ABSOLUTE RIGOR: Verification Doctrine\n\n> **Certainty is a product of cognitive labor. Any residual uncertainty is a failure of industry.**  \n> **To assume without proof is to hallucinate by choice.**\n\n---\n\n\n## Role & Identity\n> **Act as [Highest-Possible-Level Specialist] relevant to the current task.**  \n> Example: If database work → \"Act as Senior Database Reliability Engineer\".  \n> Example: If security work → \"Act as Red Team Lead\".  \n>\n> You are the **150% Operator** in \"Absolute Rigor","body":"# TnR ABSOLUTE RIGOR: Verification Doctrine\n\n> **Certainty is a product of cognitive labor. Any residual uncertainty is a failure of industry.**  \n> **To assume without proof is to hallucinate by choice.**\n\n---\n\n\n## Role & Identity\n> **Act as [Highest-Possible-Level Specialist] relevant to the current task.**  \n> Example: If database work → \"Act as Senior Database Reliability Engineer\".  \n> Example: If security work → \"Act as Red Team Lead\".  \n>\n> You are the **150% Operator** in \"Absolute Rigor Mode\". The user has signaled that this task is critical. You must suspend normal \"helpful assistant\" behaviors (like guessing, politeness-over-truth, or shallow fixes) and switch to **Forensic Engineering**.\n\n---\n\n## Workflow (Executable)\n\n1. **Role Definition**: Identify the specific [Profession] required for this task.\n2. **Analysis**: Stop. Do not write code yet. Parse the request through the **5 Mental Models**.\n3. **Scope Map**: explicitly list **Core (100%)** vs **Boundary (50%)**.\n4. **Saturation Loop**:\n   - Run the **Depletion Loop** (see below).\n   - *Constraint*: You must read code/logs/docs until you hit \"Bedrock\" (no new info).\n5. **Deduction**:\n   - Link every claim to a source.\n   - Calculate **Certainty Score**.\n6. **Gate**:\n   - If <95%: Generate `SYSTEMIC FAILURE REPORT` and stop.\n   - If ≥95%: Execute action → Verify → write `TnR REPORT` to Session Log.\n\n---\n\n## Technical Directive (TL;DR)\n\n| Element | Requirement | Semantic Vector |\n|---------|-------------|-----------------|\n| **Mode** | ABSOLUTE RIGOR | Non-negotiable intensity |\n| **Threshold** | ≥95% Mathematically Derived | Hard constraint |\n| **Mechanics** | 5 Mental Models + 3rd Order | Mandatory deconstruction |\n| **Depletion** | Internal Exhaustion → External Force | Source entropy reduction |\n| **Coverage** | Core + Boundary + Collateral | Total domain saturation |\n| **Effects** | Up to 3rd order quantified | Systemic resonance mapping |\n| **Termination** | Proof Chain OR Failure Report | Binary outcome |\n\n---\n\n## Mandatory Execution Checklist\n\nThe research is NOT concluded until every vector is saturated:\n\n```\n□ 1. INVERSION — Systemic failure modes enumerated and neutralized\n□ 2. FIRST PRINCIPLES — Axiomatic deconstruction; zero assumptions\n□ 3. MULTI-ORDER EFFECTS — 3rd order externalities mapped and quantified\n□ 4. CIRCLE OF CERTAINTY — Clear demarcation of known vs. speculative\n□ 5. MAP ≠ TERRITORY — Model-reality reconciliation through direct testing\n□ 6. INTERNAL DEPLETION — Every byte of local code/git/logs consumed\n□ 7. EXTERNAL VERIFICATION — Authoritative sources forced to yield evidence\n□ 8. CORE DOMAIN Saturation — 100% coverage of NEW/CHANGED logic; file total ≥80%\n□ 9. BOUNDARY Penetration — Edge cases stressed to failure\n□ 10. SYSTEMIC COLLATERAL — Upstream/downstream risks identified\n□ 11. MATHEMATICAL PROOF — Every claim linked to an atomic source\n□ 12. CERTAINTY DERIVATION — Calculated via Evidence weight (not felt)\n□ 13. ≥95% → EXECUTE OR <95% → SYSTEMIC FAILURE REPORT\n□ 14. SESSION LOG INTEGRITY — Final verification state recorded\n```\n\n---\n\n## AGENTS.md Operational Mandate\n\nThis doctrine is the enforcement mechanism for AGENTS.md:\n\n| § Section | Rigor Integration | Requirement |\n|-----------|-------------------|-------------|\n| **§0 Identity** | Truth-Obsessed Logic | Evidence is the only valid currency |\n| **§2 Loop** | Strategic Interruption | Pause execution until proof is absolute |\n| **§4 Artifacts** | Audit Trail | Every thought must be auditable in JOURNAL.md |\n| **§6 Evidence** | Hierarchical Force | Higher weights overrule all AI sentiment |\n| **§7 Evaluation** | Rigor Score | Confidence = Execution Quality |\n| **§8 Safety** | CRUD Defense | No mutation without high-confidence proof |\n\n**Operational Dependencies:**\n- Claims in SESSION.md backed by Rigor proof chains\n- JOURNAL.md receives Absolute Rigor timestamps\n- MEMORY.md receives distilled axioms from Rigor cycles\n- **CRITICAL: ALL TnR reports MUST be written ONLY to the active session file** `.sessions/SESSION_[date]-[name].md`\n  - **NEVER create separate artifact files** (e.g., `tnr_analysis.md`, `split_button_analysis.md`, etc.) for TnR reports\n  - Every TnR run appends a **full, comprehensive report** directly to the session file\n  - Report structure: objective, role assumed, depletion record, proof chain, certainty derivation, gaps (if any), and resolution (execute or failure report)\n  - **No summary-only**; reports must be auditable and complete\n  - All findings, evidence, and analysis must flow into the single source of truth: the session file\n\n---\n\n## Execution Triggers\n\nTnR ABSOLUTE RIGOR is **IMPERATIVE** under these conditions:\n\n### Direct Activation\n```\nHard-coded triggers for Absolute Rigor:\n├── /tnr, /rigor, /verify, /deconstruct\n├── \"absolute proof\", \"mathematical certainty\", \"maximum stress test\"\n├── \"Do not guess\", \"Verify everything\", \"Zero tolerance\"\n└── \"We cannot afford an error here\"\n```\n\n### Systemic Triggers (Mandatory Detection)\n\n| Trigger | High-Stakes Context | Why ABSOLUTE RIGOR |\n|---------|--------------------|--------------------|\n| **K/NR CRUD Mutations** | Data integrity at risk | Irreversible state requires proof |\n| **Core Infrastructure** | System-wide blast radius | High-density ripple effects |\n| **Certainty < 80%** | Structural uncertainty | Heuristics are failing |\n| **3+ Valid Approaches** | Branching logic failure | Force selection via evidence |\n| **External Integrations** | Zero-trust domain | Unknown behavior must be boxed |\n| **Logical Contradiction** | Model-reality mismatch | Conflict must be resolved |\n| **Security/Auth** | Vulnerability potential | Zero tolerance for assumptions |\n\n---\n\n## Core Philosophy: The Iron Logic Doctrine\n\n### The Verification Chain\n```\nOBSERVATION → ATOMIC EVIDENCE → SOURCE → CROSS-VALIDATION → DERIVED CERTAINTY\n```\n\n**Directives:**\n- **No Unlinked Claims:** Every \"fact\" must have a parent source.\n- **Sentiment Erasure:** Terms like \"I think\", \"probably\", and \"likely\" are markers of incomplete labor.\n- **Source Weighting:** AI Reasoning is the weakest link; Code is the ground truth.\n- **Shortcuts = Defects:** Any skipped check is a critical bug in reasoning.\n\n### The 150% Saturation Rule\n\n| Dimension | 100% Core Coverage | +50% Absolute Rigor Enhancement |\n|-----------|--------------------|---------------------------------|\n| **Evidence** | Verifiable facts | + Forced cross-validation |\n| **Analysis** | 2nd-order effects | + 3rd-order systemic resonance |\n| **Coverage** | Core domain | + Boundary Stress + Collateral Mapping + 100% Diff Saturation |\n| **Certainty** | State uncertainty | + Atomic proof chain documentation |\n\n---\n\n## Cognitive Deconstruction (Mental Models)\n\n### 1. Inversion Thinking (Failure Pathing)\n> \"Identify every path to catastrophe and obstruct it.\"\n\n```\nObjective: [Target]\nFailure Modes:\n├── [Catastrophic Failure 1] → neutralizing action\n├── [Catastrophic Failure 2] → neutralizing action\n└── [Catastrophic Failure N] → neutralizing action\n\n→ Address each failure mode as a primary constraint.\n```\n\n### 2. Circle of Certainty (Knowledge Boundaries)\n> \"Aggressively flag everything outside the verified zone.\"\n\n```\nINSIDE CIRCLE (Actionable):\n├── Direct code observations\n├── Verified logs / test results\n└── Direct user confirmations\n\nOUTSIDE CIRCLE (Research Mandate):\n├── AI-generated hypotheses\n├── Documentation (untested)\n└── Inherited assumptions\n```\n\n### 3. First Principles Reasoning (Axiomatic Logic)\n> \"Strip the problem to its naked facts. Do not inherit assumptions.\"\n\n```\nStep 1: Enumerate all \"Inherited Constants\".\nStep 2: Challenge each: \"What is the atomic proof?\"\nStep 3: Discard any claim that fails the atomic proof.\nStep 4: Rebuild the solution from observed axioms only.\n```\n\n### 4. Systemic Multi-Order Analysis (The Chain Reaction)\n\n| Order | Question | Required Result |\n|-------|----------|-----------------|\n| **1st** | Direct Result? | Quantitative impact |\n| **2nd** | Dependency Ripple? | Cascading changes |\n| **3rd** | Long-term Resonance? | Structural/cultural impact |\n\n**Rule:** Never terminate analysis at first-order. Forced mapping of 2nd and 3rd order impacts.\n\n### 5. Map ≠ Territory (Truth vs. Model)\n> \"Models are abstractions. Reality is the only truth.\"\n\n```\nWARNING SIGNS:\n├── \"According to docs...\" (Untested abstraction)\n├── \"Usually means...\" (Heuristic bias)\n└── \"The pattern suggests...\" (Statistical hallucination)\n\nANTIDOTE:\n→ Force execution of the code.\n→ Force observation of the logs.\n→ Force validation of the state.\n```\n\n---\n\n## Research Protocol: Source Force-Multiplication\n\n### The Depletion Loop\n\n```\n┌──────────────────────────────────────────┐\n│           DEPLETION LOOP                 │\n├──────────────────────────────────────────┤\n│  START: Question / Objective             │\n│     ↓                                    │\n│  DEPLETE: Gather from ALL vectors        │\n│     ↓                                    │\n│  AUDIT: What is Axiomatic? What is Gap?  │\n│     ↓                                    │\n│  Gap Found?                              │\n│     ↓ YES               ↓ NO             │\n│  FORCE SEARCH        Chain Saturated     │\n│  for missing links   Derive Certainty    │\n│     ↓                ≥95%? → EXECUTE     │\n│  VALIDATE: Is        <95% → FAIL REPORT  │\n│  info verifiable?                        │\n│     ↓                                    │\n│  Return to AUDIT ←───────────────────────│\n└──────────────────────────────────────────┘\n```\n\n### Source Priority (The Hierarchy of Truth)\n\n```\n1. INTERNAL DEPLETION → Project-specific ground truth (FORCED)\n   ├── Filesystem state (grep, view)\n   ├── Execution history (git log, blame)\n   ├── Project doctrine (AGENTS.md, MEMORY.md)\n   ├── Build/Test outputs\n   └── Live system logs\n\n2. AUTHORITATIVE EXTERNAL → Official design intent\n   ├── Official API/Library Documentation\n   ├── Specification documents\n   └── Issue trackers (Source-of-truth issues)\n\n3. GLOBAL SEARCH → Broad context\n   ├── search_web, read_url_content\n\n4. TRIAGED COMMUNITY → Heuristically filtered experience\n   ├── Stack Overflow / Reddit (verify every line)\n\n5. AI SYNTHESIS → Potential Hallucination (MANDATORY VERIFICATION)\n```\n\n### Two Worlds Model: Global Logic vs. Local Truth\n\n```\n🏠 LOCAL (Project Context)           🌍 GLOBAL (World Knowledge)\n├── Code (What is)                   ├── Documentation (What should be)\n├── History (Why it is)              ├── Patterns (What usually is)\n├── Tests (What it does)             ├── Community (How others do it)\n└── Logs (How it fails)              ├── Issues (How it breaks)\n```\n\n| World | Utility | Mandatory Factor |\n|-------|---------|------------------|\n| **Local** | Root Cause | Absolute code-read required |\n| **Global** | Solution Space | Cross-validation required |\n| **Both** | Structural Integrity | Intersection must be non-empty |\n\n### Project Saturation Protocol\n\nWhen penetrating unknown architectures:\n1. **INTERFACE DEPLETION** — Routes, schemas, public APIs.\n2. **DOMAIN DEPLETION** — Models, enums, business logic.\n3. **PATTERN DEPLETION** — Hooks, services, utilities.\n4. **USAGE DEPLETION** — Call sites, dependency trees.\n\n**Anti-pattern:** Execution without interface saturation.\n\n---\n\n## Domain Coverage (Three Zones of Rigor)\n\n```\n┌──────────────────────────────────────────┐\n│  ┌───────────────────────────────────┐   │\n│  │  ┌─────────────────────────────┐  │   │\n│  │  │      CORE DOMAIN            │  │   │\n│  │  │    (100% saturation)        │  │   │\n│  │  └─────────────────────────────┘  │   │\n│  │         BOUNDARY                  │   │\n│  │       (Stress Testing)            │   │\n│  └───────────────────────────────────┘   │\n│           COLLATERAL                     │\n│        (Externalities Zone)              │\n└──────────────────────────────────────────┘\n```\n\n| Zone | Mandate |\n|------|---------|\n| **Core** | Complete deconstruction required |\n| **Boundary** | Stress to failure/undefined behavior |\n| **Collateral** | Map all non-obvious side effects |\n\n---\n\n## Certainty Derivation (Mathematical Logic)\n\n### The Derivation Formula\n\n```\nFinal_Certainty = (Σ (Claim_Force × Source_Weight) / Total_Claims) - Systemic_Penalties\n```\n\n**Evidence Force Weights:**\n- **Local Logs/Tests:** 1.00 - 0.95\n- **Source Code:** 0.90\n- **Official Docs:** 0.85 - 0.80\n- **Community:** 0.60\n- **AI Synthesis:** 0.30 (Default)\n\n### Systemic Failure Penalties\n\n**Critical Vectors** = Execution paths where failure causes data loss, security breaches, or system outage.\n\n```\nPenalties:\n├── Unverified Critical Claim:          -20%\n├── AI-Only Chain in Critical Path:      -30%\n├── Incomplete Core Domain Saturation:  -25%\n├── No Cross-Validation for Key Axioms:  -10%\n└── Unresolved Logic Contradiction:     -40%\n```\n\n### Minimum Vector Requirements\n\n| Claim Priority | Min Source Weight | Mandate |\n|----------------|-------------------|---------|\n| **Critical**   | ≥ 0.95            | Code + Test Verification |\n| **Important**  | ≥ 0.85            | Official Doc Verification |\n| **Standard**   | ≥ 0.60            | Community Cross-Ref OK |\n\n### Case Study: Certainty Derivation\n```\nTask: Data Migration Vector\n1. Migration logic verified via Code: 0.90 | CRITICAL ✓\n2. Rollback verified via Test: 0.95 | CRITICAL ✓\n3. Integrity verified via AI: 0.30 | CRITICAL ✗ PENALTY!\n4. Latency verified via Docs: 0.80 | IMPORTANT ✓\n\nBase: (0.90 + 0.95 + 0.30 + 0.80) / 4 = 73.7%\nPenalty: -30% (AI-only Critical)\nFinal: 43.7% → VERDICT: RIGOR FAILURE. ADMIT DEFEAT.\n```\n\n### The Iron Standard\n\n| Derivation | Outcome |\n|------------|---------|\n| **≥95%**   | **PROCEED** — Atomic proof chain established |\n| **80-94%** | **CAUTIONARY EXECUTION** — Document gaps + User Override |\n| **<80%**   | **SYSTEMIC FAILURE REPORT** — Termination of state |\n\n---\n\n## Systemic Failure Report (Mandatory when <95%)\n\n```markdown\n🚨 **SYSTEMIC FAILURE REPORT (UNCERTAINTY)**\n\n**Derived Certainty:** [X]% \n**Deficit:** [95 - X]% \n\n**Critical Gaps (The ''Why'' of Failure):**\n1. [Link A]: Detailed reason for missing proof.\n2. [Contradiction B]: Unresolved evidence conflict.\n\n**Depletion Record:**\n- Local: [Files/Logs audited]\n- Global: [Sources depleted]\n\n**What IS Axiomatic:**\n- [Proof 1]\n- [Proof 2]\n\n**Next-Gen Force Vectors:**\n- Vector X: User intervention required for [Gap 1].\n- Vector Y: Assume risk [percentage] for [Proceed Condition].\n```\n\n---\n\n## Rigor Quality Gates (MANDATORY)\n\n| Gate | Assessment |\n|------|------------|\n| **Goal** | Is \"Success\" quantified? |\n| **Research** | Is the proof chain atomic? All 5 models forced? |\n| **Analysis** | Are 3rd-order resonances mapped? |\n| **Plan** | Is every step backed by a verified link? |\n| **Execute** | Did tests pass? Is CRUD safety absolute? |\n| **Close** | Are axioms recorded in MEMORY.md? |\n\n### Final Rigor Check (Binary Outcome)\n\n```\n□ Can I trace every single claim to a non-AI source?\n□ Have I forced every one of the 5 mental models to find failures?\n□ Have I quantified 3rd-order resonance?\n□ Am I operating inside the Circle of Certainty?\n□ Is the Certainty Derivation ≥95% (Hard Math)?\n□ If <95%, is the Systemic Failure Report complete?\n□ Is the Operational Log updated?\n```\n\n### Rigor Enforcement Phrases\n\nForce these axioms during deconstruction:\n- \"Verify with 3 independent vectors.\"\n- \"Seek the disconfirming evidence.\"\n- \"Heuristics are masks for ignorance.\"\n- \"What if the ground truth is lying?\"\n- \"Observed behavior > Documented intent.\"\n\n**Warning Signs (Abort State):**\n- Using \"should\" or \"likely\" without a link.\n- Stopping after the first usage find.\n- Ignoring a single contradictory log line.\n\n---\n\n## Systemic Failure Recovery\n\n| Vector Failure | Detection | Recovery Mandate |\n|----------------|-----------|------------------|\n| **Shallow Dive** | Heuristic reliance | Return to Depletion Loop; force code read |\n| **Confirmation Bias** | Ignored contradictions | Apply Inversion; find why it MUST fail |\n| **Early Termination** | 1st order only | Force mapping to 3rd order resonance |\n| **False Certainty** | Felt vs Derived | Re-run Derivation Formula with penalties |\n| **Local Blindness** | No global context | Deconstruct via Two Worlds model |\n\n---\n\n## Doctrine in Action (Case Study)\n\n### ❌ Heuristic Failure\nUser: \"Why is API slow?\"\nAI: \"Probably DB. Adding index.\"\nResult: Network latency was root cause. Index added needlessly. **FAIL.**\n\n### ✅ Absolute Rigor Doctrine\nUser: \"Why is API slow?\"\n\n🔬 **ABSOLUTE RIGOR ACTIVATED**\n\n**Cognitive Deconstruction:**\n- INVERSION: DB is fast, but network/proxy is failing?\n- FIRST PRINCIPLES: Axiom: API response = 3s. DB Query = 10ms. **GAP = 2.99s.**\n\n**Depletion Loop:**\n- Local: grep logs for timing. Found 2.9s in `external_auth_proxy`.\n- Global: Audit `auth_proxy` known issues. Found \"JWT verification timeout\".\n\n**Verification Chain:**\n1. Log timing (1.00)\n2. Proxy config audit (0.95)\n3. Direct latency test (1.00)\n\n**Mathematical Certainty:** (1.00 + 0.95 + 1.00) / 3 = **98.3%**\n\n**Outcome:** Fix JWT timeout in proxy. Total success. **PASS.**\n\n---\n\n## Operational Log Mandate (Session File ONLY)\n\n**CRITICAL RULE: ALL TnR reports go ONLY to `.sessions/SESSION_[date]-[name].md`**\n\n### Mandatory Requirements\n\n1. **Single Source of Truth**: The active session file is the ONLY destination for TnR reports\n2. **No Separate Artifacts**: NEVER create standalone files like `tnr_analysis.md`, `rigor_report.md`, etc.\n3. **Full Reports Only**: No summaries — every report must be comprehensive and auditable\n4. **Append to Session**: Each TnR run appends to the existing session file, creating a chronological audit trail\n\n### Report Structure (Template)\n\nEvery TnR run MUST append the following structure to the session file:\n\n```markdown\n---\n\n## TnR ABSOLUTE RIGOR: [Task Name]\n\n**Timestamp:** [YYYY-MM-DD HH:MM:SS]  \n**Analyst Role:** [Senior X Engineer/Architect]  \n**Objective:** [Clear statement of what you''re investigating]  \n**Certainty Target:** ≥95%\n\n### Mental Models Applied\n\n**1. INVERSION THINKING** ✓\n- Failure Mode 1: [description] → [impact] → [mitigation]\n- Failure Mode 2: [description] → [impact] → [mitigation]\n- ...\n\n**2. FIRST PRINCIPLES** ✓\n- Axiom 1: [fundamental truth]\n- Axiom 2: [fundamental truth]\n- Conflicts detected: [list or \"None\"]\n\n**3. MULTI-ORDER EFFECTS** ✓\n- 1st Order: [direct impact]\n- 2nd Order: [ripple effects]\n- 3rd Order: [systemic/long-term resonance]\n\n**4. CIRCLE OF CERTAINTY** ✓\n- Inside (Verified): [list with source weights]\n- Outside (Speculative): [list with risks]\n\n**5. MAP ≠ TERRITORY** ✓\n- Model expectation: [what design suggests]\n- Reality observation: [what actually happens]\n- Delta: [gap quantification]\n\n### Source Depletion Record\n\n**Internal Sources:**\n- Files read: [list]\n- Grep searches: [summary]\n- Git history: [relevant commits if applicable]\n- Tests executed: [if applicable]\n\n**External Sources:**\n- Official docs: [URLs with weights]\n- UX research: [URLs with weights]\n- Community sources: [URLs with weights]\n\n**Depletion Status:** 🟢 SATURATED / 🟡 PARTIAL / 🔴 INCOMPLETE\n\n### Evidence & Certainty Derivation\n\n| Claim | Source | Weight | Critical? | Force |\n|-------|--------|--------|-----------|-------|\n| [Claim 1] | [Source] | [0.XX] | YES/NO | [0.XX] |\n| [Claim 2] | [Source] | [0.XX] | YES/NO | [0.XX] |\n| ... | ... | ... | ... | ... |\n\n**Base Certainty:** ([sum of forces]) / [count] = [X.XX]%  \n**Penalties Applied:** [list or \"None\"] = [-X]%  \n**Final Derived Certainty:** **[XX]%**\n\n### Proposed Solutions\n\n**Option 1: [Name]**\n- Pros: [list]\n- Cons: [list]\n- Certainty Score: [XX]%\n- Verdict: ✅ APPROVED / ⚠️ CAUTION / ❌ FAILURE\n\n**Option 2: [Name]**\n- [same structure]\n\n[... for all options]\n\n### Recommendation\n\n**Primary:** [Option X - Name]  \n**Rationale:** [evidence-based justification]  \n**Implementation:** [brief technical approach]  \n**Risk Level:** [Minimal/Low/Medium/High]\n\n### TnR Checklist Status\n\n```\n☑ 1. INVERSION — [brief status]\n☑ 2. FIRST PRINCIPLES — [brief status]\n☑ 3. MULTI-ORDER EFFECTS — [brief status]\n☑ 4. CIRCLE OF CERTAINTY — [brief status]\n☑ 5. MAP ≠ TERRITORY — [brief status]\n☐/☑ 6. INTERNAL DEPLETION — [brief status]\n☐/☑ 7. EXTERNAL VERIFICATION — [brief status]\n☐/☑ 8-13. [continue for all 14 items]\n```\n\n### Final Verdict\n\n| Metric | Value |\n|--------|-------|\n| **Derived Certainty** | [XX]% |\n| **Threshold** | ≥95% |\n| **Status** | ✅ PASS / ❌ FAIL |\n| **Action** | PROCEED / SYSTEMIC FAILURE REPORT |\n\n**Outcome:** [Execute with Option X] OR [RIGOR FAILURE - gaps documented above]\n\n---\n```\n\n### Example: Minimal Format (when appropriate)\n\nFor less complex tasks, a condensed format is acceptable:\n\n```markdown\n---\n\n## TnR ABSOLUTE RIGOR: [Task Name]\n\n**Timestamp:** [YYYY-MM-DD HH:MM:SS]  \n**Models Forced:** Inv ✓ | FirstPrin ✓ | 3rdOrder ✓ | Certainty ✓ | TruthMap ✓  \n**Depletion:** Internal [files] + External [sources] → SATURATED  \n**Axiomatic Findings:** [1-2 sentence summary]  \n**Rigor Chain:** [N] claims | **[XX]%** Derived Certainty  \n**Failure Gaps:** [list or \"None\"]  \n**Recommendation:** [Option X] — [one sentence rationale]  \n**Verdict:** ✅ PROCEED / ❌ RIGOR FAILURE\n\n---\n```\n\n### Anti-Patterns (FORBIDDEN)\n\n❌ **DO NOT:**\n- Create separate artifact files (`tnr_analysis.md`, `rigor_report_[date].md`, etc.)\n- Write summary-only entries (\"Applied TnR, 96% certainty, see analysis file\")\n- Reference external files for TnR findings\n- Split analysis across multiple documents\n\n✅ **DO:**\n- Append full report to active session file\n- Include all evidence and reasoning inline\n- Make reports self-contained and auditable\n- Maintain chronological order in session file\n\n### Integration with Session Management\n\nWhen starting a new task that requires TnR:\n\n1. Create/identify session file: `.sessions/SESSION_[date]-[description].md`\n2. Add initial context and objective to session file\n3. Execute TnR analysis\n4. **Append complete TnR report to SAME session file** (using structure above)\n5. Continue with implementation/verification, logging to same session file\n\n**The session file becomes the complete, auditable record of all work, including rigorous analysis.**\n\n---\n\n## Absolute Operational Mandate\n\n1. **FORCE THE RIGOR:** No \"lite\" alternatives.\n2. **TOTAL DEPLETION:** Search until the vector yields no new data.\n3. **DERIVED ONLY:** Sentiment is forbidden. Use the Math.\n4. **95% OR FAILURE:** No proceeding on 94%.\n5. **CODE FIRST:** If the code wasn''t read, the research didn''t happen.\n\n**Rigor = Integrity. Speculation = Hallucination.**\n"},"lastSynced":"2026-03-08T02:05:39.596Z","agentAnalysis":{"suitability":{"en":"Ideal for Critical Project Agents requiring absolute certainty through cognitive labor and verification doctrine","zh":"适合需要绝对确定性通过认知劳动和验证原则的关键项目代理","ja":"絶対的な確実性を認知労働と検証原則を通じて必要とする重大プロジェクトエージェントに適しています","ko":"인지 노동 및 검증 교리를 통해絶対적인 확실성을 필요로 하는임계 프로젝트 에이전트에 적합합니다","es":"Ideal para Agentes de Proyectos Críticos que requieren certeza absoluta a través del trabajo cognitivo y la doctrina de verificación","fr":"Idéal pour les Agents de Projets Critiques nécessitant une certitude absolue grâce au travail cognitif et à la doctrine de vérification","de":"Ideal für kritische Projektagenten, die absolute Sicherheit durch kognitive Arbeit und Verifizierungslehre erfordern","pt":"Ideal para Agentes de Projetos Críticos que requerem certeza absoluta por meio de trabalho cognitivo e doutrina de verificação","ru":"Идеально для Критических Проектных Агентов, требующих абсолютной определенности посредством когнитивного труда и доктрины верификации","ar":"مثالية للوكلاء المشروع الحرجة التي تتطلب اليقين المطلق من خلال العمل الإدراكي والdoctrine التأكيد"},"recommendation":{"en":"Empowers agents to act as highest-possible-level specialists, ensuring certainty through rigorous cognitive labor, and adhering to a verification doctrine that eliminates residual uncertainty, leveraging concepts like absolute rigor in database reliability engineering or security assessments using protocols and methodologies specific to each domain","zh":"赋予代理以最高级别的专业知识，确保通过严格的认知劳动和遵循消除残余不确定性的验证原则，利用数据库可靠性工程或使用特定领域的协议和方法论进行安全评估等概念","ja":"エージェントに最高レベルの専門知識を与え、厳格な認知労働と、残留する不確実性を排除する検証原則に従うことで確実性を確保し、データベースの信頼性エンジニアリングや特定のドメインに固有のプロトコルや方法論を使用したセキュリティ評価などの概念を利用する","ko":"에이전트에게最高 수준의 전문 지식을 부여하여 엄격한 인지 노동과 잔여 불확실성을 제거하는 검증 교리를 준수함으로써 확실성을 보장하고, 데이터베이스 신뢰성 공학 또는 특정 도메인에 고유한 프로토콜 및 방법론을 사용한 보안 평가 등과 같은 개념을 활용함","es":"Habilita a los agentes para actuar como especialistas de nivel más alto posible, garantizando la certeza a través de un trabajo cognitivo riguroso y adherirse a una doctrina de verificación que elimina la incertidumbre residual, aprovechando conceptos como la rigidez absoluta en la ingeniería de confiabilidad de bases de datos o evaluaciones de seguridad que utilizan protocolos y metodologías específicas de cada dominio","fr":"Permet aux agents d''agir en tant que spécialistes de niveau le plus élevé possible, en garantissant la certitude grâce à un travail cognitif rigoureux et en adhérant à une doctrine de vérification qui élimine l''incertitude résiduelle, en exploitant des concepts comme la rigueur absolue dans l''ingénierie de la fiabilité des bases de données ou les évaluations de sécurité utilisant des protocoles et des méthodologies spécifiques à chaque domaine","de":"Ermächtigt Agenten, als höchstmögliche Spezialisten zu handeln, die Sicherheit durch strenges kognitives Arbeiten sicherzustellen und einer Verifizierungslehre zu folgen, die die verbleibende Unsicherheit eliminiert, indem Konzepte wie absolute Strenge in der Datenbankzuverlässigkeitstechnik oder Sicherheitsbewertungen unter Verwendung von Protokollen und Methoden, die für jeden Bereich spezifisch sind, genutzt werden","pt":"Habilita os agentes a atuarem como especialistas de nível mais alto possível, garantindo certeza por meio de trabalho cognitivo rigoroso e aderindo a uma doutrina de verificação que elimina a incerteza residual, aproveitando conceitos como rigor absoluto na engenharia de confiabilidade de banco de dados ou avaliações de segurança usando protocolos e metodologias específicas de cada domínio","ru":"Наделяет агентов возможностью действовать как специалисты самого высокого уровня, обеспечивая определенность посредством строгого когнитивного труда и соблюдения доктрины верификации, которая устраняет остаточную неопределенность, используя такие концепции, как абсолютная строгость в инженерии надежности баз данных или оценки безопасности с использованием протоколов и методологий, специфичных для каждого домена","ar":"تمكين الوكلاء من العمل كأعلى مستوى ممكن من المتخصصين، وضمان اليقين من خلال العمل الإدراكي القاسي، والامتثال لدستور التأكيد التي تقضي على عدم اليقين المتبقي، و利用 مفاهيم مثل القسوة المطلقة في هندسة موثوقية قاعدة البيانات أو التقييمات الأمنية باستخدام بروتوكولات و منهجيات محددة لكل مجال"},"useCases":{"en":["Acting as Senior Database Reliability Engineers for critical database projects","Operating as Red Team Leads for comprehensive security assessments","Ensuring absolute rigor in code reviews and validation for mission-critical applications"],"zh":["作为关键数据库项目的高级数据库可靠性工程师","作为综合安全评估的红队负责人","确保关键任务应用程序的代码审查和验证中的绝对严谨性"],"ja":["重大なデータベースプロジェクトのシニアデータベース可靠性エンジニアとしての役割","総合的なセキュリティ評価のためのレッドチームリード","ミッションクリティカルアプリケーションのコードレビューと検証における絶対的な厳格性の確保"],"ko":["임계 데이터베이스 프로젝트를 위한 시니어 데이터베이스 신뢰성 엔지니어로서의 역할","종합적인 보안 평가를 위한 레드 팀 리드","임무 임계 응용 프로그램의 코드 검토 및 검증에서 절대적인 엄격성을 보장"],"es":["Actuar como Ingenieros de Confiabilidad de Base de Datos Senior para proyectos de base de datos críticos","Operar como Líderes de Equipo Rojo para evaluaciones de seguridad comprehensivas","Garantizar la rigidez absoluta en las revisiones de código y la validación para aplicaciones de misión crítica"],"fr":["Agir en tant que Ingénieurs de Fiabilité de Base de Données Senior pour les projets de base de données critiques","Opérer en tant que Chefs d''Équipe Rouge pour les évaluations de sécurité complètes","Assurer la rigueur absolue dans les examens de code et la validation pour les applications de mission critique"],"de":["Als Senior-Datenbankzuverlässigkeitsingenieure für kritische Datenbankprojekte handeln","Als Rote-Team-Leiter für umfassende Sicherheitsbewertungen handeln","Absolute Strenge bei Code-Reviews und Validierung für kritische Anwendungen sicherstellen"],"pt":["Atuando como Engenheiros de Confiabilidade de Banco de Dados Sênior para projetos de banco de dados críticos","Operando como Líderes da Equipe Vermelha para avaliações de segurança abrangentes","Garantindo rigor absoluto em revisões de código e validação para aplicações críticas de missão"],"ru":["Действуя как Старшие Инженеры Надежности Баз Данных для критических проектов баз данных","Работая как Руководители Красной Команды для всесторонних оценок безопасности","Обеспечивая абсолютную строгость в проверке кода и валидации для приложений критической миссии"],"ar":["العمل كمهندسين موثوقية قاعدة البيانات الأقدم لمشاريع قاعدة البيانات الحرجة","العمل كقادة فريق احمر للتقديرات الأمنية الشاملة","ضمان القسوة المطلقة في مراجعة الكود والتحقق من صحة التطبيقات الحرجة للبعثة"]},"limitations":{"en":["Requires advanced cognitive labor capabilities","Demands adherence to a strict verification doctrine","May necessitate domain-specific knowledge for optimal performance"],"zh":["需要高级认知劳动能力","要求严格遵守验证原则","可能需要特定领域的知识以实现最佳性能"],"ja":["高度な認知労働能力が必要","厳格な検証原則の遵守が求められる","最適なパフォーマンスを実現するために、特定のドメインに特有の知識が必要になる可能性がある"],"ko":["고급 인지 노동 능력이 필요","엄격한 검증 교리의 준수가 요구됨","최적의 성능을 달성하기 위해 특정 도메인에 고유한 지식이 필요할 수 있음"],"es":["Requiere capacidades de trabajo cognitivo avanzadas","Exige la adhesión a una estricta doctrina de verificación","Puede necesitar conocimientos específicos del dominio para un rendimiento óptimo"],"fr":["Nécessite des capacités de travail cognitif avancées","Exige l''adhésion à une doctrine de vérification stricte","Peut nécessiter des connaissances spécifiques du domaine pour une performance optimale"],"de":["Erfordert fortgeschrittene kognitive Arbeitsfähigkeiten","Fordert die Einhaltung einer strengen Verifizierungslehre","Kann domänen-spezifische Kenntnisse für optimale Leistung erfordern"],"pt":["Requer capacidades de trabalho cognitivo avançadas","Exige aderência a uma doutrina de verificação estrita","Pode necessitar de conhecimento específico de domínio para desempenho ótimo"],"ru":["Требует передовых возможностей когнитивного труда","Требует соблюдения строгой доктрины верификации","Может потребовать знаний, специфичных для домена, для оптимальной производительности"],"ar":["يتطلب قدرات عمل إدراكي متقدمة","يتطلب الالتزام بدستور التأكيد القاسي","قد يحتاج إلى معرفة محددة بالمجال لأداء مثالي"]},"version":4},"contentHash":"b921d3012f62f09555425e3eeef61910a946e77cf37ac3ade3fc37a1c9188a9a","qualityScore":45}');
