INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chongdashu/phaserjs-oakwoods/playwright-testing', 'playwright-testing', 'chongdashu', 'phaserjs-oakwoods', 'community', 'playwright-testing chongdashu phaserjs-oakwoods community playwright-testing enables reliable confidence in frontend testing by making apps observable and eliminating nondeterminism. It benefits developers seeking to maximize signal and minimize test failures. Playwright Testing 是一个用于前端测试的工具，帮助开发者构建可靠的测试，最大化信号，减少噪音 Playwright Testing は、フロントエンドテストを構築するためのツールで、信頼性の高いテストを実現します Playwright Testing은 프론트엔드 테스트를 구축하는 데 도움을 주는 도구로, 신뢰할 수 있는 테스트를 구축하는 데 도움이 됩니다 Playwright-testing es una implementación para pruebas frontend que permite maximizar la confianza y minimizar errores Playwright-testing est une implémentation pour les tests frontend qui permet de maximiser la confiance et de minimiser les erreurs Playwright-testing ist eine Implementierung für Frontend-Tests, die die Zuverlässigkeit maximiert und Fehler minimiert O playwright-testing é uma implementação de teste de frontend que permite aos desenvolvedores criar testes rápidos e confiáveis, maximizando a confiança por minuto Playwright-testing - это реализация фронтенд тестирования, которая позволяет разработчикам создавать быстрые и надёжные тесты, максимизируя уверенность в минуту playwright-testing هو تطبيق لاختبار واجهة المستخدم الأمامية يسمح للمطورين بإنشاء اختبارات سريعة وموثوقة، وتحقيق أقصى قدر من الثقة في الدقيقة how to use playwright-testing playwright-testing setup guide playwright-testing alternative playwright-testing vs jest playwright-testing install what is playwright-testing playwright-testing tutorial playwright-testing examples frontend testing with playwright-testing playwright-testing best practices Playwright Testing 前端测试 自动化测试 可靠的测试 最大化信号 减少噪音 AIエージェント 前端测试工具 Enables safe refactors by choosing the right test layer Makes the app observable for actionable failures Eliminates nondeterminism to minimize test failures Maximizes signal to ensure reliable test results Helps identify user risk coverage for money, progression, auth, and data loss Supports test reliability through philosophy of Confidence Per Minute playwright-testing is a vibe-coded implementation of an RPG platformer that enables reliable frontend testing through observability and nondeterminism elimination.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('a2f0/tearleads/update-everything', 'community', 'a2f0', 'tearleads', 'a2f0/tearleads', 'update-everything', 0, 0, 45, '2026-03-08T01:57:15.390Z', '2026-03-08T02:06:01.181Z', '4ee2d783755f16d42f0bb514fac31807f27f1adef4cb11714f815fa0940ef7f9', '{"id":"a2f0/tearleads/update-everything","name":"update-everything","description":{"en":"The update-everything skill updates all dependencies in the workspace and verifies linting, builds, and tests. It benefits developers by streamlining their workflow.","zh":"Update Everything 是一个自动更新依赖和代码的工具，确保代码质量和稳定性","ja":"Update Everything は依存関係とコードを自動更新するツールで、コード品質と安定性を確保します","ko":"Update Everything는 의존성 및 코드를 자동으로 업데이트하여 코드 품질 및 안정성을 보장하는 툴입니다","es":"Update-everything es una herramienta que actualiza todas las dependencias en el workspace y verifica linting, builds y tests","fr":"Update-everything est un outil qui met à jour toutes les dépendances dans l''espace de travail et vérifie la linting, les builds et les tests","de":"Update-Everything ist ein Tool, das alle Abhängigkeiten im Workspace aktualisiert und Linting, Builds und Tests überprüft","pt":"O update-everything é uma ferramenta que atualiza todas as dependências no workspace e verifica linting, builds e testes","ru":"Update-everything — это инструмент, который обновляет все зависимости в рабочем пространстве и проверяет линтинг, сборку и тесты","ar":"update-everything هو أداة تحديث جميع التبعيات في مساحة العمل وتحقق من لينTING و 빌د واختبارات"},"seo":{"title":{"en":"update-everything: Automated Dependency Updates for AI Ag...","zh":"Update Everything 设置指南：自动更新依赖和代码","ja":"Update Everything Setup Guide: 依存関係とコードの自動更新","ko":"Update Everything 설정 가이드: 의존성 및 코드 자동 업데이트","es":"Guía de configuración de update-everything para desarroll...","fr":"Mise à jour de tout avec update-everything : Guide de dém...","de":"Update-Everything-Setup: Leitfaden für Entwickler","pt":"Guia de Configuração do update-everything para Desenvolve...","ru":"Настройка update-everything: Руководство для Разработчико...","ar":"دليل إعداد update-everything لمنصة آداة الذكاء الاصطناعي"},"description":{"en":"Discover how update-everything simplifies dependency management. Learn to automate updates, linting, and testing with this AI agent skill. Get started now!","zh":"学习如何使用 Update Everything 自动更新依赖和代码，确保代码质量和稳定性","ja":"Update Everything を使用して依存関係とコードを自動更新し、コード品質と安定性を確保する方法を学びます","ko":"Update Everything를 사용하여 의존성 및 코드를 자동으로 업데이트하고 코드 품질 및 안정성을 보장하는 방법을 배웁니다","es":"Aprende a utilizar update-everything para actualizar dependencias y verificar linting, builds y tests en tu workspace","fr":"Découvrez comment mettre à jour vos dépendances et vérifier la linting, les builds et les tests avec update-everything","de":"Erfahren Sie, wie Sie update-everything verwenden, um Abhängigkeiten zu aktualisieren und Linting, Builds und Tests zu überprüfen","pt":"Aprenda a utilizar o update-everything para atualizar dependências e verificar linting, builds e testes em seu workspace","ru":"Узнайте, как использовать update-everything для обновления зависимостей и проверки линтинга, сборки и тестов в вашем рабочем пространстве ИИ Агентов","ar":"تعلم كيفية استخدام update-everything لتحديث التبعيات وتحقق من لينTING و 빌د واختبارات في مساحة العمل الخاصة بك لآداة الذكاء الاصطناعي"},"definition":{"en":"update-everything is a skill that automates the process of updating dependencies, checking linting, builds, and tests, and capturing warnings and deprecations.","zh":"Update Everything 是一个自动更新依赖和代码的工具","ja":"Update Everything は依存関係とコードを自動更新するツールです","ko":"Update Everything는 의존성 및 코드를 자동으로 업데이트하는 툴입니다","es":"Update-everything es una herramienta de línea de comandos que actualiza dependencias y verifica la integridad del código","fr":"Update-everything est un outil en ligne de commande qui met à jour les dépendances et vérifie l''intégrité du code","de":"Update-Everything ist ein Kommandozeilen-Tool, das Abhängigkeiten aktualisiert und die Code-Integrität überprüft","pt":"O update-everything é uma ferramenta de atualização de dependências","ru":"Update-everything — это инструмент обновления зависимостей","ar":"update-everything هو أداة تحديث التبعيات"},"features":{"en":["Updates all dependencies in the workspace, especially under `packages/`","Verifies linting, builds, and tests using scripts like `./scripts/updateEverything.sh`","Captures and summarizes warnings and deprecations","Enforces a branch guard to prevent updates on `main` or `master` branches by default","Allows override of branch guard with `SKIP_BRANCH_GUARD=1` for intentional updates"],"zh":["自动更新依赖","代码linting和builds检查","测试和警告/过期检查","支持git分支管理","CLI脚本支持"],"ja":["依存関係の自動更新","コードのlintingとbuildsの確認","テストと警告/廃止の確認","gitブランチ管理のサポート","CLIスクリプトのサポート"],"ko":["의존성 자동 업데이트","코드 linting 및 builds 확인","테스트 및 경고/ 폐기 확인","git 브랜치 관리 지원","CLI 스크립트 지원"],"es":["Actualiza dependencias en el workspace","Verifica linting, builds y tests","Captura y resume advertencias y deprecaciones","Soporte para scripts de actualización personalizados","Integración con Git para verificar el estado del repositorio"],"fr":["Met à jour les dépendances dans l''espace de travail","Vérifie la linting, les builds et les tests","Capture et résume les avertissements et les dépréciations","Prise en charge des scripts de mise à jour personnalisés","Intégration avec Git pour vérifier l''état du référentiel"],"de":["Aktualisiert Abhängigkeiten im Workspace","Überprüft Linting, Builds und Tests","Erfasst und fasst Warnungen und Veraltungen zusammen","Unterstützung für benutzerdefinierte Update-Skripte","Integration mit Git zum Überprüfen des Repository-Zustands"],"pt":["Atualiza todas as dependências no workspace","Verifica linting, builds e testes","Captura e resume warnings e depreciações","Executa script de atualização via CLI","Verifica status do git antes de executar atualizações"],"ru":["Обновляет все зависимости в рабочем пространстве","Проверяет линтинг, сборку и тесты","Захватывает и суммирует предупреждения и устаревания","Выполняет скрипт обновления через CLI","Проверяет статус git перед выполнением обновлений"],"ar":["تحديث جميع التبعيات في مساحة العمل","تحقق من لينTING و 빌드 واختبارات","التقاط وتلخيص تحذيرات وتراجع","تشغيل سكريبت تحديث عبر CLI","تحقق من حالة git قبل تشغيل التحديثات"]},"keywords":{"en":["how to use update-everything","update-everything setup guide","update-everything alternative","update-everything vs dependency managers","automated dependency updates","AI agent skills for developers","update-everything install","dependency management with update-everything"],"zh":["Update Everything","自动更新依赖","代码质量","代码稳定性","git分支管理","CLI脚本","AIエージェント","代码自动更新"],"ja":["Update Everything","依存関係の自動更新","コード品質","コード安定性","gitブランチ管理","CLIスクリプト","AIエージェント","コード自動更新"],"ko":["Update Everything","의존성 자동 업데이트","코드 품질","코드 안정성","git 브랜치 관리","CLI 스크립트","AI 에이전트","코드 자동 업데이트"],"es":["update-everything","herramientas de desarrollo","actualización de dependencias","verificación de linting","verificación de builds","verificación de tests","Agentes de IA","Herramientas de línea de comandos"],"fr":["update-everything","outils de développement","mise à jour de dépendances","vérification de linting","vérification de builds","vérification de tests","Agents IA","Outils en ligne de commande"],"de":["update-everything","Entwicklungstools","Aktualisierung von Abhängigkeiten","Überprüfung von Linting","Überprüfung von Builds","Überprüfung von Tests","KI-Agents","Kommandozeilen-Tools"],"pt":["update-everything","atualização de dependências","linting","builds","testes","CLI","git","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["update-everything","обновление зависимостей","линтинг","сборка","тесты","CLI","git","разработка программного обеспечения","инструменты разработки ИИ Агентов"],"ar":["update-everything","تحديث التبعيات","لينTING","بیلد","اختبارات","CLI","git","تطوير البرمجيات","أدوات تطوير آداة الذكاء الاصطناعي"]}},"owner":"a2f0","repo":"tearleads","repoPath":"a2f0/tearleads","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.390Z","topics":[],"category":"community","skillMd":{"name":"update-everything","description":"Update all dependencies across the repo (including Ruby/iOS/Android), fix lint/type/test issues, and prepare the PR for merge.","bodyPreview":"# Update Everything\n\nUpdate all dependencies in the workspace (especially under `packages/`) and verify linting, builds, and tests. Capture and summarize warnings/deprecations.\n\n## Preflight\n\n- Confirm you are not on `main`; create/switch branches before running updates.\n- `./scripts/updateEverything.sh` now enforces a branch guard and exits on `main`/`master` by default. Override only when intentional: `SKIP_BRANCH_GUARD=1`.\n- Start from a clean `git status` or note existing changes so you do n","body":"# Update Everything\n\nUpdate all dependencies in the workspace (especially under `packages/`) and verify linting, builds, and tests. Capture and summarize warnings/deprecations.\n\n## Preflight\n\n- Confirm you are not on `main`; create/switch branches before running updates.\n- `./scripts/updateEverything.sh` now enforces a branch guard and exits on `main`/`master` by default. Override only when intentional: `SKIP_BRANCH_GUARD=1`.\n- Start from a clean `git status` or note existing changes so you do not clobber them.\n- `mise` must be available on PATH; if missing, stop and report the blocker.\n- Run `mise install node` to match `.nvmrc`.\n- Never install or update Node with Homebrew in this workflow.\n- Ensure platform tooling is available (pnpm, bundler, CocoaPods, Android SDK). If optional platform tooling is missing, the script now skips that phase and reports it in a warning summary.\n\n## Workflow\n\nUse the shared script to perform the standard update flow:\n\n```bash\n./scripts/updateEverything.sh\n```\n\nThis now includes `mise install node` (hard-fails if `mise` is unavailable) and an automatic toolchain sync step before dependency updates.\n\nOptional toggles (set to `1` as needed): `SKIP_BRANCH_GUARD`, `SKIP_TOOLCHAIN_SYNC`, `SKIP_TOOLCHAIN_NODE`, `SKIP_TOOLCHAIN_ANDROID`, `SKIP_RUBY`, `SKIP_CAP_SYNC`, `SKIP_POD_CLEAN`, `SKIP_MAESTRO`, `SKIP_TESTS`, `SKIP_BUILD`, `SKIP_LINT`, `SKIP_UPDATE`, `SKIP_INSTALL`, `UPGRADE_CODEX`.\n\nAdditional toolchain controls:\n\n- `TOOLCHAIN_SYNC_MAX_ANDROID_JUMP=<n>`: limit Android API-level bump in one run (default: `1`)\n- `TOOLCHAIN_SYNC_ALLOW_RUNTIME_MISMATCH=1`: continue even when active `node` runtime differs from updated `.nvmrc`\n\nScript exits early on dependency hygiene checks—fix then rerun:\n\n- Caret/tilde ranges in `dependencies`/`devDependencies` are blocked. Pin versions where reported.\n- Pinned `peerDependencies` must match `packages/client/package.json` versions. Align the peer versions to the client version before rerunning.\n- `@capacitor/*` versions in `packages/client/package.json` must match the resolved versions in `packages/client/ios/App/Podfile.lock` (when present). Align and rerun sync/pod install if mismatched.\n\n## Automatic Toolchain Sync\n\n`./scripts/updateEverything.sh` runs `./scripts/syncToolchainVersions.sh --apply` before package updates:\n\n1. **Node/Electron**: reads `electron` from `packages/client/package.json`, resolves its bundled Node version from `https://releases.electronjs.org/releases.json`, then aligns:\n   - `.nvmrc`\n   - `package.json` `engines.node`\n2. **Android SDK levels**: reads latest stable platform API from `https://dl.google.com/android/repository/repository2-1.xml`, then bumps:\n   - `packages/client/android/variables.gradle` `compileSdkVersion`\n   - `packages/client/android/variables.gradle` `targetSdkVersion`\n3. **Ansible playbooks**: uses the Node major version from step 1 (or falls back to `.nvmrc`) to align:\n   - `ansible/playbooks/tuxedo.yml` `nodejs_major_version`\n   - `ansible/playbooks/developerLaptop.yml` `nodejs_major_version`\n\nGuardrails:\n\n- Android bumps are capped by `TOOLCHAIN_SYNC_MAX_ANDROID_JUMP` to avoid large blind jumps.\n- If Node files are updated and active runtime does not match `.nvmrc`, the toolchain script exits so you can run `mise install node` and rerun.\n\n## Fastlane and Ruby Gems Update\n\nFastlane and other Ruby gems should be updated as part of the dependency update process:\n\n```bash\ncd packages/client\nbundle update fastlane\n```\n\nTo update all gems (not just fastlane):\n\n```bash\ncd packages/client\nbundle update\n```\n\n**When to update fastlane**: Always check for fastlane updates when:\n\n- Running a full dependency update\n- Encountering App Store Connect API errors\n- Seeing deprecation warnings from fastlane actions\n\n**Verify the update**: After updating, run a dry-run to ensure fastlane still works:\n\n```bash\ncd packages/client\nbundle exec fastlane ios build_release --dry_run\n```\n\n**Important**: The `Gemfile.lock` must be committed along with other dependency changes.\n\n## Node.js Version Alignment (Electron)\n\nNode alignment is now automatic via toolchain sync. For manual fallback, when updating `electron`, align Node.js versions:\n\n1. Check Electron''s bundled Node.js version at <https://releases.electronjs.org/>.\n2. Update `.nvmrc` to match (e.g., `v22.21.1`).\n3. Update `engines.node` in `package.json` to the same major range (e.g., `>=22.21.1 <23`).\n\n## Gradle Wrapper Update\n\nOnly if a new Gradle version is available:\n\n1. Edit `packages/client/android/gradle/wrapper/gradle-wrapper.properties`.\n2. Update `distributionUrl` (e.g., `gradle-8.12-all.zip`).\n3. Delete the existing JAR: `rm packages/client/android/gradle/wrapper/gradle-wrapper.jar`.\n4. Run `./packages/client/scripts/downloadGradleWrapper.sh`.\n5. Validate: `cd packages/client/android && ./gradlew assembleDebug`.\n\n## Native Module Rebuilds\n\nWhen updating packages with native Node.js addons (e.g., `better-sqlite3-multiple-ciphers`), they may need rebuilding. Symptoms:\n\n```text\nError: The module ''better_sqlite3.node'' was compiled against NODE_MODULE_VERSION 143.\nThis version of Node.js requires NODE_MODULE_VERSION 127.\n```\n\nFix by rebuilding the module:\n\n```bash\ncd packages/cli\nnpm rebuild better-sqlite3-multiple-ciphers\n```\n\nThe client package runs `electron-rebuild` via postinstall, but CLI uses system Node and may need manual rebuild.\n\n## Biome Schema Migration\n\nWhen biome is updated, migrate the schema:\n\n```bash\npnpm biome migrate --write\n```\n\n## Coverage Threshold Adjustments\n\nDependency updates can cause pre-push hook failures due to coverage threshold mismatches. This happens when:\n\n- New code was added without tests (thresholds drift below configured values)\n- Coverage exclusion patterns changed\n- Test file organization changed\n\n**Symptoms**: Pre-push hook fails with \"Coverage threshold not met\" even though no test code changed.\n\n**Fix approach**:\n\n1. **Exclude untested modules** from coverage in `vitest.config.ts`:\n\n   ```typescript\n   coverage: {\n     exclude: [\n       ''src/**/*.test.ts'',\n       ''src/test/**/*'',\n       ''src/untested-module/**/*''  // Add exclusions for untested code\n     ]\n   }\n   ```\n\n2. **Lower thresholds** to match actual coverage if exclusions aren''t appropriate.\n\n3. **Add TODO comments** explaining the reduction - Gemini will request this:\n\n   ```typescript\n   // TODO: Increase coverage thresholds back to X% by adding tests\n   // for <specific modules that need tests>\n   thresholds: {\n     statements: 85,\n     branches: 75,\n     functions: 90,\n     lines: 85\n   }\n   ```\n\n**Important**: Gemini code review will flag threshold reductions without explanation. Adding TODO comments preemptively satisfies this requirement and documents technical debt.\n\n## pdfjs-dist and react-pdf Version Coupling\n\n**CRITICAL**: `pdfjs-dist` must match the version expected by `react-pdf`. Web E2E tests will fail if versions mismatch.\n\n**Guardrails in place:**\n\n1. **Dependabot grouping** (`.github/dependabot.yml`): `react-pdf` and `pdfjs-dist` are grouped so Dependabot proposes them together.\n2. **CI parity check** (`scripts/checks/checkPdfVersionParity.sh`): Fails the guardrails job if the declared `pdfjs-dist` version doesn''t match what `react-pdf` expects (parsed from the lockfile).\n\n```bash\n# Quick manual check\n./scripts/checks/checkPdfVersionParity.sh\n```\n\nIf versions differ, revert pdfjs-dist to match react-pdf''s dependency:\n\n```bash\n# Example: if react-pdf expects 5.4.296 but pnpm updated to 5.4.624\npnpm --filter @tearleads/client add pdfjs-dist@5.4.296\n```\n\nThe update script should NOT update pdfjs-dist independently - always revert to react-pdf''s expected version.\n\n## Researching Breaking Changes\n\nAfter updates, review changelogs for major version bumps:\n\n1. **Check pnpm output** for deprecated subdependencies (transitive - usually not actionable)\n2. **Review GitHub releases** for direct deps:\n   - Capacitor plugins: <https://github.com/ionic-team/capacitor-plugins/releases>\n   - Biome: <https://github.com/biomejs/biome/releases>\n   - pdfjs-dist: <https://github.com/mozilla/pdf.js/releases>\n   - i18next: <https://github.com/i18next/i18next/releases>\n3. **Document deprecations** in the PR for future reference\n\n## Known Acceptable Warnings\n\nThese warnings are expected and do not require action:\n\n- **electron-builder peer dependency mismatches**: Internal conflicts between `dmg-builder`/`electron-builder-squirrel-windows` tracked upstream\n- **Deprecated transitive dependencies**: `glob`, `rimraf`, `inflight` etc. are deep deps resolved when upstream updates\n\n## Drizzle-ORM Peer Dependency Conflicts\n\nWhen `drizzle-orm` is used across multiple packages, its optional peer dependencies (like `sql.js`) can resolve to different versions. This causes TypeScript errors like:\n\n```text\nTypes have separate declarations of a private property ''shouldInlineParams''.\nType ''SQL<unknown>'' is not assignable to type ''SQL<unknown>''.\n```\n\n**Diagnosis**: Run `pnpm why sql.js --recursive` to see version mismatches.\n\n**Fix**: Add a pnpm override in root `package.json`:\n\n```json\n\"pnpm\": {\n  \"overrides\": {\n    \"sql.js\": \"1.14.0\"\n  }\n}\n```\n\nThen run `pnpm install` to apply.\n\n## Known Flaky CI Issues\n\nSome CI failures are transient infrastructure issues:\n\n### Android Instrumented Tests Packaging\n\n`capacitor-community-sqlite:packageDebugAndroidTest` may fail with `PackageAndroidArtifact$IncrementalSplitterRunnable` error. **Fix**: Rerun workflow (Gradle cache issue).\n\n### PDF Worker E2E Tests\n\nPDF loading tests may timeout after pdfjs-dist updates (shows \"Loading...\" instead of \"Page 1 of\"). **Fix**: Check for version mismatch with react-pdf - see \"pdfjs-dist and react-pdf Version Coupling\" section.\n\n### iOS Maestro \"App crashed or stopped\" Across Random Flows\n\niOS Maestro may fail with:\n\n```text\nApp crashed or stopped while executing flow\n```\n\nThe failing flow can vary (`database-reset-setup`, `sync-login-landscape-keyboard`, `orphan-cleanup`, etc.). In `maestro.log`, this often appears as:\n\n```text\nXCTestDriver request failed ... \"Application com.tearleads.app is not running\"\n```\n\nimmediately after `Launch app \"com.tearleads.app\" with clear state`.\n\n**Fix**:\n\n1. Rerun only the failed iOS Maestro workflow/job.\n2. If `CI Gate` already failed due to that first attempt, rerun `CI Gate` after the iOS rerun is green.\n\n## Warnings/Deprecations\n\nCollect warnings/deprecations from `pnpm`, bundler, CocoaPods, Gradle, and test runs. Summarize them in the final response along with any required follow-ups.\n\n## Finish\n\n- Review changes with `git status` and `git diff`.\n- **Verify `packages/client/ios/App/Podfile.lock` is staged** if iOS dependencies changed (the script regenerates it via `pod install`).\n- Commit and push using `$commit-and-push`.\n- Prepare the PR for merging using `$enter-merge-queue`.\n\n## Token Efficiency\n\nThe update script and its sub-commands produce thousands of lines of output. Suppress stdout where only the exit code matters:\n\n```bash\n# Suppress verbose output - only show errors\n./scripts/updateEverything.sh >/dev/null\n\n# Or capture to file for debugging later\n./scripts/updateEverything.sh > /tmp/update.log 2>&1\n```\n\nWhen running individual commands manually:\n\n```bash\npnpm install >/dev/null\npnpm build >/dev/null\npnpm test:coverage >/dev/null\nbundle install >/dev/null\npod install --repo-update >/dev/null\n./gradlew assembleDebug >/dev/null\n```\n\nOn failure, stderr is preserved. Re-run without suppression to debug.\n"},"lastSynced":"2026-03-08T02:06:01.181Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined dependency updates and validation","zh":"非常适合需要简化依赖更新和验证的开发代理","ja":"開発エージェントが依存関係の更新と検証を効率化する必要がある場合に最適","ko":"의존성 업데이트와 검증을 간소화해야 하는 개발 에이전트에게 적합","es":"Perfecto para Agentes de Desarrollo que necesitan actualizaciones de dependencias y validación optimizadas","fr":"Parfait pour les agents de développement nécessitant des mises à jour de dépendances et une validation optimisées","de":"Perfekt für Entwicklungssagenten, die optimierte Abhängigkeitsupdates und -validierung benötigen","pt":"Perfeito para Agentes de Desenvolvimento que precisam de atualizações de dependências e validação simplificadas","ru":"Идеально подходит для агентов разработки, которым необходимы упрощенные обновления зависимостей и проверка","ar":"مثالي للعملاء النمطية الذين يحتاجون إلى تحديثات зависимости ومصادقة مبسطة"},"recommendation":{"en":"Empowers agents to update all dependencies in the workspace, verify linting, builds, and tests, and capture warnings and deprecations using scripts like `updateEverything.sh`, ensuring a clean `git status` and proper branch management","zh":"赋予代理更新工作空间中的所有依赖项，验证linting、构建和测试，并使用诸如`updateEverything.sh`的脚本捕获警告和弃用，确保干净的`git status`和适当的分支管理","ja":"エージェントがワークスペース内のすべての依存関係を更新し、linting、ビルド、テストを検証し、`updateEverything.sh`などのスクリプトを使用して警告や非推奨事項をキャプチャし、クリーンな`git status`と適切なブランチ管理を確保する","ko":"에이전트가 작업 공간의 모든 의존성을 업데이트하고, 린팅, 빌드 및 테스트를 검증하며, `updateEverything.sh`와 같은 스크립트를 사용하여 경고와 사용 중단을 캡처하여 깔끔한 `git status`와 적절한 브랜치 관리를 보장","es":"Habilita a los agentes a actualizar todas las dependencias en el espacio de trabajo, verificar la limpieza, las compilaciones y las pruebas, y capturar advertencias y deprecaciones utilizando scripts como `updateEverything.sh`, asegurando un estado limpio de `git status` y una gestión de ramas adecuada","fr":"Permet aux agents de mettre à jour toutes les dépendances dans l''espace de travail, de vérifier la mise en page, les constructions et les tests, et de capturer les avertissements et les dépréciations en utilisant des scripts comme `updateEverything.sh`, en garantissant un état de `git status` propre et une gestion de branches appropriée","de":"Ermöglicht es Agenten, alle Abhängigkeiten im Arbeitsbereich zu aktualisieren, die Formatierung, Builds und Tests zu überprüfen und Warnungen und Veraltungen mithilfe von Skripten wie `updateEverything.sh` zu erfassen, um einen sauberen `git status` und eine ordnungsgemäße Verwaltung von Branches sicherzustellen","pt":"Habilita os agentes a atualizar todas as dependências no espaço de trabalho, verificar linting, compilações e testes e capturar avisos e depreciações usando scripts como `updateEverything.sh`, garantindo um `git status` limpo e gerenciamento de branch adequado","ru":"Наделяет агентов возможностью обновлять все зависимости в рабочем пространстве, проверять линтинг, сборки и тесты, и захватывать предупреждения и устаревшие функции с помощью скриптов, таких как `updateEverything.sh`, обеспечивая чистый `git status` и правильное управление ветками","ar":"تمكين العملاء من تحديث جميع التبعيات في مساحة العمل، و التحقق من لينتينج و بناء واختبارات، و 捕获 تحذيرات و إهمال باستخدام سكريبتات مثل `updateEverything.sh`، و ضمان حالة جيت نظيفة و إدارة فرع مناسبة"},"useCases":{"en":["Automating dependency updates across multiple packages","Validating builds and tests for workspace consistency","Debugging warnings and deprecations in dependencies"],"zh":["跨多个包自动更新依赖项","验证构建和测试以确保工作空间的一致性","调试依赖项中的警告和弃用"],"ja":["複数のパッケージの依存関係を自動更新する","ビルドとテストを検証してワークスペースの一貫性を確保する","依存関係の警告や非推奨事項をデバッグする"],"ko":["여러 패키지의 의존성을 자동으로 업데이트","빌드 및 테스트를 검증하여 작업 공간의 일관성을 보장","의존성의 경고 및 사용 중단을 디버그"],"es":["Automatización de actualizaciones de dependencias en varios paquetes","Validación de compilaciones y pruebas para la coherencia del espacio de trabajo","Depuración de advertencias y deprecaciones en dependencias"],"fr":["Automatisation des mises à jour de dépendances sur plusieurs packages","Validation des constructions et des tests pour la cohérence de l''espace de travail","Débogage des avertissements et des dépréciations dans les dépendances"],"de":["Automatisierung von Abhängigkeitsupdates über mehrere Pakete hinweg","Validierung von Builds und Tests für die Konsistenz des Arbeitsbereichs","Fehlerbehebung von Warnungen und Veraltungen in Abhängigkeiten"],"pt":["Automatizar atualizações de dependências em vários pacotes","Validar compilações e testes para consistência do espaço de trabalho","Depurar avisos e depreciações em dependências"],"ru":["Автоматизировать обновления зависимостей в нескольких пакетах","Проверять сборки и тесты для согласованности рабочего пространства","Отладить предупреждения и устаревшие функции в зависимостях"],"ar":["توفير تحديثات تبعية في حزم متعددة","التحقق من بناء واختبارات لتسلسل مساحة العمل","تصحيح تحذيرات و إهمال في التبعيات"]},"limitations":{"en":["Requires a non-main branch to operate","Needs a clean git status or noted existing changes","Exits on main/master branch by default unless overridden with SKIP_BRANCH_GUARD=1"],"zh":["需要一个非主分支来操作","需要一个干净的git状态或已知的现有更改","默认情况下在主/主分支上退出，除非使用SKIP_BRANCH_GUARD=1覆盖"],"ja":["操作するにはメイン以外のブランチが必要","クリーンなGit状態または既知の既存の変更が必要","デフォルトでメイン/マスター ブランチで終了するが、SKIP_BRANCH_GUARD=1で上書き可能"],"ko":["작동하려면 메인以外의 브랜치가 필요","깔끔한 Git 상태 또는 알려진 기존 변경이 필요","기본적으로 메인/마스터 브랜치에서 종료하지만, SKIP_BRANCH_GUARD=1로 재정의할 수 있음"],"es":["Requiere una rama que no sea principal para operar","Necesita un estado limpio de git o cambios existentes anotados","Sale de la rama principal o maestra por defecto a menos que se anule con SKIP_BRANCH_GUARD=1"],"fr":["Nécessite une branche non principale pour fonctionner","A besoin d''un état de git propre ou de changements existants notés","Sortie de la branche principale ou maîtresse par défaut à moins que cela ne soit contourné avec SKIP_BRANCH_GUARD=1"],"de":["Benötigt einen nicht primären Branch, um zu funktionieren","Benötigt einen sauberen Git-Status oder notierte vorhandene Änderungen","Beendet den primären oder Master-Branch standardmäßig, sofern nicht mit SKIP_BRANCH_GUARD=1 überlagert"],"pt":["Exige uma branch não principal para operar","Necessita de um `git status` limpo ou alterações existentes anotadas","Sai da branch principal por padrão, a menos que substituído com SKIP_BRANCH_GUARD=1"],"ru":["Требует непосновной ветки для работы","Требует чистого `git status` или существующих изменений с заметками","Выходит из основной ветки по умолчанию, если не переопределено с SKIP_BRANCH_GUARD=1"],"ar":["يتطلب فرع غير رئيسي للتشغيل","يحتاج إلى حالة جيت نظيفة أو تغييرات موجودة محددة","يخرج من الفرع الرئيسي افتراضيًا،除非 يتم استبداله ب SKIP_BRANCH_GUARD=1"]},"version":4},"contentHash":"4ee2d783755f16d42f0bb514fac31807f27f1adef4cb11714f815fa0940ef7f9","qualityScore":45}');
