INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('a2f0/tearleads/update-everything', 'update-everything', 'a2f0', 'tearleads', 'community', 'update-everything a2f0 tearleads community The update-everything skill updates all dependencies in the workspace and verifies linting, builds, and tests. It benefits developers by streamlining their workflow. Update Everything 是一个自动更新依赖和代码的工具，确保代码质量和稳定性 Update Everything は依存関係とコードを自動更新するツールで、コード品質と安定性を確保します Update Everything는 의존성 및 코드를 자동으로 업데이트하여 코드 품질 및 안정성을 보장하는 툴입니다 Update-everything es una herramienta que actualiza todas las dependencias en el workspace y verifica linting, builds y tests Update-everything est un outil qui met à jour toutes les dépendances dans l''espace de travail et vérifie la linting, les builds et les tests Update-Everything ist ein Tool, das alle Abhängigkeiten im Workspace aktualisiert und Linting, Builds und Tests überprüft O update-everything é uma ferramenta que atualiza todas as dependências no workspace e verifica linting, builds e testes Update-everything — это инструмент, который обновляет все зависимости в рабочем пространстве и проверяет линтинг, сборку и тесты update-everything هو أداة تحديث جميع التبعيات في مساحة العمل وتحقق من لينTING و 빌د واختبارات how to use update-everything update-everything setup guide update-everything alternative update-everything vs dependency managers automated dependency updates AI agent skills for developers update-everything install dependency management with update-everything Update Everything 自动更新依赖 代码质量 代码稳定性 git分支管理 CLI脚本 AIエージェント 代码自动更新 Updates all dependencies in the workspace, especially under `packages/` Verifies linting, builds, and tests using scripts like `./scripts/updateEverything.sh` Captures and summarizes warnings and deprecations Enforces a branch guard to prevent updates on `main` or `master` branches by default Allows override of branch guard with `SKIP_BRANCH_GUARD=1` for intentional updates update-everything is a skill that automates the process of updating dependencies, checking linting, builds, and tests, and capturing warnings and deprecations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aizhimou/pigeon-pod/requirements-analysis', 'community', 'aizhimou', 'pigeon-pod', 'aizhimou/pigeon-pod', 'requirements-analysis', 0, 0, 45, '2026-03-08T01:57:15.393Z', '2026-03-08T02:06:15.755Z', 'b73f74282df21ce869477991d072a637711dfc98cc2775d1f59372486c4a8d04', '{"id":"aizhimou/pigeon-pod/requirements-analysis","name":"requirements-analysis","description":{"en":"The requirements-analysis skill helps developers analyze requirements against project goals and architecture. It benefits developers by streamlining the analysis process.","zh":"需求分析是优化PigeonPod项目的关键步骤，涉及分析需求、识别类型、定义预期值和读取相关文档","ja":"要求分析はPigeonPodプロジェクトを最適化するための重要なステップであり、要求の分析、タイプの識別、予想値の定義、関連ドキュメントの読み取りを含む","ko":"요구사항 분석은 PigeonPod 프로젝트를 최적화하는 데 중요한 단계로 요구사항 분석, 유형 식별, 예상 값 정의 및 관련 문서 읽기를 포함","es":"El análisis de requisitos es crucial para el desarrollo de software. Aprende a hacerlo de manera efectiva.","fr":"L''analyse de besoins est essentielle pour le développement de logiciels. Découvrez comment le faire de manière efficace.","de":"Die Anforderungsanalyse ist entscheidend für die Softwareentwicklung. Erfahren Sie, wie Sie es effektiv tun können.","pt":"Análise de requisitos é um processo crítico que envolve a avaliação de necessidades contra metas, arquitetura e realidade de implementação.","ru":"Анализ требований - это критический процесс, который включает оценку потребностей против целей, архитектуры и реальности реализации.","ar":"تحليل المتطلبات هو عملية حاسمة تتضمن تقييم الاحتياجات مقابل الأهداف والهيكل والواقع التنفيذي."},"seo":{"title":{"en":"Requirements-Analysis: Setup Guide for AI Agents","zh":"需求分析设置指南 - 优化PigeonPod项目","ja":"要求分析ベストプラクティス - PigeonPodプロジェクトの最適化","ko":"요구사항 분석 설정 가이드 - PigeonPod 프로젝트 최적화","es":"Guía de Análisis de Requisitos para Desarrolladores","fr":"Guide de Bonnes Pratiques pour l''Analyse de Besoins","de":"Leitfaden für Anforderungsanalyse mit MCP/Context7","pt":"Guia de Configuração para Análise de Requisitos com Ferra...","ru":"Руководство по настройке анализа требований с помощью ИИ ...","ar":"دليل إعداد وتشغيل أداة تحليل المتطلبات باستخدام أدوات الذ..."},"description":{"en":"Unlock efficient requirement analysis with our step-by-step guide. Learn how to integrate MCP/Context7 for dependency checks and optimize your workflow today!","zh":"了解需求分析的技术细节，优化PigeonPod项目的架构和实现，AIエージェント","ja":"要求分析の技術的詳細を学び、PigeonPodプロジェクトのアーキテクチャと実装を最適化する、AIエージェント","ko":"요구사항 분석의 기술적 세부 사항을 배우고 PigeonPod 프로젝트의 아키텍처와 구현을 최적화하는 방법, AI 도구","es":"Aprende a analizar requisitos con eficacia utilizando MCP/Context7 y mejora tu flujo de trabajo de desarrollo","fr":"Découvrez comment analyser les besoins avec efficacité en utilisant MCP/Context7 et améliorez votre flux de travail de développement","de":"Erfahren Sie, wie Sie Anforderungen effektiv analysieren können, indem Sie MCP/Context7 verwenden und Ihren Entwicklungsworkflow verbessern","pt":"Aprenda a analisar requisitos com eficiência usando ferramentas de IA e melhore a implementação de projetos","ru":"Узнайте, как эффективно анализировать требования с помощью ИИ Агентов и улучшить реализацию проектов","ar":"تعرف على كيفية تحليل المتطلبات بفعالية باستخدام أدوات الذكاء الاصطناعي وتحسين تنفيذ المشاريع"},"definition":{"en":"requirements-analysis is a systematic approach to evaluating requirements against project objectives, architecture, and implementation feasibility","zh":"需求分析是对需求进行分析和评估，以确定其与PigeonPod项目的目标、架构和实现的兼容性","ja":"要求分析は、要求を分析して評価し、PigeonPodプロジェクトの目標、アーキテクチャ、実装との互換性を決定すること","ko":"요구사항 분석은 요구사항을 분석 및 평가하여 PigeonPod 프로젝트의 목표, 아키텍처 및 구현과의 호환성을 결정하는 것","es":"Análisis de requisitos es el proceso de evaluar necesidades contra objetivos y arquitectura","fr":"L''analyse de besoins est le processus d''évaluation des besoins par rapport aux objectifs et à l''architecture","de":"Anforderungsanalyse ist der Prozess der Bewertung von Anforderungen gegenüber Zielen und Architektur","pt":"Análise de requisitos é a avaliação sistemática de necessidades para definir soluções eficazes","ru":"Анализ требований - это систематическая оценка потребностей для определения эффективных решений","ar":"تحليل المتطلبات هو التقييم المنظم للاحتياجات لتحديد حلول فعالة"},"features":{"en":["Restates requirements in concise paragraphs for clarity","Identifies requirement types such as feature, enhancement, bugfix, non-functional, integration, or migration","Defines expected user and business value for informed decision-making","Utilizes MCP/Context7 for dependency and API constraint confirmation","Reads relevant project documentation and code for thorough analysis"],"zh":["分析需求与PigeonPod项目目标的兼容性","识别需求类型：特性、增强、错误修复、非功能、集成、迁移","定义预期用户价值和业务价值","阅读相关项目文档和代码","使用MCP/Context7确认依赖或API约束"],"ja":["要求とPigeonPodプロジェクトの目標との互換性を分析する","要求のタイプを識別：機能、強化、バグ修正、非機能、統合、移行","予想ユーザー価値とビジネス価値を定義する","関連プロジェクトのドキュメントとコードを読む","MCP/Context7を使用して依存やAPIの制約を確認する"],"ko":["요구사항과 PigeonPod 프로젝트 목표의 호환성을 분석","요구사항 유형 식별: 기능, 개선, 버그 수정, 비기능, 통합, 마이그레이션","예상 사용자 가치와 비즈니스 가치를 정의","관련 프로젝트 문서와 코드를 읽기","MCP/Context7를 사용하여 종속성 또는 API 제약을 확인"],"es":["Restablecer requisitos en un párrafo corto","Identificar tipo de requisito: característica, mejora, corrección de errores, no funcional, integración o migración","Definir valor esperado para el usuario y el negocio","Utilizar MCP/Context7 para confirmar dependencias o restricciones de API","Leer documentación de proyecto relevante y código antes de dar conclusiones"],"fr":["Réénoncer les besoins en un paragraphe court","Identifier le type de besoin: fonctionnalité, amélioration, correction de bogues, non fonctionnel, intégration ou migration","Définir la valeur attendue pour l''utilisateur et l''entreprise","Utiliser MCP/Context7 pour confirmer les dépendances ou les contraintes d''API","Lire la documentation de projet pertinente et le code avant de tirer des conclusions"],"de":["Anforderungen in einem kurzen Absatz neu formulieren","Anforderungstyp identifizieren: Funktion, Verbesserung, Fehlerbehebung, nicht funktional, Integration oder Migration","Erwarteten Nutzen für den Benutzer und das Unternehmen definieren","MCP/Context7 verwenden, um Abhängigkeiten oder API-Einschränkungen zu bestätigen","Relevante Projekt-Dokumentation und Code lesen, bevor Schlussfolgerungen gezogen werden"],"pt":["Restate os requisitos em um parágrafo conciso","Identifique o tipo de requisito: recurso, melhoria, correção de bug, não funcional, integração ou migração","Defina o valor esperado para o usuário e o negócio","Leia a documentação relevante do projeto e o código antes de tirar conclusões","Use MCP/Context7 para confirmar dependências ou restrições de API"],"ru":["Переформулируйте требования в кратком параграфе","Определите тип требования: функция, улучшение, исправление бага, нефункциональное, интеграция или миграция","Определите ожидаемую пользу для пользователя и бизнеса","Прочитайте актуальную документацию проекта и код перед тем, как делать выводы","Используйте MCP/Context7 для подтверждения зависимостей или ограничений API"],"ar":["إعادة صياغة المتطلبات في فقرة موجزة","تحديد نوع المتطلبات: ميزة، تحسين، إصلاح عيب، غير وظيفي، تكامل أو هجرة","تحديد القيمة المتوقعة للمستخدم والعمل","قراءة مستندات المشروع ذات الصلة والكود قبل الاستنتاج","استخدام MCP/Context7 للتأكد من الارتباطات أو قيود واجهة برمجة التطبيقات"]},"keywords":{"en":["how to use requirements-analysis","requirements-analysis setup guide","what is requirements-analysis","requirements-analysis alternative","requirements-analysis vs competing tools","requirements-analysis install for AI agents"],"zh":["需求分析","PigeonPod项目","AIエージェント","要求分析","项目优化","架构设计","实现细节","MCP/Context7"],"ja":["要求分析","PigeonPodプロジェクト","AIエージェント","プロジェクト最適化","アーキテクチャ設計","実装詳細","MCP/Context7"],"ko":["요구사항 분석","PigeonPod 프로젝트","AI 도구","프로젝트 최적화","아키텍처 설계","구현 세부 사항","MCP/Context7"],"es":["análisis de requisitos","desarrollo de software","MCP/Context7","análisis de necesidades","flujo de trabajo de desarrollo","tipo de requisito","valor esperado para el usuario","restricciones de API"],"fr":["analyse de besoins","développement de logiciels","MCP/Context7","analyse de nécessités","flux de travail de développement","type de besoin","valeur attendue pour l''utilisateur","contraintes d''API"],"de":["Anforderungsanalyse","Softwareentwicklung","MCP/Context7","Anforderungsanalyse","Entwicklungsworkflow","Anforderungstyp","erwarteter Nutzen für den Benutzer","API-Einschränkungen"],"pt":["análise de requisitos","ferramentas de ia","desenvolvimento de software","requisitos de projeto","implementação de projetos","análise de necessidades","soluções eficazes"],"ru":["анализ требований","ии агенты","разработка программного обеспечения","требования проекта","реализация проектов","анализ потребностей","эффективные решения"],"ar":["تحليل المتطلبات","أدوات الذكاء الاصطناعي","تطوير البرمجيات","متطلبات المشروع","تنفيذ المشاريع","تحليل الاحتياجات","حلول فعالة"]}},"owner":"aizhimou","repo":"pigeon-pod","repoPath":"aizhimou/pigeon-pod","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.393Z","topics":[],"category":"community","skillMd":{"name":"requirements-analysis","description":"Analyze product/feature requirements for the PigeonPod project with software engineering rigor. Use when users ask to evaluate a requirements value, feasibility, architecture fit, implementation impact, risk, delivery scope, or tradeoffs. Always inspect current repository docs/code first (especially architecture and README files), then use MCP tools (including Context7) to verify external library/framework/API constraints before concluding.","bodyPreview":"# Requirements Analysis\n\nAnalyze requirements against PigeonPod goals, current architecture, and implementation reality.\n\n## Follow This Workflow\n\n1. Restate the requirement in one short paragraph.\n2. Identify requirement type: `feature`, `enhancement`, `bugfix`, `non-functional`, `integration`, or `migration`.\n3. Define expected user value and business value.\n4. Read relevant project docs and code before giving conclusions.\n5. Use MCP/Context7 to confirm dependency or API constraints when exter","body":"# Requirements Analysis\n\nAnalyze requirements against PigeonPod goals, current architecture, and implementation reality.\n\n## Follow This Workflow\n\n1. Restate the requirement in one short paragraph.\n2. Identify requirement type: `feature`, `enhancement`, `bugfix`, `non-functional`, `integration`, or `migration`.\n3. Define expected user value and business value.\n4. Read relevant project docs and code before giving conclusions.\n5. Use MCP/Context7 to confirm dependency or API constraints when external libraries/services are involved.\n6. Evaluate architecture fit, implementation complexity, data impact, and operational impact.\n7. Propose an implementation strategy with phased scope (`MVP`, `next`, `later`).\n8. Output a decision with explicit rationale and open questions.\n\n## Read Local Context First\n\nPrioritize these files for PigeonPod:\n\n- `README.md`\n- `dev-docs/architecture/architecture-design-en.md`\n- `backend/src/main/resources/application.yml`\n- `backend/src/main/resources/db/migration/*.sql`\n- Relevant backend packages under `backend/src/main/java/top/asimov/pigeon/`\n- Relevant frontend routes/components under `frontend/src/pages/` and `frontend/src/components/`\n\nUse fast discovery commands when needed:\n\n```bash\nrg -n \"keyword|concept|module\" backend/src/main/java frontend/src dev-docs README.md\nrg --files dev-docs/\n```\n\n## Use Context7 and MCP Deliberately\n\nUse Context7/MCP when the requirement depends on framework/library/service behavior, version constraints, configuration, or integration details.\n\nTypical triggers:\n\n- Spring Boot/MyBatis-Plus/Sa-Token behavior or config decisions\n- React/Mantine/React Router/i18next/Axios constraints\n- YouTube Data API v3 limits/quotas/contract details\n- RSS/Podcasting namespace compatibility details\n- yt-dlp options/behavior and compatibility implications\n\nRules:\n\n- Resolve library ID first, then query focused questions.\n- Prefer primary/official docs and version-aware guidance.\n- Distinguish facts from inference.\n- If docs conflict with local implementation, prioritize local code reality and call out the gap.\n\n## Evaluate With These Dimensions\n\nAssess each dimension explicitly:\n\n1. Value Alignment: Match with PigeonPod core goals (YouTube-to-podcast conversion, auto-sync/download, feed usability, operations simplicity).\n2. Feasibility: Confirm technical possibility with current stack and constraints.\n3. Architecture Fit: Check compatibility with backend service boundaries, scheduler/event flow, DB schema, and frontend route/state model.\n4. Data and Migration Impact: Identify new fields/tables, migration requirements, backfill, and backward compatibility.\n5. API and Contract Impact: Identify REST/RSS contract changes and consumer compatibility risks.\n6. Security and Compliance: Review auth, permissions, secrets/API keys, abuse vectors.\n7. Performance and Cost: Estimate queue pressure, I/O/download load, external API quota consumption, and storage growth.\n8. Testability and Operability: Define unit/integration/e2e coverage and monitoring/logging needs.\n\n## Produce This Output Format\n\nUse this structure in final analysis:\n\n```markdown\n## Requirement Summary\n- User request:\n- Requirement type:\n- Assumptions:\n\n## Value Assessment\n- User value:\n- Product/business value:\n- Priority suggestion: High/Medium/Low\n\n## Feasibility and Architecture Fit\n- Current touchpoints:\n- Proposed changes:\n- Architecture fit verdict: Good/Partial/Poor\n\n## Impact Analysis\n- Backend impact:\n- Frontend impact:\n- Database/migration impact:\n- External dependency impact:\n- Security/performance/ops impact:\n\n## Delivery Plan\n- MVP scope:\n- Non-MVP scope:\n- Estimated complexity: S/M/L/XL\n- Key risks and mitigations:\n\n## Decision\n- Recommendation: Proceed / Proceed with constraints / Defer / Reject\n- Reasoning:\n- Open questions:\n```\n\n## Decision Heuristics\n\n- Recommend `Proceed` when value is clear, fit is good, and risk is manageable.\n- Recommend `Proceed with constraints` when value is high but scope/risk needs staged delivery.\n- Recommend `Defer` when value exists but prerequisites are missing.\n- Recommend `Reject` when requirement conflicts with core goals or creates disproportional cost/risk.\n\n## Quality Bar\n\nBefore finalizing, verify all checks:\n\n- Base conclusions on repository evidence, not assumptions only.\n- Confirm external-library/API claims through Context7/MCP when relevant.\n- Separate facts, assumptions, and unknowns.\n- Include at least one feasible implementation path.\n- Include explicit tradeoffs and rollback/fallback considerations.\n"},"lastSynced":"2026-03-08T02:06:15.755Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring streamlined project analysis and goal alignment, such as Cursor or AutoGPT.","zh":"适用于需要简化项目分析和目标对齐的开发代理，例如 Cursor 或 AutoGPT。","ja":"開発エージェントがプロジェクト分析と目標の整列をストリームライン化する必要がある場合、Cursor または AutoGPT などに最適です。","ko":"프로젝트 분석 및 목표 정렬을 간소화해야 하는 개발 에이전트에 적합합니다. 예를 들어 Cursor 또는 AutoGPT와 같은 경우입니다.","es":"Ideal para agentes de desarrollo que requieren un análisis de proyecto y alineación de objetivos simplificados, como Cursor o AutoGPT.","fr":"Idéal pour les agents de développement nécessitant une analyse de projet et une alignement d''objectifs rationalisés, tels que Cursor ou AutoGPT.","de":"Ideal für Entwicklungssagenten, die eine strukturierte Projektanalyse und Zielausrichtung benötigen, wie z. B. Cursor oder AutoGPT.","pt":"Ideal para Agentes de Desenvolvimento que exigem análise de projeto e alinhamento de metas simplificados, como Cursor ou AutoGPT.","ru":"Идеально для агентов разработки, требующих упрощенного анализа проекта и согласования целей, таких как Cursor или AutoGPT.","ar":"مثالي لعميل التطوير الذي يتطلب تحليلًا مشروعًا مبسطًا وتنسيق أهداف ، مثل Cursor أو AutoGPT."},"recommendation":{"en":"Empowers agents to analyze requirements against project goals and architecture using MCP/Context7, defining expected user and business value while identifying requirement types like feature, enhancement, or bugfix.","zh":"赋予代理分析项目目标和架构的能力，使用 MCP/Context7 定义预期的用户和商业价值，同时识别需求类型，如功能、增强或 bug 修复。","ja":"MCP/Context7 を使用して、エージェントがプロジェクトの目標とアーキテクチャに対する要件を分析し、期待されるユーザーとビジネスの価値を定義し、機能、強化、またはバグ修正などの要件のタイプを識別することができます。","ko":"MCP/Context7를 사용하여 에이전트가 프로젝트 목표 및 아키텍처에 대한 요구 사항을 분석하고 예상 사용자 및 비즈니스 가치를 정의하며 기능, 개선 또는 버그 수정과 같은 요구 사항 유형을 식별할 수 있습니다.","es":"Habilita a los agentes a analizar los requisitos frente a los objetivos y la arquitectura del proyecto utilizando MCP/Context7, definiendo el valor esperado para el usuario y el negocio, al mismo tiempo que identifica tipos de requisitos como características, mejoras o correcciones de errores.","fr":"Permet aux agents d''analyser les exigences par rapport aux objectifs et à l''architecture du projet en utilisant MCP/Context7, en définissant la valeur attendue pour l''utilisateur et l''entreprise, tout en identifiant les types d''exigences tels que les fonctionnalités, les améliorations ou les corrections de bogue.","de":"Ermächtigt Agenten, Anforderungen gegenüber den Projektzielen und der Architektur unter Verwendung von MCP/Context7 zu analysieren, wobei der erwartete Benutzer- und Geschäftswert definiert wird, während Anforderungstypen wie Funktionen, Verbesserungen oder Fehlerbehebungen identifiziert werden.","pt":"Habilita os agentes a analisar os requisitos contra os objetivos e a arquitetura do projeto usando MCP/Context7, definindo o valor esperado do usuário e do negócio, enquanto identifica os tipos de requisitos, como recurso, melhoria ou correção de bug.","ru":"Наделяет агентов возможностью анализировать требования в отношении целей и архитектуры проекта с использованием MCP/Context7, определяя ожидаемое пользовательское и бизнес-ценность, а также определяя типы требований, такие как функция, улучшение или исправление ошибки.","ar":"يمكن للعميل تحليل المتطلبات مقابل أهداف المشروع وهندستها باستخدام MCP/Context7 ، مما يحدد القيمة المتوقعة للمستخدم والشركات أثناء تحديد أنواع المتطلبات مثل الميزة أو التحسين أو إصلاح العطل."},"useCases":{"en":["Analyzing requirements against PigeonPod goals","Identifying and categorizing requirement types","Defining expected user and business value for project enhancements"],"zh":["分析 PigeonPod 目标的需求","识别和分类需求类型","定义项目增强的预期用户和商业价值"],"ja":["PigeonPod の目標に対する要件を分析する","要件のタイプを識別して分类する","プロジェクトの強化の期待されるユーザーとビジネスの価値を定義する"],"ko":["PigeonPod 목표에 대한 요구 사항 분석","요구 사항 유형 식별 및 분류","프로젝트 개선에 대한 예상 사용자 및 비즈니스 가치 정의"],"es":["Análisis de requisitos frente a los objetivos de PigeonPod","Identificación y categorización de tipos de requisitos","Definir el valor esperado para el usuario y el negocio para las mejoras del proyecto"],"fr":["Analyse des exigences par rapport aux objectifs de PigeonPod","Identification et catégorisation des types d''exigences","Définition de la valeur attendue pour l''utilisateur et l''entreprise pour les améliorations du projet"],"de":["Analyse von Anforderungen im Vergleich zu den Zielen von PigeonPod","Identifizierung und Kategorisierung von Anforderungstypen","Definition des erwarteten Benutzer- und Geschäftswerts für Projekterweiterungen"],"pt":["Analisar os requisitos contra os objetivos do PigeonPod","Identificar e categorizar os tipos de requisitos","Definir o valor esperado do usuário e do negócio para melhorias de projeto"],"ru":["Анализ требований против целей PigeonPod","Определение и категоризация типов требований","Определение ожидаемого пользовательского и бизнес-ценности для улучшений проекта"],"ar":["تحليل المتطلبات مقابل أهداف PigeonPod","تحديد وفئات أنواع المتطلبات","تحديد القيمة المتوقعة للمستخدم والشركات لتحسينات المشروع"]},"limitations":{"en":["Requires access to project documentation and code","Dependent on MCP/Context7 for dependency and API constraint confirmation"],"zh":["需要访问项目文档和代码","依赖于 MCP/Context7 进行依赖和 API 约束确认"],"ja":["プロジェクトのドキュメントとコードへのアクセスが必要","依存関係と API の制約確認のために MCP/Context7 依存"],"ko":["프로젝트 문서 및 코드에 대한 액세스가 필요합니다.","의존성 및 API 제약 확인을 위해 MCP/Context7에 의존"],"es":["Requiere acceso a la documentación y el código del proyecto","Dependiente de MCP/Context7 para la confirmación de dependencias y restricciones de API"],"fr":["Nécessite un accès à la documentation et au code du projet","Dépend de MCP/Context7 pour la confirmation des dépendances et des contraintes d''API"],"de":["Benötigt Zugriff auf die Projekt-Dokumentation und den Code","Abhängig von MCP/Context7 für die Bestätigung von Abhängigkeiten und API-Einschränkungen"],"pt":["Requer acesso à documentação e código do projeto","Dependente do MCP/Context7 para confirmação de dependência e restrição de API"],"ru":["Требует доступа к документации и коду проекта","Зависит от MCP/Context7 для подтверждения зависимости и ограничения API"],"ar":["يتطلب الوصول إلى توثيق المشروع ورمزه","يعتمد على MCP/Context7 لإثبات الاعتماد وقيود واجهة برمجة التطبيقات"]},"version":4},"contentHash":"b73f74282df21ce869477991d072a637711dfc98cc2775d1f59372486c4a8d04","qualityScore":45}');
