INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aizhimou/pigeon-pod/requirements-analysis', 'requirements-analysis', 'aizhimou', 'pigeon-pod', 'community', 'requirements-analysis aizhimou pigeon-pod community The requirements-analysis skill helps developers analyze requirements against project goals and architecture. It benefits developers by streamlining the analysis process. 需求分析是优化PigeonPod项目的关键步骤，涉及分析需求、识别类型、定义预期值和读取相关文档 要求分析はPigeonPodプロジェクトを最適化するための重要なステップであり、要求の分析、タイプの識別、予想値の定義、関連ドキュメントの読み取りを含む 요구사항 분석은 PigeonPod 프로젝트를 최적화하는 데 중요한 단계로 요구사항 분석, 유형 식별, 예상 값 정의 및 관련 문서 읽기를 포함 El análisis de requisitos es crucial para el desarrollo de software. Aprende a hacerlo de manera efectiva. L''analyse de besoins est essentielle pour le développement de logiciels. Découvrez comment le faire de manière efficace. Die Anforderungsanalyse ist entscheidend für die Softwareentwicklung. Erfahren Sie, wie Sie es effektiv tun können. Análise de requisitos é um processo crítico que envolve a avaliação de necessidades contra metas, arquitetura e realidade de implementação. Анализ требований - это критический процесс, который включает оценку потребностей против целей, архитектуры и реальности реализации. تحليل المتطلبات هو عملية حاسمة تتضمن تقييم الاحتياجات مقابل الأهداف والهيكل والواقع التنفيذي. how to use requirements-analysis requirements-analysis setup guide what is requirements-analysis requirements-analysis alternative requirements-analysis vs competing tools requirements-analysis install for AI agents 需求分析 PigeonPod项目 AIエージェント 要求分析 项目优化 架构设计 实现细节 MCP/Context7 Restates requirements in concise paragraphs for clarity Identifies requirement types such as feature, enhancement, bugfix, non-functional, integration, or migration Defines expected user and business value for informed decision-making Utilizes MCP/Context7 for dependency and API constraint confirmation Reads relevant project documentation and code for thorough analysis requirements-analysis is a systematic approach to evaluating requirements against project objectives, architecture, and implementation feasibility');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zby/llm-do/decomplect-py', 'community', 'zby', 'llm-do', 'zby/llm-do', 'decomplect-py', 0, 0, 45, '2026-03-08T01:57:15.394Z', '2026-03-08T02:06:16.639Z', 'c7495484fe8ff66f28289d8233864cbb63eb16e274bf7044c07bf1274fd8262c', '{"id":"zby/llm-do/decomplect-py","name":"decomplect-py","description":{"en":"decomplect-py is a Python design quality analyzer that helps developers refactor and stabilize their code. It provides three analyzers: simplicity, fcis, and coupling.","zh":"Decomplect-Py 是一个 Python 设计质量分析工具，帮助开发者优化代码结构和设计。","ja":"Decomplect-Py は Python 設計品質を分析するツールで、開発者がコードの構造と設計を最適化するのに役立ちます。","ko":"Decomplect-Py 는 Python 설계 품질을 분석하는 도구로, 개발자가 코드 구조와 설계를 최적화하는 데 도움을 줍니다.","es":"Decomplect-py es una herramienta de análisis de calidad de diseño de Python que ayuda a mejorar la simplicidad, separación de lógica y reducción de acoplamiento en el código","fr":"Decomplect-py est un outil d''analyse de la qualité de conception Python qui aide à améliorer la simplicité, la séparation de la logique et la réduction du couplage dans le code","de":"Decomplect-py ist ein Tool zur Analyse der Python-Designqualität, das dabei hilft, die Einfachheit, Trennung der Logik und Reduzierung der Kopplung im Code zu verbessern","pt":"O Decomplect-Py é uma ferramenta de análise de código Python que ajuda a melhorar a qualidade do design do código. Ele oferece três analisadores: simplicity-analyzer, fcis-analyzer e coupling-analyzer.","ru":"Decomplect-Py - это инструмент анализа кода Python, который помогает улучшить качество дизайна кода. Он предлагает три анализатора: simplicity-analyzer, fcis-analyzer и coupling-analyzer.","ar":"Decomplect-Py هو أداة تحليل الكود بايثون التي تساعد على تحسين جودة تصميم الكود. يقدم ثلاثة محللين: simplicity-analyzer، fcis-analyzer و coupling-analyzer"},"seo":{"title":{"en":"decomplect-py: Architectural Analysis for Python | AI Age...","zh":"Decomplect-Py 架构分析工具：Python 设计质量优化","ja":"Decomplect-Py のベストプラクティス: Python設計の品質向上","ko":"Decomplect-Py 설정 가이드: Python 설계 품질 분석 도구","es":"Guía de configuración de decomplect-py para análisis de c...","fr":"Guide d''installation de decomplect-py pour l''analyse de l...","de":"Einrichtungsleitfaden für decomplect-py zur Analyse der P...","pt":"Guia de Configuração do Decomplect-Py: Ferramentas de Aná...","ru":"ИИ Агенты: Decomplect-Py - Руководство по Настройке и Ана...","ar":"دليل إعداد Decomplect-Py: أدوات تحليل الكود بايثون"},"description":{"en":"Unlock Python design quality with decomplect-py. Run analyzers in parallel and refactor with ease. Learn how to use decomplect-py today!","zh":"了解 Decomplect-Py 的功能和用法，优化 Python 代码设计质量，提高开发效率，AIエージェント","ja":"Decomplect-Py を使用して Python コードの設計品質を向上させる方法を学びましょう。AIエージェント","ko":"Decomplect-Py 를 사용하여 Python 설계 품질을 분석하고 개선하는 방법을 알아보세요. AI 툴","es":"Aprende a utilizar decomplect-py para mejorar la calidad de tu código Python con análisis de simplicidad, FCIS y acoplamiento","fr":"Découvrez comment utiliser decomplect-py pour améliorer la qualité de votre code Python avec des analyses de simplicité, FCIS et couplage","de":"Erfahren Sie, wie Sie decomplect-py verwenden, um die Qualität Ihres Python-Codes mit Analysen von Einfachheit, FCIS und Kopplung zu verbessern","pt":"Aprenda a configurar e utilizar o Decomplect-Py para melhorar a qualidade do design do seu código Python com nossas ferramentas de análise","ru":"Узнайте, как настроить и использовать Decomplect-Py для улучшения качества дизайна вашего кода Python с нашей помощью","ar":"تعرف على كيفية إعداد وتشغيل Decomplect-Py لتحسين جودة تصميم كود بايثون الخاص بك مع أدواتنا"},"definition":{"en":"decomplect-py is an architectural analysis tool for Python that assesses design quality and provides insights for improvement.","zh":"Decomplect-Py 是一个用于分析 Python 代码设计质量的工具，包括简洁性、耦合性和 FCIS 分析。","ja":"Decomplect-Py は、Python コードの設計品質を分析するツールで、シンプルさ、結合度、FCIS 分析などを実行します。","ko":"Decomplect-Py 는 Python 코드의 설계 품질을 분석하는 도구로, 단순성, 결합도, FCIS 분석 등을 수행합니다.","es":"Decomplect-py es una herramienta de análisis de código que evalúa la calidad del diseño de Python","fr":"Decomplect-py est un outil d''analyse de code qui évalue la qualité de la conception Python","de":"Decomplect-py ist ein Code-Analyse-Tool, das die Qualität des Python-Designs bewertet","pt":"O Decomplect-Py é uma ferramenta de análise de código Python que ajuda a melhorar a qualidade do design do código","ru":"Decomplect-Py - это инструмент анализа кода Python, который помогает улучшить качество дизайна кода","ar":"Decomplect-Py هو أداة تحليل الكود بايثون التي تساعد على تحسين جودة تصميم الكود"},"features":{"en":["Runs three analyzers in parallel: simplicity, fcis, and coupling","Supports specific analyzer execution via commands: --simplicity, --fcis, --coupling","Provides refactoring capabilities between workers and tools","Analyzes Python code design quality using simplicity-analyzer, fcis-analyzer, and coupling-analyzer"],"zh":["支持简洁性分析","支持耦合性分析","支持 FCIS 分析","并行运行多个分析器","命令行接口（CLI）"],"ja":["シンプルさ分析のサポート","結合度分析のサポート","FCIS 分析のサポート","複数の分析器の並行実行","コマンドラインインターフェース（CLI）"],"ko":["단순성 분석 지원","결합도 분석 지원","FCIS 분석 지원","다중 분석기 병렬 실행","명령줄 인터페이스（CLI）"],"es":["Análisis de simplicidad para evaluar la complejidad del código","Análisis FCIS para separar la lógica de la entrada/salida","Análisis de acoplamiento para reducir la dependencia entre módulos","Compatibilidad con CLI para una integración fácil","Soporte para Python para el desarrollo de aplicaciones","Herramientas de refactorización para mejorar la calidad del código"],"fr":["Analyse de simplicité pour évaluer la complexité du code","Analyse FCIS pour séparer la logique de l''entrée/sortie","Analyse de couplage pour réduire la dépendance entre les modules","Compatibilité avec CLI pour une intégration facile","Prise en charge de Python pour le développement d''applications","Outils de refactoring pour améliorer la qualité du code"],"de":["Einfachheitsanalyse zur Bewertung der Code-Komplexität","FCIS-Analyse zur Trennung der Logik von der Ein-/Ausgabe","Kopplungsanalyse zur Reduzierung der Abhängigkeit zwischen Modulen","Kompatibilität mit CLI für eine einfache Integration","Unterstützung von Python für die Anwendungsentwicklung","Refactoring-Tools zur Verbesserung der Code-Qualität"],"pt":["Três analisadores: simplicity-analyzer, fcis-analyzer e coupling-analyzer","Análise de código Python para melhorar a qualidade do design","Utilização de CLI para execução de comandos","Suporte a refactoração de código","Análise de complexidade e acoplamento de código"],"ru":["Три анализатора: simplicity-analyzer, fcis-analyzer и coupling-analyzer","Анализ кода Python для улучшения качества дизайна","Использование CLI для выполнения команд","Поддержка рефакторинга кода","Анализ сложности и связности кода"],"ar":["ثلاثة محللين: simplicity-analyzer، fcis-analyzer و coupling-analyzer","تحليل الكود بايثون لتحسين جودة تصميم الكود","استخدام CLI لتشغيل الأوامر","دعم إعادة هيكلة الكود","تحليل التعقيد والارتباط بين الكود"]},"keywords":{"en":["how to use decomplect-py","decomplect-py setup guide","decomplect-py alternative","decomplect-py vs pylint","decomplect-py install","python design quality analysis","decomplect-py documentation"],"zh":["Decomplect-Py","Python 设计质量","代码分析工具","AIエージェント","Python 开发","代码优化"],"ja":["Decomplect-Py","Python 設計品質","コード分析ツール","AIエージェント","Python 開発","コード最適化"],"ko":["Decomplect-Py","Python 설계 품질","코드 분석 도구","AI 툴","Python 개발","코드 최적화"],"es":["herramientas de análisis de código","calidad de diseño de Python","análisis de simplicidad","análisis FCIS","análisis de acoplamiento","desarrollo de aplicaciones Python","refactorización de código","mejora de la calidad del código"],"fr":["outils d''analyse de code","qualité de conception Python","analyse de simplicité","analyse FCIS","analyse de couplage","développement d''applications Python","refactoring de code","amélioration de la qualité du code"],"de":["Code-Analyse-Tools","Python-Designqualität","Einfachheitsanalyse","FCIS-Analyse","Kopplungsanalyse","Python-Anwendungsentwicklung","Code-Refactoring","Verbesserung der Code-Qualität"],"pt":["Decomplect-Py","análise de código Python","qualidade do design","simplicity-analyzer","fcis-analyzer","coupling-analyzer","CLI","refatoração de código"],"ru":["Decomplect-Py","анализ кода Python","качество дизайна","simplicity-analyzer","fcis-analyzer","coupling-analyzer","CLI","рефакторинг кода"],"ar":["Decomplect-Py","تحليل الكود بايثون","جودة تصميم الكود","simplicity-analyzer","fcis-analyzer","coupling-analyzer","CLI","إعادة هيكلة الكود"]}},"owner":"zby","repo":"llm-do","repoPath":"zby/llm-do","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.394Z","topics":[],"category":"community","skillMd":{"name":"decomplect-py","description":"Architectural code analysis for Python design quality. Evaluates simplicity (Rich Hickey), functional core/imperative shell (Gary Bernhardt), and coupling (Constantine & Yourdon). Use for design review or architectural assessment of Python code.","bodyPreview":"# Decomplect-Py\n\nArchitectural analysis for Python design quality.\n\n## Usage\n\n```\n/decomplect-py                # Run all 3 analyzers in parallel\n/decomplect-py --simplicity   # Specific analyzer\n/decomplect-py --fcis         # Specific analyzer\n/decomplect-py --coupling     # Specific analyzer\n```\n\n## Analyzers\n\n| Analyzer | Question |\n|----------|----------|\n| **simplicity-analyzer** | Is this truly simple or just easy? |\n| **fcis-analyzer** | Is pure logic separated from I/O? |\n| **coupling-a","body":"# Decomplect-Py\n\nArchitectural analysis for Python design quality.\n\n## Usage\n\n```\n/decomplect-py                # Run all 3 analyzers in parallel\n/decomplect-py --simplicity   # Specific analyzer\n/decomplect-py --fcis         # Specific analyzer\n/decomplect-py --coupling     # Specific analyzer\n```\n\n## Analyzers\n\n| Analyzer | Question |\n|----------|----------|\n| **simplicity-analyzer** | Is this truly simple or just easy? |\n| **fcis-analyzer** | Is pure logic separated from I/O? |\n| **coupling-analyzer** | Are modules well-separated? |\n\n## What It Checks\n\n| Pillar | Focus |\n|--------|-------|\n| **Simplicity** | Values over state, decomplected concerns |\n| **FCIS** | Functional core (pure), imperative shell (I/O) |\n| **Coupling** | High cohesion, low coupling |\n\n## When to Use\n\n- Reviewing Python system design\n- Before major refactoring\n- Assessing architectural quality\n- Checking if code is \"Rich Hickey approved\"\n\n## Supported Languages\n\n- Python (`.py` files only)\n\n## Python-Specific Patterns\n\n- `dataclasses(frozen=True)` and `NamedTuple` for immutable values\n- Mutable default argument anti-patterns\n- Django/Flask view architecture\n- Circular import detection\n- Module-level state analysis\n\n## Reference Documentation\n\n- [Rich Hickey Principles](reference/rich-hickey.md)\n- [Functional Core/Imperative Shell](reference/fcis.md)\n- [Cohesion & Coupling](reference/coupling.md)\n\n## See Also\n\n- `/decomplect` - Analysis for TypeScript/Go/Rust\n- `/unslopify` - Tactical code cleanup\n"},"lastSynced":"2026-03-08T02:06:16.639Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing advanced Python design quality assessment capabilities.","zh":"适用于需要高级Python设计质量评估能力的代码分析代理。","ja":"Python設計の品質評価能力に高度な機能を必要とするコード分析エージェントに適しています。","ko":"고급 Python 설계 품질 평가 기능을 필요로 하는 코드 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Código que necesitan capacidades avanzadas de evaluación de la calidad del diseño de Python.","fr":"Parfait pour les agents d''analyse de code nécessitant des capacités avancées d''évaluation de la qualité de conception Python.","de":"Perfekt für Code-Analyse-Agents, die erweiterte Python-Design-Qualitätsbewertungsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Código que necessitam de capacidades avançadas de avaliação de qualidade de design Python.","ru":"Идеально подходит для агентов анализа кода, требующих передовых возможностей оценки качества проектирования Python.","ar":"مثالي لعميل تحليل الشفرة الذي يحتاج إلى قدرات متقدمة لتقييم جودة تصميم بايثون."},"recommendation":{"en":"Empowers agents to refactor and stabilize code using simplicity, fcis, and coupling analyzers, providing comprehensive architectural analysis for Python design quality through command-line interfaces like `/decomplect-py --simplicity` and `/decomplect-py --fcis`.","zh":"赋予代理重构和稳定代码的能力，使用简单性、fcis和耦合分析器，通过命令行接口（如`/decomplect-py --simplicity`和`/decomplect-py --fcis`）提供全面性的架构分析用于Python设计质量。","ja":"シンプリシティ、fcis、アナライザを使用して、コードをリファクタリングおよび安定化するエージェントをEmpowerし、コマンドラインインターフェイス（例：`/decomplect-py --simplicity`および`/decomplect-py --fcis`）を介してPython設計の品質を分析するための包括的なアーキテクチャ分析を提供します。","ko":"단순성, fcis, 결합 분석기를 사용하여 코드를 리팩토링하고 안정화하는 에이전트를 강화하여, 명령줄 인터페이스(예: `/decomplect-py --simplicity` 및 `/decomplect-py --fcis`)를 통해 Python 설계 품질에 대한 포괄적인 아키텍처 분석을 제공합니다.","es":"Habilita a los agentes a refactorizar y estabilizar el código utilizando la simplicidad, los analizadores fcis y de acoplamiento, proporcionando un análisis arquitectónico integral de la calidad del diseño de Python a través de interfaces de línea de comandos como `/decomplect-py --simplicity` y `/decomplect-py --fcis`.","fr":"Permet aux agents de refactoriser et de stabiliser le code en utilisant la simplicité, les analyseurs fcis et de couplage, fournissant une analyse architecturale complète de la qualité de conception Python via des interfaces de ligne de commande comme `/decomplect-py --simplicity` et `/decomplect-py --fcis`.","de":"Ermöglicht es den Agents, den Code mithilfe von Einfachheit, fcis- und Kopplungsanalyse-Tools zu refaktorisieren und zu stabilisieren, wodurch eine umfassende architektonische Analyse der Python-Design-Qualität über Befehlszeilen-Schnittstellen wie `/decomplect-py --simplicity` und `/decomplect-py --fcis` bereitgestellt wird.","pt":"Habilita os agentes a refatorar e estabilizar o código usando simplicidade, fcis e analisadores de acoplamento, fornecendo análise arquitetural abrangente para a qualidade do design Python por meio de interfaces de linha de comando como `/decomplect-py --simplicity` e `/decomplect-py --fcis`.","ru":"Наделяет агентов возможностью рефакторинга и стабилизации кода с помощью простоты, fcis и анализаторов связности, обеспечивая всесторонний архитектурный анализ качества проектирования Python посредством интерфейсов командной строки, таких как `/decomplect-py --simplicity` и `/decomplect-py --fcis`.","ar":"يمكن للعميل إعادة هيكلة الشفرة وتثبيتها باستخدام البساطة و fcis ومحللات الارتباط ، مما يوفر تحليلًا معماريًا شاملاً لجودة تصميم بايثون من خلال واجهات سطر الأوامر مثل `/decomplect-py --simplicity` و `/decomplect-py --fcis`."},"useCases":{"en":["Refactoring complex Python modules for simplicity","Analyzing function-call and import dependencies with fcis-analyzer","Measuring coupling between objects and modules"],"zh":["重构复杂的Python模块以提高简单性","使用fcis-analyzer分析函数调用和导入依赖","测量对象和模块之间的耦合"],"ja":["シンプリシティの向上のための複雑なPythonモジュールのリファクタリング","fcis-analyzerを使用した関数呼び出しとインポート依存関係の分析","オブジェクトとモジュール間の結合の測定"],"ko":["단순성을 높이기 위한 복잡한 Python 모듈의 리팩토링","fcis-analyzer를 사용한 함수 호출 및 가져오기 종속성 분석","객체와 모듈 간의 결합 측정"],"es":["Reestructuración de módulos Python complejos para la simplicidad","Análisis de dependencias de llamadas a funciones y de importación con fcis-analyzer","Medición del acoplamiento entre objetos y módulos"],"fr":["Réorganisation de modules Python complexes pour la simplicité","Analyse des dépendances d''appels de fonctions et d''importation avec fcis-analyzer","Mesure du couplage entre les objets et les modules"],"de":["Umstrukturierung komplexer Python-Module für Einfachheit","Analyse von Funktionsaufruf- und Import-Abhängigkeiten mit fcis-analyzer","Messung des Kopplungsgrades zwischen Objekten und Modulen"],"pt":["Reestruturação de módulos Python complexos para simplicidade","Análise de dependências de chamada de função e importação com fcis-analyzer","Medição do acoplamento entre objetos e módulos"],"ru":["Рефакторинг сложных модулей Python для простоты","Анализ зависимостей вызова функций и импорта с помощью fcis-analyzer","Измерение связности между объектами и модулями"],"ar":["إعادة هيكلة وحدات بايثون المعقدة من أجل البساطة","تحليل التبعيات بين الدوال والمهاجر مع محلل fcis","قياس الارتباط بين الكائنات والوحدات"]},"limitations":{"en":["Requires Python environment","Limited to Python design quality analysis"],"zh":["需要Python环境","仅限Python设计质量分析"],"ja":["Python環境が必要","Python設計の品質分析のみ"],"ko":["Python 환경이 필요","Python 설계 품질 분석만 가능"],"es":["Requiere entorno de Python","Limitado al análisis de la calidad del diseño de Python"],"fr":["Nécessite un environnement Python","Limité à l''analyse de la qualité de conception Python"],"de":["Benötigt Python-Umgebung","Begrenzt auf die Analyse der Python-Design-Qualität"],"pt":["Requer ambiente Python","Limitado à análise de qualidade de design Python"],"ru":["Требуется среда Python","Ограничен анализ качества проектирования Python"],"ar":["يتطلب بيئة بايثون","محدود لتحليل جودة تصميم بايثون"]},"version":4},"contentHash":"c7495484fe8ff66f28289d8233864cbb63eb16e274bf7044c07bf1274fd8262c","qualityScore":45}');
