INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zby/llm-do/decomplect-py', 'decomplect-py', 'zby', 'llm-do', 'community', 'decomplect-py zby llm-do community decomplect-py is a Python design quality analyzer that helps developers refactor and stabilize their code. It provides three analyzers: simplicity, fcis, and coupling. Decomplect-Py 是一个 Python 设计质量分析工具，帮助开发者优化代码结构和设计。 Decomplect-Py は Python 設計品質を分析するツールで、開発者がコードの構造と設計を最適化するのに役立ちます。 Decomplect-Py 는 Python 설계 품질을 분석하는 도구로, 개발자가 코드 구조와 설계를 최적화하는 데 도움을 줍니다. Decomplect-py es una herramienta de análisis de calidad de diseño de Python que ayuda a mejorar la simplicidad, separación de lógica y reducción de acoplamiento en el código Decomplect-py est un outil d''analyse de la qualité de conception Python qui aide à améliorer la simplicité, la séparation de la logique et la réduction du couplage dans le code Decomplect-py ist ein Tool zur Analyse der Python-Designqualität, das dabei hilft, die Einfachheit, Trennung der Logik und Reduzierung der Kopplung im Code zu verbessern O Decomplect-Py é uma ferramenta de análise de código Python que ajuda a melhorar a qualidade do design do código. Ele oferece três analisadores: simplicity-analyzer, fcis-analyzer e coupling-analyzer. Decomplect-Py - это инструмент анализа кода Python, который помогает улучшить качество дизайна кода. Он предлагает три анализатора: simplicity-analyzer, fcis-analyzer и coupling-analyzer. Decomplect-Py هو أداة تحليل الكود بايثون التي تساعد على تحسين جودة تصميم الكود. يقدم ثلاثة محللين: simplicity-analyzer، fcis-analyzer و coupling-analyzer how to use decomplect-py decomplect-py setup guide decomplect-py alternative decomplect-py vs pylint decomplect-py install python design quality analysis decomplect-py documentation Decomplect-Py Python 设计质量 代码分析工具 AIエージェント Python 开发 代码优化 Runs three analyzers in parallel: simplicity, fcis, and coupling Supports specific analyzer execution via commands: --simplicity, --fcis, --coupling Provides refactoring capabilities between workers and tools Analyzes Python code design quality using simplicity-analyzer, fcis-analyzer, and coupling-analyzer decomplect-py is an architectural analysis tool for Python that assesses design quality and provides insights for improvement.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jbmiller10/semantik-plugin-template/semantik-plugin-development', 'community', 'jbmiller10', 'semantik-plugin-template', 'jbmiller10/semantik-plugin-template', 'semantik-plugin-development', 0, 0, 45, '2026-03-08T01:57:15.397Z', '2026-03-08T02:06:24.423Z', 'b05737da19ccfaa338f8ab9cd3b8962bbcb8fdd67de90c5bbdbdd6fa9ae96b6b', '{"id":"jbmiller10/semantik-plugin-template/semantik-plugin-development","name":"semantik-plugin-development","description":{"en":"The semantik-plugin-development skill enables developers to create custom plugins for Semantik, extending its capabilities for AI agents. This skill benefits developers working with semantic search engines.","zh":"Semantik 插件开发允许您扩展语义搜索引擎的功能，实现文档处理、嵌入、分块、重新排序、提取和 AI 代理的集成","ja":"Semantik プラグイン開発により、セマンティック検索エンジンの機能を拡張し、ドキュメント処理、埋め込み、チャンキング、再ランキング、抽出、AI エージェントの統合を実現","ko":"Semantik 플러그인 개발을 통해 의미 검색 엔진의 기능을 확장하고 문서 처리, 임베딩, 청킹, 재정렬, 추출 및 AI 에이전트 통합을 구현","es":"El desarrollo de plugins Semantik permite extender las capacidades del motor de búsqueda semántica para la ingesta de documentos, incrustación, chunking, reordenamiento, extracción y agentes de inteligencia artificial.","fr":"Le développement de plugins Semantik permet d''étendre les fonctionnalités du moteur de recherche sémantique pour l''ingestion de documents, l''incrustation, le chunking, le réordonnancement, l''extraction et les agents d''intelligence artificielle.","de":"Die Entwicklung von Semantik-Plugins ermöglicht die Erweiterung der Fähigkeiten der semantischen Suchmaschine für die Dokumentenverarbeitung, Einbettung, Chunking, Neusortierung, Extraktion und KI-Agents","pt":"O desenvolvimento de plugins Semantik permite estender as capacidades do mecanismo de busca semântico para documentação de ingestão, embutimento, chunking, reranking, extração e agentes de IA","ru":"Разработка плагинов Semantik позволяет расширить возможности самохостингового семантического поискового движка для документации по инжестии, эмбеддингу, чанкингу, реранкингу, экстракции и ИИ Агентов","ar":"تطوير البرامج المساعدة Semantik يسمح بتوسيع قدرات محرك البحث الدلالي لتوثيق عملية الابتلاع والتحويل والتجزئة وإعادة الترتيب والاستخراج والأدوات الذكية"},"seo":{"title":{"en":"semantik-plugin-development: Plugin Setup Guide for AI Ag...","zh":"Semantik 插件开发 Setup Guide - AIエージェント集成","ja":"Semantik プラグイン開発 Best Practices - AIエージェントとの連携","ko":"Semantik 플러그인 개발 가이드 - AI 에이전트 통합","es":"Desarrollo de Plugins Semantik: Guía de Configuración","fr":"Développement de Plugins Semantik: Meilleures Pratiques","de":"Semantik-Plugin-Entwicklung: Einrichtungsleitfaden","pt":"Desenvolvimento de Plugin Semantik: Guia de Configuração","ru":"Разработка Плагинов Semantik: Лучшие Практики для ИИ Агентов","ar":"تطوير البرامج المساعدة Semantik: دليل الإعداد للأدوات الذكية"},"description":{"en":"Unlock Semantik''s full potential with custom plugins. Learn how to develop and integrate plugins for document ingestion, embedding, and more. Get started now!","zh":"了解 Semantik 插件开发，扩展语义搜索引擎的功能，实现文档处理、嵌入、分块、重新排序、提取和 AI 代理的集成","ja":"Semantik プラグイン開発で、セマンティック検索エンジンの機能を拡張し、ドキュメント処理、埋め込み、チャンキング、再ランキング、抽出、AI エージェントの統合を実現","ko":"Semantik 플러그인 개발을 통해 의미 검색 엔진의 기능을 확장하고 문서 처리, 임베딩, 청킹, 재정렬, 추출 및 AI 에이전트 통합을 구현","es":"Aprende a crear plugins para Semantik, un motor de búsqueda semántica autoalojado, y amplía sus capacidades con Agentes de Inteligencia Artificial","fr":"Découvrez comment développer des plugins pour Semantik, un moteur de recherche sémantique auto-hébergé, et étendez ses fonctionnalités avec des Outils d''Inte...","de":"Erfahren Sie, wie Sie Plugins für Semantik, eine selbstgehostete semantische Suchmaschine, erstellen und erweitern können, mit KI-Agents","pt":"Aprenda a criar plugins para o mecanismo de busca semântico Semantik e estenda suas capacidades com documentação de ingestão, embutimento e reranking","ru":"Узнайте, как создавать плагины для самохостингового семантического поискового движка Semantik и расширьте его возможности с помощью документации по инжестии,...","ar":"تعلم كيفية إنشاء البرامج المساعدة لمحرك البحث الدلالي Semantik وتوسيع قدراته باستخدام توثيق过程 الابتلاع والتحويل والترتيب 다시 للأدوات الذكية"},"definition":{"en":"semantik-plugin-development is a skill that allows developers to create plugins for Semantik, a self-hosted semantic search engine, to extend its capabilities for document ingestion, embedding, and other tasks.","zh":"Semantik 插件开发是一种扩展语义搜索引擎功能的方法，实现文档处理和 AI 代理的集成","ja":"Semantik プラグイン開発は、セマンティック検索エンジンの機能を拡張する方法で、ドキュメント処理と AI エージェントの統合を実現","ko":"Semantik 플러그인 개발은 의미 검색 엔진의 기능을 확장하는 방법으로 문서 처리와 AI 에이전트 통합을 구현","es":"El desarrollo de plugins Semantik es la creación de complementos que amplían las capacidades de la búsqueda semántica","fr":"Le développement de plugins Semantik est la création de compléments qui étendent les fonctionnalités de la recherche sémantique","de":"Die Entwicklung von Semantik-Plugins ist die Erstellung von Erweiterungen, die die Fähigkeiten der semantischen Suche erweitern","pt":"Desenvolvimento de plugin Semantik é a criação de extensões para o mecanismo de busca semântico Semantik","ru":"Разработка плагинов Semantik - это создание расширений для самохостингового семантического поискового движка Semantik","ar":"تطوير البرامج المساعدة Semantik هو إنشاء ملحقات لمحرك البحث الدلالي Semantik"},"features":{"en":["Extends Semantik''s capabilities for document ingestion, embedding, chunking, reranking, extraction, and AI agents","Supports protocol version 1.0.0 with backwards compatibility","Allows plugins to run in-process with the main Semantik app","Enables customization of Semantik''s search engine functionality","Supports development of plugins for specific use cases, such as extraction and embedding"],"zh":["文档处理功能扩展","嵌入和分块支持","重新排序和提取功能","AI 代理集成","协议版本控制（当前版本 1.0.0）","安全性：插件运行在主 Semantik 应用程序进程中"],"ja":["ドキュメント処理機能の拡張","埋め込みとチャンキングのサポート","再ランキングと抽出機能","AI エージェントの統合","プロトコルバージョン管理（現在のバージョン 1.0.0）","セキュリティ：プラグインはメイン Semantik アプリケーションプロセスで実行"],"ko":["문서 처리 기능 확장","임베딩과 청킹 지원","재정렬과 추출 기능","AI 에이전트 통합","프로토콜 버전 관리（현재 버전 1.0.0）","보안：플러그인은 메인 Semantik 애플리케이션 프로세스에서 실행"],"es":["Extensión de capacidades para ingesta de documentos","Incrustación y chunking de documentos","Reordenamiento y extracción de información","Compatibilidad con agentes de inteligencia artificial","Protocolo de versión 1.0.0","Seguridad: ejecución de plugins en proceso con la aplicación principal"],"fr":["Extension des fonctionnalités pour l''ingestion de documents","Incrustation et chunking de documents","Réordonnancement et extraction d''informations","Compatibilité avec les outils d''intelligence artificielle","Protocole de version 1.0.0","Sécurité: exécution de plugins en processus avec l''application principale"],"de":["Erweiterung der Fähigkeiten für die Dokumentenverarbeitung","Einbettung und Chunking von Dokumenten","Neusortierung und Extraktion von Informationen","Kompatibilität mit KI-Agents","Protokoll-Version 1.0.0","Sicherheit: Ausführung von Plugins im Prozess mit der Hauptanwendung"],"pt":["Protocolo de versão 1.0.0","Extensão de capacidades de ingestão de documentos","Embutimento de documentos","Chunking e reranking de resultados","Extração de informações com agentes de IA"],"ru":["Протокол версии 1.0.0","Расширение возможностей инжестии документов","Эмбеддинг документов","Чанкинг и реранкинг результатов","Экстракция информации с помощью ИИ Агентов"],"ar":["بروتوكول الإصدار 1.0.0","توسيع قدرات ابتلاع المستندات","تحويل المستندات","تجزئة وإعادة ترتيب النتائج","استخراج المعلومات باستخدام الأدوات الذكية"]},"keywords":{"en":["how to develop semantik plugins","semantik-plugin-development tutorial","semantik plugin alternatives","semantik-plugin-development vs semantic search engines","semantik-plugin-development setup guide","semantik-plugin-development install","what is semantik-plugin-development","semantik-plugin-development documentation","semantik plugin development best practices"],"zh":["Semantik 插件开发","语义搜索引擎","AI 代理集成","文档处理","嵌入和分块","重新排序和提取","协议版本控制","安全性和性能"],"ja":["Semantik プラグイン開発","セマンティック検索エンジン","AI エージェントの統合","ドキュメント処理","埋め込みとチャンキング","再ランキングと抽出","プロトコルバージョン管理","セキュリティとパフォーマンス"],"ko":["Semantik 플러그인 개발","의미 검색 엔진","AI 에이전트 통합","문서 처리","임베딩과 청킹","재정렬과 추출","프로토콜 버전 관리","보안과 성능"],"es":["desarrollo de plugins Semantik","búsqueda semántica","agentes de inteligencia artificial","ingesta de documentos","incrustación y chunking","reordenamiento y extracción","protocolo de versión 1.0.0","seguridad de plugins","configuración de plugins Semantik"],"fr":["développement de plugins Semantik","recherche sémantique","outils d''intelligence artificielle","ingestion de documents","incrustation et chunking","réordonnancement et extraction","protocole de version 1.0.0","sécurité des plugins","configuration de plugins Semantik"],"de":["Entwicklung von Semantik-Plugins","semantische Suche","KI-Agents","Dokumentenverarbeitung","Einbettung und Chunking","Neusortierung und Extraktion","Protokoll-Version 1.0.0","Sicherheit von Plugins","Konfiguration von Semantik-Plugins"],"pt":["desenvolvimento de plugin Semantik","mecanismo de busca semântico","documentação de ingestão","embutimento de documentos","chunking e reranking","extração de informações com IA","agentes de IA","plugins Semantik"],"ru":["разработка плагинов Semantik","самохостинговый семантический поисковый движок","документация по инжестии","эмбеддинг документов","чанкинг и реранкинг","экстракция информации с помощью ИИ Агентов","ИИ Агенты","плагины Semantik"],"ar":["تطوير البرامج المساعدة Semantik","محرك بحث دلالي","توثيق عملية الابتلاع","تحويل المستندات","تجزئة وإعادة ترتيب","استخراج المعلومات باستخدام الأدوات الذكية","الأدوات الذكية","البرامج المساعدة Semantik"]}},"owner":"jbmiller10","repo":"semantik-plugin-template","repoPath":"jbmiller10/semantik-plugin-template","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.397Z","topics":[],"category":"community","skillMd":{"name":"semantik-plugin-development","description":"Create semantik plugins (connectors, embeddings, chunkers, rerankers, extractors, agents). Use when developing plugins, creating new integrations, or asking about plugin patterns, protocols, or testing.","bodyPreview":"# Semantik Plugin Development\n\nThis skill helps you create plugins for Semantik, a self-hosted semantic search engine. Plugins extend Semantik''s capabilities for document ingestion, embedding, chunking, reranking, extraction, and AI agents.\n\n## Protocol Version\n\n**Current Version:** 1.0.0\n\nBreaking changes to protocols increment the major version. Your plugins continue to work as long as they satisfy the protocol interface.\n\n## Security Note\n\nPlugins run **in-process** with the main Semantik app","body":"# Semantik Plugin Development\n\nThis skill helps you create plugins for Semantik, a self-hosted semantic search engine. Plugins extend Semantik''s capabilities for document ingestion, embedding, chunking, reranking, extraction, and AI agents.\n\n## Protocol Version\n\n**Current Version:** 1.0.0\n\nBreaking changes to protocols increment the major version. Your plugins continue to work as long as they satisfy the protocol interface.\n\n## Security Note\n\nPlugins run **in-process** with the main Semantik application (no sandboxing). Only install plugins you trust. See [Security Guide](security-guide.md) for details.\n\n## Quick Start\n\nCreate a minimal connector plugin in 5 minutes:\n\n```python\n# my_connector.py\nfrom typing import ClassVar, Any, AsyncIterator\nimport hashlib\n\nclass MyConnector:\n    PLUGIN_ID: ClassVar[str] = \"my-connector\"\n    PLUGIN_TYPE: ClassVar[str] = \"connector\"\n    PLUGIN_VERSION: ClassVar[str] = \"1.0.0\"\n\n    def __init__(self, config: dict[str, Any]) -> None:\n        self._config = config\n\n    async def authenticate(self) -> bool:\n        return True\n\n    async def load_documents(self, source_id: int | None = None) -> AsyncIterator[dict[str, Any]]:\n        content = \"Document content...\"\n        yield {\n            \"content\": content,\n            \"unique_id\": \"doc-1\",\n            \"source_type\": self.PLUGIN_ID,\n            \"metadata\": {},\n            \"content_hash\": hashlib.sha256(content.encode()).hexdigest(),\n        }\n\n    @classmethod\n    def get_config_fields(cls) -> list[dict[str, Any]]:\n        return []\n\n    @classmethod\n    def get_secret_fields(cls) -> list[dict[str, Any]]:\n        return []\n\n    @classmethod\n    def get_manifest(cls) -> dict[str, Any]:\n        return {\"id\": cls.PLUGIN_ID, \"type\": cls.PLUGIN_TYPE, \"version\": cls.PLUGIN_VERSION,\n                \"display_name\": \"My Connector\", \"description\": \"Custom connector\"}\n```\n\n---\n\n## Plugin Types\n\n| Type | Purpose | Key Method | Template |\n|------|---------|------------|----------|\n| `connector` | Ingest documents from sources | `load_documents()` | [connector.py](../../../templates/connector.py) |\n| `embedding` | Convert text to vectors | `embed_texts()` | [embedding.py](../../../templates/embedding.py) |\n| `chunking` | Split documents into chunks | `chunk()` | [chunking.py](../../../templates/chunking.py) |\n| `reranker` | Reorder search results | `rerank()` | [reranker.py](../../../templates/reranker.py) |\n| `extractor` | Extract entities/metadata | `extract()` | [extractor.py](../../../templates/extractor.py) |\n| `agent` | LLM-powered capabilities | `execute()` | [agent.py](../../../templates/agent.py) |\n\n**Type-specific guides:**\n- [Connector Guide](connector-guide.md) - Document sources, async iterators\n- [Embedding Guide](embedding-guide.md) - Query/document modes, dimensions\n- [Chunking Guide](chunking-guide.md) - Text segmentation strategies\n- [Reranker Guide](reranker-guide.md) - Cross-encoder reranking\n- [Extractor Guide](extractor-guide.md) - Entity and metadata extraction\n- [Agent Guide](agent-guide.md) - LLM agents, streaming, context\n\n**Cross-cutting guides:**\n- [Testing Guide](testing-guide.md) - Contract tests, mocks, fixtures\n- [Security Guide](security-guide.md) - Trust model, best practices\n- [Advanced Guide](advanced-guide.md) - Health checks, dependencies, migration\n\n---\n\n## Development Approach\n\n### Protocol-Based (Recommended)\n\nUse plain Python classes with no semantik imports. Plugins are validated by structural typing (duck typing):\n\n```python\nclass MyPlugin:\n    PLUGIN_ID: ClassVar[str] = \"my-plugin\"\n    PLUGIN_TYPE: ClassVar[str] = \"connector\"  # or embedding, chunking, etc.\n    PLUGIN_VERSION: ClassVar[str] = \"1.0.0\"\n    # ... implement required methods\n```\n\n**Benefits:**\n- Zero dependencies on semantik\n- Develop in separate repository\n- Distribute via PyPI or git\n- No version conflicts\n\n### ABC-Based (Advanced)\n\nInherit from semantik base classes when you need access to internal utilities:\n\n```python\nfrom shared.connectors.base import BaseConnector\n\nclass MyConnector(BaseConnector):\n    # ... inherit helper methods\n```\n\n**Use when:**\n- Building embedding plugins with GPU management\n- Need access to shared utilities\n- Developing internal/builtin plugins\n\n---\n\n## Required Class Variables\n\nEvery plugin must define:\n\n```python\nfrom typing import ClassVar, Any\n\nclass MyPlugin:\n    PLUGIN_ID: ClassVar[str] = \"my-plugin\"      # Unique ID (lowercase, hyphens)\n    PLUGIN_TYPE: ClassVar[str] = \"connector\"    # One of 6 types\n    PLUGIN_VERSION: ClassVar[str] = \"1.0.0\"     # Semantic version\n```\n\nSome plugin types require additional class variables:\n\n| Type | Additional Variables |\n|------|---------------------|\n| `connector` | `METADATA` (dict with name, description, icon) |\n| `embedding` | `INTERNAL_NAME`, `API_ID`, `PROVIDER_TYPE`, `METADATA` |\n| `chunking` | (none) |\n| `reranker` | (none) |\n| `extractor` | (none) |\n| `agent` | (none) |\n\n---\n\n## Manifest Method\n\nAll plugins must implement `get_manifest()`:\n\n```python\n@classmethod\ndef get_manifest(cls) -> dict[str, Any]:\n    return {\n        \"id\": cls.PLUGIN_ID,\n        \"type\": cls.PLUGIN_TYPE,\n        \"version\": cls.PLUGIN_VERSION,\n        \"display_name\": \"My Plugin\",\n        \"description\": \"What the plugin does\",\n        # Optional fields:\n        \"author\": \"Your Name\",\n        \"license\": \"MIT\",\n        \"homepage\": \"https://github.com/...\",\n        \"requires\": [\"other-plugin\"],  # Dependencies\n        \"capabilities\": {},  # Plugin-specific capabilities\n    }\n```\n\n---\n\n## Configuration\n\n### Config Fields (UI)\n\nDefine configuration fields for the Semantik UI:\n\n```python\n@classmethod\ndef get_config_fields(cls) -> list[dict[str, Any]]:\n    return [\n        {\n            \"name\": \"base_url\",\n            \"type\": \"text\",        # text, password, number, boolean, select\n            \"label\": \"Base URL\",\n            \"description\": \"API endpoint\",\n            \"required\": True,\n            \"placeholder\": \"https://api.example.com\",\n        },\n        {\n            \"name\": \"model\",\n            \"type\": \"select\",\n            \"label\": \"Model\",\n            \"options\": [\"model-a\", \"model-b\"],\n            \"default\": \"model-a\",\n        },\n    ]\n```\n\n### Secret Fields\n\nMark fields that contain secrets (encrypted at rest):\n\n```python\n@classmethod\ndef get_secret_fields(cls) -> list[dict[str, Any]]:\n    return [\n        {\"name\": \"api_key\", \"label\": \"API Key\", \"required\": True},\n    ]\n```\n\n### Environment Variables\n\nUse the `_env` suffix pattern for secrets:\n\n```python\n# In config schema - user enters env var name\n\"api_key_env\": \"OPENAI_API_KEY\"\n\n# At runtime, semantik resolves it\nconfig = {\"api_key\": \"sk-actual-key-value\"}  # Resolved\n```\n\n---\n\n## Testing\n\n### Manual Verification\n\n```bash\npip install -e .\npython -c \"\nfrom my_plugin import MyConnector\nprint(f''ID: {MyConnector.PLUGIN_ID}'')\nprint(f''Type: {MyConnector.PLUGIN_TYPE}'')\nprint(f''Manifest: {MyConnector.get_manifest()}'')\n\"\n```\n\n### Protocol Validation\n\n```python\nimport pytest\n\nclass TestMyPlugin:\n    def test_has_required_attributes(self):\n        assert hasattr(MyPlugin, \"PLUGIN_ID\")\n        assert hasattr(MyPlugin, \"PLUGIN_TYPE\")\n        assert hasattr(MyPlugin, \"PLUGIN_VERSION\")\n        assert MyPlugin.PLUGIN_TYPE == \"connector\"\n\n    def test_manifest_format(self):\n        manifest = MyPlugin.get_manifest()\n        assert \"id\" in manifest\n        assert \"type\" in manifest\n        assert \"display_name\" in manifest\n\n    @pytest.mark.asyncio\n    async def test_core_functionality(self):\n        plugin = MyPlugin(config={})\n        # Test plugin-specific methods\n```\n\n### With Semantik Test Mixins\n\nIf semantik is installed:\n\n```python\nfrom shared.plugins.testing.contracts import ConnectorProtocolTestMixin\n\nclass TestMyConnector(ConnectorProtocolTestMixin):\n    plugin_class = MyConnector\n```\n\n---\n\n## Packaging\n\n### pyproject.toml\n\n```toml\n[project]\nname = \"semantik-plugin-myconnector\"\nversion = \"1.0.0\"\nrequires-python = \">=3.10\"\ndependencies = []  # Your dependencies only\n\n[project.entry-points.\"semantik.plugins\"]\nmy-connector = \"my_plugin.connector:MyConnector\"\n\n[build-system]\nrequires = [\"hatchling\"]\nbuild-backend = \"hatchling.build\"\n```\n\nSee [templates/pyproject.toml](../../../templates/pyproject.toml) for a complete template.\n\n### Entry Point Format\n\n```\nplugin-id = \"module.path:ClassName\"\n```\n\n- `plugin-id`: Should match `PLUGIN_ID`\n- `module.path`: Python import path\n- `ClassName`: Your plugin class\n\n### Installation\n\n```bash\n# Development\npip install -e .\n\n# From git\npip install git+https://github.com/you/semantik-plugin-myconnector.git\n\n# Via Semantik API\nPOST /api/v2/plugins/install\n{\"install_command\": \"git+https://github.com/...\"}\n```\n\n---\n\n## Common Issues\n\n### Plugin Not Loading\n\n1. Check entry point is registered:\n   ```bash\n   pip show semantik-plugin-myconnector\n   ```\n\n2. Verify PLUGIN_TYPE is valid:\n   ```python\n   assert PLUGIN_TYPE in [\"connector\", \"embedding\", \"chunking\", \"reranker\", \"extractor\", \"agent\"]\n   ```\n\n3. Check for import errors:\n   ```python\n   try:\n       from my_plugin import MyConnector\n   except ImportError as e:\n       print(f\"Error: {e}\")\n   ```\n\n### Validation Errors\n\n| Error | Fix |\n|-------|-----|\n| `missing required keys: {''content''}` | Add all required fields to returned dict |\n| `Invalid role: ''xyz''` | Use valid string from MESSAGE_ROLES |\n| `content_hash must be 64 characters` | Use `hashlib.sha256(text.encode()).hexdigest()` |\n\n### Async Issues\n\nAll I/O methods must be async:\n\n```python\n# Wrong\ndef load_documents(self):\n    yield {\"content\": \"...\"}\n\n# Right\nasync def load_documents(self) -> AsyncIterator[dict]:\n    yield {\"content\": \"...\"}\n```\n\n---\n\n## Templates\n\nReady-to-use templates in `templates/`:\n\n| File | Description |\n|------|-------------|\n| `connector.py` | Document source connector |\n| `embedding.py` | Embedding model provider |\n| `chunking.py` | Text chunking strategy |\n| `reranker.py` | Search result reranker |\n| `extractor.py` | Entity/metadata extractor |\n| `agent.py` | LLM-powered agent |\n| `pyproject.toml` | Package configuration |\n\nCopy a template and modify:\n\n```bash\ncp templates/connector.py my_connector.py\n# Edit PLUGIN_ID, PLUGIN_VERSION, and implement methods\n```\n\n---\n\n## Data Format Reference\n\n### Connector Documents (IngestedDocumentDict)\n\n```python\n{\n    \"content\": str,              # Full text (required)\n    \"unique_id\": str,            # Unique identifier (required)\n    \"source_type\": str,          # Your PLUGIN_ID (required)\n    \"metadata\": dict,            # Source metadata (required)\n    \"content_hash\": str,         # SHA-256, 64 hex chars (required)\n    \"file_path\": str | None,     # Local path (optional)\n}\n```\n\n### Chunk Format (ChunkDict)\n\n```python\n{\n    \"content\": str,              # Chunk text (required)\n    \"metadata\": {                # Chunk metadata (required)\n        \"chunk_index\": int,\n        \"start_offset\": int,\n        \"end_offset\": int,\n    },\n    \"chunk_id\": str | None,      # Unique ID (optional)\n    \"embedding\": list[float] | None,  # Pre-computed (optional)\n}\n```\n\n### Rerank Result (RerankResultDict)\n\n```python\n{\n    \"index\": int,                # Original document index (required)\n    \"score\": float,              # Relevance score (required)\n    \"text\": str | None,          # Document text (optional)\n    \"metadata\": dict | None,     # Metadata (optional)\n}\n```\n\n### Agent Message (AgentMessageDict)\n\n```python\n{\n    \"id\": str,                   # Unique ID (required)\n    \"role\": str,                 # user, assistant, system, tool_call, tool_result, error\n    \"type\": str,                 # text, thinking, tool_use, tool_output, partial, final, error\n    \"content\": str,              # Message content (required)\n    \"timestamp\": str,            # ISO 8601 (required)\n    \"is_partial\": bool,          # Streaming partial (optional)\n    \"sequence_number\": int,      # Message order (optional)\n}\n```\n\n---\n\n## Getting Help\n\n- **Semantik docs**: See `semantik/docs/external-plugins.md` for protocol details\n- **Protocol reference**: See `semantik/docs/plugin-protocols.md` for full specifications\n- **Examples**: Check `semantik/packages/shared/plugins/builtins/` for built-in plugins\n"},"lastSynced":"2026-03-08T02:06:24.423Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing custom semantic search engine integration, such as extending document ingestion, embedding, and reranking capabilities.","zh":"适用于需要自定义语义搜索引擎集成的AI代理，例如扩展文档摄取、嵌入和重新排名的能力。","ja":"カスタムのセマンティック検索エンジン統合を必要とするAIエージェントに最適です。例えば、ドキュメントの摄取、埋め込み、並び替えの機能を拡張する場合など。","ko":"사용자 지정 의미 검색 엔진 통합이 필요한 AI 에이전트에 적합합니다. 문서摄取, 내장 및 재정렬 기능 확장 등","es":"Perfecto para agentes de IA que necesitan integración de motor de búsqueda semántica personalizado, como ampliar la ingesta de documentos, la incrustación y las capacidades de reordenamiento.","fr":"Parfait pour les agents IA ayant besoin d''une intégration de moteur de recherche sémantique personnalisée, telle que l''extension de l''ingestion de documents, de l''incrustation et des capacités de réorganisation.","de":"Perfekt für KI-Agents, die eine benutzerdefinierte Integration von semantischen Suchmaschinen benötigen, wie z. B. die Erweiterung der Dokumentenübernahme, der Einbettung und der Umrangierungs-Funktionen.","pt":"Perfeito para agentes de IA que necessitam de integração de mecanismo de busca semântico personalizado, como estender a ingestão de documentos, incorporação e capacidades de reclassificação.","ru":"Идеально для агентов ИИ, которым требуется настраиваемая интеграция семантического поискового движка, например, расширение ингестии документов, встраивания и возможностей переупорядочения.","ar":"مثالي لعميل الذكاء الاصطناعي الذين يحتاجون إلى دمج محرك بحث دلالية مخصص، مثل توسيع استهلاك الوثائق وتضمين وإعادة تصنيف القدرات."},"recommendation":{"en":"Empowers agents to create custom plugins for Semantik using protocol version 1.0.0, enabling advanced semantic search functionalities like chunking, extraction, and AI agent integration, all while ensuring compatibility through the protocol interface.","zh":"赋予代理创建使用协议版本1.0.0的Semantik自定义插件的能力，实现高级语义搜索功能，例如分块、提取和AI代理集成，同时通过协议接口确保兼容性。","ja":"バージョン1.0.0のプロトコルを使用して、Semantikのカスタムプラグインを作成するエージェントの能力を提供します。これにより、チャンキング、抽出、AIエージェント統合などの高度なセマンティック検索機能を実現しながら、プロトコルインターフェースを介して互換性を確保します。","ko":"에이전트가 프로토콜 버전 1.0.0을 사용하여 Semantik의 사용자 지정 플러그인을 생성할 수 있는 기능을 제공하여 분할, 추출, AI 에이전트 통합 등의 고급 의미 검색 기능을 제공同时 프로토콜 인터페이스를 통해 호환성을 보장합니다.","es":"Habilita a los agentes a crear complementos personalizados para Semantik utilizando la versión de protocolo 1.0.0, lo que permite funcionalidades de búsqueda semántica avanzadas como chunking, extracción e integración de agente de IA, todo mientras se garantiza la compatibilidad a través de la interfaz de protocolo.","fr":"Autonomise les agents à créer des plug-ins personnalisés pour Semantik en utilisant la version de protocole 1.0.0, permettant ainsi des fonctionnalités de recherche sémantique avancées comme le chunking, l''extraction et l''intégration d''agent IA, le tout en garantissant la compatibilité via l''interface de protocole.","de":"Ermöglicht es Agenten, benutzerdefinierte Plug-ins für Semantik mit der Protokollversion 1.0.0 zu erstellen, wodurch erweiterte semantische Suchfunktionen wie Chunking, Extraktion und KI-Agent-Integration ermöglicht werden, während die Kompatibilität durch die Protokoll-Schnittstelle gewährleistet wird.","pt":"Habilita os agentes a criar plugins personalizados para Semantik usando a versão 1.0.0 do protocolo, permitindo funcionalidades de pesquisa semântica avançadas como chunking, extração e integração de agentes de IA, garantindo compatibilidade através da interface do protocolo.","ru":"Наделяет агентов возможностью создавать пользовательские плагины для Semantik с использованием версии 1.0.0 протокола, обеспечивая расширенные функции семантического поиска, такие как chunking, извлечение и интеграция агентов ИИ, гарантируя совместимость через интерфейс протокола.","ar":"يمنح الوكلاء khảية إنشاء ملحقات مخصصة لبرنامج Semantik باستخدام إصدار 1.0.0 من البروتوكول، مما يتيح وظائف بحث دلالية متقدمة مثل chunking و الاستخراج و دمج عميل الذكاء الاصطناعي، مع ضمان التوافق من خلال واجهة البروتوكول."},"useCases":{"en":["Extending document ingestion for specialized data formats","Creating custom embedding models for improved search results","Developing plugins for reranking search queries based on specific criteria"],"zh":["扩展用于专用数据格式的文档摄取","创建自定义嵌入模型以提高搜索结果","开发用于根据特定标准重新排名搜索查询的插件"],"ja":["特殊なデータ形式のドキュメントの摄取を拡張する","検索結果の向上のためのカスタム埋め込みモデルを作成する","特定の基準に基づいて検索クエリを再ランキングするためのプラグインを開発する"],"ko":["특별한 데이터 형식의 문서摄取 확장","검색 결과 개선을 위한 사용자 지정 임베딩 모델 생성","특정 기준에 따라 검색 쿼리 재정렬을 위한 플러그인 개발"],"es":["Ampliar la ingesta de documentos para formatos de datos especializados","Crear modelos de incrustación personalizados para mejorar los resultados de búsqueda","Desarrollar plug-ins para reordenar consultas de búsqueda según criterios específicos"],"fr":["Étendre l''ingestion de documents pour des formats de données spécialisés","Créer des modèles d''incrustation personnalisés pour améliorer les résultats de recherche","Développer des plug-ins pour réorganiser les requêtes de recherche en fonction de critères spécifiques"],"de":["Erweitern der Dokumentenübernahme für spezielle Datenformate","Erstellen benutzerdefinierter Einbettungsmodelle für verbesserte Suchergebnisse","Entwickeln von Plug-ins zur Umrangierung von Suchabfragen basierend auf spezifischen Kriterien"],"pt":["Estender a ingestão de documentos para formatos de dados especializados","Criar modelos de incorporação personalizados para melhorar os resultados da pesquisa","Desenvolver plugins para reclassificar consultas de pesquisa com base em critérios específicos"],"ru":["Расширить ингестию документов для специализированных форматов данных","Создать пользовательские модели встраивания для улучшения результатов поиска","Разработать плагины для переупорядочения поисковых запросов на основе конкретных критериев"],"ar":["توسيع استهلاك الوثائق لتنسيقات بيانات متخصصة","إنشاء نماذج تضمين مخصصة لتحسين نتائج البحث","تطوير ملحقات لإعادة تصنيف استفسارات البحث بناءً على معايير محددة"]},"limitations":{"en":["Plugins run in-process with the main Semantik app, requiring careful security considerations","Compatibility dependent on adherence to the Semantik protocol interface"],"zh":["插件在主Semantik应用程序中运行，需要谨慎的安全考虑","兼容性取决于遵守Semantik协议接口"],"ja":["プラグインはメインのSemantikアプリケーション内で実行されるため、慎重なセキュリティ対策が必要","互換性はSemantikプロトコルインターフェースへの準拠に依存する"],"ko":["플러그인이 주요 Semantik 애플리케이션에서 실행되므로 주의 깊은 보안 고려가 필요합니다.","호환성은 Semantik 프로토콜 인터페이스 준수에 따라 달라집니다."],"es":["Los complementos se ejecutan en proceso con la aplicación principal de Semantik, lo que requiere cuidadosas consideraciones de seguridad","La compatibilidad depende del cumplimiento de la interfaz de protocolo de Semantik"],"fr":["Les plug-ins s''exécutent en processus avec l''application principale de Semantik, ce qui nécessite des considérations de sécurité minutieuses","La compatibilité dépend de l''adéquation à l''interface de protocole de Semantik"],"de":["Die Plug-ins werden im Prozess mit der Hauptanwendung von Semantik ausgeführt, was sorgfältige Sicherheitsüberlegungen erfordert","Die Kompatibilität hängt von der Einhaltung der Semantik-Protokoll-Schnittstelle ab"],"pt":["Os plugins são executados em processo com o aplicativo Semantik principal, exigindo considerações de segurança cuidadosas","Compatibilidade dependente da aderência à interface do protocolo Semantik"],"ru":["Плагины выполняются в процессе с основным приложением Semantik, требуя тщательных соображений безопасности","Совместимость зависит от соблюдения интерфейса протокола Semantik"],"ar":["تعمل الإضافات في عملية مع تطبيق Semantik الرئيسي، مما يتطلب考虑ات أمنية محددة","التوافق يعتمد على الالتزام بواجهة بروتوكول Semantik"]},"version":4},"contentHash":"b05737da19ccfaa338f8ab9cd3b8962bbcb8fdd67de90c5bbdbdd6fa9ae96b6b","qualityScore":45}');
