INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jbmiller10/semantik-plugin-template/semantik-plugin-development', 'semantik-plugin-development', 'jbmiller10', 'semantik-plugin-template', 'community', 'semantik-plugin-development jbmiller10 semantik-plugin-template community The semantik-plugin-development skill enables developers to create custom plugins for Semantik, extending its capabilities for AI agents. This skill benefits developers working with semantic search engines. Semantik 插件开发允许您扩展语义搜索引擎的功能，实现文档处理、嵌入、分块、重新排序、提取和 AI 代理的集成 Semantik プラグイン開発により、セマンティック検索エンジンの機能を拡張し、ドキュメント処理、埋め込み、チャンキング、再ランキング、抽出、AI エージェントの統合を実現 Semantik 플러그인 개발을 통해 의미 검색 엔진의 기능을 확장하고 문서 처리, 임베딩, 청킹, 재정렬, 추출 및 AI 에이전트 통합을 구현 El desarrollo de plugins Semantik permite extender las capacidades del motor de búsqueda semántica para la ingesta de documentos, incrustación, chunking, reordenamiento, extracción y agentes de inteligencia artificial. Le développement de plugins Semantik permet d''étendre les fonctionnalités du moteur de recherche sémantique pour l''ingestion de documents, l''incrustation, le chunking, le réordonnancement, l''extraction et les agents d''intelligence artificielle. Die Entwicklung von Semantik-Plugins ermöglicht die Erweiterung der Fähigkeiten der semantischen Suchmaschine für die Dokumentenverarbeitung, Einbettung, Chunking, Neusortierung, Extraktion und KI-Agents O desenvolvimento de plugins Semantik permite estender as capacidades do mecanismo de busca semântico para documentação de ingestão, embutimento, chunking, reranking, extração e agentes de IA Разработка плагинов Semantik позволяет расширить возможности самохостингового семантического поискового движка для документации по инжестии, эмбеддингу, чанкингу, реранкингу, экстракции и ИИ Агентов تطوير البرامج المساعدة Semantik يسمح بتوسيع قدرات محرك البحث الدلالي لتوثيق عملية الابتلاع والتحويل والتجزئة وإعادة الترتيب والاستخراج والأدوات الذكية how to develop semantik plugins semantik-plugin-development tutorial semantik plugin alternatives semantik-plugin-development vs semantic search engines semantik-plugin-development setup guide semantik-plugin-development install what is semantik-plugin-development semantik-plugin-development documentation semantik plugin development best practices Semantik 插件开发 语义搜索引擎 AI 代理集成 文档处理 嵌入和分块 重新排序和提取 协议版本控制 安全性和性能 Extends Semantik''s capabilities for document ingestion, embedding, chunking, reranking, extraction, and AI agents Supports protocol version 1.0.0 with backwards compatibility Allows plugins to run in-process with the main Semantik app Enables customization of Semantik''s search engine functionality Supports development of plugins for specific use cases, such as extraction and embedding semantik-plugin-development is a skill that allows developers to create plugins for Semantik, a self-hosted semantic search engine, to extend its capabilities for document ingestion, embedding, and other tasks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fefogarcia/approved-skills/project-workflow', 'community', 'fefogarcia', 'approved-skills', 'fefogarcia/approved-skills', 'project-workflow', 0, 0, 45, '2026-03-08T01:57:15.402Z', '2026-03-08T02:06:47.000Z', 'fccd42a49848b65d2902f2c5361f5d6df35e8f3576742d0df7874ef4b1fda9ff', '{"id":"fefogarcia/approved-skills/project-workflow","name":"project-workflow","description":{"en":"The project-workflow skill automates the project lifecycle, from idea validation to release, saving developers 35-55 minutes per project. It integrates 9 slash commands for a seamless experience.","zh":"Project Workflow AIエージェント提供9个集成的斜杠命令，实现项目生命周期自动化","ja":"プロジェクトワークフローAIエージェントは、9つの統合されたスラッシュコマンドを提供し、プロジェクトライフサイクルを自動化","ko":"프로젝트 워크플로우 AI 에이전트는 9개의 통합된 슬래시 명령을 제공하여 프로젝트 生命周期를 자동화","es":"Project-workflow es un conjunto de habilidades de agente de IA que automatiza el ciclo de vida de los proyectos con 9 comandos integrados","fr":"Project-workflow est un ensemble de compétences d''agent IA qui automatisent le cycle de vie des projets avec 9 commandes intégrées","de":"Project-workflow ist ein Satz von Fähigkeiten des IA-Agents, der den Projekt-Lebenszyklus mit 9 integrierten Befehlen automatisiert","pt":"O Project Workflow é um skill aprovado pela equipe DodaTech que automatiza o ciclo de vida do projeto com 9 comandos integrados","ru":"Project Workflow - это навык, утвержденный командой DodaTech, который автоматизирует жизненный цикл проекта с помощью 9 интегрированных команд","ar":"Project Workflow هو مهارة معتمدة من فريق DodaTech التي تautomatiza دورة حياة المشروع مع 9 أوامر مدمجة"},"seo":{"title":{"en":"project-workflow: Automated Project Lifecycle Setup Guide...","zh":"Project Workflow Setup Guide - AIエージェント集成","ja":"プロジェクトワークフロー設定ガイド - AIエージェント","ko":"프로젝트 워크플로우 설정 가이드 - AI 에이전트","es":"Guía de configuración de project-workflow para automatiza...","fr":"Guide de configuration de project-workflow pour l''automat...","de":"Einrichtungsanleitung für project-workflow zur Automatisi...","pt":"Guia de Configuração do Project Workflow para Automatizaç...","ru":"Настройка Project Workflow: ИИ Агенты для Автоматизации П...","ar":"دليل إعداد Project Workflow لتحسين مشروعك"},"description":{"en":"Discover how to streamline your project workflow with 9 integrated slash commands. Learn how to install and use project-workflow to save 35-55 minutes per pr...","zh":"使用Project Workflow AIエージェント，实现项目生命周期自动化，节省35-55分钟","ja":"プロジェクトワークフローAIエージェントを使用して、プロジェクトライフサイクルを自動化し、35-55分を節約","ko":"프로젝트 워크플로우 AI 에이전트를 사용하여 프로젝트 生命周期를 자동화하고 35-55분을 절약","es":"Aprende a configurar project-workflow para ahorrar 35-55 minutos por ciclo de vida de proyecto con 9 comandos integrados de automatización","fr":"Découvrez comment configurer project-workflow pour gagner 35-55 minutes par cycle de vie de projet avec 9 commandes intégrées d''automatisation","de":"Erfahren Sie, wie Sie project-workflow konfigurieren, um 35-55 Minuten pro Projekt-Lebenszyklus mit 9 integrierten Automatisierungsbefehlen zu sparen","pt":"Aprenda a configurar o Project Workflow e economize 35-55 minutos por ciclo de vida do projeto com 9 comandos integrados","ru":"Узнайте, как настроить Project Workflow и сэкономить 35-55 минут на каждом проекте с помощью 9 интегрированных команд","ar":"تعرف على كيفية إعداد Project Workflow وتوفير 35-55 دقيقة لكل دورة حياة للمشروع مع 9 أوامر مدمجة"},"definition":{"en":"project-workflow is a DodaTech team-approved AI agent skill that automates the project lifecycle using 9 integrated slash commands","zh":"Project Workflow AIエージェント是一种自动化项目生命周期的工具","ja":"プロジェクトワークフローAIエージェントは、プロジェクトライフサイクルを自動化するツール","ko":"프로젝트 워크플로우 AI 에이전트는 프로젝트 生命周期를 자동화하는 도구","es":"Project-workflow es una herramienta de automatización de ciclo de vida de proyectos que utiliza comandos de automatización para ahorrar tiempo","fr":"Project-workflow est un outil d''automatisation du cycle de vie des projets qui utilise des commandes d''automatisation pour gagner du temps","de":"Project-workflow ist ein Tool zur Automatisierung des Projekt-Lebenszyklus, das Automatisierungsbefehle verwendet, um Zeit zu sparen","pt":"O Project Workflow é um conjunto de comandos que automatizam o ciclo de vida do projeto, desde a validação de ideias até a execução","ru":"Project Workflow - это набор команд, которые автоматизируют жизненный цикл проекта, от проверки идей до выполнения","ar":"Project Workflow هو مجموعة من الأوامر التي تautomatiza دورة حياة المشروع, من التحقق من الأفكار إلى التنفيذ"},"features":{"en":["9 integrated slash commands for complete project lifecycle automation","Supports installation via `/plugin install project-workflow@jezweb-skills` command","Manual installation by copying `commands/*.md` to `~/.claude/commands/` directory","Includes `/explore-idea` command for pre-planning exploration","Enables session management and context preservation"],"zh":["9个集成的斜杠命令","项目生命周期自动化","支持idea验证、规划、执行、会话管理、上下文保留和发布","使用/explore-idea命令进行预规划探索","支持Time savings：35-55分钟"],"ja":["9つの統合されたスラッシュコマンド","プロジェクトライフサイクル自動化","アイデア検証、計画、実行、セッション管理、コンテキスト保存、リリースをサポート","/explore-ideaコマンドを使用した予備計画探索","Time savings：35-55分をサポート"],"ko":["9개의 통합된 슬래시 명령","프로젝트 生命周期 자동화","아이디어 검증, 계획, 실행, 세션 관리, 컨텍스트 보존, 릴리즈를 지원","/explore-idea 명령을 사용한 예비 계획 탐색","Time savings：35-55분을 지원"],"es":["9 comandos integrados de automatización para el ciclo de vida de los proyectos","Compatibilidad con entornos remotos y seguridad escaneada","Instalación sencilla a través del marketplace o manual","Comandos personalizados para la exploración de ideas y la planificación de proyectos","Automatización de la gestión de sesiones y la preservación de contexto","Integración con herramientas de desarrollo para una mayor eficiencia"],"fr":["9 commandes intégrées d''automatisation pour le cycle de vie des projets","Compatibilité avec les environnements distants et sécurité scannée","Installation facile via le marketplace ou manuelle","Commandes personnalisées pour l''exploration d''idées et la planification de projets","Automatisation de la gestion de sessions et de la préservation de contexte","Intégration avec des outils de développement pour une plus grande efficacité"],"de":["9 integrierte Automatisierungsbefehle für den Projekt-Lebenszyklus","Kompatibilität mit Remote-Umgebungen und gescannter Sicherheit","Einfache Installation über den Marketplace oder manuell","Benutzerdefinierte Befehle für die Ideenexploration und Projektplanung","Automatisierung der Sitzungsverwaltung und Kontexterhaltung","Integration mit Entwicklungstools für eine höhere Effizienz"],"pt":["9 comandos integrados para automação do ciclo de vida do projeto","Validação de ideias com o comando /explore-idea","Planejamento e execução de projetos com comandos personalizados","Gerenciamento de sessões e preservação de contexto","Economia de 35-55 minutos por ciclo de vida do projeto"],"ru":["9 интегрированных команд для автоматизации жизненного цикла проекта","Проверка идей с помощью команды /explore-idea","Планирование и выполнение проектов с помощью индивидуальных команд","Управление сессиями и сохранение контекста","Экономия 35-55 минут на каждом проекте"],"ar":["9 أوامر مدمجة لتحسين دورة حياة المشروع","التحقق من الأفكار باستخدام الأمر /explore-idea","التخطيط والتنفيذ للمشاريع بأوامر مخصصة","إدارة الجلسات وحفظ السياق","توفير 35-55 دقيقة لكل دورة حياة للمشروع"]},"keywords":{"en":["how to use project-workflow","project-workflow install guide","project-workflow setup tutorial","what is project-workflow","project-workflow alternative","project-workflow vs other automation tools","project-workflow automated project lifecycle","project-workflow time savings","project-workflow for developers"],"zh":["Project Workflow AIエージェント","项目生命周期自动化","斜杠命令","idea验证","规划","执行","会话管理","上下文保留","发布"],"ja":["プロジェクトワークフローAIエージェント","プロジェクトライフサイクル自動化","スラッシュコマンド","アイデア検証","計画","実行","セッション管理","コンテキスト保存","リリース"],"ko":["프로젝트 워크플로우 AI 에이전트","프로젝트 生命周期 자동화","슬래시 명령","아이디어 검증","계획","실행","세션 관리","컨텍스트 보존","릴리즈"],"es":["project-workflow","automatización de ciclo de vida de proyectos","herramientas de agente de IA","comandos de automatización","entornos remotos","seguridad escaneada","desarrollo de proyectos","gestión de sesiones","preservación de contexto","integración con herramientas de desarrollo"],"fr":["project-workflow","automatisation du cycle de vie des projets","outils d''agent IA","commandes d''automatisation","environnements distants","sécurité scannée","développement de projets","gestion de sessions","préservation de contexte","intégration avec des outils de développement"],"de":["project-workflow","Automatisierung des Projekt-Lebenszyklus","IA-Agent-Tools","Automatisierungsbefehle","Remote-Umgebungen","gescannte Sicherheit","Projektentwicklung","Sitzungsverwaltung","Kontexterhaltung","Integration mit Entwicklungstools"],"pt":["project workflow","automação de projetos","validação de ideias","planejamento de projetos","execução de projetos","gerenciamento de sessões","preservação de contexto","economia de tempo"],"ru":["project workflow","автоматизация проектов","проверка идей","планирование проектов","выполнение проектов","управление сессиями","сохранение контекста","экономия времени","ИИ Агенты"],"ar":["project workflow","تحسين مشاريع","التحقق من الأفكار","تخطيط المشاريع","تنفيذ المشاريع","إدارة الجلسات","حفظ السياق","توفير الوقت","أدوات الذكاء الاصطناعي"]}},"owner":"fefogarcia","repo":"approved-skills","repoPath":"fefogarcia/approved-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.402Z","topics":[],"category":"community","skillMd":{"name":"project-workflow","description":"|","bodyPreview":"# Project Workflow Skill\n\n9 integrated slash commands for complete project lifecycle automation: idea validation → planning → execution → session management → context preservation → release.\n\n**Time savings**: 35-55 minutes per project lifecycle\n\n## Installation\n\n**Marketplace**: `/plugin install project-workflow@jezweb-skills`\n\n**Manual**: Copy `commands/*.md` to `~/.claude/commands/`\n\n## The 9 Commands\n\n### 1. `/explore-idea` - Pre-Planning Exploration\n\n**Use when**: Rough idea that needs tech","body":"# Project Workflow Skill\n\n9 integrated slash commands for complete project lifecycle automation: idea validation → planning → execution → session management → context preservation → release.\n\n**Time savings**: 35-55 minutes per project lifecycle\n\n## Installation\n\n**Marketplace**: `/plugin install project-workflow@jezweb-skills`\n\n**Manual**: Copy `commands/*.md` to `~/.claude/commands/`\n\n## The 9 Commands\n\n### 1. `/explore-idea` - Pre-Planning Exploration\n\n**Use when**: Rough idea that needs tech stack validation, scope management, or research before planning.\n\n**Creates**: PROJECT_BRIEF.md with validated decisions → hands off to /plan-project\n\n**Time savings**: 10-15 min\n\n---\n\n### 2. `/plan-project` - Generate Project Planning Docs\n\n**Use when**: Starting new project with clear requirements, or after /explore-idea.\n\n**Creates**: IMPLEMENTATION_PHASES.md, SESSION.md, DATABASE_SCHEMA.md (if needed), API_ENDPOINTS.md (if needed), ARCHITECTURE.md\n\n**Invokes**: project-planning skill\n\n**Time savings**: 5-7 min\n\n---\n\n### 3. `/plan-feature` - Add Features to Existing Projects\n\n**Use when**: Adding feature to existing project with SESSION.md + IMPLEMENTATION_PHASES.md.\n\n**Does**: Generates new phases via project-planning skill, integrates into IMPLEMENTATION_PHASES.md with renumbering, updates SESSION.md.\n\n**Time savings**: 7-10 min\n\n---\n\n### 4. `/wrap-session` - End-of-Session Checkpoint\n\n**Use when**: Context full (>150k tokens), end of work session, or before task switch.\n\n**Does**: Task agent analyzes session → updates SESSION.md (progress, Next Action, blockers) → git checkpoint commit → formatted handoff summary.\n\n**Time savings**: 2-3 min\n\n---\n\n### 5. `/continue-session` - Start-of-Session Context Loading\n\n**Use when**: Starting new session or after /wrap-session checkpoint.\n\n**Does**: Explore agent loads SESSION.md + planning docs → shows git history + session summary (phase, progress, Next Action, blockers) → optionally opens file → asks permission to continue.\n\n**Time savings**: 1-2 min\n\n---\n\n### 6. `/workflow` - Interactive Workflow Guide\n\n**Use when**: First time user, unsure which command to use, or need quick reference.\n\n**Does**: Shows all 9 commands → context-aware guidance with decision trees → offers to execute appropriate command.\n\n---\n\n### 7. `/release` - Pre-Release Safety Checks\n\n**Use when**: Ready to push to public GitHub or create release.\n\n**8 Phases**:\n1. **Critical Safety** (BLOCKERS): Secrets scan (gitleaks), personal artifacts check, git remote verification\n2. **Documentation** (REQUIRED): LICENSE, README (>100 words), CONTRIBUTING.md (>500 LOC), CODE_OF_CONDUCT (>1000 LOC)\n3. **Configuration**: .gitignore, package.json, git branch warning\n4. **Quality** (NON-BLOCKING): Build test, npm audit, large files (>1MB)\n5. **Report**: Blockers/warnings/recommendations + safe to release verdict\n6-8. **Auto-Fix & Publish**: Fix issues, release prep commit, optional git tag + GitHub release\n\n**Time savings**: 10-15 min\n\n---\n\n### 8. `/brief` - Context Preservation Document\n\n**Use when**: Before clearing context, to preserve key decisions and requirements for future sessions.\n\n**Creates**: `docs/brief-[slug].md` with extracted information from current conversation.\n\n**Does**: Analyzes conversation → extracts what''s being built, decisions made, technical details → creates organized markdown file → optionally creates GitHub issue for tracking.\n\n**Time savings**: 3-5 min\n\n---\n\n### 9. `/reflect` - Capture Operational Knowledge\n\n**Use when**: Before context compaction, after completing significant work, or when valuable learnings accumulated.\n\n**Does**: Reviews conversation → identifies workflows discovered, patterns learned, tool sequences, corrections made → routes each learning to appropriate destination (rules, CLAUDE.md, skills, docs) → optionally suggests automation (scripts, commands, custom agents).\n\n**Key Feature**: Considers whether processes should become custom agents when they require reasoning/decisions, benefit from parallel execution, or involve research/exploration.\n\n**Time savings**: 5-10 min\n\n---\n\n## Workflow Examples\n\n**Full**: /explore-idea → /plan-project → work → /wrap-session → /continue-session → /plan-feature (if needed) → repeat → /reflect → /release\n\n**Quick** (clear requirements): /plan-project → work → /wrap-session → /continue-session → /release\n\n**Context Preservation**: /brief (before clearing context), /reflect (capture learnings)\n\n**Helpers**: /workflow (guidance), /plan-feature (add feature), /release (publish)\n\n---\n\n## Integration\n\n**project-planning**: Invoked by /plan-project and /plan-feature (generates IMPLEMENTATION_PHASES.md, DATABASE_SCHEMA.md, API_ENDPOINTS.md)\n\n**project-session-management**: SESSION.md protocol for /wrap-session and /continue-session\n\n**Claude Code agents**: /wrap-session (Task agent), /continue-session + /explore-idea (Explore agent)\n\n---\n\n## Command Relationships\n\n```\nEXPLORATION PHASE\n/explore-idea (optional)\n    ↓\n    Creates PROJECT_BRIEF.md\n    ↓\nPLANNING PHASE\n/plan-project (reads PROJECT_BRIEF.md if exists)\n    ↓\n    Creates IMPLEMENTATION_PHASES.md + SESSION.md\n    ↓\nEXECUTION PHASE\nWork on phases\n    ↓\n/wrap-session (when context full)\n    ↓\n    Updates SESSION.md, git checkpoint\n    ↓\n/continue-session (new session)\n    ↓\n    Loads SESSION.md, continues work\n    ↓\n/plan-feature (when need new features)\n    ↓\n    Adds phases to IMPLEMENTATION_PHASES.md\n    ↓\nContinue wrap → resume cycle\n    ↓\nCONTEXT PRESERVATION\n/brief (before clearing context)\n    ↓\n    Creates docs/brief-[slug].md\n    ↓\n/reflect (capture learnings)\n    ↓\n    Routes knowledge to rules, docs, CLAUDE.md\n    ↓\nRELEASE PHASE\n/release (when ready to publish)\n    ↓\n    Safety checks → GitHub release\n\nHELPER\n/workflow (anytime)\n    ↓\n    Interactive guidance\n```\n\n---\n\n## Time Savings Breakdown\n\n| Command | Time Saved | Tasks Automated |\n|---------|------------|-----------------|\n| `/explore-idea` | 10-15 min | Research, validation, scope management, tech stack evaluation |\n| `/plan-project` | 5-7 min | Planning doc generation, git setup, phase structuring |\n| `/plan-feature` | 7-10 min | Feature planning, phase integration, doc updates |\n| `/wrap-session` | 2-3 min | SESSION.md updates, git checkpoint, handoff summary |\n| `/continue-session` | 1-2 min | Context loading, git history review, next action display |\n| `/workflow` | Instant | Navigation, decision trees, command selection |\n| `/release` | 10-15 min | Secret scanning, doc validation, build testing, release creation |\n| `/brief` | 3-5 min | Context extraction, decisions capture, markdown generation |\n| `/reflect` | 5-10 min | Learning extraction, knowledge routing, automation suggestions |\n\n**Total per project lifecycle:** 45-70 minutes\n\n---\n\n## Prerequisites\n\n**All**: Claude Code CLI, git repo (recommended)\n\n**/plan-feature**: Existing SESSION.md + IMPLEMENTATION_PHASES.md\n\n**/wrap-session, /continue-session**: SESSION.md (created by /plan-project)\n\n**/release**: Git repo with commits, package.json (Node.js), remote URL (for publishing)\n\n---\n\n## Troubleshooting\n\n**/plan-project \"No project description\"**: Use /explore-idea first or discuss project with Claude\n\n**/plan-feature \"Prerequisites not met\"**: Run /plan-project first (creates SESSION.md + IMPLEMENTATION_PHASES.md)\n\n**/wrap-session \"No git repository\"**: Run `git init`\n\n**/continue-session \"SESSION.md not found\"**: Run /plan-project\n\n**/release \"Secrets detected\"**: Add to .gitignore, remove from git history\n\n---\n\n## Version History\n\n**1.1.0** (2026-01-11)\n- Added `/brief` command for context preservation\n- Added `/reflect` command for capturing operational knowledge\n- `/reflect` now suggests custom agents for processes requiring reasoning\n- Total commands: 9\n\n**1.0.0** (2025-11-12)\n- Initial release\n- 7 integrated slash commands\n- Plugin marketplace distribution\n- Command bundling via plugin.json\n\n---\n\n**Issues**: https://github.com/jezweb/claude-skills/issues | **Author**: Jeremy Dawes (jeremy@jezweb.net) | **License**: MIT\n"},"lastSynced":"2026-03-08T02:06:47.000Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined project lifecycle automation and time-saving workflow integrations.","zh":"非常适合需要简化项目生命周期自动化和时间节省工作流集成的开发代理。","ja":"開発エージェントがプロジェクトのライフサイクルを自動化し、時間を節約できるワークフローの統合を必要とする場合に最適です。","ko":"프로젝트 생명주기 자동화 및 시간 절약 워크플로 통합이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una automatización del ciclo de vida del proyecto optimizada y una integración de flujos de trabajo que ahorre tiempo.","fr":"Parfait pour les agents de développement qui ont besoin d''une automatisation du cycle de vie du projet rationalisée et d''une intégration de flux de travail gain de temps.","de":"Perfekt für Entwicklungsmittelstände, die eine optimierte Automatisierung des Projekt-Lebenszyklus und eine zeitsparende Arbeitsablauf-Integration benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de automação de ciclo de vida de projeto simplificada e integrações de fluxo de trabalho que economizam tempo.","ru":"Идеально подходит для агентов разработки, которым требуется упрощенная автоматизация жизненного цикла проекта и интеграция рабочих процессов, экономящая время.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى автомatisation دورة حياة المشروع简化 وتكاملات سير العمل التي توفر الوقت."},"recommendation":{"en":"Empowers agents to automate the project lifecycle, from idea validation to release, utilizing 9 integrated slash commands for seamless execution, session management, and context preservation, saving 35-55 minutes per project.","zh":"赋予代理人自动化项目生命周期的能力，从想法验证到发布，利用 9 个集成的斜杠命令实现无缝执行、会话管理和上下文保留，每个项目节省 35-55 分钟。","ja":"エージェントがプロジェクトのライフサイクルを自動化する機能を提供し、アイデアの検証からリリースまで、9 つの統合されたスラッシュコマンドを使用してシームレスに実行し、セッション管理とコンテキスト保留を行い、各プロジェクトで 35-55 分を節約します。","ko":"에이전트가 프로젝트 생명주기를 자동화 할 수 있는 능력을 부여하여 아이디어 검증에서 출시까지 9개의 통합 슬래시 명령을 사용하여 무중단 실행, 세션 관리 및 컨텍스트 보존을 구현하며 각 프로젝트당 35-55분을 절약합니다.","es":"Habilita a los agentes a automatizar el ciclo de vida del proyecto, desde la validación de la idea hasta la versión, utilizando 9 comandos integrados de barra para una ejecución sin problemas, gestión de sesiones y preservación de contexto, ahorrando 35-55 minutos por proyecto.","fr":"Permet aux agents d''automatiser le cycle de vie du projet, de la validation de l''idée à la version, en utilisant 9 commandes intégrées de barre pour une exécution sans problème, une gestion de sessions et une préservation de contexte, ce qui permet d''économiser 35-55 minutes par projet.","de":"Ermöglicht es Agenten, den Projekt-Lebenszyklus zu automatisieren, von der Ideenvalidierung bis zur Veröffentlichung, indem 9 integrierte Befehle verwendet werden, um eine reibungslose Ausführung, Sitzungsverwaltung und Kontexterhaltung zu ermöglichen und so 35-55 Minuten pro Projekt zu sparen.","pt":"Habilita os agentes a automatizar o ciclo de vida do projeto, desde a validação da ideia até a liberação, utilizando 9 comandos de barra integrados para execução sem interrupções, gerenciamento de sessão e preservação de contexto, economizando 35-55 minutos por projeto.","ru":"Позволяет агентам автоматизировать жизненный цикл проекта, от проверки идеи до выпуска, используя 9 интегрированных команд слэша для бесперебойного выполнения, управления сессиями и сохранения контекста, экономя 35-55 минут на проект.","ar":"يمنح الوكلاء القدرة على 자동atisation دورة حياة المشروع، من التحقق من الفكرة إلى الإصدار، باستخدام 9 أوامر منقطة متكاملة للتنفيذ السلس، وإدارة الجلسة والحفاظ على السياق، وتوفير 35-55 دقيقة لكل مشروع."},"useCases":{"en":["Automating idea validation and planning phases","Streamlining project execution with integrated slash commands","Preserving context across project sessions for efficient collaboration"],"zh":["自动化想法验证和规划阶段","使用集成的斜杠命令简化项目执行","在项目会话中保留上下文以实现高效的协作"],"ja":["アイデアの検証と計画段階の自動化","統合されたスラッシュコマンドを使用したプロジェクトの実行の簡素化","プロジェクトセッション間のコンテキストの保存による効率的なコラボレーション"],"ko":["아이디어 검증 및 계획 단계의 자동화","통합 슬래시 명령을 사용한 프로젝트 실행의 간소화","프로젝트 세션 간 컨텍스트 보존을 통한 효율적인 협업"],"es":["Automatización de las fases de validación y planificación de ideas","Optimización de la ejecución del proyecto con comandos integrados de barra","Preservación del contexto a lo largo de las sesiones del proyecto para una colaboración eficiente"],"fr":["Automatisation des phases de validation et de planification des idées","Optimisation de l''exécution du projet avec des commandes intégrées de barre","Préservation du contexte tout au long des sessions de projet pour une collaboration efficace"],"de":["Automatisierung der Ideenvalidierungs- und Planungsphasen","Optimierung der Projekt-Ausführung mit integrierten Befehlen","Erhaltung des Kontexts während der Projekt-Sitzungen für eine effiziente Zusammenarbeit"],"pt":["Automação das fases de validação e planejamento de ideias","Simplificação da execução do projeto com comandos de barra integrados","Preservação de contexto em sessões de projeto para colaboração eficiente"],"ru":["Автоматизация фазы проверки и планирования идеи","Упрощение выполнения проекта с помощью интегрированных команд слэша","Сохранение контекста в сессиях проекта для эффективного сотрудничества"],"ar":["تأشير自动atisation مراحل التحقق والتنظيم للفكرة","تبسيط تنفيذ المشروع باستخدام أوامر منقطة متكاملة","الحفاظ على السياق في جلسات المشروع للتعاون الفعال"]},"limitations":{"en":["Requires installation via marketplace or manual command installation","Limited to projects utilizing the specified 9 slash commands"],"zh":["需要通过市场或手动命令安装","仅限于使用指定的 9 个斜杠命令的项目"],"ja":["マーケットプレイスまたは手動コマンドを介したインストールが必要","指定された 9 つのスラッシュコマンドのみを使用するプロジェクトに限定"],"ko":["마켓플레이스 또는 수동 명령을 통해 설치해야함","지정된 9개의 슬래시 명령만을 사용하는 프로젝트로 제한"],"es":["Requiere instalación a través del marketplace o instalación de comandos manuales","Limitado a proyectos que utilizan los 9 comandos de barra especificados"],"fr":["Nécessite une installation via le marketplace ou une installation de commandes manuelles","Limité aux projets qui utilisent les 9 commandes de barre spécifiées"],"de":["Erfordert eine Installation über den Marketplace oder eine manuelle Befehlsinstallation","Begrenzt auf Projekte, die die spezifizierten 9 Befehle verwenden"],"pt":["Requer instalação via marketplace ou instalação de comando manual","Limitado a projetos que utilizam os 9 comandos de barra especificados"],"ru":["Требует установки через marketplace или ручной установки команды","Ограничен проектами, которые используют указанные 9 команд слэша"],"ar":["يتطلب التثبيت عبر سوق التطبيقات أو تثبيت أمر يدوي","محدود بمشاريع تستخدم 9 أوامر منقطة محددة"]},"version":4},"contentHash":"fccd42a49848b65d2902f2c5361f5d6df35e8f3576742d0df7874ef4b1fda9ff","qualityScore":45}');
