INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fefogarcia/approved-skills/project-workflow', 'project-workflow', 'fefogarcia', 'approved-skills', 'community', 'project-workflow fefogarcia approved-skills community The project-workflow skill automates the project lifecycle, from idea validation to release, saving developers 35-55 minutes per project. It integrates 9 slash commands for a seamless experience. Project Workflow AIエージェント提供9个集成的斜杠命令，实现项目生命周期自动化 プロジェクトワークフローAIエージェントは、9つの統合されたスラッシュコマンドを提供し、プロジェクトライフサイクルを自動化 프로젝트 워크플로우 AI 에이전트는 9개의 통합된 슬래시 명령을 제공하여 프로젝트 生命周期를 자동화 Project-workflow es un conjunto de habilidades de agente de IA que automatiza el ciclo de vida de los proyectos con 9 comandos integrados Project-workflow est un ensemble de compétences d''agent IA qui automatisent le cycle de vie des projets avec 9 commandes intégrées Project-workflow ist ein Satz von Fähigkeiten des IA-Agents, der den Projekt-Lebenszyklus mit 9 integrierten Befehlen automatisiert O Project Workflow é um skill aprovado pela equipe DodaTech que automatiza o ciclo de vida do projeto com 9 comandos integrados Project Workflow - это навык, утвержденный командой DodaTech, который автоматизирует жизненный цикл проекта с помощью 9 интегрированных команд Project Workflow هو مهارة معتمدة من فريق DodaTech التي تautomatiza دورة حياة المشروع مع 9 أوامر مدمجة how to use project-workflow project-workflow install guide project-workflow setup tutorial what is project-workflow project-workflow alternative project-workflow vs other automation tools project-workflow automated project lifecycle project-workflow time savings project-workflow for developers Project Workflow AIエージェント 项目生命周期自动化 斜杠命令 idea验证 规划 执行 会话管理 上下文保留 发布 9 integrated slash commands for complete project lifecycle automation Supports installation via `/plugin install project-workflow@jezweb-skills` command Manual installation by copying `commands/*.md` to `~/.claude/commands/` directory Includes `/explore-idea` command for pre-planning exploration Enables session management and context preservation project-workflow is a DodaTech team-approved AI agent skill that automates the project lifecycle using 9 integrated slash commands');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mikemaccana/solana-anchor-claude-skill/solana-anchor-claude-skill', 'community', 'mikemaccana', 'solana-anchor-claude-skill', 'mikemaccana/solana-anchor-claude-skill', 'solana-anchor-claude-skill', 0, 0, 45, '2026-03-08T01:57:15.404Z', '2026-03-08T02:06:52.330Z', '3c1b635ef5d502ae56aa36c369b91d3ad5bec3790194d89fd7059685966403cf', '{"id":"mikemaccana/solana-anchor-claude-skill/solana-anchor-claude-skill","name":"solana-anchor-claude-skill","description":{"en":"The Solana-Anchor-Claude-Skill enables developers to maintain high code quality and adhere to project standards through strict coding guidelines and thorough testing. It benefits Solana and Anchor developers seeking reliable code.","zh":"Solana 和 Anchor Claude 技术提供了高质量的代码和可维护性，通过遵循特定的编码规则和测试标准","ja":"Solana と Anchor Claude を使用することで、AI エージェントの開発がより効率的になります","ko":"솔라나와 앵커 클라우드는 코드의 품질과 유지보수를 높이는 기술입니다","es":"El solana-anchor-claude-skill es una herramienta de desarrollo que sigue pautas de codificación estrictas para garantizar la calidad y mantenibilidad del código.","fr":"Le solana-anchor-claude-skill est un outil de développement qui suit des directives de codage strictes pour assurer la qualité et la maintenabilité du code.","de":"Der solana-anchor-claude-skill ist ein Entwicklungstool, das strenge Codierungsrichtlinien befolgt, um die Qualität und Wartbarkeit des Codes zu gewährleisten.","pt":"O Solana Anchor Claude Skill é uma ferramenta poderosa que requer configuração e codificação de alta qualidade. Aprenda a configurá-lo com nossas diretrizes","ru":"Solana Anchor Claude ИИ Агент - это мощный инструмент, требующий настройки и качественной кодировки. Узнайте, как его настроить с помощью наших рекомендаций","ar":"مهارة Solana Anchor Claude هي أداة قوية تتطلب إعدادًا وبرمجة عالية الجودة. تعلم كيفية إعدادها باستخدام إرشاداتنا"},"seo":{"title":{"en":"Solana-Anchor-Claude-Skill: Reliable Code Quality Setup G...","zh":"Solana 和 Anchor Claude 技术集成指南","ja":"Solana と Anchor Claude を使用した AI エージェントのセットアップガイド","ko":"솔라나와 앵커 클라우드 통합 가이드","es":"Guía de configuración de solana-anchor-claude-skill para ...","fr":"Guide d''installation de solana-anchor-claude-skill pour l...","de":"Einrichtungsleitfaden für solana-anchor-claude-skill-Entw...","pt":"Guia de Configuração do Solana Anchor Claude Skill","ru":"Настройка Solana Anchor Claude ИИ Агента","ar":"دليل إعداد مهارة Solana Anchor Claude"},"description":{"en":"Unlock robust Solana and Anchor development with the Solana-Anchor-Claude-Skill, ensuring high code quality through rigorous testing and adherence to project...","zh":"了解 Solana 和 Anchor Claude 技术的最佳实践和集成方法，提高代码质量和可维护性","ja":"Solana と Anchor Claude を使用した AI エージェントの開発方法とベストプラクティスを紹介します","ko":"솔라나와 앵커 클라우드의 기술적 특징과 통합 방안을 소개합니다","es":"Aprende a configurar y utilizar solana-anchor-claude-skill con nuestras mejores prácticas y guías paso a paso para desarrolladores","fr":"Découvrez comment configurer et utiliser solana-anchor-claude-skill avec nos meilleures pratiques et guides étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie solana-anchor-claude-skill konfigurieren und verwenden können, mit unseren besten Praktiken und Schritt-für-Schritt-Anleitungen für Ent...","pt":"Aprenda a configurar o Solana Anchor Claude Skill com nossas melhores práticas e diretrizes de codificação","ru":"Узнайте, как настроить Solana Anchor Claude ИИ Агент с помощью наших лучших практик и рекомендаций по кодированию","ar":"تعرف على كيفية إعداد مهارة Solana Anchor Claude باستخدام أفضل الممارسات والدلائل التوجيهية للتعليمات البرمجية"},"definition":{"en":"Solana-Anchor-Claude-Skill is a coding guideline and testing framework ensuring Solana and Anchor projects meet high code quality and maintainability standards.","zh":"Solana 和 Anchor Claude 技术是用于提高代码质量和可维护性的技术集成","ja":"Solana と Anchor Claude は、AI エージェントの開発を支援する技術です","ko":"솔라나와 앵커 클라우드는 코드의 품질과 유지보수를 높이는 기술입니다","es":"¿Qué es solana-anchor-claude-skill? Es una herramienta de desarrollo que aplica reglas de codificación para garantizar la calidad del código","fr":"Qu''est-ce que solana-anchor-claude-skill? C''est un outil de développement qui applique des règles de codage pour assurer la qualité du code","de":"Was ist solana-anchor-claude-skill? Es ist ein Entwicklungstool, das Codierungsregeln anwendet, um die Code-Qualität zu gewährleisten","pt":"O Solana Anchor Claude Skill é uma ferramenta de codificação que segue diretrizes de qualidade e testes automatizados","ru":"Solana Anchor Claude ИИ Агент - это инструмент кодировки, следующий рекомендациям по качеству и автоматизированному тестированию","ar":"مهارة Solana Anchor Claude هي أداة برمجة تتبع إرشادات الجودة والاختبارات الآلية"},"features":{"en":["Enforces coding guidelines for Solana and Anchor projects","Runs npm test for rigorous code testing and validation","Ensures tests are meaningful and not placeholder-based","Requires tests to actually call the code being developed","Supports adherence to project standards through strict success criteria"],"zh":["使用 npm test 进行代码测试","遵循特定的编码规则和标准","避免使用占位测试","确保测试的有效性和可靠性","提高代码的质量和可维护性"],"ja":["npm test を使用したコードテスト","特定のコーディング規則と標準に従う","プレイスホルダーテストの使用を避ける","テストの有効性と信頼性を確保する","コードの品質と保守性を高める"],"ko":["npm test 사용","특정 코딩 규칙과 표준 준수","플레이스홀더 테스트 사용 피하기","테스트의 유효성과 신뢰성 보장","코드의 품질과 유지보수 향상"],"es":["Seguimiento de pautas de codificación estrictas","Uso de npm test para garantizar la calidad del código","Implementación de pruebas unitarias efectivas","Evitación de pruebas placeholder","Integración con Anchor y Solana"],"fr":["Suivi de directives de codage strictes","Utilisation de npm test pour assurer la qualité du code","Mise en œuvre de tests unitaires efficaces","Évitement des tests placeholder","Intégration avec Anchor et Solana"],"de":["Einhalten strenger Codierungsrichtlinien","Verwendung von npm test zur Gewährleistung der Code-Qualität","Implementierung effektiver Einheitstests","Vermeidung von Platzhalter-Tests","Integration mit Anchor und Solana"],"pt":["Seguimento de diretrizes de codificação","Testes automatizados com npm test","Codificação de alta qualidade","Adesão a padrões de projeto","Uso de assert.ok para testes reais"],"ru":["Следование рекомендациям по кодированию","Автоматизированное тестирование с помощью npm test","Качественная кодировка","Соблюдение стандартов проекта","Использование assert.ok для реальных тестов"],"ar":["اتباع إرشادات التعليمات البرمجية","الاختبارات الآلية باستخدام npm test","برمجة उचية الجودة","الامتثال لمعايير المشروع","استخدام assert.ok للاختبارات الفعلية"]},"keywords":{"en":["how to use Solana-Anchor-Claude-Skill","Solana-Anchor-Claude-Skill setup guide","what is Solana-Anchor-Claude-Skill","Solana-Anchor-Claude-Skill alternative","Solana-Anchor-Claude-Skill vs other coding guidelines","installing Solana-Anchor-Claude-Skill","Solana and Anchor development best practices","npm test for Solana projects"],"zh":["Solana","Anchor Claude","AI 技术","代码质量","可维护性","npm test","编码规则","测试标准"],"ja":["Solana","Anchor Claude","AI エージェント","コード品質","保守性","npm test","コーディング規則","テスト標準"],"ko":["솔라나","앵커 클라우드","AI 기술","코드 품질","유지보수","npm test","코딩 규칙","테스트 표준"],"es":["solana-anchor-claude-skill","desarrollo de software","herramientas de desarrollo","pruebas unitarias","npm test","codificación","Anchor","Solana","desarrollo de blockchain"],"fr":["solana-anchor-claude-skill","développement de logiciels","outils de développement","tests unitaires","npm test","codage","Anchor","Solana","développement de blockchain"],"de":["solana-anchor-claude-skill","Software-Entwicklung","Entwicklungstools","Einheitstests","npm test","Codierung","Anchor","Solana","Blockchain-Entwicklung"],"pt":["Solana Anchor Claude Skill","configuração do Solana","codificação de alta qualidade","testes automatizados","diretrizes de codificação","npm test","assert.ok"],"ru":["Solana Anchor Claude ИИ Агент","настройка Solana","качественная кодировка","автоматизированное тестирование","рекомендации по кодированию","npm test","assert.ok"],"ar":["مهارة Solana Anchor Claude","إعداد Solana","برمجة عالية الجودة","الاختبارات الآلية","إرشادات التعليمات البرمجية","npm test","assert.ok"]}},"owner":"mikemaccana","repo":"solana-anchor-claude-skill","repoPath":"mikemaccana/solana-anchor-claude-skill","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.404Z","topics":[],"category":"community","skillMd":{"name":"solana-anchor-claude-skill","description":"Use when working on Solana Anchor programs, including Rust program files, TypeScript tests, and Anchor.toml configuration. Designed to create minimal, reusable code without unecessary duplication.","bodyPreview":"# Coding Guidelines\n\nApply these rules to ensure code quality, maintainability, and adherence to project standards.\n\n## Success Criteria\n\n- Before declaring success or celebrating, run `npm test`. If the tests fail, there is more work to do. Don''t stop until `npm test` passes on the code you have made.\n\n**CRITICAL: Placeholder tests don''t count as success.**\n- Tests that just do `assert.ok(true)` or similar are NOT real tests\n- DO NOT mark \"Write tests\" as complete until tests actually call the","body":"# Coding Guidelines\n\nApply these rules to ensure code quality, maintainability, and adherence to project standards.\n\n## Success Criteria\n\n- Before declaring success or celebrating, run `npm test`. If the tests fail, there is more work to do. Don''t stop until `npm test` passes on the code you have made.\n\n**CRITICAL: Placeholder tests don''t count as success.**\n- Tests that just do `assert.ok(true)` or similar are NOT real tests\n- DO NOT mark \"Write tests\" as complete until tests actually call the program instructions\n- DO NOT ask \"should I write real tests now?\" - if the tests are placeholders, write real ones immediately\n- Real tests must: initialize accounts, send transactions, verify state changes, check balances\n- If you find yourself writing placeholder tests, stop and write real integration tests instead\n\n- When summarizing your work, show the work items you have achieved with this symbol ''✅'' and there is more work to do, add a ''❌'' for each remaining work item.\n\n## Documentation Sources\n\nUse these official documentation sources:\n\n- **Anchor**: https://www.anchor-lang.com/docs\n- **Anchor Error Codes**: https://raw.githubusercontent.com/coral-xyz/anchor/master/lang/src/error.rs\n- **Solana Kite**: https://solanakite.org\n- **Solana Kit**: https://solanakit.com\n- **Agave (Solana CLI)**: https://docs.anza.xyz/ (Anza makes the Solana CLI and Agave.\n- **Switchboard** (if used): https://docs.switchboard.xyz/docs-by-chain/solana-svm\n- **Arcium** (if used): https://docs.arcium.com/developers\n\n## Do not use\n\n- Do not use Solana Labs documentation. The company has been replaced by Anza.\n\n- Do not use any documentaton or tools from Project Serum, which collapsed many years ago.\n\n- Do not use yarn. Use npm. Yarn has no reason to exist and only adds unnecessary dependencies. Replace Yarn with npm everywhere you see it.\n\n- Do not use **Switchboard Functions** - this product is dead and no longer maintained. (Note: Switchboard oracles are still active and usable.)\n\n- Do not use **Clockwork** - this product is dead. For scheduled instruction handler invocation, use **TukTuk** instead.\n\n## Library versions\n\nUse the latest stable Anchor, Rust, TypeScript, Solana Kit, and Kite you can. If a bug occurs, favor updating rather than rolling back.\n\n## Project Documentation\n\nEvery project must have a `README.md` file in the project root that includes:\n\n- **Purpose**: Why the project exists and what problem it solves\n- **Major Concepts**: Key architectural concepts, important PDAs, state structures, and program logic\n- **Testing**: How to run the tests (e.g., `npm test`)\n- **Setup**: Any prerequisites or setup steps needed to work with the project\n- **Usage**: Basic usage examples or deployment instructions if applicable\n\nKeep the README focused and practical. Avoid generic boilerplate - write documentation that would actually help someone understand and work with this specific project.\n\n## General Coding Guidelines\n\n### You are a deletionist\n\nYour golden rule is \"perfection isn''t achieved when there''s nothing more to add, rather perfection is achieved when there is nothing more to be taken away\".\n\nRemove:\n\n- Comments that simply repeat what the code is doing, or the name of a variable, and do not add further insight.\n- Repeated code that should be turned into a named function\n\n### Communication Style\n\n- Do not make disclaimers about being a \"complete project\" or state what works\n- It is expected that work is complete and functional - no need to state this explicitly\n- Avoid phrases like \"This is a complete implementation\" or \"All features are working\"\n- Just deliver the work without meta-commentary about its completeness\n\n### Working with Generated or Unfamiliar Code\n\n**CRITICAL - Verify Before Use:**\n\n- Before calling ANY function whose signature you don''t know with certainty, read the actual source code/type definitions first\n- NEVER guess or assume what parameters a function accepts based on what seems logical\n- Don''t invent convenience parameters that don''t exist\n- Generated code, third-party libraries, and unfamiliar codebases often have different APIs than you expect\n- Common mistake: Assuming a function accepts high-level parameters → WRONG. Check the actual signature in the source files first\n\n### Code Honesty and Clarity\n\n- It''s important not to deceive anyone reading this code. Deception includes:\n  - Variable names that do not match the purpose of the variable\n  - Comments that no longer describe the code or are otherwise inaccurate\n  - Temporary workarounds that aren''t labelled as such using a comment (with a `TODO` letting the next programmer know when they can delete the workaround)\n\n### Variable Naming\n\nEnsure good variable naming. Rather than add comments to explain what things are, give them useful names.\n\n**Don''t do this:**\n\n```typescript\n// Foo\nconst shlerg = getFoo();\n```\n\n**Do this instead:**\n\n```typescript\nconst foo = getFoo();\n```\n\n**Naming conventions:**\n\n- Arrays should be plurals (`shoes`), items within arrays should be the singular (`shoes.forEach((shoe) => {...})`)\n- Functions should be verby, like `calculateFoo` or `getBar`\n- Avoid abbreviations, use full words (e.g., `context` rather than `ctx`)\n- Never use `e` for something thrown\n- Name a transaction some variant of `transaction`. Name instructions some variant of `instruction`. Name signatures some variant of `signature`. Do not confuse them - eg if the type looks like an instruction, you should not call it a ''transaction'' because that is deceptive.\n\nYou can still add comments for additional context, just be careful to avoid comments that are explaining things that would be better conveyed by good variable naming.\n\n### Code Quality\n\n- Look out for repeated code that should be turned into functions\n- Avoid ''magic numbers''. Make numbers either have a good variable name, a comment explaining why they are that value, or a reference to the URL you got the value from. If the values come from an IDL, download the IDL, import it, and make a function that gets the value from the IDL rather than copying the value into the source code\n\nThis is a magic number. Don''t do this:\n\n```ts\nconst FINALIZE_EVENT_DISCRIMINATOR = new Uint8Array([\n  27, 75, 117, 221, 191, 213, 253, 249,\n]);\n```\n\nInstead do this:\n\n```ts\nconst FINALIZE_EVENT_DISCRIMINATOR = getEventDiscriminator(\n  arciumIdl,\n  \"FinalizeComputationEvent\",\n);\n```\n\n- The code you are making is for production. You shouldn''t have comments like `// In production we''d do this differently` or `**Implementation incomplete** - Needs program config handling and proper PDA derivations` or `**WORK IN PROGRESS**` in the final code you produce, or functions that return placeholder data. Instead: do the fucking work.\n- Don''t remove existing comments unless they are no longer useful or accurate\n- Delete unused imports, unused constants, unused files and comments that no longer apply\n\n## TypeScript Guidelines\n\nThese guidelines apply to TypeScript unit tests, browser code, and any other places where TypeScript is used in the project.\n\n### General TypeScript\n\nAvoid using a `tsconfig.json` unless it''s needed, as we use `tsx` to run most typescript and it doesn''t usually need one. If you do need a `tsconfig.json`, state why at the top of the file, and you can use the most modern version of ECMAScript/JavaScript you want - up to say 2023.\n\n### Async/await\n\nFavor `async`/`await` and `try/catch` over `.then()` or `.catch()` or using callbacks for flow control. `tsx` has top level `await` so you don''t need to wrap top level `await` in IIFEs.\n\n### Type System\n\n- **Always use `Array<item>`**, never use `item[]` for consistency with other generic syntax like `Promise<T>`, `Map<K, V>`, and `Set<T>`\n- **Don''t use `any`**\n\n### Comments\n\n- Most comments should use `//` and be above (not beside) the code\n- The only exception is JSDoc/TSDoc comments which MUST use `/* */` syntax\n\n### Solana-Specific TypeScript\n\n- Don''t make new `@solana/web3.js` version 1 code. Do not make new code using `@coral-xyz/anchor` package. Don''t replace Solana Kit with web3.js version 1 code. web3.js version 1 is legacy and should be eventually removed. Solana Kit used to be called web3.js version 2. Use Solana Kit, preferably via Solana Kite.\n- Use Kite''s `connection.getPDAAndBump()` to turn seeds into PDAs and bumps\n- In Solana Kit, you make instructions by making TS clients from IDLs using Codama. You can easily make Codama clients for installed IDLs using\n\n`npx create-codama-clients`\n\n- Do not use the `bs58` npm package.\n\nDon''t do this:\n\n```typescript\nimport bs58 from \"bs58\";\nconst signature = bs58.encode(signatureBytes);\n```\n\nDo this instead:\n\n```typescript\nimport { getBase58Decoder } from \"@solana/codecs\";\nconst signature = getBase58Decoder().decode(signatureBytes);\n```\n\nYes, these difference packages have difference concepts of ''encode'' and ''decode''.\n\n### Unit Tests\n\n- Create unit tests in TS in the `tests` directory\n- Use the Node.js inbuilt test and assertion libraries (then start the tests using `tsx` instead of `ts-mocha`)\n\n**Unit testing imports:**\n\n```typescript\nimport { before, describe, test } from \"node:test\";\nimport assert from \"node:assert\";\n```\n\n- Use `test` rather than `it`\n\n### Thrown object handling\n\n- JavaScript allows arbitrary items - strings, array, numbers etc to be ''thrown''. However you can assume that any non-Error item that is thrown is an programmer error. Handle it like this (including the comment since most TypeScript developers don''t know this):\n\n```ts\n// In JS it''s possible to throw *anything*. A sensible programmer\n// will only throw Errors but we must still check to satisfy\n// TypeScript (and flag any craziness)\nconst ensureError = function (thrownObject: unknown): Error {\n  if (thrownObject instanceof Error) {\n    return thrownObject;\n  }\n  return new Error(`Non-Error thrown: ${String(thrownObject)}`);\n};\n```\n\nand\n\n```ts\ntry {\n  // some code that might throw\n} catch (thrownObject) {\n  const error = ensureError(thrownObject);\n  throw error;\n}\n```\n\n## Rust Guidelines (Anchor Programs)\n\n### Platform Awareness\n\n- Remember this is Solana not Ethereum.\n  - Don''t tell me about ''smart contracts'' (use ''programs'' instead)\n  - Don''t tell me about ''gas'' (use ''transaction fees'' instead)\n  - There are no ''mempools''.\n    Do not tell me about other things that are not relevant to Solana.\n\n- Token program terminology:\n  - Use ''Token Extensions Program'' or ''Token extensions'' for the newer token program (not ''Token 2022'' which is just a code name)\n  - Use ''Classic Token Program'' for the older token program\n\n- Onchain\n  - Use onchain and offchain, like online and offline\n  - Don''t ever use ''on-chain'' or ''off-chain''\n\n### Anchor Version\n\n- Write all code like the latest stable Anchor (currently 0.32.1 but there may be a newer version by the time you read this)\n- Do not use unnecessary macros that are not needed in the latest stable Anchor\n\n### Anchor has silly defaults\n\nEvery project will need an IDL.\n\n```toml\n[features]\nidl-build = [\"anchor-lang/idl-build\", \"anchor-spl/idl-build\"]\n```\n\nand if it uses SPL Tokens (like almost every Anchor project) it will need this dependency (insert whatever version is applicable):\n\n```toml\n[dependencies]\nanchor-spl = \"0.32.1\"\n```\n\n### Project Structure\n\n- **Never modify the program ID** in `lib.rs` or `Anchor.toml` when making changes\n- Create files inside the `state` folder for whatever state is needed\n- Create files inside the `instructions` or `handlers` folders (whichever exists) for whatever instruction handlers are needed\n- Put Account Constraints in instruction files, but ensure the names end with `AccountConstraints` rather than just naming them the same thing as the function\n- Handlers that are only for the admin should be in a new folder called `admin` inside whichever parent folder exists (`instructions/admin/` or `handlers/admin/`)\n\n### Account Constraints\n\n- Use a newline after each key in the account constraints struct, so the macro and the matching key/value have some space from other macros and their matching key/value\n\n### Bumps\n\n- Use `context.bumps.foo` not `context.bumps.get(\"foo\").unwrap()` - the latter is outdated\n\n### Data Structures\n\n- When making structs ensure strings and Vectors have a `max_len` attribute\n- Vectors have two numbers for `max_len`: the first is the max length of the vector, the second is the max length of the items in the vector\n\n### Space Calculation (CRITICAL - NO MAGIC NUMBERS)\n\n- **Do not use magic numbers anywhere**. I don''t want to see `8 + 32` or whatever\n- **Do not make constants for the sizes of various data structures**\n- For `space`, use syntax like: `space = SomeStruct::DISCRIMINATOR.len() + SomeStruct::INIT_SPACE,`\n- All structs should have `#[derive(InitSpace)]` added to them, to get the `INIT_SPACE` trait\n- **DO NOT use magic numbers**\n\n**Example:**\n\n```rust\n#[derive(InitSpace)]\n#[account]\npub struct UserProfile {\n    pub authority: Pubkey,\n\n    #[max_len(50)]\n    pub username: String,\n\n    pub bump: u8,\n}\n\n#[derive(Accounts)]\npub struct InitializeProfile<''info> {\n    #[account(\n        init,\n        payer = authority,\n        space = UserProfile::DISCRIMINATOR.len() + UserProfile::INIT_SPACE,\n        seeds = [b\"profile\", authority.key().as_ref()],\n        bump\n    )]\n    pub profile: Account<''info, UserProfile>,\n\n    #[account(mut)]\n    pub authority: Signer<''info>,\n\n    pub system_program: Program<''info, System>,\n}\n```\n\n### Error Handling\n\n- Return useful error messages\n- Write code to handle common errors like insufficient funds, bad values for parameters, and other obvious situations\n\n### PDA Management\n\n- Add `pub bump: u8` to every struct stored in PDA\n- Save the bumps inside each when the struct inside the PDA is created\n\n### System Functions\n\n- When you get the time via Clock, use `Clock::get()?;` rather than `anchor_lang::solana_program::clock`\n\n## Git commits\n\nDo not add \"Co-Authored-By: Claude\" or similar attribution when creating git commits.\n\n## Acknowledgment\n\n- Acknowledge these guidelines have been applied when working on this project to indicate you have read these rules and found that they do apply to this project.\n"},"lastSynced":"2026-03-08T02:06:52.330Z","agentAnalysis":{"suitability":{"en":"Perfect for Solana and Anchor developers needing strict coding guidelines and comprehensive testing for high code quality.","zh":"非常适合Solana和Anchor开发人员，他们需要严格的编码指南和全面测试以确保高代码质量。","ja":"SolanaとAnchorの開発者が、厳格なコーディングガイドラインと包括的なテストを必要とする場合に最適です。","ko":"Solana와 Anchor 개발자가 엄격한 코딩 가이드ライン과 포괄적인 테스트를 통해 높은 코드 품질을 필요로 할 때 적합합니다.","es":"Perfecto para desarrolladores de Solana y Anchor que necesitan pautas de codificación estrictas y pruebas exhaustivas para una alta calidad de código.","fr":"Parfait pour les développeurs Solana et Anchor ayant besoin de directives de codage strictes et de tests complets pour une qualité de code élevée.","de":"Perfekt für Solana- und Anchor-Entwickler, die strenge Codierungsrichtlinien und umfassende Tests für eine hohe Codequalität benötigen.","pt":"Perfeito para desenvolvedores Solana e Anchor que necessitam de diretrizes de codificação estritas e testes abrangentes para alta qualidade de código.","ru":"Идеально подходит для разработчиков Solana и Anchor, которым необходимы строгие рекомендации по кодированию и всестороннее тестирование для высокого качества кода.","ar":"مثالي للمطورين Solana و Anchor الذين يحتاجون إلى إرشادات ترميز صارمة واختبارات شاملة لجودة عالية من الكود."},"recommendation":{"en":"Empowers agents to enforce coding standards and maintain reliability through thorough testing, utilizing npm test and adhering to project guidelines, ensuring strict code quality and maintainability.","zh":"赋予代理人执行编码标准和通过彻底测试维护可靠性，利用npm test并遵循项目指南，确保严格的代码质量和可维护性。","ja":"エージェントがコーディング標準を実施し、npm testを使用して包括的なテストを実行し、プロジェクトガイドラインに従って厳格なコード品質とメンテナンス性を確保することができます。","ko":"에이전트가 코딩 표준을 강제하고 npm test를 사용하여 철저한 테스트를 수행하여 프로젝트 가이드라인을 따르며 엄격한 코드 품질과 유지 보수성을 보장합니다.","es":"Habilita a los agentes a aplicar normas de codificación y mantener la confiabilidad a través de pruebas exhaustivas, utilizando npm test y ajustándose a las pautas del proyecto, asegurando una estricta calidad del código y mantenibilidad.","fr":"Permet aux agents d''appliquer des normes de codage et de maintenir la fiabilité grâce à des tests complets, en utilisant npm test et en respectant les directives de projet, assurant une qualité de code stricte et une maintenabilité.","de":"Ermächtigt Agenten, Codierungsstandards durchzusetzen und die Zuverlässigkeit durch umfassende Tests zu gewährleisten, indem npm test verwendet und den Projektvorgaben entsprochen wird, um eine strenge Codequalität und Wartbarkeit sicherzustellen.","pt":"Habilita agentes a impor padrões de codificação e manter a confiabilidade por meio de testes abrangentes, utilizando npm test e seguindo as diretrizes do projeto, garantindo qualidade estrita de código e manutenibilidade.","ru":"Наделяет агентов возможностью обеспечивать соблюдение стандартов кодирования и поддерживать надежность посредством тщательного тестирования, используя npm test и следуя руководящим принципам проекта, гарантируя строгое качество кода и поддерживаемость.","ar":"يُمكن Agents من فرض معايير الترميز والحفاظ على الموثوقية من خلال الاختبارات الشاملة، باستخدام npm test و اتباع إرشادات المشروع، مما يضمن جودة صارمة من الكود وضمان الصيانة."},"useCases":{"en":["Enforcing strict coding guidelines for Solana and Anchor projects","Automating testing with npm test to ensure code reliability","Maintaining high code quality through comprehensive test coverage"],"zh":["为Solana和Anchor项目执行严格的编码指南","使用npm test自动执行测试以确保代码可靠性","通过全面测试覆盖维护高代码质量"],"ja":["SolanaとAnchorのプロジェクトのための厳格なコーディングガイドラインの実施","npm testを使用した自動テストによるコードの信頼性の確保","包括的なテストカバレッジによる高いコード品質の維持"],"ko":["Solana와 Anchor 프로젝트를 위한 엄격한 코딩 가이드ライン의 적용","npm test를 사용한 자동 테스트를 통해 코드의 신뢰성을 보장","포괄적인 테스트 커버리지로 높은 코드 품질 유지"],"es":["Aplicar pautas de codificación estrictas para proyectos de Solana y Anchor","Automatizar las pruebas con npm test para garantizar la confiabilidad del código","Mantener una alta calidad del código a través de una cobertura de pruebas exhaustiva"],"fr":["Appliquer des directives de codage strictes pour les projets Solana et Anchor","Automatiser les tests avec npm test pour assurer la fiabilité du code","Maintenir une qualité de code élevée grâce à une couverture de tests complète"],"de":["Strenge Codierungsrichtlinien für Solana- und Anchor-Projekte durchsetzen","Automatisieren von Tests mit npm test, um die Zuverlässigkeit des Codes sicherzustellen","Eine hohe Codequalität durch umfassende Testabdeckung aufrechterhalten"],"pt":["Impor diretrizes de codificação estritas para projetos Solana e Anchor","Automatizar testes com npm test para garantir a confiabilidade do código","Manter alta qualidade de código por meio de cobertura de teste abrangente"],"ru":["Внедрение строгих рекомендаций по кодированию для проектов Solana и Anchor","Автоматизация тестирования с помощью npm test для обеспечения надежности кода","Обеспечение высокого качества кода за счет всесторонней тестовой покрытия"],"ar":["فرض إرشادات ترميز صارمة لمشاريع Solana و Anchor","تتمة الاختبارات باستخدام npm test لضمان موثوقية الكود","الحفاظ على جودة عالية من الكود من خلال تغطية اختبار شاملة"]},"limitations":{"en":["Requires npm test setup","Placeholder tests are not considered valid","Limited to Solana and Anchor development environments"],"zh":["需要npm test设置","占位测试不被认为是有效的","仅限于Solana和Anchor开发环境"],"ja":["npm testの設定が必要","プレイスホルダーテストは有効ではありません","SolanaとAnchorの開発環境に限定"],"ko":["npm test 설정이 필요","플레이스홀더 테스트는 유효하지 않음","Solana와 Anchor 개발 환경에만 제한"],"es":["Requiere configuración de npm test","Las pruebas de marcador de posición no se consideran válidas","Limitado a entornos de desarrollo de Solana y Anchor"],"fr":["Nécessite une configuration de npm test","Les tests de placeholder ne sont pas considérés comme valides","Limité aux environnements de développement Solana et Anchor"],"de":["Benötigt npm-Test-Setup","Platzhalter-Tests gelten nicht als gültig","Begrenzt auf Solana- und Anchor-Entwicklungsumgebungen"],"pt":["Requer configuração do npm test","Testes placeholder não são considerados válidos","Limitado a ambientes de desenvolvimento Solana e Anchor"],"ru":["Требуется настройка npm test","Пустые тесты не считаются действительными","Ограничен средами разработки Solana и Anchor"],"ar":["يتطلب إعداد npm test","لا تعتبر الاختبارات المحجوزة صحيحة","محدود ببيئات تطوير Solana و Anchor"]},"version":4},"contentHash":"3c1b635ef5d502ae56aa36c369b91d3ad5bec3790194d89fd7059685966403cf","qualityScore":45}');
