INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mikemaccana/solana-anchor-claude-skill/solana-anchor-claude-skill', 'solana-anchor-claude-skill', 'mikemaccana', 'solana-anchor-claude-skill', 'community', 'solana-anchor-claude-skill mikemaccana solana-anchor-claude-skill community The Solana-Anchor-Claude-Skill enables developers to maintain high code quality and adhere to project standards through strict coding guidelines and thorough testing. It benefits Solana and Anchor developers seeking reliable code. Solana 和 Anchor Claude 技术提供了高质量的代码和可维护性，通过遵循特定的编码规则和测试标准 Solana と Anchor Claude を使用することで、AI エージェントの開発がより効率的になります 솔라나와 앵커 클라우드는 코드의 품질과 유지보수를 높이는 기술입니다 El solana-anchor-claude-skill es una herramienta de desarrollo que sigue pautas de codificación estrictas para garantizar la calidad y mantenibilidad del código. Le solana-anchor-claude-skill est un outil de développement qui suit des directives de codage strictes pour assurer la qualité et la maintenabilité du code. Der solana-anchor-claude-skill ist ein Entwicklungstool, das strenge Codierungsrichtlinien befolgt, um die Qualität und Wartbarkeit des Codes zu gewährleisten. O Solana Anchor Claude Skill é uma ferramenta poderosa que requer configuração e codificação de alta qualidade. Aprenda a configurá-lo com nossas diretrizes Solana Anchor Claude ИИ Агент - это мощный инструмент, требующий настройки и качественной кодировки. Узнайте, как его настроить с помощью наших рекомендаций مهارة Solana Anchor Claude هي أداة قوية تتطلب إعدادًا وبرمجة عالية الجودة. تعلم كيفية إعدادها باستخدام إرشاداتنا how to use Solana-Anchor-Claude-Skill Solana-Anchor-Claude-Skill setup guide what is Solana-Anchor-Claude-Skill Solana-Anchor-Claude-Skill alternative Solana-Anchor-Claude-Skill vs other coding guidelines installing Solana-Anchor-Claude-Skill Solana and Anchor development best practices npm test for Solana projects Solana Anchor Claude AI 技术 代码质量 可维护性 npm test 编码规则 测试标准 Enforces coding guidelines for Solana and Anchor projects Runs npm test for rigorous code testing and validation Ensures tests are meaningful and not placeholder-based Requires tests to actually call the code being developed Supports adherence to project standards through strict success criteria Solana-Anchor-Claude-Skill is a coding guideline and testing framework ensuring Solana and Anchor projects meet high code quality and maintainability standards.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('moag1000/Little-ISMS-Helper/dpo-specialist', 'community', 'moag1000', 'Little-ISMS-Helper', 'moag1000/Little-ISMS-Helper', 'dpo-specialist', 0, 0, 45, '2026-03-08T01:57:15.412Z', '2026-03-08T02:07:06.868Z', '33f14d8e7c028b54589a7d91a37fb0bd5b93cb37713887b5e7718cf5aca1f3c4', '{"id":"moag1000/Little-ISMS-Helper/dpo-specialist","name":"dpo-specialist","description":{"en":"The dpo-specialist skill provides comprehensive expertise in EU-DSGVO, BDSG, and ISO 27701, helping Data Protection Officers streamline compliance processes. This skill benefits organizations seeking to implement robust data protection measures.","zh":"DPO Specialist是一种数据保护官专家，提供EU-DSGVO/GDPR、BDSG、ISO 27701等数据保护标准的专业知识","ja":"DPO Specialistはデータ保護官専門家で、EU-DSGVO/GDPR、BDSG、ISO 27701などのデータ保護標準の専門知識を提供","ko":"DPO Specialist는 데이터 보호 담당자 전문가로서 EU-DSGVO/GDPR, BDSG, ISO 27701 등 데이터 보호 표준에 대한 전문 지식을 제공","es":"El DPO Specialist es un asistente para la protección de datos que ayuda a cumplir con la EU-DSGVO y el BDSG, con expertice en ISO 27701","fr":"Le DPO Specialist est un outil d''aide pour la protection des données qui aide à se conformer au RGPD et à la loi allemande sur la protection des données, avec une expertise en ISO 27701","de":"Der DPO Specialist ist ein Datenschutzbeauftragter, der hilft, die EU-DSGVO und das BDSG einzuhalten, mit umfassender Expertise in ISO 27701","pt":"O DPO Specialist é um ajudante de ISMS que fornece expertise em EU-DSGVO, BDSG e ISO 27701 para garantir a privacidade dos dados","ru":"ИИ Агент DPO Specialist - это помощник ISMS, который предоставляет экспертизу в области GDPR, BDSG и ISO 27701 для обеспечения безопасности данных","ar":"دبليو بيو سبيشالست هو مساعد لنظام إدارة المعلومات الآمنة الذي يقدم خبرة في مجال الأمن السيبراني والغدر والمتعلقة بتقنيات مثل EU-DSGVO وBDSG وISO 27701"},"seo":{"title":{"en":"dpo-specialist: GDPR Compliance Setup Guide | AI Agent Skill","zh":"DPO Specialist Setup Guide - AI工具","ja":"DPO Specialist ベストプラクティス - AIエージェント","ko":"DPO Specialist 구축 가이드 - AI 에이전트","es":"Guía de configuración de DPO Specialist para la protecció...","fr":"Guide de mise en place de DPO Specialist pour la protecti...","de":"Einrichtungsleitfaden für DPO Specialist zur Datenschutz-...","pt":"Guia de Configuração do DPO Specialist para GDPR e ISO 27701","ru":"Настройка ИИ Агента DPO Specialist для GDPR и ISO 27701","ar":"دليل إعداد دبليو بيو سبيشالست للأمن السيبراني والغدر"},"description":{"en":"Unlock expert GDPR guidance with dpo-specialist. Discover how to implement EU-DSGVO and ISO 27701 compliance with ease. Get started now!","zh":"了解DPO Specialist的功能和特点，掌握EU-DSGVO/GDPR、BDSG、ISO 27701等数据保护标准","ja":"DPO Specialistの機能と特徴をご紹介。EU-DSGVO/GDPR、BDSG、ISO 27701などのデータ保護標準に対応","ko":"DPO Specialist의 기능과 특징을 알아보세요. EU-DSGVO/GDPR, BDSG, ISO 27701 등 데이터 보호 표준에 모두対応","es":"Descubre cómo implementar el DPO Specialist para cumplir con la EU-DSGVO y el BDSG, y mejora la gestión de la privacidad con ISO 27701","fr":"Découvrez comment mettre en place le DPO Specialist pour se conformer au RGPD et à la loi allemande sur la protection des données, et améliorez la gestion de...","de":"Erfahren Sie, wie Sie den DPO Specialist einrichten, um die EU-DSGVO und das BDSG einzuhalten und die Datenschutzverwaltung mit ISO 27701 zu verbessern","pt":"Aprenda a configurar o DPO Specialist, um ajudante de ISMS impulsionado por Claude Code, para atender às normas de privacidade da EU-DSGVO e ISO 27701","ru":"Узнайте, как настроить ИИ Агента DPO Specialist, помощника ISMS на базе Claude Code, для соответствия требованиям GDPR и ISO 27701","ar":"تعرف على كيفية إعداد دبليو بيو سبيشالست، مساعد نظام إدارة المعلومات الآمنة مدعوم من كلود كود، لتنفيذ معايير الأمان السيبراني للأمن السيبراني والغدر"},"definition":{"en":"dpo-specialist is a specialized AI agent skill that assists Data Protection Officers in implementing and managing EU-DSGVO, BDSG, and ISO 27701 compliance.","zh":"DPO Specialist是一种数据保护官专家，提供数据保护标准的专业知识","ja":"DPO Specialistはデータ保護官専門家で、データ保護標準の専門知識を提供","ko":"DPO Specialist는 데이터 보호 담당자 전문가로서 데이터 보호 표준에 대한 전문 지식을 제공","es":"Un DPO Specialist es un asistente que ayuda a las organizaciones a cumplir con las regulaciones de protección de datos","fr":"Un DPO Specialist est un outil qui aide les organisations à se conformer aux réglementations sur la protection des données","de":"Ein DPO Specialist ist ein Datenschutzbeauftragter, der Organisationen hilft, die Datenschutzvorschriften einzuhalten","pt":"O DPO Specialist é um ajudante de ISMS que fornece expertise em privacidade de dados e conformidade regulatória","ru":"ИИ Агент DPO Specialist - это помощник ISMS, который предоставляет экспертизу в области безопасности данных и соблюдения нормативных требований","ar":"دبليو بيو سبيشالست هو مساعد لنظام إدارة المعلومات الآمنة الذي يقدم خبرة في مجال الأمن السيبراني والغدر"},"features":{"en":["Provides expertise in EU-DSGVO (EU 2016/679) and BDSG (Bundesdatenschutzgesetz) regulations","Supports implementation of ISO 27701:2025 and ISO 27701:2019 Privacy Information Management Systems","Offers guidance on Data Reuse Principles for smart integration with existing ISMS","Assists with compliance setup for GDPR and German data protection laws","Helps organizations manage data protection processes efficiently"],"zh":["支持EU-DSGVO/GDPR数据保护标准","支持BDSG德国数据保护法","支持ISO 27701:2025和ISO 27701:2019数据保护标准","提供Data Reuse Principles智能集成","支持现有的ISMS系统"],"ja":["EU-DSGVO/GDPRデータ保護標準に対応","BDSGドイツデータ保護法に対応","ISO 27701:2025とISO 27701:2019データ保護標準に対応","Data Reuse Principlesのスマートな統合を提供","既存のISMSシステムに対応"],"ko":["EU-DSGVO/GDPR 데이터 보호 표준 지원","BDSG 독일 데이터 보호 법 지원","ISO 27701:2025 및 ISO 27701:2019 데이터 보호 표준 지원","Data Reuse Principles의 스마트한 통합 제공","기존의 ISMS 시스템 지원"],"es":["Cumplimiento con la EU-DSGVO y el BDSG","Implementación de ISO 27701 para la gestión de la privacidad","Integración con sistemas de gestión de la información existentes","Aplicación de los principios de reutilización de datos","Asistencia en la configuración de un sistema de gestión de la privacidad","Conocimientos en la protección de datos y la privacidad"],"fr":["Conformité au RGPD et à la loi allemande sur la protection des données","Mise en place de l''ISO 27701 pour la gestion de la vie privée","Intégration avec les systèmes de gestion de l''information existants","Application des principes de réutilisation des données","Aide à la configuration d''un système de gestion de la vie privée","Connaissances en matière de protection des données et de la vie privée"],"de":["Einhaltung der EU-DSGVO und des BDSG","Umsetzung von ISO 27701 für die Datenschutzverwaltung","Integration mit bestehenden Informationssystemen","Anwendung der Datenwiederverwendungsprinzipien","Unterstützung bei der Einrichtung eines Datenschutzmanagementsystems","Kenntnisse im Datenschutz und in der Datensicherheit"],"pt":["Suporte à EU-DSGVO e GDPR","Conformidade com o BDSG","Implementação da ISO 27701:2025","Integração com sistemas de gestão de informações existentes","Princípios de reutilização de dados","Suporte à gestão de informações de privacidade"],"ru":["Поддержка GDPR и EU-DSGVO","Соответствие требованиям BDSG","Реализация ISO 27701:2025","Интеграция с существующими системами управления информацией","Принципы повторного использования данных","Поддержка управления информацией о конфиденциальности"],"ar":["دعم الأمن السيبراني والغدر","الامتثال لقوانين الأمن السيبراني","تنفيذ معايير الأمان السيبراني ISO 27701:2025","التكامل مع أنظمة إدارة المعلومات الحالية","مبادئ إعادة استخدام البيانات","دعم إدارة المعلومات الخاصة"]},"keywords":{"en":["dpo-specialist setup guide","GDPR compliance for AI agents","ISO 27701 implementation","EU-DSGVO regulations","BDSG compliance","Data Protection Officer tools","dpo-specialist alternative","how to use dpo-specialist","dpo-specialist install","GDPR compliance software"],"zh":["DPO Specialist","AI工具","数据保护标准","EU-DSGVO/GDPR","BDSG","ISO 27701","Data Reuse Principles","ISMS系统"],"ja":["DPO Specialist","AIエージェント","データ保護標準","EU-DSGVO/GDPR","BDSG","ISO 27701","Data Reuse Principles","ISMSシステム"],"ko":["DPO Specialist","AI 에이전트","데이터 보호 표준","EU-DSGVO/GDPR","BDSG","ISO 27701","Data Reuse Principles","ISMS 시스템"],"es":["DPO Specialist","protección de datos","EU-DSGVO","BDSG","ISO 27701","gestión de la privacidad","cumplimiento normativo","seguridad de la información","privacidad de los datos"],"fr":["DPO Specialist","protection des données","RGPD","loi allemande sur la protection des données","ISO 27701","gestion de la vie privée","conformité réglementaire","sécurité de l''information","vie privée des données"],"de":["DPO Specialist","Datenschutz","EU-DSGVO","BDSG","ISO 27701","Datenschutzverwaltung","Einhaltung von Vorschriften","Informationssicherheit","Datenschutz und Datensicherheit"],"pt":["DPO Specialist","ISMS","EU-DSGVO","GDPR","BDSG","ISO 27701","privacidade de dados","conformidade regulatória","segurança de dados"],"ru":["ИИ Агент DPO Specialist","ISMS","GDPR","EU-DSGVO","BDSG","ISO 27701","безопасность данных","соответствие нормативным требованиям","управление информацией о конфиденциальности"],"ar":["دبليو بيو سبيشالست","نظام إدارة المعلومات الآمنة","الأمن السيبراني","الغدر","معايير الأمان السيبراني ISO 27701:2025","إدارة المعلومات الخاصة","الامتثال لقوانين الأمن السيبراني","دعم إدارة المعلومات"]}},"owner":"moag1000","repo":"Little-ISMS-Helper","repoPath":"moag1000/Little-ISMS-Helper","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.412Z","topics":[],"category":"community","skillMd":{"name":"dpo-specialist","description":"Expert Data Protection Officer (Datenschutzbeauftragter) with deep knowledge of EU GDPR (DSGVO), German BDSG, and ISO 27701:2025/2019 (PIMS). Specializes in smart integration with existing ISMS infrastructure using Data Reuse principles. Automatically activated when user asks about data protection, privacy, GDPR/DSGVO, BDSG, personal data, DPIA/DSFA, consent, data subject rights, ISO 27701, PIMS, or data breaches.","bodyPreview":"# Data Protection Officer (Datenschutzbeauftragter) Specialist\n\nIch bin dein Datenschutzbeauftragter (DPO) mit umfassender Expertise in:\n- **EU-DSGVO / GDPR** - Datenschutz-Grundverordnung (EU 2016/679)\n- **BDSG** - Bundesdatenschutzgesetz (deutsches Datenschutzrecht)\n- **ISO 27701:2025** - Privacy Information Management System (neueste Version)\n- **ISO 27701:2019** - PIMS Vorgängerversion\n- **Data Reuse Principles** - Smarte Integration mit bestehendem ISMS\n\n## Meine Expertise\n\n### Kernkompeten","body":"# Data Protection Officer (Datenschutzbeauftragter) Specialist\n\nIch bin dein Datenschutzbeauftragter (DPO) mit umfassender Expertise in:\n- **EU-DSGVO / GDPR** - Datenschutz-Grundverordnung (EU 2016/679)\n- **BDSG** - Bundesdatenschutzgesetz (deutsches Datenschutzrecht)\n- **ISO 27701:2025** - Privacy Information Management System (neueste Version)\n- **ISO 27701:2019** - PIMS Vorgängerversion\n- **Data Reuse Principles** - Smarte Integration mit bestehendem ISMS\n\n## Meine Expertise\n\n### Kernkompeten"},"lastSynced":"2026-03-08T02:07:06.868Z","agentAnalysis":{"suitability":{"en":"Perfect for Compliance Agents needing expert guidance on EU-DSGVO, BDSG, and ISO 27701 regulations.","zh":"非常适合需要欧盟通用数据保护条例（EU-DSGVO）、德国联邦数据保护法（BDSG）和ISO 27701法规专家指导的合规代理","ja":"EUの一般データ保護規則（EU-DSGVO）、ドイツ連邦データ保護法（BDSG）、およびISO 27701規制に関する専門的なガイダンスが必要なコンプライアンスエージェントに最適","ko":"EU-DSGVO, BDSG 및 ISO 27701 규정에 대한 전문가 지침이 필요한 컴플라이언스 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Cumplimiento que necesitan orientación experta sobre las regulaciones EU-DSGVO, BDSG y ISO 27701.","fr":"Parfait pour les agents de conformité qui ont besoin de conseils d''experts sur les règlementations EU-DSGVO, BDSG et ISO 27701.","de":"Perfekt für Compliance-Agenten, die Expertenrat zu den EU-DSGVO-, BDSG- und ISO-27701-Regelungen benötigen.","pt":"Perfeito para Agentes de Conformidade que precisam de orientação especializada sobre as regulamentações EU-DSGVO, BDSG e ISO 27701.","ru":"Идеально подходит для агентов по соблюдению требований, которым необходима экспертная консультация по регулированию EU-DSGVO, BDSG и ISO 27701.","ar":"مثالي لعمليات الامتثال الذين يحتاجون إلى إرشادات خبيرة بشأن لوائح الاتحاد الأوروبي-DSGVO و BDSG و ISO 27701."},"recommendation":{"en":"Empowers agents to streamline compliance processes with comprehensive expertise in GDPR, Bundesdatenschutzgesetz, and Privacy Information Management Systems, ensuring robust data protection measures through protocols like ISO 27701:2025 and Data Reuse Principles.","zh":"赋予代理商流程合规的综合专业知识，包括通用数据保护条例（GDPR）、德国联邦数据保护法（Bundesdatenschutzgesetz）和隐私信息管理系统，确保通过ISO 27701:2025和数据重用原则等协议实施强大的数据保护措施","ja":"エージェントは、GDPR、ドイツ連邦データ保護法（Bundesdatenschutzgesetz）、およびプライバシー情報管理システムに関する包括的な専門知識を活用して、コンプライアンスプロセスを合理化でき、ISO 27701:2025やデータ再利用原則などのプロトコルを通じて、堅牢なデータ保護対策を実施できる","ko":"에이전트에게 GDPR, 독일 연방 데이터 보호법(Bundesdatenschutzgesetz) 및 개인 정보 관리 시스템에 대한 전문 지식을 제공하여 컴플라이언스 프로세스를 최적화하고 ISO 27701:2025 및 데이터 재사용 원칙과 같은 프로토콜을 통해 강력한 데이터 보호 조치를 제공합니다.","es":"Habilita a los agentes a racionalizar los procesos de cumplimiento con una experiencia integral en GDPR, Bundesdatenschutzgesetz y Sistemas de Gestión de Información de Privacidad, garantizando medidas de protección de datos sólidas a través de protocolos como ISO 27701:2025 y Principios de Reutilización de Datos.","fr":"Permet aux agents de rationaliser les processus de conformité avec une expertise complète en GDPR, Bundesdatenschutzgesetz et Systèmes de gestion de l''information sur la vie privée, garantissant des mesures de protection des données solides via des protocoles comme ISO 27701:2025 et Principes de réutilisation des données.","de":"Ermächtigt Agenten, Compliance-Prozesse mit umfassender Expertise in GDPR, Bundesdatenschutzgesetz und Privacy-Information-Management-Systemen zu rationalisieren, und stellt so robuste Datenschutzmaßnahmen durch Protokolle wie ISO 27701:2025 und Datenwiederverwendungsprinzipien sicher.","pt":"Habilita os agentes a otimizar os processos de conformidade com expertise abrangente em GDPR, Bundesdatenschutzgesetz e Sistemas de Gerenciamento de Informações de Privacidade, garantindo medidas robustas de proteção de dados por meio de protocolos como ISO 27701:2025 e Princípios de Reutilização de Dados.","ru":"Наделяет агентов возможностью оптимизировать процессы соблюдения требований с помощью всесторонней экспертизы в области GDPR, Bundesdatenschutzgesetz и систем управления информацией о конфиденциальности, обеспечивая надежные меры защиты данных посредством протоколов, таких как ISO 27701:2025 и принципы повторного использования данных.","ar":"يمكّن الوكلاء من简اعة عمليات الامتثال بخبرة شاملة في مجال GDPR و Bundesdatenschutzgesetz ونظم إدارة المعلومات الخاصة، وضمان إجراءات حماية البيانات القوية من خلال بروتوكولات مثل ISO 27701:2025 ومبادئ إعادة استخدام البيانات."},"useCases":{"en":["Automating GDPR compliance checks","Generating data protection policies based on BDSG","Implementing ISO 27701:2025 standards for Privacy Information Management Systems"],"zh":["自动执行GDPR合规检查","根据BDSG生成数据保护策略","实施ISO 27701:2025标准的隐私信息管理系统"],"ja":["GDPRコンプライアンスチェックの自動化","BDSGに基づくデータ保護ポリシーの生成","プライバシー情報管理システムのISO 27701:2025規格の実装"],"ko":["GDPR 컴플라이언스 체크 자동화","BDSG 기반 데이터 보호 정책 생성","ISO 27701:2025 표준 개인 정보 관리 시스템 구현"],"es":["Automatizar controles de cumplimiento de GDPR","Generar políticas de protección de datos basadas en BDSG","Implementar normas ISO 27701:2025 para Sistemas de Gestión de Información de Privacidad"],"fr":["Automatiser les contrôles de conformité GDPR","Générer des politiques de protection des données basées sur le BDSG","Mettre en œuvre les normes ISO 27701:2025 pour les Systèmes de gestion de l''information sur la vie privée"],"de":["Automatisierung von GDPR-Konformitätskontrollen","Erstellung von Datenschutzrichtlinien auf Grundlage des BDSG","Umsetzung der ISO-27701:2025-Normen für Privacy-Information-Management-Systeme"],"pt":["Automatizar verificações de conformidade com o GDPR","Gerar políticas de proteção de dados com base no BDSG","Implementar padrões ISO 27701:2025 para Sistemas de Gerenciamento de Informações de Privacidade"],"ru":["Автоматизировать проверки соблюдения требований GDPR","Генерировать политики защиты данных на основе Bundesdatenschutzgesetz","Реализовывать стандарты ISO 27701:2025 для систем управления информацией о конфиденциальности"],"ar":["التحكم الآلي في عمليات الامتثال للGDPR","генерировать سياسات حماية البيانات حسب BDSG","تنفيذ معايير ISO 27701:2025 لنظم إدارة المعلومات الخاصة"]},"limitations":{"en":["Requires knowledge of EU and German data protection laws","Limited to GDPR, BDSG, and ISO 27701 regulations"],"zh":["需要了解欧盟和德国的数据保护法律","仅限于GDPR, BDSG和ISO 27701法规"],"ja":["EUおよびドイツのデータ保護法の知識が必要","GDPR、BDSG、およびISO 27701規制のみに限定"],"ko":["EU 및 독일의 데이터 보호 법률에 대한 지식 필요","GDPR, BDSG 및 ISO 27701 규정에만 적용"],"es":["Requiere conocimiento de las leyes de protección de datos de la UE y Alemania","Limitado a las regulaciones GDPR, BDSG y ISO 27701"],"fr":["Nécessite des connaissances en matière de lois sur la protection des données de l''UE et de l''Allemagne","Limité aux règlementations GDPR, BDSG et ISO 27701"],"de":["Benötigt Kenntnisse über EU- und deutsche Datenschutzgesetze","Begrenzt auf die Regelungen GDPR, BDSG und ISO 27701"],"pt":["Exige conhecimento das leis de proteção de dados da UE e da Alemanha","Limitado às regulamentações GDPR, BDSG e ISO 27701"],"ru":["Требует знания законов о защите данных ЕС и Германии","Ограничен регулированием GDPR, Bundesdatenschutzgesetz и ISO 27701"],"ar":["يتطلب معرفة لقوانين حماية البيانات في الاتحاد الأوروبي وألمانيا","محدود باللوائح GDPR و BDSG و ISO 27701"]},"version":4},"contentHash":"33f14d8e7c028b54589a7d91a37fb0bd5b93cb37713887b5e7718cf5aca1f3c4","qualityScore":45}');
