INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('moag1000/Little-ISMS-Helper/dpo-specialist', 'dpo-specialist', 'moag1000', 'Little-ISMS-Helper', 'community', 'dpo-specialist moag1000 Little-ISMS-Helper community The dpo-specialist skill provides comprehensive expertise in EU-DSGVO, BDSG, and ISO 27701, helping Data Protection Officers streamline compliance processes. This skill benefits organizations seeking to implement robust data protection measures. DPO Specialist是一种数据保护官专家，提供EU-DSGVO/GDPR、BDSG、ISO 27701等数据保护标准的专业知识 DPO Specialistはデータ保護官専門家で、EU-DSGVO/GDPR、BDSG、ISO 27701などのデータ保護標準の専門知識を提供 DPO Specialist는 데이터 보호 담당자 전문가로서 EU-DSGVO/GDPR, BDSG, ISO 27701 등 데이터 보호 표준에 대한 전문 지식을 제공 El DPO Specialist es un asistente para la protección de datos que ayuda a cumplir con la EU-DSGVO y el BDSG, con expertice en ISO 27701 Le DPO Specialist est un outil d''aide pour la protection des données qui aide à se conformer au RGPD et à la loi allemande sur la protection des données, avec une expertise en ISO 27701 Der DPO Specialist ist ein Datenschutzbeauftragter, der hilft, die EU-DSGVO und das BDSG einzuhalten, mit umfassender Expertise in ISO 27701 O DPO Specialist é um ajudante de ISMS que fornece expertise em EU-DSGVO, BDSG e ISO 27701 para garantir a privacidade dos dados ИИ Агент DPO Specialist - это помощник ISMS, который предоставляет экспертизу в области GDPR, BDSG и ISO 27701 для обеспечения безопасности данных دبليو بيو سبيشالست هو مساعد لنظام إدارة المعلومات الآمنة الذي يقدم خبرة في مجال الأمن السيبراني والغدر والمتعلقة بتقنيات مثل EU-DSGVO وBDSG وISO 27701 dpo-specialist setup guide GDPR compliance for AI agents ISO 27701 implementation EU-DSGVO regulations BDSG compliance Data Protection Officer tools dpo-specialist alternative how to use dpo-specialist dpo-specialist install GDPR compliance software DPO Specialist AI工具 数据保护标准 EU-DSGVO/GDPR BDSG ISO 27701 Data Reuse Principles ISMS系统 Provides expertise in EU-DSGVO (EU 2016/679) and BDSG (Bundesdatenschutzgesetz) regulations Supports implementation of ISO 27701:2025 and ISO 27701:2019 Privacy Information Management Systems Offers guidance on Data Reuse Principles for smart integration with existing ISMS Assists with compliance setup for GDPR and German data protection laws Helps organizations manage data protection processes efficiently dpo-specialist is a specialized AI agent skill that assists Data Protection Officers in implementing and managing EU-DSGVO, BDSG, and ISO 27701 compliance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('edrouhardmicrosoft/agent-canvas-skills/canvas-edit', 'community', 'edrouhardmicrosoft', 'agent-canvas-skills', 'edrouhardmicrosoft/agent-canvas-skills', 'canvas-edit', 0, 0, 45, '2026-03-08T01:57:15.413Z', '2026-03-08T02:07:08.900Z', '5409f531343118efd4d2139c9d8db3f4c61d103e1fed4d2cfc1ebdc7f45c71a5', '{"id":"edrouhardmicrosoft/agent-canvas-skills/canvas-edit","name":"canvas-edit","description":{"en":"canvas-edit is a floating toolbar that overlays design review findings directly on web pages in real-time. It benefits developers and QA teams by providing immediate visual annotations for identified issues during the debugging process.","zh":"Canvas Edit 是一个实时注释工具栏，能够直接在网页上显示设计审查结果","ja":"Canvas Edit は、リアルタイムの注釈ツールバーで、デザインレビュー結果を Web ページに直接表示します","ko":"Canvas Edit는 실시간 주석 도구 모음으로 웹 페이지에 디자인 리뷰 결과를 직접 표시합니다","es":"Canvas-edit es una herramienta de anotación en tiempo real que permite a los desarrolladores mejorar la experiencia de diseño con anotaciones y herramientas de AI","fr":"Canvas-edit est un outil d''annotation en temps réel qui permet aux développeurs d''améliorer l''expérience de conception avec des annotations et des outils d''IA","de":"Canvas-edit ist ein Tool für Echtzeit-Annotierungen, das es Entwicklern ermöglicht, die Konstruktionserfahrung mit Annotierungen und KI-Tools zu verbessern","pt":"O Canvas Edit é uma ferramenta de anotação em tempo real que overlay design review findings diretamente em páginas web. Ele oferece recursos como anotações ao vivo, indicadores de gravidade e captura de tela em um clique.","ru":"Canvas Edit - это инструмент живой аннотации, который наложает результаты проверки дизайна непосредственно на веб-страницы в режиме реального времени. Он предлагает функции, такие как живые аннотации, индикаторы серьезности и захват экрана в один клик для ИИ Агентов.","ar":"Canvas Edit هو أداة للتعليق المباشر التي تعلق نتائج مراجعة التصميم مباشرة على صفحات الويب في الوقت الفعلي. يقدم ميزات مثل التعليقات الحية ومؤشرات الحدة وتصوير الشاشة في نقرة واحدة للوكلاء الذكية"},"seo":{"title":{"en":"canvas-edit: Live Web Annotation Toolbar | AI Agent Skill","zh":"Canvas Edit 设置指南 - 实时注释工具栏","ja":"Canvas Edit のベストプラクティス - AIエージェントによるリアルタイム注釈","ko":"Canvas Edit 설치 가이드 - 실시간 주석 도구 모음","es":"Guía de configuración de canvas-edit para herramientas de AI","fr":"Configurer canvas-edit pour les outils d''IA - Guide","de":"Einrichten von canvas-edit für KI-Tools - Leitfaden","pt":"Guia de Configuração do Canvas Edit - Ferramenta de Anota...","ru":"Настройка Canvas Edit - Инструмент живой аннотации для ИИ...","ar":"دليل إعداد Canvas Edit - أداة التعليق المباشر للوكلاء الذكية"},"description":{"en":"Add real-time design review overlays to any webpage. canvas-edit displays numbered badges on problematic elements with severity-colored borders and one-click...","zh":"了解 Canvas Edit 的实时注释工具栏，实现网页设计审查的自动化和优化","ja":"Canvas Edit を使用して、リアルタイムの注釈とデザインレビューの自動化を実現します","ko":"Canvas Edit를 사용하여 실시간 주석과 디자인 리뷰의 자동화를实现하세요","es":"Aprende a utilizar canvas-edit para anotaciones en tiempo real y mejora la experiencia de diseño con herramientas de AI","fr":"Découvrez comment configurer canvas-edit pour des annotations en temps réel et améliorer l''expérience de conception avec les outils d''IA","de":"Erfahren Sie, wie Sie canvas-edit für Echtzeit-Annotierungen einrichten und die Konstruktionserfahrung mit KI-Tools verbessern","pt":"Aprenda a usar o Canvas Edit para anotações em tempo real em suas aplicações web com nossa guia de configuração","ru":"Узнайте, как настроить Canvas Edit для живой аннотации на ваших веб-страницах с нашей инструкцией по настройке для ИИ Агентов","ar":"تعلم كيفية استخدام Canvas Edit لأداة التعليق المباشر في تطبيقات الويب الخاصة بك مع دليل الإعداد الخاص بنا للوكلاء الذكية"},"definition":{"en":"canvas-edit is an AI Agent skill that provides a live annotation toolbar for web design reviews. It overlays numbered badges with color-coded severity borders on problematic page elements and enables detailed issue inspection via hover popovers.","zh":"Canvas Edit 是一个实时注释工具栏，用于网页设计审查和优化","ja":"Canvas Edit は、デザインレビューと最適化のためのリアルタイム注釈ツールバーです","ko":"Canvas Edit는 디자인 리뷰와 최적화를 위한 실시간 주석 도구 모음입니다","es":"Canvas-edit es una herramienta de AI que permite anotaciones en tiempo real en páginas web","fr":"Canvas-edit est un outil d''IA qui permet des annotations en temps réel sur les pages web","de":"Canvas-edit ist ein KI-Tool, das Echtzeit-Annotierungen auf Webseiten ermöglicht","pt":"O Canvas Edit é uma ferramenta de anotação em tempo real que permite anotações ao vivo e indicadores de gravidade em páginas web","ru":"Canvas Edit - это инструмент живой аннотации, который позволяет создавать живые аннотации и индикаторы серьезности на веб-страницах для ИИ Агентов","ar":"Canvas Edit هو أداة للتعليق المباشر التي تمكن من التعليقات الحية ومؤشرات الحدة على صفحات الويب للوكلاء الذكية"},"features":{"en":["Displays live numbered badges on elements as issues are found","Applies color-coded severity borders (red/orange/blue) to badges","Provides hover popovers with detailed issue information","Enables one-click screenshot capture for documentation"],"zh":["实时注释","编号徽章和严重性指示器","悬停弹出式问题详细信息","一键截图捕获"],"ja":["リアルタイム注釈","番号バッジとSeverity インディケーター","ホーバーポップオーバーによる問題詳細","ワンクリックスクリーンショットキャプチャ"],"ko":["실시간 주석","번호 배지와 심각도 지시기","호버 팝오버에 의한 문제 세부 정보","한 번의 클릭으로 스크린샷 캡처"],"es":["Anotaciones en tiempo real","Indicadores de gravedad con colores","Emergentes de detalles de problemas","Captura de pantalla de un solo clic"],"fr":["Annotations en temps réel","Indicateurs de gravité avec des couleurs","Bulles d''informations pour les détails des problèmes","Capture d''écran en un seul clic"],"de":["Echtzeit-Annotierungen","Schweregrade-Indikatoren mit Farben","Popups mit Problemdetails","Ein-Klick-Screenshot"],"pt":["Anotações ao vivo com números e bordas coloridas","Indicadores de gravidade com contagens e cores","Popovers de problemas com detalhes de issues","Captura de tela em um clique"],"ru":["Живые аннотации с номерами и цветными границами","Индикаторы серьезности с подсчетами и цветами для ИИ Агентов","Поповеры проблем с подробной информацией об ошибках","Захват экрана в один клик"],"ar":["التعليقات الحية مع الأرقام والحدود الملونة","مؤشرات الحدة مع العد وال ألوان للوكلاء الذكية","نافذات منبثقة للمشاكل بالتفاصيل حول القضايا","تصوير الشاشة في نقرة واحدة"]},"keywords":{"en":["what is canvas-edit","how to use canvas-edit annotation toolbar","canvas-edit vs browser devtools","canvas-edit alternative","canvas-edit install guide","canvas-edit setup for AI agents","real-time web design review tool","live annotation toolbar for developers"],"zh":["Canvas Edit","实时注释工具栏","网页设计审查","AI工具","自动化","优化","设计审查","实时注释"],"ja":["Canvas Edit","リアルタイム注釈ツールバー","デザインレビュー","AIエージェント","自動化","最適化","デザインレビュー","リアルタイム注釈"],"ko":["Canvas Edit","실시간 주석 도구 모음","디자인 리뷰","AI_tools","자동화","최적화","디자인 리뷰","실시간 주석"],"es":["herramientas de AI","anotaciones en tiempo real","diseño de experiencia de usuario","canvas-edit","desarrollo web","herramientas de desarrollo"],"fr":["outils d''IA","annotations en temps réel","conception d''expérience utilisateur","canvas-edit","développement web","outils de développement"],"de":["KI-Tools","Echtzeit-Annotierungen","Benutzererfahrungsentwicklung","canvas-edit","Webentwicklung","Entwicklungstools"],"pt":["Canvas Edit","Ferramenta de anotação em tempo real","Anotações ao vivo","Indicadores de gravidade","Captura de tela","Desenvolvimento web","Ferramentas de desenvolvimento"],"ru":["Canvas Edit","Инструмент живой аннотации","Живые аннотации","Индикаторы серьезности","Захват экрана","Разработка веб-страниц","ИИ Агенты","Инструменты для ИИ Агентов"],"ar":["Canvas Edit","أداة التعليق المباشر","التعليقات الحية","مؤشرات الحدة","تصوير الشاشة","تطوير الويب","الوكلاء الذكية","أدوات الوكلاء الذكية"]}},"owner":"edrouhardmicrosoft","repo":"agent-canvas-skills","repoPath":"edrouhardmicrosoft/agent-canvas-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.413Z","topics":[],"category":"community","skillMd":{"name":"canvas-edit","description":"Live Annotation Feedback Toolbar that overlays design review findings directly on web pages. Displays numbered badges on elements with issues, severity indicators, filtering, and screenshot capture. Integrates with design-review for real-time issue display. Triggers on show annotations, display issues, annotate page, overlay findings, or after running design-review.","bodyPreview":"# Canvas Edit - Live Annotation Toolbar\n\nFloating toolbar that overlays design review findings directly on web pages in real-time. Displays numbered badges on problematic elements with severity-colored borders, hover popovers for issue details, and one-click screenshot capture.\n\n**Key features:**\n- **Live annotations** - Numbered badges appear on elements as issues are found\n- **Severity indicators** - Color-coded badges (red/orange/blue) with counts\n- **Issue popovers** - Click badges to see fu","body":"# Canvas Edit - Live Annotation Toolbar\n\nFloating toolbar that overlays design review findings directly on web pages in real-time. Displays numbered badges on problematic elements with severity-colored borders, hover popovers for issue details, and one-click screenshot capture.\n\n**Key features:**\n- **Live annotations** - Numbered badges appear on elements as issues are found\n- **Severity indicators** - Color-coded badges (red/orange/blue) with counts\n- **Issue popovers** - Click badges to see full issue details and recommendations\n- **Screenshot capture** - Capture annotated page (toolbar hidden, annotations visible)\n- **Shadow DOM** - Toolbar is invisible to agent-eyes screenshots\n- **Filtering** - Filter by severity or pillar category\n\n## Breaking Changes from v1\n\n> **This is a complete redesign.** Canvas-edit is now a **viewing tool**, not an editing tool.\n\n| Old Functionality | New Behavior |\n|-------------------|--------------|\n| Text editing via textarea | **REMOVED** |\n| Style sliders (fontSize, etc.) | **REMOVED** |\n| \"Save All to Code\" button | **REPLACED** with screenshot capture |\n| contentEditable toggle | **REMOVED** |\n| `edit` command | **REPLACED** with `inject` command |\n\nFor live editing, use `agent-canvas --with-edit` instead.\n\n## Prerequisites\n\n- Python 3.10+\n- `uv` package manager\n- Playwright browsers: `playwright install chromium`\n\n## Commands\n\n```bash\nSKILL_DIR=\".claude/skills/canvas-edit/scripts\"\n```\n\n### Inject Annotations onto Page\n\n```bash\n# Inject toolbar with issues from JSON file\nuv run $SKILL_DIR/canvas_edit.py inject http://localhost:3000 --issues issues.json\n\n# Inject with issues from stdin\necho ''[{\"id\": 1, \"selector\": \"h1\", \"severity\": \"major\", \"title\": \"Contrast issue\"}]'' | \\\n  uv run $SKILL_DIR/canvas_edit.py inject http://localhost:3000 --issues -\n\n# Auto-screenshot on load\nuv run $SKILL_DIR/canvas_edit.py inject http://localhost:3000 --issues issues.json --screenshot\n```\n\n### Typical Workflow: Design Review + Annotations\n\n```bash\n# 1. Run design review to find issues\nuv run .claude/skills/design-review/scripts/design_review.py review http://localhost:3000 \\\n  --output-json issues.json\n\n# 2. Inject annotations onto the page\nuv run $SKILL_DIR/canvas_edit.py inject http://localhost:3000 --issues issues.json\n\n# 3. User interacts with annotations, takes screenshots, closes browser\n```\n\n## Toolbar Controls\n\nThe floating toolbar (top-right by default) provides:\n\n**Status Display**\n- Issue count (\"5 Issues\" or \"All looks good!\")\n- Severity badges: 🔴 blocking, 🟡 major, 🔵 minor\n\n**Actions**\n- **👁 Visibility**: Show/hide all annotations\n- **⚙ Filter**: Filter by severity or pillar category\n- **📸 Screenshot**: Capture page with annotations (toolbar hidden)\n- **↕/↔ Orientation**: Toggle vertical/horizontal toolbar\n- **✕ Dismiss**: Remove toolbar and all annotations\n\n**Dragging**\n- Grab the ☰ handle to drag toolbar anywhere on screen\n- Position persists during session\n\n## Annotation Badges\n\nEach issue appears as a numbered badge on its target element:\n\n- **Position**: Top-right of target element (auto-adjusts at screen edges)\n- **Color**: Border matches severity (red/orange/blue)\n- **Click**: Opens popover with full issue details\n- **Hover**: Highlights the target element\n\n### Badge Popover Contents\n\n```\n┌─────────────────────────────────────┐\n│ #3  Contrast issue         [major] │\n├─────────────────────────────────────┤\n│ Color contrast ratio 3.2:1 fails   │\n│ WCAG AA requirement of 4.5:1       │\n│                                     │\n│ Pillar: Quality Craft               │\n│ Check: color-contrast               │\n├─────────────────────────────────────┤\n│ Recommendation:                     │\n│ Change text color to #1a1a1a or    │\n│ background to #ffffff              │\n└─────────────────────────────────────┘\n```\n\n## Issue JSON Format\n\nIssues can come from design-review output or be manually constructed:\n\n```json\n[\n  {\n    \"id\": 1,\n    \"selector\": \".hero-title\",\n    \"severity\": \"major\",\n    \"title\": \"Contrast ratio insufficient\",\n    \"description\": \"Text contrast 3.2:1 fails WCAG AA (4.5:1 required)\",\n    \"pillar\": \"Quality Craft\",\n    \"checkId\": \"color-contrast\",\n    \"recommendation\": \"Use darker text (#1a1a1a) or lighter background\"\n  },\n  {\n    \"id\": 2,\n    \"selector\": \"button.submit\",\n    \"severity\": \"minor\",\n    \"title\": \"Touch target too small\",\n    \"description\": \"Button is 36x28px, minimum is 44x44px\",\n    \"pillar\": \"Quality Craft\",\n    \"checkId\": \"touch-target-size\"\n  }\n]\n```\n\n### Required Fields\n\n| Field | Type | Description |\n|-------|------|-------------|\n| `id` | number | Unique identifier |\n| `selector` | string | CSS selector for target element |\n| `severity` | string | `\"blocking\"`, `\"major\"`, or `\"minor\"` |\n| `title` | string | Short issue title |\n\n### Optional Fields\n\n| Field | Type | Description |\n|-------|------|-------------|\n| `description` | string | Detailed explanation |\n| `pillar` | string | Design pillar category |\n| `checkId` | string | Identifier for the check that found this |\n| `recommendation` | string | Suggested fix |\n\n## Event API (Canvas Bus)\n\nCanvas-edit integrates with other skills via the canvas bus event system.\n\n### Events Emitted\n\n| Event | Payload | When |\n|-------|---------|------|\n| `annotation.clicked` | `{issueId, selector, severity}` | User clicks a badge |\n| `screenshot.requested` | `{directory, filename, issueCount}` | Screenshot button clicked |\n| `screenshot.captured` | `{path, issueCount}` | Screenshot saved (Python-side) |\n| `annotations.cleared` | `{}` | Dismiss button clicked |\n| `filter.changed` | `{severity, pillars}` | Filter settings changed |\n\n### Events Subscribed\n\n| Event | Action |\n|-------|--------|\n| `review.started` | Show \"Scanning...\" state |\n| `review.issue_found` | Add badge for new issue |\n| `review.completed` | Show final count or success message |\n| `capture_mode.changed` | Hide/show toolbar for agent-eyes |\n\n### Integration Example\n\n```javascript\n// In another skill''s JavaScript\nconst bus = window.__canvasBus;\n\n// Listen for annotation clicks\nbus.subscribe(''annotation.clicked'', (payload) => {\n  console.log(`Issue ${payload.issueId} clicked: ${payload.selector}`);\n});\n\n// Add an issue programmatically\nwindow.__annotationLayer.addIssue({\n  id: 99,\n  selector: ''.problematic-element'',\n  severity: ''major'',\n  title: ''New issue found''\n});\n```\n\n## Screenshot Output\n\nScreenshots are saved to `.canvas/screenshots/` with timestamp filenames:\n\n```\n.canvas/screenshots/\n├── 2026-01-23T15-30-45_5-issues.png\n└── 2026-01-23T15-45-12_0-issues.png\n```\n\nFilename format: `YYYY-MM-DDTHH-MM-SS_N-issues.png`\n\nScreenshots capture:\n- Full page content\n- All visible annotation badges\n- Element highlights (if active)\n- **NOT** the toolbar (hidden during capture)\n\n## Toolbar States\n\n| State | Display | Trigger |\n|-------|---------|---------|\n| **Issues Found** | \"N Issues\" + severity badges | Default when issues > 0 |\n| **All Clear** | \"✓ All looks good!\" (randomized) | Zero issues after review completes |\n| **Scanning** | \"⟳ Analyzing...\" with spinner | During `review.started` |\n\nSuccess messages rotate randomly:\n- \"All looks good!\"\n- \"Ship it!\"\n- \"Pixel perfect\"\n- \"Zero issues found\"\n- \"Looking sharp!\"\n\n## Keyboard Navigation\n\n| Key | Action |\n|-----|--------|\n| `Tab` | Navigate toolbar controls |\n| `1-9` | Jump to badge by number |\n| `Arrow keys` | Navigate between visible badges |\n| `Enter/Space` | Activate focused button/badge |\n| `Escape` | Close open popover |\n\n## Shadow DOM Isolation\n\nThe toolbar is rendered inside a closed Shadow DOM:\n- Invisible to `document.querySelector()`\n- Excluded from agent-eyes DOM snapshots\n- Hidden from screenshots (annotations remain visible)\n- Page styles cannot affect toolbar appearance\n\n## Notes\n\n- Toolbar auto-repositions to stay on screen when dragged or resized\n- Badges reposition when window resizes or scrolls\n- Multiple badges on the same element stack with offset\n- Orphaned badges (element removed) are automatically cleaned up\n- Filter state persists during session but resets on page reload\n"},"lastSynced":"2026-03-08T02:07:08.900Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing real-time web page annotation and debugging capabilities.","zh":"非常适合需要实时网页注释和调试功能的前端代理。","ja":"フロントエンドエージェントがリアルタイムのWebページ注釈とデバッグ機能を必要とする場合に最適です。","ko":"실시간 웹 페이지 주석 및 디버깅 기능이 필요한 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan capacidades de anotación y depuración de páginas web en tiempo real.","fr":"Parfait pour les agents Frontend qui ont besoin de fonctionnalités d''annotation et de débogage de pages Web en temps réel.","de":"Perfekt für Frontend-Agents, die Echtzeit-Webseiten-Anmerkung und -Debugging-Funktionen benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de capacidades de anotação e depuração de páginas da web em tempo real.","ru":"Идеально для агентов Frontend, которым необходимы возможности аннотации и отладки веб-страниц в реальном времени.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى إمكانيات التعليق والتصحيح الفوري لصفحات الويب."},"recommendation":{"en":"Empowers agents to overlay design review findings directly on web pages using live annotations, severity indicators, and issue popovers, streamlining the debugging process with numbered badges, hover popovers, and one-click screenshot capture via HTTP protocol.","zh":"使代理能够直接在网页上叠加设计审查结果，使用实时注释、严重性指标和问题弹出窗口，通过编号徽章、悬停弹出窗口和单击截图捕获通过HTTP协议简化调试过程。","ja":"エージェントがリアルタイムの注釈、重大度指標、および問題ポップオーバーを使用して、Webページに直接デザインレビューの結果をオーバーレイできます。HTTPプロトコル経由の1クリックスクリーンショットキャプチャ、番号バッジ、ホバーポップオーバーを使用して、デバッグプロセスを簡素化します。","ko":"에이전트가 라이브 주석, 심각성 지표 및 문제 팝오버를 사용하여 웹 페이지에 직접 디자인 검토 결과를 오버레이 할 수 있습니다. HTTP 프로토콜을 통해 번호 배지, 호버 팝오버 및 한 번의 클릭으로 스크린샷을 캡처하여 디버깅 프로세스를 간소화합니다.","es":"Habilita a los agentes a superponer los resultados de la revisión del diseño directamente en las páginas web utilizando anotaciones en vivo, indicadores de gravedad y emergentes de problemas, simplificando el proceso de depuración con insignias numeradas, emergentes con desplazamiento y captura de pantalla de un solo clic a través del protocolo HTTP.","fr":"Permet aux agents de superposer les résultats de l''examen de la conception directement sur les pages Web à l''aide d''annotations en direct, d''indicateurs de gravité et de fenêtres contextuelles de problème, simplifiant le processus de débogage avec des badges numérotés, des fenêtres contextuelles de survol et une capture d''écran en un seul clic via le protocole HTTP.","de":"Ermöglicht es Agents, Design-Review-Ergebnisse direkt auf Webseiten zu überlagern, indem sie Live-Anmerkungen, Schweregrad-Indikatoren und Problempopovers verwenden, wodurch der Debugging-Prozess mit nummerierten Abzeichen, Hover-Popovers und Ein-Klick-Screenshot-Erfassung über das HTTP-Protokoll vereinfacht wird.","pt":"Habilita os agentes a sobrepor as descobertas de revisão de design diretamente nas páginas da web usando anotações ao vivo, indicadores de gravidade e popovers de problemas, simplificando o processo de depuração com badges numeradas, popovers ao pairar e captura de tela com um clique via protocolo HTTP.","ru":"Наделяет агентов возможностью наложить результаты проверки дизайна непосредственно на веб-страницы с помощью живых аннотаций, индикаторов серьезности и всплывающих окон проблем, оптимизируя процесс отладки за счет пронумерованных значков, всплывающих окон при наведении и захвата экрана в один клик через протокол HTTP.","ar":"يمنح الوكلاء القدرة على وضع نتائج مراجعة التصميم مباشرة على صفحات الويب باستخدام التعليقات الحية ومؤشرات الجدية والنوافذ المنبثقة للمشاكل، وتبрощ عملية التصحيح باستخدام شارات منقطة وأشعة الضوء والتصوير بالضغط على الزر مرة واحدة عبر بروتوكول HTTP."},"useCases":{"en":["Debugging web page elements with live annotations","Generating issue reports with severity-colored borders","Capturing one-click screenshots for issue documentation"],"zh":["使用实时注释调试网页元素","使用严重性着色边框生成问题报告","使用单击截图功能捕获问题文档"],"ja":["リアルタイム注釈を使用してWebページ要素をデバッグする","重大度着色ボーダーを使用して問題報告書を生成する","1クリックスクリーンショット機能を使用して問題ドキュメントをキャプチャする"],"ko":["실시간 주석을 사용하여 웹 페이지 요소를 디버깅하는 것","심각성 着色 경계를 사용하여 문제 보고서를 생성하는 것","한 번의 클릭으로 스크린샷을 캡처하여 문제 문서를 기록하는 것"],"es":["Depuración de elementos de página web con anotaciones en vivo","Generación de informes de problemas con bordes de color de gravedad","Captura de capturas de pantalla de un solo clic para la documentación de problemas"],"fr":["Débogage d''éléments de page Web avec des annotations en direct","Génération de rapports de problèmes avec des bordures de couleur de gravité","Capture d''captures d''écran en un seul clic pour la documentation des problèmes"],"de":["Debugging von Webseitenelementen mit Live-Anmerkungen","Erstellung von Problemmeldungen mit Schweregrad-farbigen Rändern","Erfassung von Ein-Klick-Screenshots für die Problemdokumentation"],"pt":["Depuração de elementos de página da web com anotações ao vivo","Geração de relatórios de problemas com bordas coloridas de gravidade","Captura de telas com um clique para documentação de problemas"],"ru":["Отладка элементов веб-страниц с живыми аннотациями","Генерация отчетов о проблемах с цветными границами серьезности","Захват экрана в один клик для документации проблем"],"ar":["تصحيح عناصر صفحة الويب بالتعليقات الفورية","توليد تقارير المشاكل بأحواض ملونة للجدية","التقاط الشاشة باستخدام الزر مرة واحدة لتوثيق المشاكل"]},"limitations":{"en":["Requires web page access for overlay functionality","Limited to web-based applications"],"zh":["需要网页访问权限以实现叠加功能","仅限于基于Web的应用程序"],"ja":["オーバーレイ機能を実現するためにWebページへのアクセスが必要","Webベースのアプリケーションに限定される"],"ko":["오버레이 기능을 구현하기 위해 웹 페이지에 접근 권한이 필요함","웹 기반 응용 프로그램에만 제한됨"],"es":["Requiere acceso a la página web para la funcionalidad de superposición","Limitado a aplicaciones basadas en web"],"fr":["Nécessite un accès à la page Web pour la fonctionnalité de superposition","Limité aux applications basées sur le Web"],"de":["Benötigt Zugriff auf die Webseite für die Überlagerungsfunktion","Begrenzt auf webbasierte Anwendungen"],"pt":["Requer acesso à página da web para funcionalidade de sobreposição","Limitado a aplicações baseadas na web"],"ru":["Требует доступа к веб-странице для функциональности наложения","Ограничен веб-приложениями"],"ar":["يتطلب الوصول إلى صفحة الويب للوظيفة الفائقة","محدود للتطبيقات المستندة إلى الويب"]},"version":4},"contentHash":"5409f531343118efd4d2139c9d8db3f4c61d103e1fed4d2cfc1ebdc7f45c71a5","qualityScore":45}');
