INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('edrouhardmicrosoft/agent-canvas-skills/canvas-edit', 'canvas-edit', 'edrouhardmicrosoft', 'agent-canvas-skills', 'community', 'canvas-edit edrouhardmicrosoft agent-canvas-skills community canvas-edit is a floating toolbar that overlays design review findings directly on web pages in real-time. It benefits developers and QA teams by providing immediate visual annotations for identified issues during the debugging process. Canvas Edit 是一个实时注释工具栏，能够直接在网页上显示设计审查结果 Canvas Edit は、リアルタイムの注釈ツールバーで、デザインレビュー結果を Web ページに直接表示します Canvas Edit는 실시간 주석 도구 모음으로 웹 페이지에 디자인 리뷰 결과를 직접 표시합니다 Canvas-edit es una herramienta de anotación en tiempo real que permite a los desarrolladores mejorar la experiencia de diseño con anotaciones y herramientas de AI Canvas-edit est un outil d''annotation en temps réel qui permet aux développeurs d''améliorer l''expérience de conception avec des annotations et des outils d''IA Canvas-edit ist ein Tool für Echtzeit-Annotierungen, das es Entwicklern ermöglicht, die Konstruktionserfahrung mit Annotierungen und KI-Tools zu verbessern O Canvas Edit é uma ferramenta de anotação em tempo real que overlay design review findings diretamente em páginas web. Ele oferece recursos como anotações ao vivo, indicadores de gravidade e captura de tela em um clique. Canvas Edit - это инструмент живой аннотации, который наложает результаты проверки дизайна непосредственно на веб-страницы в режиме реального времени. Он предлагает функции, такие как живые аннотации, индикаторы серьезности и захват экрана в один клик для ИИ Агентов. Canvas Edit هو أداة للتعليق المباشر التي تعلق نتائج مراجعة التصميم مباشرة على صفحات الويب في الوقت الفعلي. يقدم ميزات مثل التعليقات الحية ومؤشرات الحدة وتصوير الشاشة في نقرة واحدة للوكلاء الذكية what is canvas-edit how to use canvas-edit annotation toolbar canvas-edit vs browser devtools canvas-edit alternative canvas-edit install guide canvas-edit setup for AI agents real-time web design review tool live annotation toolbar for developers Canvas Edit 实时注释工具栏 网页设计审查 AI工具 自动化 优化 设计审查 实时注释 Displays live numbered badges on elements as issues are found Applies color-coded severity borders (red/orange/blue) to badges Provides hover popovers with detailed issue information Enables one-click screenshot capture for documentation canvas-edit is an AI Agent skill that provides a live annotation toolbar for web design reviews. It overlays numbered badges with color-coded severity borders on problematic page elements and enables detailed issue inspection via hover popovers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mattgierhart/PRD-driven-context-engineering/ghm-gate-check', 'community', 'mattgierhart', 'PRD-driven-context-engineering', 'mattgierhart/PRD-driven-context-engineering', 'ghm-gate-check', 0, 0, 45, '2026-03-08T01:57:15.415Z', '2026-03-08T02:07:12.134Z', 'a4f2f571a18da68b322e3e5b314158946ae8127be8c3bf45739314dac8a3e135', '{"id":"mattgierhart/PRD-driven-context-engineering/ghm-gate-check","name":"ghm-gate-check","description":{"en":"The ghm-gate-check skill validates PRD lifecycle versions by checking gate criteria and ensuring required artifacts exist. It benefits developers and product managers by automating the validation process.","zh":"ghm-gate-check 是一个 PRD 驱动的上下文工程方法，用于构建 AI 驱动的产品。它包括加载门槛标准、验证证据、评估准备就绪性和报告等步骤","ja":"ghm-gate-check は、AI ドリブンの製品を構築するための PRD ドリブンのコンテキストエンジニアリング方法です。ゲート基準の読み込み、証拠の検証、準備就绪性の評価、レポート作成などが含まれます","ko":"ghm-gate-check는 AI 주도 제품을 구축하기 위한 PRD 주도 컨텍스트 엔지니어링 방법입니다. 게이트 기준 읽기, 증거 검증, 준비 완료 평가 및 보고서 생성 등이 포함됩니다","es":"Ghm-gate-check es una herramienta de validación de criterios de puerta para productos de IA que utiliza un enfoque sistemático para garantizar la calidad y la precisión","fr":"Ghm-gate-check est un outil de validation des critères de passerelle pour les produits d''IA qui utilise une approche systématique pour assurer la qualité et la précision","de":"Ghm-gate-check ist ein Tool zur Validierung von Tor-Kriterien für KI-Produkte, das einen systematischen Ansatz verwendet, um Qualität und Genauigkeit zu gewährleisten","pt":"O ghm-gate-check é uma abordagem sistemática para construir produtos AI usando documentação progressiva e fluxos de trabalho de desenvolvimento sensíveis ao contexto","ru":"Ghm-gate-check - системный подход к созданию продуктов ИИ с помощью прогрессивной документации и контекстно-зависимых рабочих процессов разработки","ar":"ghm-gate-check هو نهج منهجي لبناء منتجات الذكاء الاصطناعي باستخدام توثيق تدريجي وعمليات عمل متطورة حساسة للسياق"},"seo":{"title":{"en":"ghm-gate-check: PRD Validation Setup Guide | AI Agent Skill","zh":"ghm-gate-check 设置指南：AI 代理工具的上下文工程","ja":"ghm-gate-check セットアップガイド：AI エージェントのコンテキストエンジニアリング","ko":"ghm-gate-check 설정 가이드: AI 에이전트를 위한 컨텍스트 엔지니어링","es":"Guía de configuración de ghm-gate-check: Validación de cr...","fr":"Guide de mise en place de ghm-gate-check : Validation des...","de":"Einrichtungsleitfaden für ghm-gate-check: Validierung von...","pt":"Guia de Configuração do ghm-gate-check: Validação de Crit...","ru":"Настройка ghm-gate-check: Проверка Критериев Шлюза для ИИ...","ar":"دليل إعداد ghm-gate-check: التحقق من معايير البوابة لآلات..."},"description":{"en":"Streamline your PRD lifecycle with ghm-gate-check. Learn how to validate gate criteria and ensure compliance with this AI-powered tool. Get started now!","zh":"了解 ghm-gate-check 的技术细节，包括工作流概述和核心输出模板，实现 AI 代理工具的高效开发","ja":"ghm-gate-check の技術的詳細を学び、ワークフローの概要とコア出力テンプレートを理解して、AI エージェントツールの開発を効率化する","ko":"ghm-gate-check의 기술적 세부 사항을 알아보고, 워크플로우 개요와 핵심 출력 템플릿을 이해하여 AI 에이전트 도구의 개발을 효율화하세요","es":"Aprende a validar criterios de puerta para productos de IA con ghm-gate-check. Descubre cómo funciona y cómo implementarlo en tu flujo de trabajo","fr":"Découvrez comment valider les critères de passerelle pour les produits d''IA avec ghm-gate-check. Comprenez son fonctionnement et son intégration dans votre w...","de":"Erfahren Sie, wie Sie mit ghm-gate-check die Tor-Kriterien für KI-Produkte validieren. Lernen Sie, wie es funktioniert und wie Sie es in Ihren Arbeitsablauf ...","pt":"Aprenda a configurar o ghm-gate-check para validar critérios de porta e melhorar o desenvolvimento de produtos AI","ru":"Узнайте, как настроить ghm-gate-check для проверки критериев шлюза и улучшения разработки продуктов ИИ","ar":"تعرف على كيفية إعداد ghm-gate-check لتحقق من معايير البوابة وتحسين تطوير منتجات الذكاء الاصطناعي"},"definition":{"en":"ghm-gate-check is 