INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mattgierhart/PRD-driven-context-engineering/ghm-gate-check', 'ghm-gate-check', 'mattgierhart', 'PRD-driven-context-engineering', 'community', 'ghm-gate-check mattgierhart PRD-driven-context-engineering community The ghm-gate-check skill validates PRD lifecycle versions by checking gate criteria and ensuring required artifacts exist. It benefits developers and product managers by automating the validation process. ghm-gate-check 是一个 PRD 驱动的上下文工程方法，用于构建 AI 驱动的产品。它包括加载门槛标准、验证证据、评估准备就绪性和报告等步骤 ghm-gate-check は、AI ドリブンの製品を構築するための PRD ドリブンのコンテキストエンジニアリング方法です。ゲート基準の読み込み、証拠の検証、準備就绪性の評価、レポート作成などが含まれます ghm-gate-check는 AI 주도 제품을 구축하기 위한 PRD 주도 컨텍스트 엔지니어링 방법입니다. 게이트 기준 읽기, 증거 검증, 준비 완료 평가 및 보고서 생성 등이 포함됩니다 Ghm-gate-check es una herramienta de validación de criterios de puerta para productos de IA que utiliza un enfoque sistemático para garantizar la calidad y la precisión Ghm-gate-check est un outil de validation des critères de passerelle pour les produits d''IA qui utilise une approche systématique pour assurer la qualité et la précision Ghm-gate-check ist ein Tool zur Validierung von Tor-Kriterien für KI-Produkte, das einen systematischen Ansatz verwendet, um Qualität und Genauigkeit zu gewährleisten O ghm-gate-check é uma abordagem sistemática para construir produtos AI usando documentação progressiva e fluxos de trabalho de desenvolvimento sensíveis ao contexto Ghm-gate-check - системный подход к созданию продуктов ИИ с помощью прогрессивной документации и контекстно-зависимых рабочих процессов разработки ghm-gate-check هو نهج منهجي لبناء منتجات الذكاء الاصطناعي باستخدام توثيق تدريجي وعمليات عمل متطورة حساسة للسياق how to use ghm-gate-check ghm-gate-check setup guide ghm-gate-check alternative ghm-gate-check vs manual validation PRD validation tools AI-powered product development context-aware development workflows ghm-gate-check install AI 代理工具 PRD 驱动的上下文工程 ghm-gate-check 加载门槛标准 验证证据 评估准备就绪性 报告生成 AI 开发 Loads gate criteria from PRD.md files Verifies evidence by checking required artifacts with valid IDs Assesses readiness by evaluating handoff requirements Generates reports with pass/block status and specific gaps Uses a core output template to define target gates and evidence ghm-gate-check is a systematic approach to building AI-powered products using progressive documentation and context-aware development workflows to validate gate criteria.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ChetanG111/safer-claw/writing-plans', 'community', 'ChetanG111', 'safer-claw', 'ChetanG111/safer-claw', 'writing-plans', 0, 0, 45, '2026-03-08T01:57:15.416Z', '2026-03-08T02:07:14.881Z', '53988353ca1cb25d779144c9de8666f5e64ce7fa6fbdd17dc49d07709cd3c04f', '{"id":"ChetanG111/safer-claw/writing-plans","name":"writing-plans","description":{"en":"The writing-plans skill generates comprehensive implementation plans for developers, including code, testing, and documentation. It benefits skilled developers new to a codebase or toolset.","zh":"Writing Plans提供了一个全面性的实现计划，包括代码、测试和文档，用于AIエージェント项目","ja":"Writing Plansは、AIエージェントを使用した実装計画を立てるための包括的な計画を提供します","ko":"Writing Plans는 AI 에이전트를 위한 구현 계획을 수립하기 위한 포괄적인 계획을 제공합니다","es":"Los planes de escritura son esenciales para el desarrollo eficiente. Aprende a crear planes detallados con TDD y DRY.","fr":"Les plans d''écriture sont essentiels pour le développement efficace. Découvrez comment créer des plans détaillés avec TDD et DRY.","de":"Schreibpläne sind für die effiziente Entwicklung unerlässlich. Erfahren Sie, wie Sie detaillierte Pläne mit TDD und DRY erstellen.","pt":"Crie planos de escrita abrangentes para ferramentas de IA, documentando tudo o que um engenheiro precisa saber","ru":"Создавайте комплексные планы реализации для ИИ Агентов, документируя все, что инженер должен знать","ar":"أنشئ خطط كتابة شاملة للأدوات الذكية، وثمّن كل ما يحتاجه مهندس ليعرفه"},"seo":{"title":{"en":"Writing-Plans: Comprehensive Setup Guide for AI Agents","zh":"Writing Plans Setup Guide: AIエージェント项目规划","ja":"Writing Plans ベストプラクティス: AIエージェントを使用した実装計画","ko":"Writing Plans 구현 가이드: AI 에이전트를 위한 계획 수립","es":"Guía de configuración de planes de escritura para desarro...","fr":"Guide de mise en place de plans d''écriture pour les dével...","de":"Setup-Leitfaden für Schreibpläne für Entwickler","pt":"Guia de Configuração de Planos de Escrita para Ferramenta...","ru":"ИИ Агенты: Руководство по Созданию Планов для Реализации","ar":"دليل إنشاء خطط الكتابة للأدوات الذكية"},"description":{"en":"Get started with writing-plans today! Learn how to create detailed implementation plans with bite-sized tasks, DRY principles, and TDD best practices.","zh":"了解Writing Plans的技术细节和最佳实践，包括DRY、YAGNI、TDD和频繁提交，用于AIエージェント项目","ja":"Writing Plansの技術的側面とベストプラクティスを学び、AIエージェントを使用した実装計画を立てる","ko":"Writing Plans의 기술적 세부 사항과 모범 사례를 살펴보고, AI 에이전트를 위한 구현 계획을 수립하세요","es":"Aprende a crear planes de implementación detallados con tecnologías como TDD y DRY para mejorar la eficiencia del desarrollo","fr":"Découvrez comment créer des plans d''implémentation détaillés avec des technologies comme TDD et DRY pour améliorer l''efficacité du développement","de":"Erfahren Sie, wie Sie detaillierte Implementierungspläne mit Technologien wie TDD und DRY erstellen, um die EntwicklungsEffizienz zu verbessern","pt":"Aprenda a criar planos de escrita eficazes para ferramentas de IA, incluindo testes, documentação e commits frequentes","ru":"Откройте для себя, как создавать комплексные планы реализации для ИИ Агентов, включая тестирование, документацию и частые коммиты","ar":"تعرف على كيفية إنشاء خطط كتابة شاملة لادوات الذكاء الاصطناعي، بما في ذلك الاختبارات والوثائق والالتزامات المتكررة"},"definition":{"en":"writing-plans is a skill that creates detailed, step-by-step implementation plans for developers, assuming zero context and focusing on DRY, YAGNI, and TDD principles.","zh":"Writing Plans是AIエージェント项目中的一种实现计划，用于指导开发人员完成项目","ja":"Writing Plansは、AIエージェントを使用した実装計画の一種で、開発者がプロジェクトを完了するために必要なステップを提供する","ko":"Writing Plans는 AI 에이전트 프로젝트에서 구현 계획을 수립하기 위한 하나의 방법입니다","es":"Un plan de escritura es un documento que describe los pasos necesarios para implementar una funcionalidad","fr":"Un plan d''écriture est un document qui décrit les étapes nécessaires pour mettre en œuvre une fonctionnalité","de":"Ein Schreibplan ist ein Dokument, das die notwendigen Schritte zur Implementierung einer Funktionalität beschreibt","pt":"Plano de escrita é um guia passo a passo para implementação de código, incluindo testes e documentação","ru":"План реализации - это пошаговое руководство для реализации кода, включая тестирование и документацию","ar":"خطة الكتابة هي دليل خطوة بخطوة لتنفيذ الشيفرة، بما في ذلك الاختبارات والوثائق"},"features":{"en":["Generates bite-sized tasks for easy implementation","Applies DRY (Don''t Repeat Yourself) principles for efficient planning","Follows TDD (Test-Driven Development) best practices for reliable testing","Assumes zero context for new developers, providing thorough documentation","Emphasizes frequent commits for version control and collaboration","Covers code, testing, and documentation for comprehensive planning"],"zh":["DRY（不要重复）原则","YAGNI（你不会需要它）原则","TDD（测试驱动开发）","频繁提交","包括代码、测试和文档","适用于AIエージェント项目"],"ja":["DRY（Don''t Repeat Yourself）原則","YAGNI（You Ain''t Gonna Need It）原則","TDD（Test-Driven Development）","頻繁なコミット","コード、テスト、文書を含む","AIエージェントを使用した実装計画"],"ko":["DRY(중복을 피하는) 원칙","YAGNI(당신은 그것을 필요로 하지 않을 것) 원칙","TDD(테스트 주도 개발)","頻繁한 커밋","코드, 테스트, 문서를 포함","AI 에이전트를 위한 구현 계획"],"es":["Creación de planes de implementación detallados","Integración de TDD (Desarrollo Dirigido por Pruebas) y DRY (No Repetir)","Documentación de todos los pasos necesarios para la implementación","Uso de commits frecuentes para mejorar la colaboración","Asunción de un desarrollador con habilidades, pero con poco conocimiento del conjunto de herramientas o dominio del problema"],"fr":["Création de plans d''implémentation détaillés","Intégration de TDD (Développement Dirigé par les Tests) et DRY (Ne Pas Répéter)","Documentation de toutes les étapes nécessaires pour la mise en œuvre","Utilisation de commits fréquents pour améliorer la collaboration","Hypothèse d''un développeur avec des compétences, mais avec peu de connaissances de l''ensemble d''outils ou du domaine du problème"],"de":["Erstellung detaillierter Implementierungspläne","Integration von TDD (Testgetriebene Entwicklung) und DRY (Keine Wiederholung)","Dokumentation aller notwendigen Schritte für die Implementierung","Verwendung von häufigen Commits zur Verbesserung der Zusammenarbeit","Annahme eines Entwicklers mit Fähigkeiten, aber mit wenig Kenntnissen des Toolsets oder Problem_domains"],"pt":["Utilização de princípios DRY e YAGNI","Desenvolvimento orientado a testes (TDD)","Commits frequentes para controle de versão","Documentação de todos os passos necessários","Testes e validação de código"],"ru":["Применение принципов DRY и YAGNI","Разработка, ориентированная на тестирование (TDD)","Частые коммиты для контроля версий","Документирование всех необходимых шагов","Тестирование и проверка кода"],"ar":["استخدام مبادئ DRY و YAGNI","التطوير الموجه للاختبار (TDD)","الالتزامات المتكررة للسيطرة على الإصدارات","توثيق جميع الخطوات الضرورية","الاختبارات والتحقق من الشيفرة"]},"keywords":{"en":["how to use writing-plans","writing-plans setup guide","what is writing-plans","writing-plans alternative","writing-plans vs implementation plans","writing-plans install","TDD best practices","DRY principles in software development","comprehensive implementation planning"],"zh":["AIエージェント","Writing Plans","实现计划","DRY","YAGNI","TDD","频繁提交","代码","测试","文档"],"ja":["AIエージェント","Writing Plans","実装計画","DRY","YAGNI","TDD","頻繁なコミット","コード","テスト","文書"],"ko":["AI 에이전트","Writing Plans","구현 계획","DRY","YAGNI","TDD","頻繁한 커밋","코드","테스트","문서"],"es":["planes de escritura","desarrollo de software","TDD","DRY","implementación de funcionalidades","documentación de desarrollo","herramientas de desarrollo","colaboración en equipo","desarrollo ágil"],"fr":["plans d''écriture","développement de logiciels","TDD","DRY","mise en œuvre de fonctionnalités","documentation de développement","outils de développement","collaboration d''équipe","développement agile"],"de":["Schreibpläne","Software-Entwicklung","TDD","DRY","Implementierung von Funktionalitäten","Entwickler-Dokumentation","Entwicklungstools","Teamzusammenarbeit","Agile Entwicklung"],"pt":["ferramentas de IA","planos de escrita","desenvolvimento de software","testes de software","documentação de código","commits frequentes","princípios DRY e YAGNI","TDD","controle de versão"],"ru":["ИИ Агенты","планы реализации","разработка программного обеспечения","тестирование программного обеспечения","документирование кода","частые коммиты","принципы DRY и YAGNI","TDD","контроль версий"],"ar":["أدوات الذكاء الاصطناعي","خطط الكتابة","تطوير البرمجيات","اختبارات البرمجيات","توثيق الشيفرة","الالتزامات المتكررة","مبادئ DRY و YAGNI","TDD","سيطرة على الإصدارات"]}},"owner":"ChetanG111","repo":"safer-claw","repoPath":"ChetanG111/safer-claw","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.416Z","topics":[],"category":"community","skillMd":{"name":"writing-plans","description":"Use when you have a spec or requirements for a multi-step task, before touching code","bodyPreview":"# Writing Plans\n\n## Overview\n\nWrite comprehensive implementation plans assuming the engineer has zero context for our codebase and questionable taste. Document everything they need to know: which files to touch for each task, code, testing, docs they might need to check, how to test it. Give them the whole plan as bite-sized tasks. DRY. YAGNI. TDD. Frequent commits.\n\nAssume they are a skilled developer, but know almost nothing about our toolset or problem domain. Assume they don''t know good test","body":"# Writing Plans\n\n## Overview\n\nWrite comprehensive implementation plans assuming the engineer has zero context for our codebase and questionable taste. Document everything they need to know: which files to touch for each task, code, testing, docs they might need to check, how to test it. Give them the whole plan as bite-sized tasks. DRY. YAGNI. TDD. Frequent commits.\n\nAssume they are a skilled developer, but know almost nothing about our toolset or problem domain. Assume they don''t know good test design very well.\n\n**Announce at start:** \"I''m using the writing-plans skill to create the implementation plan.\"\n\n**Context:** This should be run in a dedicated worktree (created by brainstorming skill).\n\n**Save plans to:** `docs/plans/YYYY-MM-DD-<feature-name>.md`\n\n## Bite-Sized Task Granularity\n\n**Each step is one action (2-5 minutes):**\n- \"Write the failing test\" - step\n- \"Run it to make sure it fails\" - step\n- \"Implement the minimal code to make the test pass\" - step\n- \"Run the tests and make sure they pass\" - step\n- \"Commit\" - step\n\n## Plan Document Header\n\n**Every plan MUST start with this header:**\n\n```markdown\n# [Feature Name] Implementation Plan\n\n> **For Claude:** REQUIRED SUB-SKILL: Use superpowers:executing-plans to implement this plan task-by-task.\n\n**Goal:** [One sentence describing what this builds]\n\n**Architecture:** [2-3 sentences about approach]\n\n**Tech Stack:** [Key technologies/libraries]\n\n---\n```\n\n## Task Structure\n\n```markdown\n### Task N: [Component Name]\n\n**Files:**\n- Create: `exact/path/to/file.py`\n- Modify: `exact/path/to/existing.py:123-145`\n- Test: `tests/exact/path/to/test.py`\n\n**Step 1: Write the failing test**\n\n```python\ndef test_specific_behavior():\n    result = function(input)\n    assert result == expected\n```\n\n**Step 2: Run test to verify it fails**\n\nRun: `pytest tests/path/test.py::test_name -v`\nExpected: FAIL with \"function not defined\"\n\n**Step 3: Write minimal implementation**\n\n```python\ndef function(input):\n    return expected\n```\n\n**Step 4: Run test to verify it passes**\n\nRun: `pytest tests/path/test.py::test_name -v`\nExpected: PASS\n\n**Step 5: Commit**\n\n```bash\ngit add tests/path/test.py src/path/file.py\ngit commit -m \"feat: add specific feature\"\n```\n```\n\n## Remember\n- Exact file paths always\n- Complete code in plan (not \"add validation\")\n- Exact commands with expected output\n- Reference relevant skills with @ syntax\n- DRY, YAGNI, TDD, frequent commits\n\n## Execution Handoff\n\nAfter saving the plan, offer execution choice:\n\n**\"Plan complete and saved to `docs/plans/<filename>.md`. Two execution options:**\n\n**1. Subagent-Driven (this session)** - I dispatch fresh subagent per task, review between tasks, fast iteration\n\n**2. Parallel Session (separate)** - Open new session with executing-plans, batch execution with checkpoints\n\n**Which approach?\"**\n\n**If Subagent-Driven chosen:**\n- **REQUIRED SUB-SKILL:** Use superpowers:subagent-driven-development\n- Stay in this session\n- Fresh subagent per task + code review\n\n**If Parallel Session chosen:**\n- Guide them to open new session in worktree\n- **REQUIRED SUB-SKILL:** New session uses superpowers:executing-plans"},"lastSynced":"2026-03-08T02:07:14.881Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents requiring comprehensive implementation planning and codebase onboarding capabilities.","zh":"非常适合需要全面实施规划和代码库入门能力的开发代理","ja":"包括コードベースのオンボーディング機能などの総合的な実装計画を必要とする開発エージェントに最適","ko":"포괄적인 구현 계획 및 코드베이스 온보딩 기능이 필요한 개발 에이전트에게 완벽함","es":"Perfecto para Agentes de Desarrollo que requieren una planificación de implementación integral y capacidades de incorporación de código","fr":"Parfait pour les Agents de Développement nécessitant une planification de mise en œuvre complète et des capacités d''intégration de code","de":"Perfekt für Entwicklungsagenten, die eine umfassende Implementierungsplanung und Codebasis-Onboarding-Fähigkeiten erfordern","pt":"Perfeito para Agentes de Desenvolvimento que exigem planejamento de implementação abrangente e capacidades de integração de código.","ru":"Идеально подходит для агентов разработки, требующих всестороннего планирования реализации и возможностей интеграции кодовой базы.","ar":"مثالي للوكلاء التطوير الذين يتطلبون تخطيط تنفيذ شامل وقدرات الاندماج في قاعدة الشفرة."},"recommendation":{"en":"Empowers agents to generate detailed implementation plans, including code snippets, testing procedures, and documentation guidelines, leveraging principles like DRY, YAGNI, and TDD, and utilizing frequent commits for version control.","zh":"赋予代理生成详细的实现计划，包括代码片段、测试程序和文档指南，利用如 DRY、YAGNI 和 TDD 的原则，并利用频繁提交进行版本控制","ja":"エージェントに詳細な実装計画を生成させることができ、コードスニペット、テスト手順、ドキュメントのガイドラインを含み、DRY、YAGNI、TDD などの原則を利用し、頻繁なコミットをバージョン管理に利用","ko":"에이전트가 상세한 구현 계획을 생성하도록 하는데, 코드 스니펫, 테스트 절차 및 문서 지침을 포함하며, DRY, YAGNI 및 TDD와 같은 원리를 활용하고頻繁한 커밋을 버전 관리에 활용","es":"Permite a los agentes generar planes de implementación detallados, incluyendo fragmentos de código, procedimientos de prueba y directrices de documentación, aprovechando principios como DRY, YAGNI y TDD, y utilizando commits frecuentes para el control de versiones","fr":"Permet aux agents de générer des plans de mise en œuvre détaillés, y compris des extraits de code, des procédures de test et des directives de documentation, en exploitant des principes tels que DRY, YAGNI et TDD, et en utilisant des commits fréquents pour le contrôle de version","de":"Ermöglicht es Agenten, detaillierte Implementierungspläne zu erstellen, einschließlich Code-Snippets, Testverfahren und Dokumentationsrichtlinien, unter Nutzung von Prinzipien wie DRY, YAGNI und TDD, und häufigen Commits für die Versionskontrolle","pt":"Habilita os agentes a gerar planos de implementação detalhados, incluindo trechos de código, procedimentos de teste e diretrizes de documentação, aproveitando princípios como DRY, YAGNI e TDD, e utilizando commits frequentes para controle de versão.","ru":"Позволяет агентам создавать подробные планы реализации, включая фрагменты кода, процедуры тестирования и рекомендации по документации, используя принципы DRY, YAGNI и TDD, и используя частые коммиты для контроля версий.","ar":"يسمح للوكلاء بإنتاج خطط تنفيذ مفصلة، بما في ذلك شفرة مقتطفات، وإجراءات الاختبار، وإرشادات الوثائق، واستخدام مبادئ مثل DRY و YAGNI و TDD، واستخدام الالتزامات المتكررة للسيطرة على الإصدار."},"useCases":{"en":["Generating step-by-step task lists for new codebase contributors","Creating testing plans and documentation for complex software features","Onboarding skilled developers to unfamiliar toolsets and problem domains"],"zh":["为新代码库贡献者生成逐步任务列表","为复杂软件功能创建测试计划和文档","将熟练的开发人员引入陌生的工具集和问题领域"],"ja":["新しいコードベースの貢献者ためのステップバイステップのタスクリストを生成","複雑なソフトウェア機能のテストプランとドキュメントを作成","熟練した開発者を未知のツールセットや問題ドメインにオンボード"],"ko":["새로운 코드베이스 기여자를 위한 단계별 작업 목록 생성","복잡한 소프트웨어 기능을 위한 테스트 계획 및 문서 생성","熟練한 개발자를 익숙하지 않은 도구 집합 및 문제 도메인에 온보딩"],"es":["Generar listas de tareas paso a paso para nuevos contribuyentes de la base de código","Crear planes de prueba y documentación para características de software complejas","Incorporar a desarrolladores experimentados a conjuntos de herramientas y dominios de problemas desconocidos"],"fr":["Générer des listes de tâches étape par étape pour les nouveaux contributeurs de la base de code","Créer des plans de test et de documentation pour les fonctionnalités de logiciel complexes","Intégrer des développeurs expérimentés à des ensembles d''outils et à des domaines de problèmes inconnus"],"de":["Erstellen von schrittweisen Aufgabenlisten für neue Codebasis-Mitwirkende","Erstellen von Testplänen und Dokumentationen für komplexe Softwarefunktionen","Einarbeiten von erfahrenen Entwicklern in unbekannte Werkzeugsets und Problemdomänen"],"pt":["Geração de listas de tarefas passo a passo para contribuidores de nova codebase","Criação de planos de teste e documentação para recursos de software complexos","Integração de desenvolvedores qualificados a conjuntos de ferramentas e domínios de problemas desconhecidos"],"ru":["Генерация пошаговых списков задач для новых участников кодовой базы","Создание планов тестирования и документации для сложных функций программного обеспечения","Внедрение опытных разработчиков в незнакомые инструменты и области проблем"],"ar":["توليد قوائم المهام خطوة بخطوة للمساهمين في قاعدة الشفرة الجديدة","إنشاء خطط الاختبار والوثائق لسمات البرمجيات المعقدة","تكامل المطورين المهرة مع مجموعات أدوات ونطاقات مشاكل غير مألوفة"]},"limitations":{"en":["Assumes skilled developer with limited context for the codebase or toolset","Requires knowledge of testing and documentation best practices","May not be suitable for extremely complex or proprietary systems"],"zh":["假设开发人员对代码库或工具集有有限的背景知识","需要测试和文档的最佳实践知识","可能不适用于极其复杂或专有系统"],"ja":["コードベースまたはツールセットに関する背景知識が限られている熟練した開発者を前提","テストとドキュメントのベストプラクティスの知識が必要","極めて複雑またはプロプライエタリなシステムには適さない可能性"],"ko":["코드베이스 또는 도구 집합에 대한 배경 지식이 제한된熟練한 개발자를 가정","테스트 및 문서의 최고 사례 지식이 필요","극도로 복잡하거나 독점적인 시스템에는 적합하지 않을 수"],"es":["Supone un desarrollador capacitado con un contexto limitado para la base de código o el conjunto de herramientas","Requiere conocimiento de las mejores prácticas de prueba y documentación","Puede no ser adecuado para sistemas extremadamente complejos o propietarios"],"fr":["Suppose un développeur qualifié avec un contexte limité pour la base de code ou l''ensemble d''outils","Exige une connaissance des meilleures pratiques de test et de documentation","Peut ne pas être adapté pour les systèmes extrêmement complexes ou propriétaires"],"de":["Geht von einem erfahrenen Entwickler mit begrenztem Kontext für die Codebasis oder das Werkzeugset aus","Benötigt Kenntnisse der besten Praktiken für Tests und Dokumentation","Kann für extrem komplexe oder proprietäre Systeme nicht geeignet sein"],"pt":["Pressupõe desenvolvedor qualificado com contexto limitado para a codebase ou conjunto de ferramentas","Exige conhecimento das melhores práticas de teste e documentação","Pode não ser adequado para sistemas extremamente complexos ou proprietários"],"ru":["Предполагает опытного разработчика с ограниченным контекстом для кодовой базы или набора инструментов","Требует знания лучших практик тестирования и документации","Может быть не подходит для чрезвычайно сложных или проприетарных систем"],"ar":["يفترض وجود مطور ماهر مع سياق محدود لقاعدة الشفرة أو مجموعة أدوات","يتطلب معرفة بأفضل الممارسات للاختبار والتوثيق","قد لا يكون مناسبًا لأنظمة معقدة بشكل استثنائي أو مملوكة"]},"version":4},"contentHash":"53988353ca1cb25d779144c9de8666f5e64ce7fa6fbdd17dc49d07709cd3c04f","qualityScore":45}');
