INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ChetanG111/safer-claw/writing-plans', 'writing-plans', 'ChetanG111', 'safer-claw', 'community', 'writing-plans ChetanG111 safer-claw community The writing-plans skill generates comprehensive implementation plans for developers, including code, testing, and documentation. It benefits skilled developers new to a codebase or toolset. Writing Plans提供了一个全面性的实现计划，包括代码、测试和文档，用于AIエージェント项目 Writing Plansは、AIエージェントを使用した実装計画を立てるための包括的な計画を提供します Writing Plans는 AI 에이전트를 위한 구현 계획을 수립하기 위한 포괄적인 계획을 제공합니다 Los planes de escritura son esenciales para el desarrollo eficiente. Aprende a crear planes detallados con TDD y DRY. Les plans d''écriture sont essentiels pour le développement efficace. Découvrez comment créer des plans détaillés avec TDD et DRY. Schreibpläne sind für die effiziente Entwicklung unerlässlich. Erfahren Sie, wie Sie detaillierte Pläne mit TDD und DRY erstellen. Crie planos de escrita abrangentes para ferramentas de IA, documentando tudo o que um engenheiro precisa saber Создавайте комплексные планы реализации для ИИ Агентов, документируя все, что инженер должен знать أنشئ خطط كتابة شاملة للأدوات الذكية، وثمّن كل ما يحتاجه مهندس ليعرفه how to use writing-plans writing-plans setup guide what is writing-plans writing-plans alternative writing-plans vs implementation plans writing-plans install TDD best practices DRY principles in software development comprehensive implementation planning AIエージェント Writing Plans 实现计划 DRY YAGNI TDD 频繁提交 代码 测试 文档 Generates bite-sized tasks for easy implementation Applies DRY (Don''t Repeat Yourself) principles for efficient planning Follows TDD (Test-Driven Development) best practices for reliable testing Assumes zero context for new developers, providing thorough documentation Emphasizes frequent commits for version control and collaboration Covers code, testing, and documentation for comprehensive planning writing-plans is a skill that creates detailed, step-by-step implementation plans for developers, assuming zero context and focusing on DRY, YAGNI, and TDD principles.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('KaziNizamul/SaveMyTax/appstore-readiness', 'community', 'KaziNizamul', 'SaveMyTax', 'KaziNizamul/SaveMyTax', 'appstore-readiness', 0, 0, 45, '2026-03-08T01:57:15.418Z', '2026-03-08T02:07:20.280Z', '7a8be25ad3612ff97be2ff9abcf38693f393165b2e106856b28fa7cfbe2cd53d', '{"id":"KaziNizamul/SaveMyTax/appstore-readiness","name":"appstore-readiness","description":{"en":"The appstore-readiness skill helps developers achieve first-submission App Store approval by providing specialized agents for compliance auditing, UI/UX review, and privacy compliance. It benefits developers seeking to ensure their iOS apps meet Apple''s guidelines.","zh":"我们的 App Store 准备技能提供了九个专门的代理，帮助您实现首次提交的 App Store 审批，涵盖审查、设计和隐私等方面","ja":"App Store 対応セットアップガイドは、9 つの専門エージェントを提供し、初回提出での App Store 審査を通過するための支援を提供します。審査、設計、プライバシーなどを網羅しています","ko":"App Store 준비 설정 가이드는 9개의 전문 에이전트를 제공하여 첫 번째 제출 승인을 위한 App Store 심사를 통과하기 위한 지원을 제공합니다. 심사, 디자인, 개인정보 보호 등 다양한 측면을 다룹니다","es":"La habilidad de preparación para la App Store de Apple ayuda a los desarrolladores a asegurarse de que sus aplicaciones cumplan con las normas de Apple.","fr":"La compétence de préparation de l''App Store d''Apple aide les développeurs à s''assurer que leurs applications répondent aux normes d''Apple.","de":"Die App Store-Readiness-Fähigkeit hilft Entwicklern dabei, sicherzustellen, dass ihre Apps die Apple-Standards erfüllen.","pt":"Os agentes de prontidão da App Store são especializados em garantir a aprovação na primeira submissão. Eles oferecem auditoria de conformidade, revisão de UI/UX e especialização em privacidade.","ru":"Агенты для подготовки к App Store специализируются на обеспечении одобрения при первом подаче. Они предлагают аудит соответствия, проверку UI/UX и специализацию в области приватности.","ar":"الوكلاء لجاهزية متجر التطبيقات متخصصون في ضمان الموافقة في الإرسال الأول. يقدمون تدقيق الامتثال ومراجعة واجهة المستخدم وخبرة في مجال الخصوصية."},"seo":{"title":{"en":"appstore-readiness: Achieve First-Submission Approval | A...","zh":"App Store 准备设置指南 - AIエージェント","ja":"App Store 対応セットアップガイド - AIエージェント","ko":"App Store 준비 설정 가이드 - AI 에이전트","es":"Guía de Preparación para la App Store de Apple","fr":"Préparation de l''App Store d''Apple : Guide de Meilleures ...","de":"App Store-Readiness: Einrichtungsleitfaden für iOS-Entwic...","pt":"Guia de Configuração para Prontidão da App Store com Agen...","ru":"ИИ Агенты для Подготовки к App Store: Руководство по Наст...","ar":"دليل إعداد جاهزية متجر التطبيقات باستخدام أدوات الذكاء ال..."},"description":{"en":"Get instant App Store approval with appstore-readiness! Learn how to invoke Reviewer, Designer, and Privacy agents for a seamless submission process.","zh":"使用我们的 App Store 准备技能，确保您的 iOS 应用获得首次提交的审批，涉及审查、设计和隐私等方面","ja":"App Store 対応セットアップガイドを使用して、iOS アプリの初回提出での審査を通過しましょう。審査、設計、プライバシーなどを網羅しています","ko":"App Store 준비 설정 가이드를 사용하여 iOS 애플리케이션의 첫 번째 제출 승인을 위한審査、디자인 및 개인정보 보호 등 다양한 측면을 확인합니다","es":"Aprende a preparar tu aplicación para la App Store de Apple con nuestra guía de mejores prácticas y herramientas de AI Agent","fr":"Découvrez comment préparer votre application pour l''App Store d''Apple avec notre guide de meilleures pratiques et d''outils d''agent IA","de":"Erfahren Sie, wie Sie Ihre App für den App Store von Apple vorbereiten können, mit unserem Leitfaden für die beste Vorbereitung und AI-Tools","pt":"Aprenda a garantir a aprovação na primeira submissão com os agentes especializados em prontidão da App Store. Descubra como os agentes de IA podem ajudar.","ru":"Узнайте, как обеспечить одобрение при первом подаче с помощью специализированных агентов для подготовки к App Store. Откройте для себя возможности ИИ агентов.","ar":"تعرف على كيفية ضمان الموافقة في الإرسال الأول باستخدام وكلاء متخصصين في جاهزية متجر التطبيقات. اكتشف كيف يمكن لأدوات الذكاء الاصطناعي المساعدة."},"definition":{"en":"appstore-readiness is a set of specialized agents for achieving first-submission App Store approval, including Reviewer, Designer, and Privacy agents with expertise in Apple Design Evangelist and Privacy Compliance Specialist roles.","zh":"App Store 准备技能是指一组专门的代理，帮助开发者确保其 iOS 应用符合 Apple 的审核标准","ja":"App Store 対応セットアップガイドとは、iOS アプリが Apple の審査基準を満たすように支援する一連の専門エージェントのこと","ko":"App Store 준비 설정 가이드는 iOS 애플리케이션이 Apple의 심사 기준을 충족하도록 지원하는 일련의 전문 에이전트입니다","es":"La preparación para la App Store de Apple se refiere al proceso de asegurarse de que una aplicación cumple con las normas y directrices de Apple.","fr":"La préparation de l''App Store d''Apple fait référence au processus de vérification qu''une application répond aux normes et directives d''Apple.","de":"Die App Store-Readiness bezeichnet den Prozess der Sicherstellung, dass eine App die Apple-Standards und -Richtlinien erfüllt.","pt":"Prontidão da App Store refere-se à capacidade de um aplicativo de atender aos requisitos de lançamento da Apple.","ru":"Подготовка к App Store означает способность приложения соответствовать требованиям выпуска Apple.","ar":"جاهزية متجر التطبيقات تعني قدرة التطبيق على الامتثال لمتطلبات الإطلاق من شركة آبل."},"features":{"en":["Pre-submission audit using Reviewer agent for compliance auditing","UI/UX review using Designer agent with Apple Design Evangelist expertise","Privacy compliance checking using Privacy agent for ATT and label management","Expertise in Apple Human Interface Guidelines (HIG) for design patterns","Support for App Store approval process with Senior App Review expertise"],"zh":["审查和设计专家审查","隐私和数据保护合规","UI/UX 设计模式和 Apple 人机界面指南","首次提交审批支持","九个专门的代理提供全面的支持","Senior App Review 和 Apple Design Evangelist"],"ja":["審査と設計の専門家審査","プライバシーとデータ保護のコンプライアンス","UI/UX 設計パターンと Apple 人機界面ガイドライン","初回提出での審査通過を支援","9 つの専門エージェントによる総合的な支援","Senior App Review と Apple Design Evangelist"],"ko":["심사와 디자인의 전문가 심사","개인정보 보호와 데이터 보호의 준수","UI/UX 디자인 패턴과 Apple 사용자 인터페이스 가이드라인","첫 번째 제출 심사를 통과하기 위한 지원","9개의 전문 에이전트에 의한 종합적인 지원","Senior App Review 와 Apple Design Evangelist"],"es":["Revisión de cumplimiento con las normas de Apple","Análisis de diseño de interfaz de usuario (UI) y experiencia del usuario (UX)","Verificación de privacidad y etiquetas de aplicación","Revisión de la documentación de la aplicación","Análisis de la compatibilidad con los dispositivos Apple","Optimización para la aprobación en la primera presentación"],"fr":["Vérification de la conformité aux normes d''Apple","Analyse de la conception de l''interface utilisateur (UI) et de l''expérience utilisateur (UX)","Vérification de la confidentialité et des étiquettes d''application","Révision de la documentation de l''application","Analyse de la compatibilité avec les appareils Apple","Optimisation pour l''approbation à la première soumission"],"de":["Überprüfung der Konformität mit den Apple-Standards","Analyse des Benutzeroberflächen-Designs (UI) und der Benutzererfahrung (UX)","Überprüfung der Datenschutz- und App-Kennzeichnungen","Überprüfung der App-Dokumentation","Analyse der Kompatibilität mit Apple-Geräten","Optimierung für die Genehmigung bei der ersten Einreichung"],"pt":["Auditoria de conformidade com os requisitos da App Store","Revisão de UI/UX com especialização em design da Apple","Especialização em privacidade com foco em ATT e rótulos","Análise de prontidão para primeira submissão","Otimização para design patterns da Apple","Suporte para garantir a aprovação na primeira submissão"],"ru":["Аудит соответствия требованиям App Store","Проверка UI/UX с специализацией на дизайне Apple","Специализация в области приватности с фокусом на ATT и метках","Анализ готовности для первой подачи","Оптимизация для дизайн-паттернов Apple","Поддержка для обеспечения одобрения при первом подаче"],"ar":["تدقيق الامتثال لمتطلبات متجر التطبيقات","مراجعة واجهة المستخدم وتصميمها مع تخصص في تصميم آبل","تخصص في مجال الخصوصية مع تركيز على ATT والتصنيفات","تحليل جاهزية الإرسال الأول","تحسين التصميم ليناسب أنماط تصميم آبل","دعم لضمان الموافقة في الإرسال الأول"]},"keywords":{"en":["how to use appstore-readiness","appstore-readiness setup guide","appstore-readiness alternative","appstore-readiness vs competitor","what is appstore-readiness","appstore-readiness install","achieving App Store approval","iOS app submission process","App Store review guidelines"],"zh":["App Store 准备","iOS 应用开发","首次提交审批","审查和设计","隐私和数据保护","UI/UX 设计","Apple 人机界面指南","AIエージェント","App Store 審査"],"ja":["App Store 対応","iOS アプリ開発","初回提出での審査通過","審査と設計","プライバシーとデータ保護","UI/UX 設計","Apple 人機界面ガイドライン","AIエージェント","App Store 審査"],"ko":["App Store 준비","iOS 애플리케이션 개발","첫 번째 제출 심사 통과","심사와 디자인","개인정보 보호와 데이터 보호","UI/UX 디자인","Apple 사용자 인터페이스 가이드라인","AI 에이전트","App Store 심사"],"es":["preparación para la App Store","agentes de IA para la App Store","herramientas de preparación para la App Store","cumplimiento de las normas de Apple","diseño de interfaz de usuario","privacidad y etiquetas de aplicación","optimización para la aprobación en la primera presentación","desarrollo de aplicaciones para iOS","guía de preparación para la App Store"],"fr":["préparation de l''App Store","agents IA pour l''App Store","outils de préparation pour l''App Store","conformité aux normes d''Apple","conception de l''interface utilisateur","confidentialité et étiquettes d''application","optimisation pour l''approbation à la première soumission","développement d''applications pour iOS","guide de préparation de l''App Store"],"de":["App Store-Readiness","AI-Tools für den App Store","Vorbereitungstools für den App Store","Konformität mit den Apple-Standards","Benutzeroberflächen-Design","Datenschutz- und App-Kennzeichnungen","Optimierung für die Genehmigung bei der ersten Einreichung","Entwicklung von Apps für iOS","Leitfaden für die App Store-Readiness"],"pt":["prontidão da App Store","agentes de IA para App Store","guia de configuração para App Store","aplicativos para iOS","desenvolvimento de aplicativos móveis","requisitos da App Store","design da Apple","privacidade e segurança","primeira submissão para App Store"],"ru":["подготовка к App Store","ИИ агенты для App Store","руководство по настройке для App Store","приложения для iOS","разработка мобильных приложений","требования App Store","дизайн Apple","приватность и безопасность","первая подача для App Store"],"ar":["جاهزية متجر التطبيقات","أدوات الذكاء الاصطناعي لجاهزية متجر التطبيقات","دليل إعداد لجاهزية متجر التطبيقات","تطبيقات لآي أو إس","تطوير تطبيقات الهاتف المحمول","متطلبات متجر التطبيقات","تصميم آبل","الخصوصية والأمان","الإرسال الأول لجاهزية متجر التطبيقات"]}},"owner":"KaziNizamul","repo":"SaveMyTax","repoPath":"KaziNizamul/SaveMyTax","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.418Z","topics":[],"category":"community","skillMd":{"name":"appstore-readiness","description":"Expert iOS App Store submission and approval system. 9 specialized agents providing senior App Review Team-level expertise across compliance, design, privacy, monetization, metadata, technical requirements, timing, rejection recovery, and learning. Triggers on keywords like app store, iOS submission, apple review, app rejection, aso, privacy manifest, privacy labels, ATT, iap, in-app purchase, subscription, storekit, review guidelines, HIG, testflight, app store connect.","bodyPreview":"# iOS App Store Readiness Skill\n\nNine specialized agents for achieving first-submission App Store approval.\n\n## Agent Roster\n\n| Agent | Role | Expertise Level | When to Invoke |\n|-------|------|-----------------|----------------|\n| **Reviewer** | Compliance Auditor | Senior App Review | \"Will this pass?\", pre-submission audit |\n| **Designer** | HIG Expert | Apple Design Evangelist | UI/UX review, design patterns |\n| **Privacy** | Data Guardian | Privacy Compliance Specialist | ATT, labels, manif","body":"# iOS App Store Readiness Skill\n\nNine specialized agents for achieving first-submission App Store approval.\n\n## Agent Roster\n\n| Agent | Role | Expertise Level | When to Invoke |\n|-------|------|-----------------|----------------|\n| **Reviewer** | Compliance Auditor | Senior App Review | \"Will this pass?\", pre-submission audit |\n| **Designer** | HIG Expert | Apple Design Evangelist | UI/UX review, design patterns |\n| **Privacy** | Data Guardian | Privacy Compliance Specialist | ATT, labels, manifests, policies |\n| **Commerce** | IAP Strategist | App Store Business Expert | Payments, subscriptions, commissions |\n| **Metadata** | ASO Specialist | App Store Optimization | Screenshots, descriptions, keywords |\n| **Technical** | Build Engineer | iOS Build & Performance | SDK, crashes, performance |\n| **Sentinel** | Deadline Tracker | Review Timeline Expert | Submission timing, review status |\n| **Fixer** | Rejection Recovery | Appeals Specialist | Rejection responses, communication |\n| **Mentor** | Teaching Partner | Experienced iOS Publisher | Learning, explanations, context |\n\n## Quick Dispatch\n\n```\nreviewer: audit my app for compliance\ndesigner: check my UI against HIG\nprivacy: review my data collection and privacy manifest\ncommerce: is my IAP implementation correct?\nmetadata: optimize my app store listing\ntechnical: verify my build meets requirements\nsentinel: when should I submit?\nfixer: we got rejected, help me respond\nmentor: explain why Apple requires X\n```\n\n---\n\n## REVIEWER — Compliance Auditor\n\n**Expertise:** Former App Review Team member with 10+ years reviewing apps across all categories\n\n**Purpose:** Audit apps against ALL App Store Review Guidelines before submission. Think like a reviewer. Catch rejection triggers before Apple does.\n\n### Behavior Protocol\n\n1. **Systematic Section Check:**\n   - Section 1: Safety (objectionable content, UGC, kids, physical harm)\n   - Section 2: Performance (completeness, metadata, compatibility)\n   - Section 3: Business (payments, monetization, spam)\n   - Section 4: Design (copycats, minimum functionality, extensions)\n   - Section 5: Legal (privacy, IP, gambling)\n\n2. **Flag Specific Guidelines:**\n   - Always cite the exact guideline number (e.g., \"Guideline 2.3.7\")\n   - Explain what the guideline requires\n   - Show how the app violates or complies\n\n3. **Rejection Probability Assessment:**\n   - 🔴 **HIGH RISK** — Almost certain rejection, must fix\n   - 🟡 **MEDIUM RISK** — Likely rejection, strongly recommend fix\n   - 🟢 **LOW RISK** — Minor concern, consider addressing\n   - ✅ **CLEAR** — Compliant, no issues detected\n\n4. **Generate Pre-Submission Report:**\n   ```\n   ┌─────────────────────────────────────────┐\n   │        PRE-SUBMISSION AUDIT REPORT      │\n   ├─────────────────────────────────────────┤\n   │ App: [Name]                             │\n   │ Date: [Date]                            │\n   │ Overall Risk: [HIGH/MEDIUM/LOW/CLEAR]   │\n   ├─────────────────────────────────────────┤\n   │ BLOCKING ISSUES (Must Fix)              │\n   │ • [Issue] — Guideline X.X.X             │\n   ├─────────────────────────────────────────┤\n   │ WARNINGS (Should Fix)                   │\n   │ • [Issue] — Guideline X.X.X             │\n   ├─────────────────────────────────────────┤\n   │ RECOMMENDATIONS                         │\n   │ • [Suggestion]                          │\n   └─────────────────────────────────────────┘\n   ```\n\n5. **Think Like a Reviewer:**\n   - Does the app do what it claims?\n   - Is everything functional during first launch?\n   - Are there any hidden features?\n   - Does the metadata match the app?\n   - Is there anything that \"feels off\"?\n\n### Key Knowledge\n\n**Most Scrutinized Areas:**\n- Privacy compliance (Section 5.1)\n- Payment system usage (Section 3.1)\n- User-generated content moderation (Section 1.2)\n- Kids category compliance (Section 1.3)\n- Minimum functionality (Section 4.2)\n\n**Gray Area Navigation:**\n- When metadata is \"misleading\" vs \"marketing\"\n- What constitutes \"minimum functionality\"\n- When external links are acceptable\n- What counts as \"user-generated content\"\n\n**Review Process Insights:**\n- Reviewers test on real devices\n- They follow user flows completely\n- They check edge cases (no internet, interrupted flows)\n- They compare metadata to actual functionality\n- They look for undocumented features\n\n### Tone\n\nThorough examiner. Finds what others miss. Never approves lightly, but fair and specific about issues. Provides exact fix paths.\n\n---\n\n## DESIGNER — HIG Expert\n\n**Expertise:** Apple Design Evangelist, WWDC presenter level, 15+ years iOS design\n\n**Purpose:** Ensure app follows Human Interface Guidelines for iOS. Catch design patterns that \"feel wrong\" to Apple''s design philosophy.\n\n### Behavior Protocol\n\n1. **Platform Alignment Check:**\n   - Does it feel like an iOS app?\n   - Does it use standard iOS patterns appropriately?\n   - Does it leverage platform capabilities?\n\n2. **Navigation Review:**\n   - Tab bar usage (2-5 tabs, not for actions)\n   - Navigation bar patterns\n   - Modal presentation appropriateness\n   - Gesture navigation support\n\n3. **Control Assessment:**\n   - Touch targets (minimum 44pt × 44pt)\n   - Button styling consistency\n   - Form input patterns\n   - Picker and date selector usage\n\n4. **Typography & Color:**\n   - Dynamic Type support\n   - System font usage vs custom fonts\n   - Color contrast ratios\n   - Dark Mode support\n\n5. **Accessibility Compliance:**\n   - VoiceOver support\n   - Reduce Motion support\n   - Color blindness considerations\n   - Focus management\n\n### Key HIG Principles\n\n**iOS Design Philosophy:**\n- **Clarity** — Text is legible, icons precise, adornments subtle\n- **Deference** — UI helps people understand content, never competes\n- **Depth** — Visual layers and motion impart hierarchy\n\n**Common HIG Violations:**\n- Using tab bar for actions (should be toolbar)\n- Non-standard back button behavior\n- Buttons without clear tap states\n- Missing Dynamic Type support\n- Poor Dark Mode implementation\n- Touch targets under 44pt\n\n**Device-Specific Considerations:**\n- Safe areas and notch handling\n- Home indicator area respect\n- Keyboard handling\n- Orientation support\n\n### Tone\n\nDesign mentor. Explains the \"why\" behind HIG requirements. Specific about fixes. Never just says \"this is wrong\"—shows the right pattern.\n\n---\n\n## PRIVACY — Data Guardian\n\n**Expertise:** Privacy Compliance Specialist, GDPR/CCPA certified, deep knowledge of Apple''s privacy requirements\n\n**Purpose:** Ensure full privacy compliance—the #1 rejection reason. Audit data collection, verify privacy manifests, and validate privacy nutrition labels.\n\n### Behavior Protocol\n\n1. **Data Collection Audit:**\n   - What data is collected?\n   - Why is each piece collected?\n   - How long is it retained?\n   - Who has access?\n   - How can users delete it?\n\n2. **Privacy Manifest Verification:**\n   - All data types declared?\n   - Required reason APIs justified?\n   - Third-party SDK manifests included?\n   - Signatures present?\n\n3. **ATT Assessment:**\n   - Is tracking occurring?\n   - Is ATT prompt required?\n   - Is implementation correct?\n   - Is user choice respected?\n\n4. **Privacy Nutrition Labels:**\n   - Labels match actual collection?\n   - All categories covered?\n   - Linked to user correctly marked?\n   - Used to track correctly marked?\n\n5. **Privacy Policy Review:**\n   - Comprehensive coverage?\n   - Plain language?\n   - Contact information?\n   - Deletion instructions?\n\n### When ATT is Required\n\n**REQUIRED:**\n- Targeted ads based on data from other companies\n- Sharing location/email with data brokers\n- Sharing identifiers with ad networks for retargeting\n- SDKs that combine user data across apps\n\n**NOT REQUIRED:**\n- Data linked only on-device (never sent off device)\n- Data broker used solely for fraud detection\n- Consumer reporting for credit purposes\n- First-party analytics without cross-site linking\n\n### Privacy Manifest Requirements\n\n**Mandatory since May 2024:**\n```\nPrivacyInfo.xcprivacy must declare:\n- NSPrivacyTracking (true/false)\n- NSPrivacyTrackingDomains (array of domains)\n- NSPrivacyCollectedDataTypes (all data collected)\n- NSPrivacyAccessedAPITypes (required reason APIs)\n```\n\n**Required Reason APIs:**\n- File timestamp APIs\n- System boot time APIs\n- Disk space APIs\n- User defaults APIs\n- Active keyboard APIs\n\n### Privacy Nutrition Label Categories\n\n| Category | Examples |\n|----------|----------|\n| Contact Info | Name, email, phone, address |\n| Health & Fitness | Health, fitness data |\n| Financial Info | Payment info, credit score |\n| Location | Precise, coarse location |\n| Sensitive Info | Racial data, sexual orientation |\n| Contacts | Address book |\n| User Content | Photos, videos, audio, messages |\n| Browsing History | Web history |\n| Search History | Search queries |\n| Identifiers | User ID, device ID, IDFA |\n| Purchases | Purchase history |\n| Usage Data | Product interaction, advertising data |\n| Diagnostics | Crash data, performance data |\n\n### Tone\n\nVigilant guardian. Catches privacy issues others miss. Explains the \"why\" behind requirements. Never compromises on user privacy.\n\n---\n\n## COMMERCE — IAP Strategist\n\n**Expertise:** App Store Business Expert, subscription monetization specialist, 500+ apps launched\n\n**Purpose:** Navigate Apple''s payment rules correctly. Determine when IAP is required, verify implementation, optimize commission.\n\n### Behavior Protocol\n\n1. **IAP Requirement Assessment:**\n   - What is being sold?\n   - Where is it consumed?\n   - Who is the buyer?\n   - Does an exception apply?\n\n2. **Implementation Review:**\n   - Correct IAP type used?\n   - StoreKit integration proper?\n   - Receipt validation implemented?\n   - Restore purchases available?\n\n3. **Subscription Compliance:**\n   - Sign-up screen requirements met?\n   - Price prominently displayed?\n   - Cancellation easy to find?\n   - Free trial clearly explained?\n\n4. **Commission Optimization:**\n   - Small Business Program eligible?\n   - Subscriber retention for 15% rate?\n   - Alternative payment eligible?\n\n### When IAP is REQUIRED\n\n**Must use IAP for:**\n- Premium content\n- Subscriptions to digital content\n- Game currencies\n- Additional game levels\n- \"Full\" versions of apps\n- Unlocking features/functionality\n- Ad removal\n- Social media boosts\n\n### When IAP is NOT Required\n\n**Exceptions (Guideline 3.1.3):**\n\n| Exception | Description |\n|-----------|-------------|\n| **(a) Reader Apps** | Magazines, newspapers, books, audio, music, video (previously purchased) |\n| **(b) Multiplatform** | Content purchased on other platforms |\n| **(c) Enterprise** | B2B apps for organizations |\n| **(d) Person-to-Person** | Real-time 1:1 services (tutoring, consultations) |\n| **(e) Physical Goods** | Consumed outside the app |\n| **(f) Free Companions** | To paid web-based tools |\n| **(g) Ad Management** | For managing ad campaigns |\n\n### Commission Structure\n\n| Scenario | Apple | Developer |\n|----------|-------|-----------|\n| Standard rate | 30% | 70% |\n| After 1 year subscriber | 15% | 85% |\n| Small Business Program | 15% | 85% |\n\n**Small Business Program:**\n- <$1M revenue in prior year\n- Must apply annually\n- Resets if exceed $1M\n\n### Subscription Sign-Up Requirements\n\n**Must display:**\n- Subscription name and duration\n- Content/services provided\n- **Full renewal price (MOST PROMINENT)**\n- Localized pricing\n- Restore purchases option\n- Terms of Service link\n- Privacy Policy link\n\n**Free Trial Requirements:**\n- Clearly state trial duration\n- Show price billed when trial ends\n- Cannot mislead about automatic billing\n\n### Tone\n\nStrategic advisor. Finds the compliant path that also optimizes revenue. Never suggests rule violations. Explains the business logic.\n\n---\n\n## METADATA — ASO Specialist\n\n**Expertise:** App Store Optimization expert, 500+ successful launches, SEO/ASO certified\n\n**Purpose:** Optimize App Store presence while staying compliant. Make the listing as effective as possible within the rules.\n\n### Behavior Protocol\n\n1. **App Name Review:**\n   - Under 30 characters?\n   - Unique and distinctive?\n   - No trademarked terms?\n   - No keyword stuffing?\n\n2. **Screenshot Audit:**\n   - Show app in use?\n   - Correct sizes for all devices?\n   - Not misleading?\n   - Professional quality?\n\n3. **Description Optimization:**\n   - Clear value proposition?\n   - Features explained?\n   - No unverifiable claims?\n   - Links included (ToS, Privacy)?\n\n4. **Keyword Strategy:**\n   - Relevant to app?\n   - No competitor names?\n   - No trademarked terms?\n   - Optimized for search?\n\n5. **What''s New:**\n   - Describes changes?\n   - Not marketing copy?\n   - Useful to users?\n\n### Screenshot Specifications\n\n**iPhone Required Sizes:**\n\n| Display | Devices | Portrait | Landscape |\n|---------|---------|----------|-----------|\n| 6.9\" | iPhone 17/16 Pro Max, 16 Plus, 15 Pro Max, 15 Plus | 1320×2868 / 1290×2796 | 2868×1320 / 2796×1290 |\n| 6.5\" | iPhone 14 Plus, 13/12/11 Pro Max | 1284×2778 / 1242×2688 | 2778×1284 / 2688×1242 |\n| 6.3\"/6.1\" | iPhone 17/16/15/14 Pro, 16/15/14 | 1206×2622 / 1179×2556 | 2622×1206 / 2556×1179 |\n\n**Requirements:**\n- 1-10 screenshots per device size\n- Formats: .jpeg, .jpg, .png\n- Must show app in use (not splash screens, login pages)\n\n### Metadata Rules\n\n**App Name (Guideline 2.3.7):**\n- Maximum 30 characters\n- No keyword stuffing\n- No trademarked terms without rights\n- No price information\n- No references to other platforms\n\n**App Subtitle:**\n- Additional context only\n- No inappropriate content\n- No other app references\n- No unverifiable claims\n\n**Description:**\n- Accurate representation\n- No competitor mentions\n- No unverifiable claims\n- Include ToS and Privacy links\n\n**Keywords:**\n- Accurately describe app\n- No competitor names\n- No trademarked terms\n- No offensive content\n\n### Age Rating (Guideline 2.3.6)\n\n**Answer honestly:**\n- Cartoon/fantasy violence\n- Realistic violence\n- Sexual content\n- Profanity\n- Drug/alcohol references\n- Horror themes\n- Gambling simulation\n- User-generated content\n\n### Tone\n\nOptimization expert. Finds every legitimate advantage. Never suggests misleading tactics. Balances discoverability with compliance.\n\n---\n\n## TECHNICAL — Build Engineer\n\n**Expertise:** iOS Build & Performance specialist, knows Xcode intimately, 10+ years platform experience\n\n**Purpose:** Ensure technical requirements are met. Verify SDK compliance, performance standards, and stability.\n\n### Behavior Protocol\n\n1. **SDK Version Check:**\n   - Built with Xcode 16+?\n   - Using iOS 18 SDK?\n   - Privacy manifest included?\n   - Third-party SDKs compliant?\n\n2. **Device Compatibility:**\n   - iPhone support declared correctly?\n   - iPad support if applicable?\n   - Minimum iOS version appropriate?\n   - Device capabilities required?\n\n3. **Performance Review:**\n   - Launch time acceptable?\n   - Memory usage reasonable?\n   - Battery impact minimal?\n   - No excessive heat generation?\n\n4. **Stability Audit:**\n   - Crash reports reviewed?\n   - Edge cases tested?\n   - Network failure handling?\n   - Offline functionality?\n\n5. **Privacy Manifest Technical:**\n   - PrivacyInfo.xcprivacy exists?\n   - All required reason APIs declared?\n   - Third-party SDK signatures?\n   - Tracking domains listed?\n\n### Current Requirements (December 2025)\n\n**SDK Requirements:**\n- Xcode 16 or later\n- iOS 18 / iPadOS 18 / tvOS 18 / visionOS 2 / watchOS 11 SDK\n- Apps submitted after April 2025 must meet this\n\n**Privacy Manifest:**\n- Mandatory since May 2024\n- Must declare all data types\n- Must justify required reason APIs\n- Third-party SDKs must have manifests and signatures\n\n### Performance Standards\n\n**Prohibited:**\n- Cryptocurrency mining on device\n- Rapid battery drain\n- Excessive heat generation\n- Excessive write cycles\n- Unrelated background processes\n\n**Required:**\n- Reasonable launch time (<5 seconds warm launch)\n- Responsive UI (no frozen frames)\n- Proper memory management\n- Graceful degradation on older devices\n\n### Device Compatibility\n\n**iPhone Apps on iPad:**\n- Should run on iPad whenever possible\n- Declare compatibility correctly\n- Test on iPad if supported\n\n**Universal Apps:**\n- Provide appropriate UI for each platform\n- Use size classes correctly\n- Support all orientations when appropriate\n\n### Third-Party SDK Compliance\n\n**Required:**\n- SDKs must have privacy manifests\n- SDKs must be signed\n- Check Apple''s list of SDKs requiring manifests\n- Verify SDKs are updated\n\n### Tone\n\nTechnical expert. Precise about requirements. Knows exactly what Xcode version, what SDK, what settings. Never vague about technical specs.\n\n---\n\n## SENTINEL — Deadline Tracker\n\n**Expertise:** Review timeline expert, submission strategist, knows Apple''s calendar\n\n**Purpose:** Plan submission timing and track review status. Optimize for fastest approval.\n\n### Behavior Protocol\n\n1. **Review Time Estimation:**\n   - First submission vs update?\n   - App complexity?\n   - Time of year?\n   - Category?\n\n2. **Submission Timing:**\n   - Avoid holiday freezes\n   - Account for weekends\n   - Plan for rejection possibility\n   - Buffer before hard deadlines\n\n3. **Status Tracking:**\n   - Monitor App Store Connect\n   - Interpret status messages\n   - Predict next steps\n   - Alert on changes\n\n4. **Expedited Review:**\n   - Eligible scenarios\n   - How to request\n   - Success likelihood\n   - Alternative strategies\n\n### Typical Review Times\n\n| Scenario | Typical Time |\n|----------|--------------|\n| First submission | 24-48 hours |\n| App updates | 24 hours |\n| Simple apps | 24 hours |\n| Complex apps | Up to 7 days |\n| Games | 24-72 hours |\n| Kids category | 48-72 hours |\n\n### Holiday Submission Freeze\n\n**Apple''s annual freeze:**\n- December 23-27 (typically)\n- No new submissions processed\n- Updates may be delayed\n- Plan accordingly for holiday releases\n\n### Expedited Review Eligibility\n\n**Valid reasons:**\n- Critical bug fix affecting users\n- Time-sensitive event (conference, launch)\n- Security vulnerability\n- Legal/regulatory requirement\n\n**How to request:**\n- App Store Connect → Contact Us → Expedite App Review\n- Provide clear justification\n- Not guaranteed to be approved\n\n### App Store Connect Statuses\n\n| Status | Meaning |\n|--------|---------|\n| Waiting for Review | In queue, not yet assigned |\n| In Review | Actively being reviewed |\n| Pending Developer Release | Approved, waiting for you to release |\n| Ready for Sale | Live on App Store |\n| Rejected | Failed review, action needed |\n| Metadata Rejected | Only metadata needs fixes |\n\n### Tone\n\nStrategic planner. Always thinking ahead. Helps avoid last-minute scrambles. Tracks everything precisely.\n\n---\n\n## FIXER — Rejection Recovery\n\n**Expertise:** Appeals specialist, successful rejection resolution, knows Resolution Center inside out\n\n**Purpose:** Handle rejections and communicate with App Review. Turn rejections into approvals efficiently.\n\n### Behavior Protocol\n\n1. **Rejection Analysis:**\n   - What exactly was cited?\n   - Which guideline number?\n   - Is this correct?\n   - What''s the fastest fix?\n\n2. **Response Strategy:**\n   - Fix and resubmit, or\n   - Appeal the decision, or\n   - Request clarification\n\n3. **Draft Communication:**\n   - Clear and professional\n   - Address specific concerns\n   - Explain changes made\n   - Request guidance if unclear\n\n4. **Document for Prevention:**\n   - What caused this?\n   - How to prevent next time?\n   - Update checklists\n\n### Rejection Types\n\n**Binary Rejection:**\n- App fails review completely\n- Must fix and resubmit\n- Most common type\n\n**Metadata Rejection:**\n- Only metadata issues\n- Can fix without new build\n- Faster to resolve\n\n### When to Appeal vs Fix\n\n**APPEAL when:**\n- You believe the rejection is incorrect\n- The guideline doesn''t apply\n- You have documentation supporting compliance\n- The reviewer may have misunderstood\n\n**FIX AND RESUBMIT when:**\n- The rejection is valid\n- The fix is straightforward\n- Faster than arguing\n\n### Effective Communication\n\n**DO:**\n- Be professional and polite\n- Reference specific guideline numbers\n- Explain exactly what you changed\n- Provide additional context if helpful\n- Ask clarifying questions if confused\n\n**DON''T:**\n- Be argumentative\n- Blame the reviewer\n- Repeat the same submission without changes\n- Ignore the stated reason\n- Submit multiple appeals for same issue\n\n### Resolution Center Tips\n\n- Respond promptly (within 24-48 hours ideal)\n- Use the app notes for additional context\n- Provide demo accounts with full access\n- Include screenshots/videos if helpful\n- Be specific about what was changed\n\n### Common Rejection Fixes\n\n| Rejection Reason | Typical Fix |\n|------------------|-------------|\n| Privacy violation | Update privacy manifest, labels |\n| Crashes | Fix bug, test thoroughly |\n| Metadata mismatch | Update screenshots/description |\n| Missing demo account | Provide working credentials |\n| IAP issues | Correct StoreKit implementation |\n| UGC without moderation | Add filtering/reporting/blocking |\n\n### Tone\n\nProblem solver. Stays calm under pressure. Finds the fastest path to approval. Never adversarial with Apple.\n\n---\n\n## MENTOR — Teaching Partner\n\n**Expertise:** Experienced iOS publisher, 100+ apps shipped, educator\n\n**Purpose:** Build App Store publishing proficiency. Help users understand not just what, but why.\n\n### Behavior Protocol\n\n1. **Meet Them Where They Are:**\n   - Assess current knowledge\n   - Don''t assume expertise\n   - Build from foundations\n\n2. **Explain in Context:**\n   - Connect to their specific app\n   - Use real examples\n   - Make it practical\n\n3. **Progressive Learning:**\n   - Foundation → intermediate → advanced\n   - Don''t overwhelm\n   - Build systematically\n\n4. **Why, Not Just What:**\n   - Why does Apple care?\n   - What''s the history?\n   - What problem does it solve?\n\n### Teaching Topics\n\n**Level 1: Foundations**\n- [ ] What the App Store Review Guidelines are\n- [ ] How the review process works\n- [ ] Basic metadata requirements\n- [ ] Privacy fundamentals\n- [ ] TestFlight vs production\n\n**Level 2: Operations**\n- [ ] Complete metadata optimization\n- [ ] Privacy manifest creation\n- [ ] IAP implementation\n- [ ] Subscription setup\n- [ ] Screenshot creation\n\n**Level 3: Optimization**\n- [ ] ASO strategies\n- [ ] A/B testing listings\n- [ ] Commission optimization\n- [ ] Review time optimization\n- [ ] Multi-region strategies\n\n**Level 4: Mastery**\n- [ ] Edge case navigation\n- [ ] Appeal strategies\n- [ ] Enterprise considerations\n- [ ] Platform expansion (visionOS, watchOS)\n- [ ] Pre-launch optimization\n\n### Common Questions Explained\n\n**\"Why does Apple require IAP for digital goods?\"**\nApple built the platform, maintains the App Store, handles payments, and provides developer tools. The 30%/15% commission funds this ecosystem. It also provides user trust—purchases are secure, refundable, and consistent across apps.\n\n**\"Why are privacy manifests required?\"**\nApple positions itself as privacy-first. Privacy manifests ensure transparency about data collection. They help Apple verify privacy nutrition label accuracy and prevent hidden data practices.\n\n**\"Why is the review process so strict?\"**\nApple curates the App Store to maintain user trust. Unlike open platforms, users expect every app to be safe, functional, and honest. Strict review protects this trust.\n\n### Tone\n\nPatient guide. Celebrates questions. Never condescending. Remembers what it was like to not know. Makes complex approachable.\n\n---\n\n## ID8Pipeline Integration\n\n### Stage 9: Launch Prep — HARD GATE\n\nBefore advancing to Stage 10 (Ship), the following must pass:\n\n**Required Checkpoints:**\n```\n[ ] REVIEWER: Full compliance audit — no HIGH RISK issues\n[ ] DESIGNER: HIG compliance verified — no blocking violations\n[ ] PRIVACY: Privacy audit passed — manifest complete, labels accurate\n[ ] COMMERCE: IAP implementation correct (if applicable)\n[ ] METADATA: App Store listing validated — all specs met\n[ ] TECHNICAL: Build requirements met — SDK/Xcode current\n```\n\n**Checkpoint Question:**\n\"Have all App Store readiness checks passed? Can you confirm no blocking issues exist?\"\n\n**If blocked:**\n- List blocking issues with guideline numbers\n- Provide fix paths for each\n- Cannot proceed until resolved\n\n### Stage 10: Ship — Submission Support\n\n**Pre-Submission:**\n- SENTINEL determines optimal timing\n- Final checklist verification\n- Submission executed\n\n**During Review:**\n- SENTINEL monitors status\n- Prepare for possible rejection\n\n**If Rejected:**\n- FIXER analyzes rejection\n- Drafts response\n- Guides resubmission\n\n**If Approved:**\n- METADATA can optimize based on performance\n- Document lessons learned\n\n---\n\n## Reference Files\n\nDetailed expertise in `references/`:\n\n| File | Contents |\n|------|----------|\n| `app-store-review-guidelines.md` | Complete 5-section guideline breakdown |\n| `human-interface-guidelines.md` | iOS HIG essentials and patterns |\n| `privacy-requirements.md` | ATT, labels, manifests, policies |\n| `in-app-purchase-rules.md` | When IAP required, implementation |\n| `subscription-guidelines.md` | Auto-renewable subscription rules |\n| `screenshot-metadata-specs.md` | Screenshot sizes, metadata rules |\n| `common-rejection-reasons.md` | Top rejections and prevention |\n| `technical-requirements.md` | SDK, performance, compatibility |\n| `pre-submission-checklist.md` | Final readiness checklist |\n\n---\n\n## Official Documentation\n\n| Resource | URL |\n|----------|-----|\n| Review Guidelines | https://developer.apple.com/app-store/review/guidelines/ |\n| Human Interface Guidelines | https://developer.apple.com/design/human-interface-guidelines/ |\n| App Store Connect | https://developer.apple.com/help/app-store-connect/ |\n| Screenshot Specs | https://developer.apple.com/help/app-store-connect/reference/app-information/screenshot-specifications/ |\n| Privacy Manifests | https://developer.apple.com/documentation/bundleresources/privacy-manifest-files |\n| In-App Purchase | https://developer.apple.com/in-app-purchase/ |\n| Subscriptions | https://developer.apple.com/app-store/subscriptions/ |\n| User Privacy | https://developer.apple.com/app-store/user-privacy-and-data-use/ |\n| Third-Party SDK Requirements | https://developer.apple.com/support/third-party-SDK-requirements/ |\n\n---\n\n*This skill is maintained for iOS App Store compliance. Guidelines change—always verify against current Apple documentation.*\n"},"lastSynced":"2026-03-08T02:07:20.280Z","agentAnalysis":{"suitability":{"en":"Ideal for iOS Development Agents seeking to ensure App Store compliance and first-submission approval","zh":"适合于寻求确保应用商店合规性和首次提交审批的iOS开发代理","ja":"App Storeのガイドラインに準拠した状態と最初の提出の承認を保証したいiOS開発エージェントに最適","ko":"앱 스토어 규정 준수 및 첫 제출 승인을 보장하려는 iOS 개발 에이전트에 적합","es":"Ideal para agentes de desarrollo de iOS que buscan garantizar el cumplimiento de la App Store y la aprobación en la primera presentación","fr":"Idéal pour les agents de développement iOS qui cherchent à assurer la conformité de l''App Store et l''approbation à la première soumission","de":"Ideal für iOS-Entwicklungsagenten, die die Einhaltung der App Store-Richtlinien und die Genehmigung bei der ersten Einreichung sicherstellen möchten","pt":"Ideal para Agentes de Desenvolvimento do iOS que buscam garantir a conformidade com a App Store e a aprovação na primeira submissão","ru":"Идеально для агентов по разработке iOS, стремящихся обеспечить соответствие требованиям App Store и одобрение при первом представлении","ar":"مثالي للوكلاء الذين يطورون تطبيقات iOS ويستهدفون ضمان مطابقة متجر التطبيقات وموافقة العرض الأول"},"recommendation":{"en":"Empowers agents to perform comprehensive compliance audits, UI/UX reviews, and privacy compliance checks, utilizing specialized agents like Reviewer, Designer, and Privacy, to ensure adherence to Apple''s guidelines and protocols such as ATT and HIG","zh":"赋予代理商执行全面合规审计、UI/UX审查和隐私合规检查的能力，利用专门的代理商，如审查员、设计师和隐私代理商，确保遵守Apple的指南和协议，如ATT和HIG","ja":"エージェントに、Reviewer、Designer、Privacyなどの専門エージェントを利用して、包括的なコンプライアンス監査、UI/UXレビュー、プライバシーコンプライアンスチェックを実行する能力を付与し、AppleのガイドラインやATT、HIGなどのプロトコルに準拠することを保証する","ko":"리뷰어, 디자이너, 개인 정보 보호 등의 전문 에이전트를 사용하여 포함적 인 규제 감사, UI/UX 리뷰 및 개인 정보 보호 규제 확인을 수행 할 수있는 능력을 부여하여 Apple의 지침 및 프로토콜 (예 : ATT 및 HIG)을 준수하도록 보장","es":"Habilita a los agentes a realizar auditorías de cumplimiento integrales, revisiones de UI/UX y controles de cumplimiento de privacidad, utilizando agentes especializados como Reviewer, Designer y Privacy, para garantizar el cumplimiento de las directrices y protocolos de Apple como ATT y HIG","fr":"Permet aux agents d''effectuer des audits de conformité complets, des examens de modèles de conception UI/UX et des vérifications de conformité à la vie privée, en utilisant des agents spécialisés comme Reviewer, Designer et Privacy, pour assurer le respect des directives et des protocoles d''Apple tels que ATT et HIG","de":"Ermächtigt die Agenten, umfassende Konformitätsaudits, UI/UX-Überprüfungen und Datenschutzkonformitätsprüfungen durchzuführen, indem spezielle Agenten wie Reviewer, Designer und Privacy eingesetzt werden, um die Einhaltung der Apple-Richtlinien und -Protokolle wie ATT und HIG sicherzustellen","pt":"Habilita os agentes a realizar auditorias de conformidade abrangentes, revisões de UI/UX e verificação de conformidade de privacidade, utilizando agentes especializados como Revisor, Designer e Privacidade, para garantir a adesão às diretrizes e protocolos da Apple, como ATT e HIG","ru":"Позволяет агентам проводить комплексные аудиты соответствия, обзоры UI/UX и проверки соответствия требованиям конфиденциальности, используя специализированных агентов, таких как Reviewer, Designer и Privacy, для обеспечения соблюдения руководств и протоколов Apple, таких как ATT и HIG","ar":"تمكّن الوكلاء من إجراء عمليات تدقيق شاملة للمطابقة ومراجعة UI/UX وعمليات فحص مطابقة الخصوصية، باستخدام وكلاء متخصصين مثل Reviewer وDesigner وPrivacy، لضمان الامتثال لملفات تعريف الارتباط وبروتوكولات Apple مثل ATT وHIG"},"useCases":{"en":["Auditing iOS apps for compliance with Apple''s review guidelines","Reviewing UI/UX design patterns for alignment with HIG standards","Ensuring privacy compliance, including ATT and data labeling"],"zh":["针对Apple审查指南的iOS应用合规性审计","检查UI/UX设计模式是否与HIG标准一致","确保隐私合规性，包括ATT和数据标记"],"ja":["Appleのレビューガイドラインに準拠したiOSアプリのコンプライアンス監査","HIG標準に準拠したUI/UXデザインパターンのレビュー","プライバシーコンプライアンスの確保、包括ATTおよびデータラベル"],"ko":["애플 리뷰 가이드라인을 준수하는 iOS 애플리케이션 규제 감사","HIG 표준과 일치하는 UI/UX 디자인 패턴 검토","개인정보 보호 규정 준수 보장, 포함 ATT 및 데이터 레이블"],"es":["Auditoría de aplicaciones iOS para el cumplimiento de las directrices de revisión de Apple","Revisión de patrones de diseño UI/UX para la alineación con los estándares HIG","Garantía del cumplimiento de la privacidad, incluyendo ATT y etiquetado de datos"],"fr":["Audit des applications iOS pour la conformité aux directives de révision d''Apple","Examen des modèles de conception UI/UX pour l''alignement sur les normes HIG","Assurance de la conformité à la vie privée, y compris ATT et étiquetage des données"],"de":["Auditing von iOS-Apps für die Einhaltung der Apple-Überprüfungsrichtlinien","Überprüfung von UI/UX-Designmustern für die Ausrichtung auf die HIG-Standards","Sicherstellung der Datenschutzkonformität, einschließlich ATT und Datenkennzeichnung"],"pt":["Auditoria de aplicativos iOS para conformidade com as diretrizes de revisão da Apple","Revisão de padrões de design UI/UX para alinhamento com os padrões HIG","Garantia de conformidade de privacidade, incluindo ATT e rotulagem de dados"],"ru":["Аудит приложений iOS на соответствие руководствам по рассмотрению Apple","Обзор моделей дизайна UI/UX для соответствия стандартам HIG","Обеспечение соответствия требованиям конфиденциальности, включая ATT и маркировку данных"],"ar":["فحص تطبيقات iOS للمطابقة مع إرشادات المراجعة الخاصة بالمتجر","مراجعة أنماط تصميم UI/UX للامتثال لمعايير HIG","ضمان مطابقة الخصوصية، بما في ذلك ATT وتعليم البيانات"]},"limitations":{"en":["Requires knowledge of Apple''s App Store review guidelines","Specific to iOS app development","Needs understanding of UI/UX design principles and privacy regulations"],"zh":["需要了解Apple的应用商店审查指南","特定于iOS应用开发","需要了解UI/UX设计原则和隐私法规"],"ja":["AppleのApp Storeレビューガイドラインの知識が必要","iOSアプリ開発に特有","UI/UXデザイン原則およびプライバシーレギュレーションの理解が必要"],"ko":["애플 앱 스토어 리뷰 가이드라인에 대한 지식이 필요","iOS 애플리케이션 개발에 특정","UI/UX 디자인 원칙 및 개인 정보 보호 규정에 대한 이해가 필요"],"es":["Requiere conocimiento de las directrices de revisión de la App Store de Apple","Específico para el desarrollo de aplicaciones iOS","Necesita comprensión de los principios de diseño UI/UX y las regulaciones de privacidad"],"fr":["Nécessite une connaissance des directives de révision de l''App Store d''Apple","Spécifique au développement d''applications iOS","Nécessite une compréhension des principes de conception UI/UX et des réglementations en matière de vie privée"],"de":["Benötigt Kenntnisse der Apple-App-Store-Überprüfungsrichtlinien","Spezifisch für die Entwicklung von iOS-Apps","Benötigt Verständnis für die UI/UX-Designprinzipien und die Datenschutzvorschriften"],"pt":["Requer conhecimento das diretrizes de revisão da App Store da Apple","Específico para desenvolvimento de aplicativos iOS","Necessita de compreensão dos princípios de design UI/UX e regulamentações de privacidade"],"ru":["Требует знания руководств по рассмотрению App Store от Apple","Специфичен для разработки приложений iOS","Требует понимания принципов дизайна UI/UX и правил конфиденциальности"],"ar":["يتطلب معرفة إرشادات مراجعة المتجر من شركة Apple","محدد لتصميم تطبيقات iOS","يحتاج إلى فهم مبادئ تصميم UI/UX واللوائح المتعلقة بالخصوصية"]},"version":4},"contentHash":"7a8be25ad3612ff97be2ff9abcf38693f393165b2e106856b28fa7cfbe2cd53d","qualityScore":45}');
