INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('frmoretto/hardstop/hs', 'hs', 'frmoretto', 'hardstop', 'community', 'hs frmoretto hardstop community hs provides pre-execution safety validation for AI-generated commands, protecting against mistakes, hallucinations, and prompt injection. It benefits developers using Claude Code and Claude Cowork. HardStop 是一个安全保护工具，用于验证 AI 生成命令的安全性，防止错误和攻击。它支持 Claude Code 和 Claude Cowork HardStop は、AI 生成コマンドの安全性を検証する安全保護ツールであり、ミスや攻撃を防ぐために設計されています。 Claude Code と Claude Cowork をサポートしています HardStop은 AI 생성 명령의 안전성을 검증하는 안전 보호 도구로, 오류와 공격을 방지하기 위해 설계되었습니다. Claude Code와 Claude Cowork를 지원합니다 HardStop es una protección de seguridad para comandos AI generados, que verifica la seguridad de los comandos antes de su ejecución HardStop est une protection de sécurité pour les commandes AI générées, qui vérifie la sécurité des commandes avant leur exécution HardStop ist ein Sicherheitsschutz für AI-Generierte Befehle, der die Sicherheit der Befehle vor ihrer Ausführung überprüft HardStop é uma ferramenta de segurança para comandos gerados por AI, protegendo contra erros e hallucinações. Saiba mais sobre como configurar e utilizar essa tecnologia. HardStop - это инструмент безопасности для команд, сгенерированных ИИ Агентами, защищающий от ошибок и галлюцинаций. Узнайте больше о том, как настроить и использовать эту технологию. HardStop هو أداة أمنية لأوامر الإيمان الأصلي، يحمي من الأخطاء والهلوسات. تعرف على المزيد حول كيفية ضبط واستخدام هذه التكنولوجيا how to use hs hs setup guide what is hs hs alternative hs vs Claude Code hs install pre-execution safety validation AI-generated command protection Claude Cowork security AI 安全保护 HardStop Claude Code Claude Cowork AI 生成命令 安全保护设置 AI 错误防止 AI 攻击防止 Runs pre-execution safety validation for Claude Code and Claude Cowork Catches dangerous commands using Bash commands and Python scripts Supports commands like `skip [n]`, `on`, `enable`, `off`, and `disable` Utilizes `python ~/.claude/plugins/hs/commands/hs_cmd.py` for command execution Provides a safeguard against AI mistakes, hallucinations, and prompt injection hs is a security skill that validates AI-generated commands before execution, ensuring safety and preventing potential damage.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Pama-Lee/Ordo/ordo-testing', 'community', 'Pama-Lee', 'Ordo', 'Pama-Lee/Ordo', 'ordo-testing', 0, 0, 45, '2026-03-08T01:57:15.442Z', '2026-03-08T02:08:51.655Z', '178cdb7a7b0ffe97b853f202ec6ff1e8aafccd2797b46d4674b21cd734cd5024', '{"id":"Pama-Lee/Ordo/ordo-testing","name":"ordo-testing","description":{"en":"ordo-testing is a high-performance rule engine built in Rust, designed for efficient testing and benchmarking. It benefits developers seeking to optimize their workflow with robust unit tests and parallel execution.","zh":"ordo-testing是一个使用Rust开发的高性能规则引擎，提供快速的单元测试和benchmarking功能","ja":"ordo-testingはRustで開発された高パフォーマンスなルールエンジンで、単体テストとベンチマークテストを迅速に実行できます","ko":"ordo-testing은 러스트로 개발된 고성능 규칙 엔진으로 빠른 단위 테스트와 벤치마킹 기능을 제공합니다","es":"Ordo-testing es un motor de reglas de alto rendimiento construido en Rust, ideal para pruebas y benchmarking. Ofrece funcionalidades de unit tests y benchmarking","fr":"Ordo-testing est un moteur de règles haute performance construit en Rust, idéal pour les tests et le benchmarking. Il propose des fonctionnalités de tests unitaires et de benchmarking","de":"Ordo-testing ist eine Hochleistungs-Regelengine in Rust, ideal für Tests und Benchmarking. Sie bietet Funktionen für Unit-Tests und Benchmarking","pt":"O Ordo-Testing é um motor de regras de alto desempenho construído em Rust, projetado para melhorar a eficiência dos testes","ru":"Ordo-Testing - это высокопроизводительный движок правил на Rust, предназначенный для повышения эффективности тестирования и ИИ Агентов","ar":"Ordo-Testing هو محرك قواعد أداء عالي مبني على Rust، مصمم لتحسين كفاءة الاختبارات وأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"ordo-testing: Rust-Based Rule Engine Setup Guide | AI Age...","zh":"ordo-testing Rust规则引擎搭建指南","ja":"ordo-testing AIエージェントのパフォーマンステスト設定","ko":"ordo-testing 고성능 규칙 엔진 개발자 가이드","es":"Guía de configuración de ordo-testing: Motor de reglas de...","fr":"Guide de configuration d''ordo-testing : Moteur de règles ...","de":"Einrichtungsleitfaden für ordo-testing: Hochleistungs-Reg...","pt":"Guia de Configuração do Ordo-Testing: Motor de Regras de ...","ru":"Настройка Ordo-Testing: Высокопроизводительный движок пра...","ar":"دليل إعداد Ordo-Testing: محرك قواعد أداء عالي مبني على Ru..."},"description":{"en":"Unlock high-performance testing with ordo-testing. Learn how to run unit tests, benchmark, and optimize your workflow with this Rust-based rule engine. Get s...","zh":"了解ordo-testing的高性能规则引擎，使用Rust开发，实现快速的单元测试和benchmarking","ja":"ordo-testingのAIエージェントを使用して、高パフォーマンスなルールエンジンを構築する方法を学ぶ","ko":"ordo-testing의 고성능 규칙 엔진을 사용하여 개발 속도를 높이고 성능을 개선하는 방법","es":"Aprende a configurar y utilizar ordo-testing, un motor de reglas de alto rendimiento construido en Rust, para mejorar tus pruebas y benchmarking","fr":"Découvrez comment configurer et utiliser ordo-testing, un moteur de règles haute performance construit en Rust, pour améliorer vos tests et benchmarking","de":"Erfahren Sie, wie Sie ordo-testing, eine Hochleistungs-Regelengine in Rust, konfigurieren und verwenden können, um Ihre Tests und Benchmarking zu verbessern","pt":"Aprenda a configurar e utilizar o Ordo-Testing, um motor de regras de alto desempenho construído em Rust, para melhorar a eficiência dos seus testes","ru":"Узнайте, как настроить и использовать Ordo-Testing, высокопроизводительный движок правил на Rust, для повышения эффективности ваших тестов и ИИ Агентов","ar":"تعلم كيفية إعداد وتشغيل Ordo-Testing، محرك قواعد أداء عالي مبني على Rust، لتحسين كفاءة اختباراتك وأدوات الذكاء الاصطناعي"},"definition":{"en":"ordo-testing is a Rust-based rule engine for high-performance testing and benchmarking, featuring unit tests and parallel execution capabilities.","zh":"ordo-testing是一种高性能规则引擎，使用Rust开发，用于快速的单元测试和benchmarking","ja":"ordo-testingは、高パフォーマンスなルールエンジンで、Rustで開発されており、単体テストとベンチマークテストを迅速に実行できます","ko":"ordo-testing은 고성능 규칙 엔진으로 러스트로 개발되어 빠른 단위 테스트와 벤치마킹을 수행합니다","es":"Ordo-testing es un motor de reglas de software que permite la ejecución de reglas y pruebas de forma eficiente","fr":"Ordo-testing est un moteur de règles logiciel qui permet l''exécution de règles et de tests de manière efficace","de":"Ordo-testing ist eine Regelengine-Software, die die effiziente Ausführung von Regeln und Tests ermöglicht","pt":"O Ordo-Testing é um motor de regras de software que executa testes de unidade e benchmarks em Rust","ru":"Ordo-Testing - это программный движок правил, который выполняет модульное тестирование и бенчмарки на Rust для ИИ Агентов","ar":"Ordo-Testing هو محرك قواعد برمجية ي chạy اختبارات الوحدة والبENCHMARKS على Rust لأدوات الذكاء الاصطناعي"},"features":{"en":["Runs unit tests using the Cargo test command","Supports parallel test execution with --test-threads flag","Allows running specific tests with the cargo test --package command","Enables output display with the --nocapture flag","Features a test example in Rust for rule execution"],"zh":["使用Rust开发，提供高性能的规则引擎","支持快速的单元测试和benchmarking","提供cargo test命令用于运行测试","支持并行测试，提高测试效率","提供测试输出和错误日志功能"],"ja":["Rustで開発された高パフォーマンスなルールエンジン","単体テストとベンチマークテストを迅速に実行","cargo testコマンドを使用してテストを実行","並列テストをサポートしてテスト効率を向上","テスト出力とエラーログ機能を提供"],"ko":["러스트로 개발된 고성능 규칙 엔진","빠른 단위 테스트와 벤치마킹을 지원","cargo test 명령어를 사용하여 테스트를 실행","병렬 테스트를 지원하여 테스트 효율을 향상","테스트 출력과 에러 로그 기능을 제공"],"es":["Motor de reglas de alto rendimiento en Rust","Soporte para unit tests y benchmarking","Ejecución de pruebas específicas con cargo test","Control paralelo con cargo test --test-threads","Salida detallada con cargo test -- --nocapture"],"fr":["Moteur de règles haute performance en Rust","Prise en charge des tests unitaires et du benchmarking","Exécution de tests spécifiques avec cargo test","Contrôle parallèle avec cargo test --test-threads","Sortie détaillée avec cargo test -- --nocapture"],"de":["Hochleistungs-Regelengine in Rust","Unterstützung für Unit-Tests und Benchmarking","Ausführung spezifischer Tests mit cargo test","Parallele Steuerung mit cargo test --test-threads","Detaillierte Ausgabe mit cargo test -- --nocapture"],"pt":["Execução de testes de unidade com Cargo","Suporte a testes paralelos com --test-threads","Exibição de saída de teste com --nocapture","Integração com o ecossistema Rust","Desempenho otimizado para testes de alto volume"],"ru":["Выполнение модульных тестов с помощью Cargo","Поддержка параллельных тестов с --test-threads","Отображение вывода теста с --nocapture","Интеграция с экосистемой Rust для ИИ Агентов","Оптимизированное производительность для тестирования большого объема"],"ar":["تشغيل اختبارات الوحدة مع Cargo","دعم الاختبارات المتوازية مع --test-threads","عرض مخرجات الاختبار مع --nocapture","التكامل مع نظام Rust لأدوات الذكاء الاصطناعي","أداء محسّن للاختبارات الكبيرة"]},"keywords":{"en":["how to use ordo-testing","ordo-testing alternative","ordo-testing install","what is ordo-testing","ordo-testing vs rust test","ordo-testing setup guide","rust based rule engine","high performance testing with ordo-testing","ordo-testing benchmarking"],"zh":["ordo-testing","Rust规则引擎","单元测试","benchmarking","cargo test","并行测试","测试输出","错误日志"],"ja":["ordo-testing","AIエージェント","ルールエンジン","単体テスト","ベンチマークテスト","cargo test","並列テスト","テスト出力","エラーログ"],"ko":["ordo-testing","고성능 규칙 엔진","단위 테스트","벤치마킹","cargo test","병렬 테스트","테스트 출력","에러 로그","러스트 개발"],"es":["ordo-testing","motor de reglas","Rust","unit tests","benchmarking","cargo test","pruebas de software","desarrollo de software","herramientas de testing"],"fr":["ordo-testing","moteur de règles","Rust","tests unitaires","benchmarking","cargo test","tests logiciels","développement de logiciels","outils de testing","agents d''IA"],"de":["ordo-testing","Regelengine","Rust","Unit-Tests","Benchmarking","cargo test","Software-Tests","Software-Entwicklung","Testing-Tools","Künstliche Intelligenz Tools","II Agenten"],"pt":["ordo-testing","motor de regras rust","testes de unidade rust","desempenho de testes","cargo test","rust testing","desenvolvimento de software","ferramentas de teste"],"ru":["ordo-testing","движок правил rust","модульное тестирование rust","производительность тестирования","cargo test","rust testing","разработка программного обеспечения","инструменты тестирования для ИИ Агентов"],"ar":["ordo-testing","محرك قواعد rust","اختبارات الوحدة rust","أداء الاختبارات","cargo test","rust testing","تطوير البرمجيات","أدوات اختبار لأدوات الذكاء الاصطناعي"]}},"owner":"Pama-Lee","repo":"Ordo","repoPath":"Pama-Lee/Ordo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.442Z","topics":[],"category":"community","skillMd":{"name":"ordo-testing","description":"Ordo testing and benchmarking guide. Includes unit tests, integration tests, Criterion benchmarks, k6 load tests, CI configuration. Use for writing tests, performance analysis, continuous integration.","bodyPreview":"# Ordo Testing and Benchmarking\n\n## Unit Tests\n\n### Running Tests\n\n```bash\n# Run all tests\ncargo test\n\n# Run specific crate\ncargo test --package ordo-core\ncargo test --package ordo-server\n\n# Run specific test\ncargo test test_full_workflow\n\n# Show output\ncargo test -- --nocapture\n\n# Parallel control\ncargo test -- --test-threads=4\n```\n\n### Test Example\n\n```rust\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use ordo_core::prelude::*;\n\n    #[test]\n    fn test_rule_execution() {\n        let mut rule","body":"# Ordo Testing and Benchmarking\n\n## Unit Tests\n\n### Running Tests\n\n```bash\n# Run all tests\ncargo test\n\n# Run specific crate\ncargo test --package ordo-core\ncargo test --package ordo-server\n\n# Run specific test\ncargo test test_full_workflow\n\n# Show output\ncargo test -- --nocapture\n\n# Parallel control\ncargo test -- --test-threads=4\n```\n\n### Test Example\n\n```rust\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use ordo_core::prelude::*;\n\n    #[test]\n    fn test_rule_execution() {\n        let mut ruleset = RuleSet::new(\"test\", \"start\");\n        \n        ruleset.add_step(\n            Step::decision(\"start\", \"Start\")\n                .branch(Condition::from_string(\"value > 10\"), \"high\")\n                .default(\"low\")\n                .build()\n        );\n        \n        ruleset.add_step(Step::terminal(\"high\", \"High\", \n            TerminalResult::new(\"HIGH\")));\n        ruleset.add_step(Step::terminal(\"low\", \"Low\", \n            TerminalResult::new(\"LOW\")));\n\n        let executor = RuleExecutor::new();\n        \n        // Test high value\n        let input: Value = serde_json::from_str(r#\"{\"value\": 20}\"#).unwrap();\n        let result = executor.execute(&ruleset, input).unwrap();\n        assert_eq!(result.code, \"HIGH\");\n        \n        // Test low value\n        let input: Value = serde_json::from_str(r#\"{\"value\": 5}\"#).unwrap();\n        let result = executor.execute(&ruleset, input).unwrap();\n        assert_eq!(result.code, \"LOW\");\n    }\n\n    #[test]\n    fn test_expression_eval() {\n        let evaluator = Evaluator::new();\n        let parser = ExprParser::new();\n        \n        let expr = parser.parse(\"age >= 18 && status == \\\"active\\\"\").unwrap();\n        let ctx = Context::from_json(r#\"{\"age\": 25, \"status\": \"active\"}\"#).unwrap();\n        let result = evaluator.eval(&expr, &ctx).unwrap();\n        \n        assert_eq!(result, Value::Bool(true));\n    }\n}\n```\n\n## Integration Tests\n\n### gRPC Tests\n\n```bash\ncargo test --package ordo-server --test grpc_test\n```\n\n### UDS Tests\n\n```bash\ncargo test --package ordo-server --test uds_test\n```\n\n## Benchmarks\n\n### Running Criterion Benchmarks\n\n```bash\n# All benchmarks\ncargo bench --package ordo-core\n\n# Specific benchmarks\ncargo bench --package ordo-core --bench engine_bench\ncargo bench --package ordo-core --bench jit_comparison_bench\ncargo bench --package ordo-core --bench schema_jit_bench\ncargo bench --package ordo-core --bench optimization_bench\n```\n\n### Benchmark Files\n\n| File | Description |\n|------|-------------|\n| `engine_bench.rs` | Overall engine performance |\n| `jit_comparison_bench.rs` | JIT vs interpreter comparison |\n| `jit_realistic_bench.rs` | Realistic JIT scenarios |\n| `jit_stress_bench.rs` | JIT stress testing |\n| `schema_jit_bench.rs` | Schema JIT performance |\n| `optimization_bench.rs` | Optimization effectiveness |\n\n### Writing Benchmarks\n\n```rust\nuse criterion::{black_box, criterion_group, criterion_main, Criterion};\nuse ordo_core::prelude::*;\n\nfn bench_rule_execution(c: &mut Criterion) {\n    let mut ruleset = RuleSet::new(\"bench\", \"start\");\n    // ... setup rules\n    \n    let executor = RuleExecutor::new();\n    let input: Value = serde_json::from_str(r#\"{\"value\": 100}\"#).unwrap();\n    \n    c.bench_function(\"rule_execution\", |b| {\n        b.iter(|| {\n            executor.execute(&ruleset, black_box(input.clone()))\n        })\n    });\n}\n\ncriterion_group!(benches, bench_rule_execution);\ncriterion_main!(benches);\n```\n\n## k6 Load Testing\n\n### Running Load Tests\n\n```bash\n# Basic test\n./scripts/benchmark.sh\n\n# Custom parameters\n./scripts/benchmark.sh \\\n    -h localhost \\\n    -p 8080 \\\n    -d 60s \\\n    -u 50 \\\n    -r 500 \\\n    --rule order_discount \\\n    --analyze\n```\n\n### Parameter Reference\n\n| Parameter | Description | Default |\n|-----------|-------------|---------|\n| `-h, --host` | Server address | localhost |\n| `-p, --port` | Port | 8080 |\n| `-d, --duration` | Test duration | 30s |\n| `-u, --vus` | Virtual users | 10 |\n| `-r, --rps` | Target RPS | 100 |\n| `--rule` | Rule name to test | order_discount |\n| `--analyze` | Show CPU analysis | false |\n\n### Custom k6 Script\n\n```javascript\nimport http from ''k6/http'';\nimport { check } from ''k6'';\n\nexport const options = {\n    scenarios: {\n        constant_load: {\n            executor: ''constant-arrival-rate'',\n            rate: 100,\n            timeUnit: ''1s'',\n            duration: ''30s'',\n            preAllocatedVUs: 10,\n        },\n    },\n    thresholds: {\n        http_req_duration: [''p(95)<500'', ''p(99)<1000''],\n    },\n};\n\nexport default function() {\n    const url = ''http://localhost:8080/api/v1/execute/my-rule'';\n    const payload = JSON.stringify({\n        input: { value: Math.random() * 1000 }\n    });\n    \n    const response = http.post(url, payload, {\n        headers: { ''Content-Type'': ''application/json'' },\n    });\n    \n    check(response, {\n        ''status is 200'': (r) => r.status === 200,\n        ''response time < 100ms'': (r) => r.timings.duration < 100,\n    });\n}\n```\n\n## CI Configuration\n\n### GitHub Actions\n\nKey workflow file: `.github/workflows/ci.yml`\n\n```yaml\n# Test job\ntest:\n  runs-on: ${{ matrix.os }}\n  strategy:\n    matrix:\n      os: [ubuntu-latest, macos-latest, windows-latest]\n      rust: [stable, beta]\n  steps:\n    - uses: actions/checkout@v4\n    - uses: dtolnay/rust-toolchain@master\n      with:\n        toolchain: ${{ matrix.rust }}\n    - run: cargo test --all-features\n```\n\n### Local CI Simulation\n\n```bash\n# Format check\ncargo fmt --all -- --check\n\n# Clippy check\ncargo clippy --all-targets --all-features -- -D warnings\n\n# Test\ncargo test --all-features\n\n# Build\ncargo build --release\n```\n\n## Test Coverage\n\n```bash\n# Install tarpaulin\ncargo install cargo-tarpaulin\n\n# Generate coverage report\ncargo tarpaulin --out Html --output-dir coverage/\n\n# Or use llvm-cov\ncargo install cargo-llvm-cov\ncargo llvm-cov --html\n```\n\n## Frontend Testing\n\n```bash\ncd ordo-editor\n\n# Run tests\npnpm test\n\n# Run specific package tests\npnpm --filter @ordo-engine/editor-core test\n```\n\n## Key Files\n\n- `crates/ordo-core/benches/` - Rust benchmarks\n- `crates/ordo-server/tests/` - Server integration tests\n- `scripts/benchmark.sh` - k6 load test script\n- `.github/workflows/ci.yml` - CI configuration\n- `ordo-editor/packages/core/src/engine/__tests__/` - Frontend tests\n"},"lastSynced":"2026-03-08T02:08:51.655Z","agentAnalysis":{"suitability":{"en":"Perfect for Rust-based AI Agents needing high-performance unit testing and benchmarking capabilities.","zh":"适用于需要高性能单元测试和基准测试功能的Rust-based AI Agents。","ja":"RustベースのAIエージェントが高性能のユニットテストとベンチマーキング機能を必要とする場合に適しています。","ko":"고성능 단위 테스트 및 벤치마크 기능이 필요한 Rust 기반 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de inteligencia artificial basados en Rust que necesitan capacidades de prueba de unidades y benchmarking de alto rendimiento.","fr":"Parfait pour les agents d''intelligence artificielle basés sur Rust nécessitant des capacités de test unitaire et de benchmarking à haute performance.","de":"Perfekt für auf Rust basierende KI-Agents, die hochleistungsfähige Unit-Tests und Benchmarking-Funktionen benötigen.","pt":"Perfeito para agentes de IA baseados em Rust que precisam de capacidades de teste de unidade de alto desempenho e benchmarking.","ru":"Идеально подходит для агентов ИИ на основе Rust, требующих возможностей высокопроизводительного юнит-тестирования и бенчмаркинга.","ar":"مثالي لعميل الذكاء الاصطناعي المبني على Rust الذي يحتاج إلى قدرات اختبار الوحدة عالية الأداء وتحليل الأداء."},"recommendation":{"en":"Empowers agents to execute robust unit tests and parallel execution using Cargo, leveraging Rust''s performance and reliability, with features like test threading control and nocapture output.","zh":"赋予代理执行使用Cargo的强大的单元测试和并行执行功能，利用Rust的性能和可靠性，具有测试线程控制和nocapture输出等功能。","ja":"Cargoを使用した強力なユニットテストと並列実行機能をエージェントが実行できるようにし、Rustのパフォーマンスと信頼性を利用し、テストスレッド制御やnocapture出力を含む機能を提供します。","ko":"Cargo를 사용한 강력한 단위 테스트 및 병렬 실행 기능을 에이전트가 실행할 수 있도록 하여 Rust의 성능 및 신뢰성을 활용하고 테스트 스레드 제어 및 nocapture 출력 등의 기능을 제공합니다.","es":"Habilita a los agentes a ejecutar pruebas de unidades robustas y ejecución paralela utilizando Cargo, aprovechando el rendimiento y la confiabilidad de Rust, con características como control de subprocesos de prueba y salida de nocapture.","fr":"Permet aux agents d''exécuter des tests unitaires robustes et une exécution parallèle en utilisant Cargo, en exploitant les performances et la fiabilité de Rust, avec des fonctionnalités telles que le contrôle du threading de test et la sortie de nocapture.","de":"Ermöglicht es Agenten, robuste Unit-Tests und parallele Ausführung mit Cargo auszuführen, wobei die Leistung und Zuverlässigkeit von Rust genutzt werden, mit Funktionen wie Test-Thread-Steuerung und nocapture-Ausgabe.","pt":"Habilita os agentes a executar testes de unidade robustos e execução paralela usando Cargo, aproveitando o desempenho e a confiabilidade do Rust, com recursos como controle de threading de teste e saída nocapture.","ru":"Наделяет агентов возможностью выполнять прочные юнит-тесты и параллельную обработку с помощью Cargo, используя производительность и надежность Rust, с функциями, такими как контроль потоков тестирования и вывод nocapture.","ar":"يمنح الوكلاء القدرة على تنفيذ اختبارات وحدة قوية وتنفيذ موازٍ باستخدام Cargo، مستفيداً من أداء Rust وموثوقيته، مع ميزات مثل التحكم في threading الاختبار وnocapture الإخراج."},"useCases":{"en":["Running comprehensive unit tests with Cargo","Benchmarking workflow performance with parallel execution","Debugging specific test cases with nocapture output"],"zh":["使用Cargo运行综合单元测试","使用并行执行对工作流性能进行基准测试","使用nocapture输出调试特定测试用例"],"ja":["Cargoを使用して包括的なユニットテストを実行する","並列実行を使用してワークフローのパフォーマンスをベンチマークする","nocapture出力を使用して特定のテストケースをデバッグする"],"ko":["Cargo를 사용하여 포괄적인 단위 테스트를 실행하는 것","병렬 실행을 사용하여 워크플로우 성능을 벤치마크하는 것","nocapture 출력을 사용하여 특정 테스트 케이스를 디버깅하는 것"],"es":["Ejecución de pruebas de unidades completas con Cargo","Benchmarking del rendimiento del flujo de trabajo con ejecución paralela","Depuración de casos de prueba específicos con salida de nocapture"],"fr":["Exécution de tests unitaires complets avec Cargo","Benchmarking des performances du workflow avec exécution parallèle","Débogage de cas de test spécifiques avec sortie de nocaptur