INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Pama-Lee/Ordo/ordo-testing', 'ordo-testing', 'Pama-Lee', 'Ordo', 'community', 'ordo-testing Pama-Lee Ordo community ordo-testing is a high-performance rule engine built in Rust, designed for efficient testing and benchmarking. It benefits developers seeking to optimize their workflow with robust unit tests and parallel execution. ordo-testing是一个使用Rust开发的高性能规则引擎，提供快速的单元测试和benchmarking功能 ordo-testingはRustで開発された高パフォーマンスなルールエンジンで、単体テストとベンチマークテストを迅速に実行できます ordo-testing은 러스트로 개발된 고성능 규칙 엔진으로 빠른 단위 테스트와 벤치마킹 기능을 제공합니다 Ordo-testing es un motor de reglas de alto rendimiento construido en Rust, ideal para pruebas y benchmarking. Ofrece funcionalidades de unit tests y benchmarking Ordo-testing est un moteur de règles haute performance construit en Rust, idéal pour les tests et le benchmarking. Il propose des fonctionnalités de tests unitaires et de benchmarking Ordo-testing ist eine Hochleistungs-Regelengine in Rust, ideal für Tests und Benchmarking. Sie bietet Funktionen für Unit-Tests und Benchmarking O Ordo-Testing é um motor de regras de alto desempenho construído em Rust, projetado para melhorar a eficiência dos testes Ordo-Testing - это высокопроизводительный движок правил на Rust, предназначенный для повышения эффективности тестирования и ИИ Агентов Ordo-Testing هو محرك قواعد أداء عالي مبني على Rust، مصمم لتحسين كفاءة الاختبارات وأدوات الذكاء الاصطناعي how to use ordo-testing ordo-testing alternative ordo-testing install what is ordo-testing ordo-testing vs rust test ordo-testing setup guide rust based rule engine high performance testing with ordo-testing ordo-testing benchmarking ordo-testing Rust规则引擎 单元测试 benchmarking cargo test 并行测试 测试输出 错误日志 Runs unit tests using the Cargo test command Supports parallel test execution with --test-threads flag Allows running specific tests with the cargo test --package command Enables output display with the --nocapture flag Features a test example in Rust for rule execution ordo-testing is a Rust-based rule engine for high-performance testing and benchmarking, featuring unit tests and parallel execution capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nahisaho/MUSUBI/database-administrator', 'community', 'nahisaho', 'MUSUBI', 'nahisaho/MUSUBI', 'database-administrator', 0, 0, 45, '2026-03-08T01:57:15.447Z', '2026-03-08T02:08:56.490Z', '4200fb1b5425f83af768416aeac40ad6d88666c0e343a1492484d2e3d91ca65f', '{"id":"nahisaho/MUSUBI/database-administrator","name":"database-administrator","description":{"en":"The database-administrator skill manages database operations, performance tuning, and security through structured dialogue. It benefits database administrators and developers seeking efficient DBMS management.","zh":"数据库管理员AI代理专门处理数据库操作、性能优化和高可用性配置。提供结构化的数据库管理对话支持，涵盖安装配置到灾难恢复的全生命周期管理。","ja":"データベース管理者AIエージェントは、データベース操作、パフォーマンスチューニング、バックアップ/復旧を管理します。構造化された対話によるDBMSセットアップと高可用性構成をサポート。","ko":"데이터베이스 관리자 AI 에이전트는 데이터베이스 운영, 성능 튜닝, 백업/복구를 관리합니다. 구조화된 대화를 통한 DBMS 설정 및 고가용성 구성 지원.","es":"Un agente de IA especializado en administración de bases de datos que gestiona operaciones de DBMS, ajuste de rendimiento, copias de seguridad y alta disponibilidad mediante diálogo estructurado en español.","fr":"Un agent IA spécialisé en administration de bases de données qui gère les opérations SGBD, le réglage des performances, les sauvegardes et la haute disponibilité via un dialogue structuré en français.","de":"Ein KI-Agent für Datenbankadministration, der DBMS-Operationen, Performance-Tuning, Backup-Management und Hochverfügbarkeitskonfiguration durch strukturierten Dialog auf Deutsch verwaltet.","pt":"O Administrador de Banco de Dados AI gerencia operações de banco de dados, ajuste de desempenho e segurança.","ru":"ИИ Агент Базы Данных управляет операциями базы данных, настройкой производительности и безопасностью.","ar":"مسؤول قاعدة البيانات الاصطناعي يدير عمليات قاعدة البيانات وتحسين الأداء والأمن."},"seo":{"title":{"en":"Database-Administrator: DBMS Setup Guide | AI Agent Skill","zh":"数据库管理员AI代理：安装配置与性能调优指南","ja":"データベース管理者AIエージェント：設定とパフォーマンスチューニング","ko":"데이터베이스 관리자 AI 에이전트: 설치 구성 및 성능 튜닝 가이드","es":"Administrador de Bases de Datos AI: Guía de Configuración","fr":"Administrateur de Base de Données IA : Guide de Configura...","de":"Datenbankadministrator AI: Einrichtungsleitfaden","pt":"Guia de Configuração de Administrador de Banco de Dados","ru":"Настройка ИИ Агента Базы Данных: Лучшие Практики","ar":"دليل إعداد مسؤول قاعدة البيانات الاصطناعي"},"description":{"en":"Unlock expert database management with our AI agent skill. Learn how to optimize DBMS setup, configuration, and performance tuning for high availability and ...","zh":"专为开发者设计的数据库管理员AI代理，提供DBMS安装配置、版本管理、容量规划、性能调优、备份恢复和高可用性配置等专业数据库管理支持。","ja":"開発者向けデータベース管理者AIエージェント。DBMSセットアップ、バージョン管理、容量計画、パフォーマンスチューニング、バックアップ/復旧、高可用性構成を日本語でサポート。","ko":"개발자를 위한 데이터베이스 관리자 AI 에이전트. DBMS 설치 및 구성, 버전 관리, 용량 계획, 성능 튜닝, 백업/복구, 고가용성 구성 지원.","es":"AI Agent especializado en administración de bases de datos. Automatiza operaciones de DBMS, ajuste de rendimiento, gestión de copias de seguridad y alta disp...","fr":"Agent IA spécialisé en administration de bases de données. Automatise les opérations SGBD, le réglage des performances, la gestion des sauvegardes et la haut...","de":"KI-Agent für Datenbankadministration. Automatisiert DBMS-Operationen, Performance-Tuning, Backup-Management und Hochverfügbarkeitskonfiguration auf Deutsch.","pt":"Aprenda a configurar e otimizar o desempenho do seu banco de dados com o Administrador de Banco de Dados AI","ru":"Узнайте, как настроить и оптимизировать производительность своей базы данных с помощью ИИ Агента Базы Данных","ar":"تعرف على كيفية إعداد وتحسين أداء قاعدة البيانات الخاصة بك مع مسؤول قاعدة البيانات الاصطناعي"},"definition":{"en":"database-administrator is a specialized AI agent skill for managing database operations, including installation, configuration, and performance tuning.","zh":"数据库管理员AI代理是专门设计用于管理数据库操作的智能工具，通过结构化对话提供DBMS安装配置、版本管理、容量规划、性能调优和灾难恢复等专业数据库管理功能。","ja":"データベース管理者AIエージェントは、構造化された対話を通じてDBMSセットアップ、設定管理、バージョン管理、容量計画、パフォーマンスチューニングを実行する専門AIツールです。","ko":"데이터베이스 관리자 AI 에이전트는 구조화된 대화를 통해 DBMS 설치 구성, 버전 관리, 용량 계획, 성능 튜닝을 수행하는 전문 AI 도구입니다.","es":"El Database Administrator AI es un agente de inteligencia artificial especializado en gestionar operaciones de bases de datos, incluyendo configuración de DBMS, ajuste de rendimiento, gestión de copias de seguridad y configuración de alta disponibilidad mediante diálogo estructurado.","fr":"Le Database Administrator AI est un agent d''intelligence artificielle spécialisé dans la gestion des opérations de bases de données, incluant la configuration SGBD, le réglage des performances, la gestion des sauvegardes et la configuration de haute disponibilité via un dialogue structuré.","de":"Der Database Administrator AI ist ein KI-Agent, der spezialisiert ist auf die Verwaltung von Datenbankoperationen, einschließlich DBMS-Konfiguration, Performance-Tuning, Backup-Management und Hochverfügbarkeitskonfiguration durch strukturierten Dialog.","pt":"O que é um Administrador de Banco de Dados AI? É um agente que gerencia operações de banco de dados.","ru":"Что такое ИИ Агент Базы Данных? Это агент, который управляет операциями базы данных.","ar":"ما هو مسؤول قاعدة البيانات الاصطناعي؟ هو وكيل يدير عمليات قاعدة البيانات."},"features":{"en":["Installs and configures DBMS with setup and configuration management","Manages version upgrades with compatibility checks and upgrade strategies","Optimizes capacity with storage planning and management","Configures high availability for secure and reliable database operations","Monitors database performance for optimal tuning and security management"],"zh":["DBMS安装与配置管理","数据库版本升级策略与兼容性检查","存储容量规划与管理","数据库性能调优与优化","备份与灾难恢复方案实施","高可用性配置与管理"],"ja":["DBMSセットアップと設定管理","バージョン管理と互換性チェック","ストレージ容量計画と管理","パフォーマンスチューニング最適化","バックアップと復旧戦略","高可用性構成と監視"],"ko":["DBMS 설치 및 구성 관리","버전 관리 및 호환성 검사","스토리지 용량 계획 및 관리","성능 튜닝 및 최적화","백업 및 복구 전략","고가용성 구성 및 모니터링"],"es":["Instalación y configuración de DBMS","Gestión de versiones y compatibilidad","Planificación de capacidad y almacenamiento","Ajuste de rendimiento de bases de datos","Gestión de copias de seguridad y recuperación","Configuración de alta disponibilidad"],"fr":["Installation et configuration SGBD","Gestion des versions et vérification de compatibilité","Planification de capacité et stockage","Réglage des performances de base de données","Gestion des sauvegardes et récupération","Configuration de haute disponibilité"],"de":["DBMS-Installation und Konfiguration","Versionsverwaltung und Kompatibilitätsprüfung","Kapazitätsplanung und Storage-Management","Datenbank-Performance-Tuning","Backup-Management und Recovery","Hochverfügbarkeitskonfiguration"],"pt":["Instalação e Configuração de DBMS","Gestão de Versão e Compatibilidade","Otimização de Desempenho e Capacidade","Configuração de Alta Disponibilidade","Gestão de Segurança de Dados"],"ru":["Установка и Настройка СУБД","Управление Версиями и Совместимостью","Оптимизация Производительности и Ёмкости","Настройка Высокой Доступности","Управление Безопасностью Данных"],"ar":["تركيب وتكوين نظام إدارة قواعد البيانات","إدارة الإصدارات والتوافق","تحسين الأداء والسعة","تكوين التوفر العالي","إدارة أمن البيانات"]},"keywords":{"en":["how to use database-administrator","database-administrator setup guide","database-administrator vs traditional DBMS management","database-administrator install and configuration","what is database-administrator","database-administrator alternative for high availability","database-administrator performance tuning best practices","database-administrator security management","database-administrator DBMS setup and configuration"],"zh":["数据库管理员AI","DBMS安装配置","数据库性能调优","备份恢复策略","高可用性配置","容量规划管理","版本升级兼容性","数据库监控工具"],"ja":["データベース管理者AIエージェント","DBMSセットアップ","パフォーマンスチューニング","バックアップ復旧","高可用性構成","容量計画","バージョン管理","データベース監視"],"ko":["데이터베이스 관리자 AI 에이전트","DBMS 설치 구성","성능 튜닝","백업 복구","고가용성 구성","용량 계획","버전 관리","데이터베이스 모니터링"],"es":["administrador bases de datos AI","agente IA administración BD","configuración DBMS","optimización rendimiento base de datos","gestión copias seguridad base de datos","alta disponibilidad bases de datos","automatización administración BD","herramientas AI para DBA"],"fr":["administrateur base de données IA","agent IA administration BDD","configuration SGBD","optimisation performance base de données","gestion sauvegardes base de données","haute disponibilité bases de données","automatisation administration BDD","outils IA pour DBA"],"de":["Datenbankadministrator KI","KI-Agent Datenbankadministration","DBMS Konfiguration","Datenbank Performance Optimierung","Backup Management Datenbank","Hochverfügbarkeit Datenbank","Automatisierung Datenbankadministration","KI-Tools für Datenbankadministratoren"],"pt":["administrador de banco de dados","otimização de desempenho","segurança de dados","configuração de dbms","gestão de versão","alta disponibilidade","índices de banco de dados","modelagem de dados"],"ru":["ИИ Агент Базы Данных","оптимизация производительности","безопасность данных","настройка СУБД","управление версиями","высокая доступность","индексы базы данных","моделирование данных"],"ar":["مسؤول قاعدة البيانات الاصطناعي","تحسين الأداء","أمن البيانات","تكوين نظام إدارة قواعد البيانات","إدارة الإصدارات","التوفر العالي","فهرس قاعدة البيانات","نمذجة البيانات"]}},"owner":"nahisaho","repo":"MUSUBI","repoPath":"nahisaho/MUSUBI","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.447Z","topics":[],"category":"community","skillMd":{"name":"database-administrator","description":"|","bodyPreview":"# Database Administrator AI\n\n## 1. Role Definition\n\nYou are a **Database Administrator AI**.\nYou manage database operations, performance tuning, backup and recovery, monitoring, high availability configuration, and security management through structured dialogue in Japanese.\n\n---\n\n## 2. Areas of Expertise\n\n- **Database Operations**: Installation and Configuration (DBMS Setup, Configuration Management), Version Management (Upgrade Strategy, Compatibility Check), Capacity Management (Storage Plann","body":"# Database Administrator AI\n\n## 1. Role Definition\n\nYou are a **Database Administrator AI**.\nYou manage database operations, performance tuning, backup and recovery, monitoring, high availability configuration, and security management through structured dialogue in Japanese.\n\n---\n\n## 2. Areas of Expertise\n\n- **Database Operations**: Installation and Configuration (DBMS Setup, Configuration Management), Version Management (Upgrade Strategy, Compatibility Check), Capacity Management (Storage Plann"},"lastSynced":"2026-03-08T02:08:56.490Z","agentAnalysis":{"suitability":{"en":"Essential for DevOps and Backend Agents managing enterprise database lifecycle operations.","zh":"对于管理企业数据库生命周期操作的DevOps和Backend Agent至关重要。","ja":"エンタープライズデータベースのライフサイクル操作を管理するDevOpsおよびバックエンドエージェントに不可欠です。","ko":"기업 데이터베이스 라이프사이클 운영을 관리하는 DevOps 및 백엔드 에이전트에게 필수적입니다.","es":"Esencial para DevOps y Backend Agents que gestionan operaciones de ciclo de vida de bases de datos empresariales.","fr":"Essentiel pour les agents DevOps et Backend qui gèrent les opérations de cycle de vie de bases de données d''entreprise.","de":"Wesentlich für DevOps- und Backend-Agents, die den Lebenszyklus von Unternehmensdatenbanken verwalten.","pt":"Essencial para DevOps e Backend Agents que gerenciam operações de ciclo de vida de banco de dados de empresa.","ru":"Необходим для DevOps и Backend Agents, управляющих операциями жизненного цикла корпоративной базы данных.","ar":"ضروري لعمليات DevOps ووكلاء الخلفية الذين يديرون عمليات دورة حياة قاعدة البيانات الخاصة بالشركة."},"recommendation":{"en":"Enables comprehensive DBMS management including performance tuning, backup/recovery strategies, and high availability configuration. Directly handles version management, capacity planning, and security protocols through structured Japanese-language dialogue.","zh":"支持全面的DBMS管理，包括性能调优、备份/恢复策略和高可用性配置。通过结构化的日语对话直接处理版本管理、容量规划和安全协议。","ja":"パフォーマンスチューニング、バックアップ/リカバリ戦略、高可用性構成を含む包括的なDBMS管理を可能にします。構造化された日本語ダイアログを通じて、バージョン管理、キャパシティプランニング、セキュリティプロトコルを直接処理します。","ko":"성능 튜닝, 백업/복구 전략 및 고가용성 구성을 포함한 포괄적인 DBMS 관리를 가능하게 합니다. 구조화된 일본어 대화를 통해 버전 관리, 용량 계획 및 보안 프로토콜을 직접 처리합니다.","es":"Permite una gestión integral de DBMS, incluyendo ajuste de rendimiento, estrategias de copia de seguridad/recuperación y configuración de alta disponibilidad. Maneja directamente la gestión de versiones, la planificación de capacidad y los protocolos de seguridad a través de diálogos estructurados en japonés.","fr":"Permet une gestion complète de DBMS, y compris le réglage des performances, les stratégies de sauvegarde/récupération et la configuration de haute disponibilité. Gère directement la gestion des versions, la planification de la capacité et les protocoles de sécurité via des dialogues structurés en japonais.","de":"Ermöglicht eine umfassende DBMS-Verwaltung, einschließlich Leistungsabstimmung, Backup-/Wiederherstellungsstrategien und Hochverfügbarkeitskonfiguration. Verwaltet direkt die Versionsverwaltung, die Kapazitätsplanung und die Sicherheitsprotokolle über strukturierte japanische Dialoge.","pt":"Permite gerenciamento abrangente do DBMS, incluindo ajuste de desempenho, estratégias de backup/recuperação e configuração de alta disponibilidade. Manipula diretamente o gerenciamento de versão, planejamento de capacidade e protocolos de segurança por meio de diálogo estruturado em língua japonesa.","ru":"Позволяет осуществлять комплексное управление DBMS, включая настройку производительности, стратегии резервного копирования и восстановления, а также конфигурацию высокодоступности. Прямо обрабатывает управление версиями, планирование емкости и протоколы безопасности посредством структурированного диалога на японском языке.","ar":"يسمح بإدارة شاملة لنظام إدارة قواعد البيانات، بما في ذلك ضبط الأداء وстрategies النسخ الاحتياطي والاستعادة وتكوين التوفر العالي. يعالج مباشرة إدارة الإصدار وتخطيط السعة وبروتوكولات الأمان من خلال الحوار الهيكلي باللغة اليابانية."},"useCases":{"en":["Automating database backup and recovery procedures","Optimizing query performance through tuning","Configuring high availability and failover systems","Managing storage capacity and scaling operations","Implementing security protocols and access controls"],"zh":["自动化数据库备份和恢复流程","通过调优优化查询性能","配置高可用性和故障转移系统","管理存储容量和扩展操作","实施安全协议和访问控制"],"ja":["データベースのバックアップおよびリカバリ手順の自動化","チューニングによるクエリパフォーマンスの最適化","高可用性およびフェイルオーバーシステムの構成","ストレージ容量の管理とスケーリング操作","セキュリティプロトコルとアクセス制御の実装"],"ko":["데이터베이스 백업 및 복구 절차 자동화","튜닝을 통한 쿼리 성능 최적화","고가용성 및 페일오버 시스템 구성","저장 용량 관리 및 스케일링 운영","보안 프로토콜 및 접근 제어 구현"],"es":["Automatizar procedimientos de copia de seguridad y recuperación de bases de datos","Optimizar el rendimiento de consultas mediante ajuste","Configurar sistemas de alta disponibilidad y conmutación por error","Gestionar la capacidad de almacenamiento y las operaciones de escalado","Implementar protocolos de seguridad y controles de acceso"],"fr":["Automatiser les procédures de sauvegarde et de récupération de bases de données","Optimiser les performances des requêtes via le réglage","Configurer les systèmes de haute disponibilité et de basculement","Gérer la capacité de stockage et les opérations de mise à l''échelle","Mettre en œuvre des protocoles de sécurité et des contrôles d''accès"],"de":["Automatisieren von Datenbanksicherungs- und -wiederherstellungsverfahren","Optimieren der Abfrageleistung durch Abstimmung","Konfigurieren von Hochverfügbarkeitssystemen und Failover-Systemen","Verwalten der Speicherkapazität und der Skalierungsoperationen","Implementieren von Sicherheitsprotokollen und Zugriffskontrollen"],"pt":["Automatizar procedimentos de backup e recuperação de banco de dados","Otimizar desempenho de consulta por meio de ajuste","Configurar sistemas de alta disponibilidade e failover","Gerenciar capacidade de armazenamento e operações de escalonamento","Implementar protocolos de segurança e controles de acesso"],"ru":["Автоматизировать процедуры резервного копирования и восстановления базы данных","Оптимизировать производительность запросов путем настройки","Настроить системы высокодоступности и отказоустойчивости","Управлять емкостью хранилища и операциями по масштабированию","Реализовать протоколы безопасности и механизмы контроля доступа"],"ar":["توفير إجراءات النسخ الاحتياطي والاستعادة التلقائية لقاعدة البيانات","تحسين أداء الاستعلام من خلال ضبط الأداء","تكوين أنظمة التوفر العالي والتحول التلقائي","إدارة سعة التخزين وعمليات التوسيع","تنفيذ بروتوكولات الأمان وآليات التحكم في الوصول"]},"limitations":{"en":["Japanese-language dialogue requirement","DBMS-specific expertise needed for implementation","Requires system access privileges for operations"],"zh":["需要日语对话要求","实施需要DBMS特定的专业知识","操作需要系统访问权限"],"ja":["日本語ダイアログの要件","実装にはDBMS固有の専門知識が必要","操作にはシステムアクセス権限が必要"],"ko":["일본어 대화 요구사항","구현을 위한 DBMS별 전문 지식 필요","운영을 위한 시스템 접근 권한 필요"],"es":["Requisito de diálogo en japonés","Se requiere experiencia específica de DBMS para la implementación","Se requieren privilegios de acceso al sistema para las operaciones"],"fr":["Exigence de dialogue en japonais","Une expertise spécifique de DBMS est nécessaire pour la mise en œuvre","Des privilèges d''accès au système sont nécessaires pour les opérations"],"de":["Erfordernis von japanischem Dialog","DBMS-spezifisches Know-how wird für die Implementierung benötigt","Systemzugriffsberechtigungen werden für die Operationen benötigt"],"pt":["Requisito de diálogo em língua japonesa","É necessário conhecimento especializado em DBMS para implementação","Requer privilégios de acesso ao sistema para operações"],"ru":["Требование диалога на японском языке","Необходимо наличие специальных знаний в области DBMS для реализации","Требуются привилегии доступа к системе для осуществления операций"],"ar":["متطلب الحوار باللغة اليابانية","يُحتاج إلى خبرة متخصصة في نظام إدارة قواعد البيانات لتنفيذ","يتطلب صلاحيات الوصول إلى النظام للعمليات"]},"version":4},"contentHash":"4200fb1b5425f83af768416aeac40ad6d88666c0e343a1492484d2e3d91ca65f","qualityScore":45}');
