INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nahisaho/MUSUBI/database-administrator', 'database-administrator', 'nahisaho', 'MUSUBI', 'community', 'database-administrator nahisaho MUSUBI community The database-administrator skill manages database operations, performance tuning, and security through structured dialogue. It benefits database administrators and developers seeking efficient DBMS management. 数据库管理员AI代理专门处理数据库操作、性能优化和高可用性配置。提供结构化的数据库管理对话支持，涵盖安装配置到灾难恢复的全生命周期管理。 データベース管理者AIエージェントは、データベース操作、パフォーマンスチューニング、バックアップ/復旧を管理します。構造化された対話によるDBMSセットアップと高可用性構成をサポート。 데이터베이스 관리자 AI 에이전트는 데이터베이스 운영, 성능 튜닝, 백업/복구를 관리합니다. 구조화된 대화를 통한 DBMS 설정 및 고가용성 구성 지원. Un agente de IA especializado en administración de bases de datos que gestiona operaciones de DBMS, ajuste de rendimiento, copias de seguridad y alta disponibilidad mediante diálogo estructurado en español. Un agent IA spécialisé en administration de bases de données qui gère les opérations SGBD, le réglage des performances, les sauvegardes et la haute disponibilité via un dialogue structuré en français. Ein KI-Agent für Datenbankadministration, der DBMS-Operationen, Performance-Tuning, Backup-Management und Hochverfügbarkeitskonfiguration durch strukturierten Dialog auf Deutsch verwaltet. O Administrador de Banco de Dados AI gerencia operações de banco de dados, ajuste de desempenho e segurança. ИИ Агент Базы Данных управляет операциями базы данных, настройкой производительности и безопасностью. مسؤول قاعدة البيانات الاصطناعي يدير عمليات قاعدة البيانات وتحسين الأداء والأمن. how to use database-administrator database-administrator setup guide database-administrator vs traditional DBMS management database-administrator install and configuration what is database-administrator database-administrator alternative for high availability database-administrator performance tuning best practices database-administrator security management database-administrator DBMS setup and configuration 数据库管理员AI DBMS安装配置 数据库性能调优 备份恢复策略 高可用性配置 容量规划管理 版本升级兼容性 数据库监控工具 Installs and configures DBMS with setup and configuration management Manages version upgrades with compatibility checks and upgrade strategies Optimizes capacity with storage planning and management Configures high availability for secure and reliable database operations Monitors database performance for optimal tuning and security management database-administrator is a specialized AI agent skill for managing database operations, including installation, configuration, and performance tuning.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('codefastlabs/codefast/tanstack-router', 'community', 'codefastlabs', 'codefast', 'codefastlabs/codefast', 'tanstack-router', 0, 0, 45, '2026-03-08T01:57:15.452Z', '2026-03-08T02:09:02.456Z', '7333cd3e68bb2b50f15c096a87f151b4234ace77ae40bd7782ad4923ced1da1f', '{"id":"codefastlabs/codefast/tanstack-router","name":"tanstack-router","description":{"en":"tanstack-router provides type-safe, file-based routing for React Single-Page Applications, benefiting developers with efficient route management.","zh":"TanStack Router提供文件级路由和数据加载，支持React单页应用","ja":"TanStack Routerはファイルベースのルーティングとデータローディングを提供し、React単一ページアプリケーションをサポートしています","ko":"TanStack Router는 파일 기반 라우팅과 데이터 로딩을 제공하며 React 단일 페이지 애플리케이션을 지원합니다","es":"TanStack Router ofrece rutas tipo seguras y carga de datos a nivel de ruta para SPAs de React","fr":"TanStack Router propose des routes de type sécurisées et une charge de données au niveau de la route pour les SPAs React","de":"TanStack Router bietet sichere Routing-Typen und Datenladung auf Routenebene für React-SPAs","pt":"O TanStack Router é uma biblioteca de roteamento para React que oferece roteamento baseado em arquivos e carregamento de dados","ru":"TanStack Router — это библиотека роутинга для React, которая предоставляет файловый роутинг и загрузку данных","ar":"TanStack Router هي مكتبة روتينج لتفاعلات React تقدم روتينج قائم على الملفات وتحميل البيانات"},"seo":{"title":{"en":"tanstack-router: Type-safe Routing Setup Guide | AI Agent...","zh":"TanStack Router_SETUP GUIDE - AIエージェント","ja":"TanStack Router設定ガイド - AIエージェント","ko":"TanStack Router설정 가이드 - AI 도구","es":"Guía de configuración de TanStack Router para SPAs de React","fr":"Configurer TanStack Router pour les SPAs React","de":"Einrichtungsanleitung für TanStack Router in React SPAs","pt":"Guia de Configuração do TanStack Router para React","ru":"Настройка TanStack Router для React: ИИ Агенты","ar":"إعداد TanStack Router للتفاعل مع واجهة المستخدم الحديثة -..."},"description":{"en":"Discover how to set up tanstack-router for React SPAs, with route-level data loading and TanStack Query integration. Get started now!","zh":"TanStack Router实现文件级路由和数据加载，集成了TanStack Query，适用于React单页应用","ja":"TanStack Routerはファイルベースのルーティングとデータローディングを実現し、TanStack Queryと統合しています","ko":"TanStack Router는 파일 기반 라우팅과 데이터 로딩을 구현하며 TanStack Query와 통합되어 있습니다","es":"Aprende a utilizar TanStack Router para crear rutas tipo seguras y carga de datos a nivel de ruta en tus SPAs de React","fr":"Découvrez comment utiliser TanStack Router pour créer des routes de type sécurisées et charger des données au niveau de la route dans vos SPAs React","de":"Erfahren Sie, wie Sie TanStack Router verwenden, um sichere Routing-Typen und Datenladung auf Routenebene in Ihren React-SPAs zu erstellen","pt":"Aprenda a configurar o TanStack Router para aplicações React com roteamento baseado em arquivos e carregamento de dados","ru":"Узнайте, как настроить TanStack Router для React-приложений с файловым роутингом и загрузкой данных","ar":"تعلم كيفية إعداد TanStack Router لتفاعلات React الحديثة مع روتينج قائم على الملفات وتحميل البيانات"},"definition":{"en":"tanstack-router is a JavaScript library for type-safe, file-based routing in React applications, integrated with TanStack Query.","zh":"TanStack Router是一种用于React单页应用的文件级路由库","ja":"TanStack RouterはReact単一ページアプリケーション用のファイルベースのルーティングライブラリです","ko":"TanStack Router는 React 단일 페이지 애플리케이션을 위한 파일 기반 라우팅 라이브러리입니다","es":"TanStack Router es una biblioteca para crear rutas tipo seguras y carga de datos a nivel de ruta en SPAs de React","fr":"TanStack Router est une bibliothèque pour créer des routes de type sécurisées et charger des données au niveau de la route dans les SPAs React","de":"TanStack Router ist eine Bibliothek zum Erstellen sicherer Routing-Typen und Datenladung auf Routenebene in React-SPAs","pt":"O que é TanStack Router? É uma biblioteca de roteamento para React","ru":"Что такое TanStack Router? Это библиотека роутинга для React","ar":"ما هي TanStack Router? هي مكتبة روتينج لتفاعلات React"},"features":{"en":["Type-safe routing using @tanstack/react-router","File-based routing for efficient route management","Route-level data loading with TanStack Query integration","Optional Zod validation adapter for enhanced data validation","Vite config support with TanStackRouterVite plugin"],"zh":["文件级路由","数据加载","TanStack Query集成","React单页应用支持","Type-safe路由","文件基于路由配置"],"ja":["ファイルベースのルーティング","データローディング","TanStack Query統合","React単一ページアプリケーションサポート","Type-safeルーティング","ファイルベースのルーティング設定"],"ko":["파일 기반 라우팅","데이터 로딩","TanStack Query 통합","React 단일 페이지 애플리케이션 지원","Type-safe 라우팅","파일 기반 라우팅 구성"],"es":["Rutas tipo seguras con integración de TanStack Query","Carga de datos a nivel de ruta","Compatibilidad con Vite","Soporte para Zod validation adapter","Instalación sencilla con npm o yarn"],"fr":["Routes de type sécurisées avec intégration de TanStack Query","Chargement de données au niveau de la route","Compatibilité avec Vite","Prise en charge de l''adaptateur de validation Zod","Installation simple avec npm ou yarn"],"de":["Sichere Routing-Typen mit TanStack Query-Integration","Datenladung auf Routenebene","Kompatibilität mit Vite","Unterstützung für Zod-Validation-Adapter","Einfache Installation mit npm oder yarn"],"pt":["Roteamento baseado em arquivos","Carregamento de dados em nível de rota","Integração com TanStack Query","Suporte ao Vite","Validação com Zod"],"ru":["Файловый роутинг","Загрузка данных на уровне роутинга","Интеграция с TanStack Query","Поддержка Vite","Валидация с Zod"],"ar":["روتينج قائم على الملفات","تحميل البيانات على مستوى الروتينج","التكامل مع TanStack Query","دعم Vite","التحقق من صحة البيانات مع Zod"]},"keywords":{"en":["how to use tanstack-router","tanstack-router install","tanstack-router setup guide","tanstack-router vs react-router","what is tanstack-router","tanstack-router alternative","tanstack-router react spa","tanstack-router type-safe routing"],"zh":["TanStack Router","React路由","文件级路由","数据加载","TanStack Query","AIエージェント","React单页应用","Type-safe路由"],"ja":["TanStack Router","Reactルーティング","ファイルベースのルーティング","データローディング","TanStack Query","AIエージェント","React単一ページアプリケーション","Type-safeルーティング"],"ko":["TanStack Router","React 라우팅","파일 기반 라우팅","데이터 로딩","TanStack Query","AI 도구","React 단일 페이지 애플리케이션","Type-safe 라우팅"],"es":["TanStack Router","rutas tipo seguras","carga de datos a nivel de ruta","React SPAs","TanStack Query","Vite","Zod validation adapter","instalación de TanStack Router"],"fr":["TanStack Router","routes de type sécurisées","chargement de données au niveau de la route","SPAs React","TanStack Query","Vite","adaptateur de validation Zod","installation de TanStack Router"],"de":["TanStack Router","sichere Routing-Typen","Datenladung auf Routenebene","React-SPAs","TanStack Query","Vite","Zod-Validation-Adapter","Installation von TanStack Router"],"pt":["TanStack Router","roteamento react","carregamento de dados","TanStack Query","Vite config","Zod validaçao","react router","roteamento baseado em arquivos"],"ru":["TanStack Router","роутинг react","загрузка данных","TanStack Query","Vite конфиг","Zod валидация","react роутер","файловый роутинг"],"ar":["TanStack Router","روتينج رياكت","تحميل البيانات","TanStack Query","تكوين Vite","تحقق من صحة Zod","روتر رياكت","روتينج قائم على الملفات"]}},"owner":"codefastlabs","repo":"codefast","repoPath":"codefastlabs/codefast","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.452Z","topics":[],"category":"community","skillMd":{"name":"tanstack-router","description":"|","bodyPreview":"# TanStack Router\n\nType-safe, file-based routing for React SPAs with route-level data loading and TanStack Query integration\n\n---\n\n## Quick Start\n\n**Last Updated**: 2026-01-09\n**Version**: @tanstack/react-router@1.146.2\n\n```bash\nnpm install @tanstack/react-router @tanstack/router-devtools\nnpm install -D @tanstack/router-plugin\n# Optional: Zod validation adapter\nnpm install @tanstack/zod-adapter zod\n```\n\n**Vite Config** (TanStackRouterVite MUST come before react()):\n```typescript\n// vite.config.t","body":"# TanStack Router\n\nType-safe, file-based routing for React SPAs with route-level data loading and TanStack Query integration\n\n---\n\n## Quick Start\n\n**Last Updated**: 2026-01-09\n**Version**: @tanstack/react-router@1.146.2\n\n```bash\nnpm install @tanstack/react-router @tanstack/router-devtools\nnpm install -D @tanstack/router-plugin\n# Optional: Zod validation adapter\nnpm install @tanstack/zod-adapter zod\n```\n\n**Vite Config** (TanStackRouterVite MUST come before react()):\n```typescript\n// vite.config.ts\nimport { TanStackRouterVite } from ''@tanstack/router-plugin/vite''\n\nexport default defineConfig({\n  plugins: [TanStackRouterVite(), react()], // Order matters!\n})\n```\n\n**File Structure**:\n```\nsrc/routes/\n├── __root.tsx         → createRootRoute() with <Outlet />\n├── index.tsx          → createFileRoute(''/'')\n└── posts.$postId.tsx  → createFileRoute(''/posts/$postId'')\n```\n\n**App Setup**:\n```typescript\nimport { createRouter, RouterProvider } from ''@tanstack/react-router''\nimport { routeTree } from ''./routeTree.gen'' // Auto-generated by plugin\n\nconst router = createRouter({ routeTree })\n<RouterProvider router={router} />\n```\n\n---\n\n## Core Patterns\n\n**Type-Safe Navigation** (routes auto-complete, params typed):\n```typescript\n<Link to=\"/posts/$postId\" params={{ postId: ''123'' }} />\n<Link to=\"/invalid\" /> // ❌ TypeScript error\n```\n\n**Route Loaders** (data fetching before render):\n```typescript\nexport const Route = createFileRoute(''/posts/$postId'')({\n  loader: async ({ params }) => ({ post: await fetchPost(params.postId) }),\n  component: ({ useLoaderData }) => {\n    const { post } = useLoaderData() // Fully typed!\n    return <h1>{post.title}</h1>\n  },\n})\n```\n\n**TanStack Query Integration** (prefetch + cache):\n```typescript\nconst postOpts = (id: string) => queryOptions({\n  queryKey: [''posts'', id],\n  queryFn: () => fetchPost(id),\n})\n\nexport const Route = createFileRoute(''/posts/$postId'')({\n  loader: ({ context: { queryClient }, params }) =>\n    queryClient.ensureQueryData(postOpts(params.postId)),\n  component: () => {\n    const { postId } = Route.useParams()\n    const { data } = useQuery(postOpts(postId))\n    return <h1>{data.title}</h1>\n  },\n})\n```\n\n---\n\n## Virtual File Routes (v1.140+)\n\nProgrammatic route configuration when file-based conventions don''t fit your needs:\n\n**Install**: `npm install @tanstack/virtual-file-routes`\n\n**Vite Config**:\n```typescript\nimport { tanstackRouter } from ''@tanstack/router-plugin/vite''\n\nexport default defineConfig({\n  plugins: [\n    tanstackRouter({\n      target: ''react'',\n      virtualRouteConfig: ''./routes.ts'', // Point to your routes file\n    }),\n    react(),\n  ],\n})\n```\n\n**routes.ts** (define routes programmatically):\n```typescript\nimport { rootRoute, route, index, layout, physical } from ''@tanstack/virtual-file-routes''\n\nexport const routes = rootRoute(''root.tsx'', [\n  index(''home.tsx''),\n  route(''/posts'', ''posts/posts.tsx'', [\n    index(''posts/posts-home.tsx''),\n    route(''$postId'', ''posts/posts-detail.tsx''),\n  ]),\n  layout(''first'', ''layout/first-layout.tsx'', [\n    route(''/nested'', ''nested.tsx''),\n  ]),\n  physical(''/classic'', ''file-based-subtree''), // Mix with file-based\n])\n```\n\n**Use Cases**: Custom route organization, mixing file-based and code-based, complex nested layouts.\n\n---\n\n## Search Params Validation (Zod Adapter)\n\nType-safe URL search params with runtime validation:\n\n**Basic Pattern** (inline validation):\n```typescript\nimport { z } from ''zod''\n\nexport const Route = createFileRoute(''/products'')({\n  validateSearch: (search) => z.object({\n    page: z.number().catch(1),\n    filter: z.string().catch(''''),\n    sort: z.enum([''newest'', ''oldest'', ''price'']).catch(''newest''),\n  }).parse(search),\n})\n```\n\n**Recommended Pattern** (Zod adapter with fallbacks):\n```typescript\nimport { zodValidator, fallback } from ''@tanstack/zod-adapter''\nimport { z } from ''zod''\n\nconst searchSchema = z.object({\n  query: z.string().min(1).max(100),\n  page: fallback(z.number().int().positive(), 1),\n  sortBy: z.enum([''name'', ''date'', ''relevance'']).optional(),\n})\n\nexport const Route = createFileRoute(''/search'')({\n  validateSearch: zodValidator(searchSchema),\n  // Type-safe: Route.useSearch() returns typed params\n})\n```\n\n**Why `.catch()` over `.default()`**: Use `.catch()` to silently fix malformed params. Use `.default()` + `errorComponent` to show validation errors.\n\n---\n\n## Error Boundaries\n\nHandle errors at route level with typed error components:\n\n**Route-Level Error Handling**:\n```typescript\nexport const Route = createFileRoute(''/posts/$postId'')({\n  loader: async ({ params }) => {\n    const post = await fetchPost(params.postId)\n    if (!post) throw new Error(''Post not found'')\n    return { post }\n  },\n  errorComponent: ({ error, reset }) => (\n    <div>\n      <p>Error: {error.message}</p>\n      <button onClick={reset}>Retry</button>\n    </div>\n  ),\n})\n```\n\n**Default Error Component** (global fallback):\n```typescript\nconst router = createRouter({\n  routeTree,\n  defaultErrorComponent: ({ error }) => (\n    <div className=\"error-page\">\n      <h1>Something went wrong</h1>\n      <p>{error.message}</p>\n    </div>\n  ),\n})\n```\n\n**Not Found Handling**:\n```typescript\nexport const Route = createFileRoute(''/posts/$postId'')({\n  notFoundComponent: () => <div>Post not found</div>,\n})\n```\n\n---\n\n## Authentication with beforeLoad\n\nProtect routes before they load (no flash of protected content):\n\n**Single Route Protection**:\n```typescript\nimport { redirect } from ''@tanstack/react-router''\n\nexport const Route = createFileRoute(''/dashboard'')({\n  beforeLoad: async ({ context }) => {\n    if (!context.auth.isAuthenticated) {\n      throw redirect({\n        to: ''/login'',\n        search: { redirect: location.pathname }, // Save for post-login\n      })\n    }\n  },\n})\n```\n\n**Protect Multiple Routes** (layout route pattern):\n```typescript\n// routes/(authenticated)/route.tsx - protects all children\nexport const Route = createFileRoute(''/(authenticated)'')({\n  beforeLoad: async ({ context }) => {\n    if (!context.auth.isAuthenticated) {\n      throw redirect({ to: ''/login'' })\n    }\n  },\n})\n```\n\n**Passing Auth Context** (from React hooks):\n```typescript\n// main.tsx - pass auth state to router\nfunction App() {\n  const auth = useAuth() // Your auth hook\n\n  return (\n    <RouterProvider\n      router={router}\n      context={{ auth }} // Available in beforeLoad\n    />\n  )\n}\n```\n\n---\n\n## Known Issues Prevention\n\nThis skill prevents **20** documented issues:\n\n### Issue #1: Devtools Dependency Resolution\n- **Error**: Build fails with `@tanstack/router-devtools-core` not found\n- **Fix**: `npm install @tanstack/router-devtools`\n\n**Issue #2: Vite Plugin Order** (CRITICAL)\n- **Error**: Routes not auto-generated, `routeTree.gen.ts` missing\n- **Fix**: TanStackRouterVite MUST come before react() in plugins array\n- **Why**: Plugin processes route files before React compilation\n\n**Issue #3: Type Registration Missing**\n- **Error**: `<Link to=\"...\">` not typed, no autocomplete\n- **Fix**: Import `routeTree` from `./routeTree.gen` in main.tsx to register types\n\n**Issue #4: Loader Not Running**\n- **Error**: Loader function not called on navigation\n- **Fix**: Ensure route exports `Route` constant: `export const Route = createFileRoute(''/path'')({ loader: ... })`\n\n**Issue #5: Memory Leak with TanStack Form** (FIXED)\n- **Error**: Production crashes when using TanStack Form + Router\n- **Source**: GitHub Issue #5734 (closed Jan 5, 2026)\n- **Resolution**: Fixed in latest versions of @tanstack/form and @tanstack/react-start. Update both packages to resolve.\n\n**Issue #6: Virtual Routes Index/Layout Conflict**\n- **Error**: route.tsx and index.tsx conflict when using `physical()` in virtual routing\n- **Source**: GitHub Issue #5421\n- **Fix**: Use pathless route instead: `_layout.tsx` + `_layout.index.tsx`\n\n**Issue #7: Search Params Type Inference**\n- **Error**: Type inference not working with `zodSearchValidator`\n- **Source**: GitHub Issue #3100 (regression since v1.81.5)\n- **Fix**: Use `zodValidator` from `@tanstack/zod-adapter` instead\n\n**Issue #8: TanStack Start Validators on Reload**\n- **Error**: `validateSearch` not working on page reload in TanStack Start\n- **Source**: GitHub Issue #3711\n- **Note**: Works on client-side navigation, fails on direct page load\n\n### Issue #9: Server Function Validation Errors Lose Structure\n\n**Error**: `inputValidator` Zod errors stringified, losing structure on client\n**Source**: [GitHub Issue #6428](https://github.com/TanStack/router/issues/6428)\n**Why It Happens**: TanStack Start server function error serialization converts Zod issues array to JSON string in `error.message`, making it unusable without manual parsing.\n\n**Prevention**:\n```typescript\n// Server function with input validation\nexport const myFn = createServerFn({ method: ''POST'' })\n  .inputValidator(z.object({\n    name: z.string().min(2),\n    age: z.number().min(18),\n  }))\n  .handler(async ({ data }) => data)\n\n// Client: Workaround to parse stringified issues\ntry {\n  await mutation.mutate({ data: invalidData })\n} catch (error) {\n  if (error.message.startsWith(''['')) {\n    const issues = JSON.parse(error.message)\n    // Now can use structured error data\n    issues.forEach(issue => {\n      console.log(issue.path, issue.message)\n    })\n  }\n}\n```\n\n**Official Status**: Known issue, tracking PR for fix\n\n### Issue #10: useParams({ strict: false }) Returns Unparsed Values\n\n**Error**: Params typed as parsed but returned as strings after navigation\n**Source**: [GitHub Issue #6385](https://github.com/TanStack/router/issues/6385)\n**Why It Happens**: In v1.147.3+, `match.params` is no longer parsed when using `strict: false`. First render works correctly, but after navigation values are stored as strings instead of parsed types.\n\n**Prevention**:\n```typescript\n// Route with param parsing\nexport const Route = createFileRoute(''/posts/$postId'')({\n  params: {\n    parse: (params) => ({\n      postId: z.coerce.number().parse(params.postId),\n    }),\n  },\n})\n\n// Component: Use strict mode (default) for parsed params\nfunction Component() {\n  const { postId } = useParams() // ✓ Parsed as number\n  // const { postId } = useParams({ strict: false }) // ✗ String!\n\n  // Or manually parse when using strict: false\n  const params = useParams({ strict: false })\n  const postId = Number(params.postId)\n}\n```\n\n**Official Status**: Known issue, workaround required\n\n### Issue #11: Pathless Route notFoundComponent Not Rendering\n\n**Error**: `notFoundComponent` on pathless layout routes ignored\n**Source**: [GitHub Issue #6351](https://github.com/TanStack/router/issues/6351), [GitHub Issue #4065](https://github.com/TanStack/router/issues/4065)\n**Why It Happens**: Pathless routes (e.g., `routes/(authenticated)/route.tsx`) don''t render their `notFoundComponent`. Instead, the `defaultNotFoundComponent` from router config is triggered. This has been broken since April 2025.\n\n**Prevention**:\n```typescript\n// ✗ Doesn''t work: notFoundComponent on pathless layout\nexport const Route = createFileRoute(''/(authenticated)'')({\n  beforeLoad: ({ context }) => {\n    if (!context.auth) throw redirect({ to: ''/login'' })\n  },\n  notFoundComponent: () => <div>Protected 404</div>, // Not rendered!\n})\n\n// ✓ Works: Define on child routes instead\nexport const Route = createFileRoute(''/(authenticated)/dashboard'')({\n  notFoundComponent: () => <div>Protected 404</div>,\n})\n```\n\n**Official Status**: Known issue, workaround required\n\n### Issue #12: Aborted Loader Renders errorComponent with Undefined Error\n\n**Error**: Rapid navigation aborts previous loader and renders errorComponent with `undefined` error\n**Source**: [GitHub Issue #6388](https://github.com/TanStack/router/issues/6388)\n**Why It Happens**: Side effect introduced after PR #4570. When user rapidly navigates (e.g., clicking through list items), aborted fetch requests trigger errorComponent without passing the abort error.\n\n**Prevention**:\n```typescript\nexport const Route = createFileRoute(''/posts/$postId'')({\n  loader: async ({ params, abortController }) => {\n    await fetch(`/api/posts/${params.postId}`, {\n      signal: abortController.signal,\n    })\n  },\n  errorComponent: ({ error, reset }) => {\n    // Check for undefined error (aborted request)\n    if (!error) {\n      return null // Or show loading state\n    }\n    return <div>Error: {error.message}</div>\n  },\n})\n```\n\n**Official Status**: Known issue, workaround required\n\n### Issue #13: Vitest Cannot Read Properties of Null (useState)\n\n**Error**: `Cannot read properties of null (reading ''useState'')` when running tests with Vitest\n**Source**: [GitHub Issue #6262](https://github.com/TanStack/router/issues/6262), [PR #6074](https://github.com/TanStack/router/pull/6074)\n**Why It Happens**: TanStack Start''s `tanstackStart()` plugin conflicts with Vitest''s React hooks rendering. This is a known duplicate issue with a PR in progress.\n\n**Prevention**:\n```typescript\n// Temporary workaround: Comment out tanstackStart() for tests\n// vite.config.ts\nexport default defineConfig({\n  plugins: [\n    // tanstackStart(), // Disable for tests\n    react(),\n  ],\n  test: { environment: ''jsdom'' },\n})\n```\n\n**Official Status**: PR #6074 in progress to fix\n\n### Issue #14: Throwing Error in Streaming SSR Loader Crashes Dev Server\n\n**Error**: Dev server crashes when route loader throws error without awaiting (using `void` instead of `await`)\n**Source**: [GitHub Issue #6200](https://github.com/TanStack/router/issues/6200)\n**Why It Happens**: SSR streaming mode can''t handle unawaited promise rejections. The error escapes the loader context and crashes the worker process.\n\n**Prevention**:\n```typescript\n// ✗ Wrong: void + throw crashes dev server\nexport const Route = createFileRoute(''/posts'')({\n  loader: async () => {\n    void fetch(''/api/posts'').then(r => {\n      throw new Error(''boom'') // Crashes!\n    })\n  },\n})\n\n// ✓ Correct: Always await or catch\nexport const Route = createFileRoute(''/posts'')({\n  loader: async () => {\n    try {\n      const data = await fetch(''/api/posts'')\n      return data\n    } catch (error) {\n      throw error // Caught by errorComponent\n    }\n  },\n})\n```\n\n**Official Status**: Known issue, workaround required\n\n### Issue #15: Prerender Hangs Indefinitely if Filter Returns Zero Results\n\n**Error**: Build step hangs when `prerender.filter` returns zero routes\n**Source**: [GitHub Issue #6425](https://github.com/TanStack/router/issues/6425)\n**Why It Happens**: TanStack Start prerendering doesn''t handle empty route sets gracefully - it waits indefinitely for routes that never come.\n\n**Prevention**:\n```typescript\n// ✗ Wrong: Empty filter causes hang\ntanstackStart({\n  prerender: {\n    enabled: true,\n    filter: (route) => false, // No routes → hangs!\n  },\n})\n\n// ✓ Correct: Ensure at least one route or disable\ntanstackStart({\n  prerender: {\n    enabled: true,\n    filter: (route) => route.path === ''/'' || route.path.startsWith(''/posts''),\n  },\n})\n\n// Or temporarily disable\ntanstackStart({\n  prerender: { enabled: false },\n})\n```\n\n**Official Status**: Known issue, workaround required\n\n### Issue #16: Prerendering Does Not Work in Docker\n\n**Error**: Build fails in Docker with \"Unable to connect\" during prerender step\n**Source**: [GitHub Issue #6275](https://github.com/TanStack/router/issues/6275), [PR #6305](https://github.com/TanStack/router/pull/6305)\n**Why It Happens**: Vite preview server used for prerendering is not accessible in Docker environment.\n\n**Prevention**:\n```typescript\n// vite.config.ts - Make preview server accessible in Docker\nexport default defineConfig({\n  preview: {\n    host: true, // Bind to 0.0.0.0 instead of localhost\n  },\n  plugins: [\n    devtools(),\n    // nitro({ preset: \"bun\" }), // Remove temporarily if issues persist\n    tanstackStart(),\n    react(),\n  ],\n})\n```\n\n**Official Status**: PR #6305 in progress\n\n### Issue #17: Route Head Function Executes Before Loader Finishes\n\n**Error**: Meta tags generated with incomplete data when `head()` runs before `loader()`\n**Source**: [GitHub Issue #6221](https://github.com/TanStack/router/issues/6221)\n**Why It Happens**: The `head()` function can execute before the route `loader()` finishes, causing meta tags to use placeholder or undefined data.\n\n**Prevention**:\n```typescript\n// ✗ Wrong: loaderData may not be available yet\nexport const Route = createFileRoute(''/posts/$postId'')({\n  loader: async ({ params }) => {\n    const post = await fetchPost(params.postId)\n    return { post }\n  },\n  head: ({ loaderData }) => ({\n    meta: [\n      { title: loaderData.post.title }, // May be undefined!\n    ],\n  }),\n})\n\n// ✓ Correct: Explicitly await if needed\nexport const Route = createFileRoute(''/posts/$postId'')({\n  loader: async ({ params }) => {\n    const post = await fetchPost(params.postId)\n    return { post }\n  },\n  head: async ({ loaderData }) => {\n    await loaderData // Ensure loaded\n    return {\n      meta: [{ title: loaderData.post.title }],\n    }\n  },\n})\n```\n\n**Official Status**: Known issue, workaround required\n\n### Issue #18: Virtual Routes Don''t Support Manual Lazy Loading (Community-sourced)\n\n**Error**: `createLazyFileRoute` automatically replaced with `createFileRoute` in virtual routes\n**Source**: [GitHub Issue #6396](https://github.com/TanStack/router/issues/6396)\n**Why It Happens**: Virtual file routes are designed for automatic code splitting only. Manual lazy routes are not supported - the plugin silently replaces them.\n\n**Prevention**:\n```typescript\n// Virtual routes: Use automatic code splitting\n// vite.config.ts\ntanstackRouter({\n  target: ''react'',\n  virtualRouteConfig: ''./routes.ts'',\n  autoCodeSplitting: true, // Use automatic splitting\n})\n\n// Don''t use createLazyFileRoute in virtual routes\n// It will be replaced with createFileRoute automatically\n```\n\n**Official Status**: By design (documented behavior)\n\n### Issue #19: NavigateOptions Type Safety Inconsistency (Community-sourced)\n\n**Error**: `NavigateOptions` type doesn''t enforce required params like `useNavigate()` does\n**Source**: [TkDodo''s Blog: The Beauty of TanStack Router](https://tkdodo.eu/blog/the-beauty-of-tan-stack-router)\n**Why It Happens**: Type definitions differ between runtime hook and type helper. `NavigateOptions` is less strict.\n\n**Prevention**:\n```typescript\n// ✗ Wrong: NavigateOptions doesn''t catch missing params\nconst options: NavigateOptions = {\n  to: ''/posts/$postId'', // No TS error, but params required!\n}\n\n// ✓ Correct: Use useNavigate() return type\nconst navigate = useNavigate()\ntype NavigateFn = typeof navigate\n// Now type-safe across all usages\n```\n\n**Verified**: Cross-referenced with TanStack Query maintainer analysis\n\n### Issue #20: Missing Leading Slash in Route Paths (Community-sourced)\n\n**Error**: Routes fail to match when path defined without leading slash\n**Source**: [Official Debugging Guide](https://tanstack.com/router/latest/docs/framework/react/how-to/debug-router-issues)\n**Why It Happens**: Very common beginner mistake - using `''about''` instead of `''/about''` causes route matching failures.\n\n**Prevention**:\n```typescript\n// ✗ Wrong: Missing leading slash\nexport const Route = createFileRoute(''about'')({ /* ... */ })\n\n// ✓ Correct: Always start with /\nexport const Route = createFileRoute(''/about'')({ /* ... */ })\n```\n\n**Verified**: Official documentation, common debugging issue\n\n---\n\n## Cloudflare Workers Integration\n\n**Vite Config** (add @cloudflare/vite-plugin):\n```typescript\nimport { cloudflare } from ''@cloudflare/vite-plugin''\n\nexport default defineConfig({\n  plugins: [TanStackRouterVite(), react(), cloudflare()],\n})\n```\n\n**API Routes Pattern** (fetch from Workers backend):\n```typescript\n// Worker: functions/api/posts.ts\nexport async function onRequestGet({ env }) {\n  const { results } = await env.DB.prepare(''SELECT * FROM posts'').all()\n  return Response.json(results)\n}\n\n// Router: src/routes/posts.tsx\nexport const Route = createFileRoute(''/posts'')({\n  loader: async () => fetch(''/api/posts'').then(r => r.json()),\n})\n```\n\n---\n\n**Related Skills**: tanstack-query (data fetching), react-hook-form-zod (form validation), cloudflare-worker-base (API backend), tailwind-v4-shadcn (UI)\n\n**Related Packages**: @tanstack/zod-adapter (search validation), @tanstack/virtual-file-routes (programmatic routes)\n\n---\n\n**Last verified**: 2026-01-20 | **Skill version**: 2.0.0 | **Changes**: Added 12 new issues from community research (inputValidator structure loss, useParams parsing bug, pathless notFoundComponent, aborted loader errors, Vitest conflicts, SSR streaming crashes, Docker prerender issues, head/loader timing, virtual routes lazy loading limitation, NavigateOptions type inconsistency, leading slash common mistake). Increased error prevention from 8 to 20 documented issues.\n"},"lastSynced":"2026-03-08T02:09:02.456Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Development Agents needing type-safe, file-based routing for React SPAs.","zh":"非常适合需要为 React 单页面应用程序（SPA）提供类型安全、基于文件的路由的前端开发智能体。","ja":"React SPAのための型安全でファイルベースのルーティングを必要とするフロントエンド開発エージェントに最適です。","ko":"React SPA를 위한 타입 안전성, 파일 기반 라우팅이 필요한 프론트엔드 개발 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Desarrollo Frontend que necesiten enrutamiento basado en archivos con seguridad de tipos para React SPAs.","fr":"Parfait pour les Agents de Développement Frontend nécessitant un routage basé sur des fichiers avec typage sécurisé pour les React SPAs.","de":"Perfekt für Frontend Development Agents, die eine typsichere, dateibasierte Routing-Lösung für React SPAs benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Frontend que necessitam de roteamento baseado em arquivos e type-safe para SPAs em React.","ru":"Идеально подходит для Frontend Development Agents, которым требуется типобезопасная маршрутизация на основе файлов для React SPA.","ar":"مثالي لوكلاء تطوير الواجهة الأمامية الذين يحتاجون إلى توجيه يعتمد على الملفات وآمن للنوع لتطبيقات React ذات الصفحة الواحدة (SPAs)."},"recommendation":{"en":"Enables agents to implement TanStack Router with automatic TypeScript integration, route-level data loading, and TanStack Query compatibility. Provides seamless Vite configuration with TanStackRouterVite plugin and optional Zod validation through @tanstack/zod-adapter.","zh":"使智能体能够实现 TanStack Router，并具备自动 TypeScript 集成、路由级数据加载和 TanStack Query 兼容性。通过 TanStackRouterVite 插件提供无缝的 Vite 配置，并通过 @tanstack/zod-adapter 提供可选的 Zod 验证。","ja":"エージェントが自動的な TypeScript 統合、ルートレベルのデータローディング、および TanStack Query 互換性を備えた TanStack Router の実装を可能にします。TanStackRouterVite プラグインによるシームレスな Vite 設定と、@tanstack/zod-adapter を通じたオプションの Zod 検証を提供します。","ko":"에이전트가 자동 TypeScript 통합, 라우트 수준 데이터 로딩 및 TanStack Query 호환성을 갖춘 TanStack Router 구현을 가능하게 합니다. TanStackRouterVite 플러그인을 통한 원활한 Vite 구성과 @tanstack/zod-adapter를 통한 선택적 Zod 유효성 검사를 제공합니다.","es":"Permite a los agentes implementar TanStack Router con integración automática de TypeScript, carga de datos a nivel de ruta y compatibilidad con TanStack Query. Proporciona una configuración perfecta de Vite con el plugin TanStackRouterVite y validación opcional mediante Zod a través de @tanstack/zod-adapter.","fr":"Permet aux agents d''implémenter TanStack Router avec une intégration automatique de TypeScript, un chargement de données au niveau des routes et une compatibilité avec TanStack Query. Offre une configuration transparente de Vite avec le plugin TanStackRouterVite et une validation Zod optionnelle via @tanstack/zod-adapter.","de":"Ermöglicht es Agents, TanStack Router mit automatischer TypeScript-Integration, datenbezogenem Laden auf Routen-Ebene und TanStack Query-Kompatibilität zu implementieren. Bietet eine nahtlose Vite-Konfiguration mit dem TanStackRouterVite-Plugin und optionaler Zod-Validierung über @tanstack/zod-adapter.","pt":"Permite que os agentes implementem o TanStack Router com integração automática do TypeScript, carregamento de dados em nível de rota e compatibilidade com TanStack Query. Fornece configuração perfeita do Vite com o plugin TanStackRouterVite e validação Zod opcional através do @tanstack/zod-adapter.","ru":"Позволяет агентам реализовать TanStack Router с автоматической интеграцией TypeScript, загрузкой данных на уровне маршрута и совместимостью с TanStack Query. Обеспечивает бесшконфигурацию Vite с плагином TanStackRouterVite и дополнительную проверку Zod через @tanstack/zod-adapter.","ar":"يمكن الوكلاء من تنفيذ TanStack Router مع تكامل TypeScript التلقائي، وتحميل البيانات على مستوى المسار، والتوافق مع TanStack Query. يوفر تكوينًا سلسًا لـ Vite مع إضافة TanStackRouterVite والتحقق الاختياري من خلال Zod عبر @tanstack/zod-adapter."},"useCases":{"en":["Implementing file-based routing structures","Configuring TanStackRouterVite build pipelines","Integrating Zod schema validation for routes"],"zh":["实现基于文件的路由结构","配置 TanStackRouterVite 构建流水线","为路由集成 Zod 模式验证"],"ja":["ファイルベースのルーティング構造の実装","TanStackRouterVite ビルドパイプラインの設定","ルートのための Zod スキーマ検証の統合"],"ko":["파일 기반 라우팅 구조 구현","TanStackRouterVite 빌드 파이프라인 구성","라우트를 위한 Zod 스키마 유효성 검사 통합"],"es":["Implementar estructuras de enrutamiento basadas en archivos","Configurar pipelines de compilación de TanStackRouterVite","Integrar validación de esquemas Zod para rutas"],"fr":["Implémenter des structures de routage basées sur des fichiers","Configurer les pipelines de build TanStackRouterVite","Intégrer la validation de schémas Zod pour les routes"],"de":["Implementierung dateibasierter Routing-Strukturen","Konfigurieren von TanStackRouterVite Build-Pipelines","Integration der Zod-Schema-Validierung für Routen"],"pt":["Implementação de estruturas de roteamento baseadas em arquivos","Configuração de pipelines de build do TanStackRouterVite","Integração de validação de esquema Zod para rotas"],"ru":["Реализация структур маршрутизации на основе файлов","Настройка pipelines сборки TanStackRouterVite","Интеграция проверки схемы Zod для маршрутов"],"ar":["تنفيذ هياكل التوجيه المعتمدة على الملفات","تكوين خطوط بناء TanStackRouterVite","دمج التحقق من مخطط Zod للمسارات"]},"limitations":{"en":["Requires React SPA environment","Needs specific Vite configuration order","Depends on @tanstack/router-devtools for full functionality"],"zh":["需要 React SPA 环境","需要特定的 Vite 配置顺序","完整功能依赖于 @tanstack/router-devtools"],"ja":["React SPA 環境が必要","特定の Vite 設定順序が必要","完全な機能は @tanstack/router-devtools に依存"],"ko":["React SPA 환경이 필요함","특정 Vite 구성 순서가 필요함","전체 기능은 @tanstack/router-devtools에 의존"],"es":["Requiere un entorno React SPA","Necesita un orden específico de configuración de Vite","Depende de @tanstack/router-devtools para la funcionalidad completa"],"fr":["Nécessite un environnement React SPA","Requiert un ordre spécifique de configuration Vite","Dépend de @tanstack/router-devtools pour une fonctionnalité complète"],"de":["Erfordert eine React SPA-Umgebung","Benötigt eine spezifische Vite-Konfigurationsreihenfolge","Ist für die volle Funktionalität von @tanstack/router-devtools abhängig"],"pt":["Requer um ambiente React SPA","Necessita de uma ordem específica de configuração do Vite","Depende do @tanstack/router-devtools para funcionalidade completa"],"ru":["Требует среду React SPA","Требует определенного порядка конфигурации Vite","Зависит от @tanstack/router-devtools для полной функциональности"],"ar":["يتطلب بيئة React لتطبيقات الصفحة الواحدة (SPA)","يحتاج إلى ترتيب تكوين محدد لـ Vite","يعتمد على @tanstack/router-devtools للوظائف الكاملة"]},"version":4},"contentHash":"7333cd3e68bb2b50f15c096a87f151b4234ace77ae40bd7782ad4923ced1da1f","qualityScore":45}');
