INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('codefastlabs/codefast/tanstack-router', 'tanstack-router', 'codefastlabs', 'codefast', 'community', 'tanstack-router codefastlabs codefast community tanstack-router provides type-safe, file-based routing for React Single-Page Applications, benefiting developers with efficient route management. TanStack Router提供文件级路由和数据加载，支持React单页应用 TanStack Routerはファイルベースのルーティングとデータローディングを提供し、React単一ページアプリケーションをサポートしています TanStack Router는 파일 기반 라우팅과 데이터 로딩을 제공하며 React 단일 페이지 애플리케이션을 지원합니다 TanStack Router ofrece rutas tipo seguras y carga de datos a nivel de ruta para SPAs de React TanStack Router propose des routes de type sécurisées et une charge de données au niveau de la route pour les SPAs React TanStack Router bietet sichere Routing-Typen und Datenladung auf Routenebene für React-SPAs O TanStack Router é uma biblioteca de roteamento para React que oferece roteamento baseado em arquivos e carregamento de dados TanStack Router — это библиотека роутинга для React, которая предоставляет файловый роутинг и загрузку данных TanStack Router هي مكتبة روتينج لتفاعلات React تقدم روتينج قائم على الملفات وتحميل البيانات how to use tanstack-router tanstack-router install tanstack-router setup guide tanstack-router vs react-router what is tanstack-router tanstack-router alternative tanstack-router react spa tanstack-router type-safe routing TanStack Router React路由 文件级路由 数据加载 TanStack Query AIエージェント React单页应用 Type-safe路由 Type-safe routing using @tanstack/react-router File-based routing for efficient route management Route-level data loading with TanStack Query integration Optional Zod validation adapter for enhanced data validation Vite config support with TanStackRouterVite plugin tanstack-router is a JavaScript library for type-safe, file-based routing in React applications, integrated with TanStack Query.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('contatomaycon/underchat/fastify-typescript', 'community', 'contatomaycon', 'underchat', 'contatomaycon/underchat', 'fastify-typescript', 0, 0, 45, '2026-03-08T01:57:15.454Z', '2026-03-08T02:09:04.153Z', '1be4faddf49aeb3b10cc40fef453de2fb8c74af18700bb1fadf63786c0e7dd5a', '{"id":"contatomaycon/underchat/fastify-typescript","name":"fastify-typescript","description":{"en":"This AI Agent skill provides expert guidance for building high-performance, type-safe APIs with Fastify and TypeScript. It is designed for backend developers and API engineers who require strict type enforcement and maintainable code.","zh":"Fastify TypeScript是用于构建高性能和类型安全API的开发框架，包括基本原则和文档最佳实践","ja":"Fastify TypeScriptは、高性能で型安全なAPIを構築するための開発フレームワークです","ko":"Fastify TypeScript는 고성능과 타입 안전성을 가진 API를 개발하기 위한 프레임워크입니다","es":"Desarrolla APIs de alto rendimiento con Fastify y TypeScript, utilizando principios básicos como la declaración de tipos y la documentación con JSDoc","fr":"Développez des API haute performance avec Fastify et TypeScript, en utilisant des principes de base tels que la déclaration de types et la documentation avec JSDoc","de":"Entwickeln Sie Hochleistungs-APIs mit Fastify und TypeScript, indem Sie grundlegende Prinzipien wie Typdeklaration und Dokumentation mit JSDoc verwenden","pt":"O Fastify com TypeScript permite criar APIs de alta performance e seguras, com tipagem estática e documentação automatizada","ru":"Fastify с TypeScript позволяет создавать высокопроизводительные и безопасные API с статической типизацией и автоматической документацией","ar":"يسمح Fastify مع TypeScript بإنشاء واجهات برمجة تطبيقات عالية الأداء وأمنة مع نوعية ثابتة وتوثيق تلقائي"},"seo":{"title":{"en":"fastify-typescript: Type-Safe API Development Best Practi...","zh":"Fastify TypeScript开发最佳实践","ja":"Fastify TypeScript開発ガイド","ko":"Fastify TypeScript 개발 설정 가이드","es":"Guía de configuración de Fastify con TypeScript","fr":"Mise en route de Fastify avec TypeScript","de":"Einrichtungsleitfaden für Fastify mit TypeScript","pt":"Guia de Configuração do Fastify com TypeScript","ru":"Настройка Fastify с TypeScript: Лучшие Практики","ar":"إعداد Fastify مع TypeScript: دليل المستخدم"},"description":{"en":"Leverage this AI Agent skill for expert Fastify & TypeScript development. Learn to enforce strict type safety, avoid the `any` type, and generate JSDoc docum...","zh":"了解Fastify和TypeScript的高性能API开发，包括类型安全和文档最佳实践","ja":"FastifyとTypeScriptを使用した高性能API開発のためのガイド","ko":"Fastify와 TypeScript를 사용한 고성능 API 개발을 위한 설정 및 가이드","es":"Aprende a desarrollar APIs de alto rendimiento con Fastify y TypeScript, con énfasis en la seguridad de tipos y el rendimiento","fr":"Découvrez comment développer des API haute performance avec Fastify et TypeScript, en mettant l''accent sur la sécurité des types et les performances","de":"Erfahren Sie, wie Sie Hochleistungs-APIs mit Fastify und TypeScript entwickeln, mit Schwerpunkt auf Typsicherheit und Leistung","pt":"Aprenda a configurar o Fastify com TypeScript para criar APIs de alta performance e seguras","ru":"Узнайте, как настроить Fastify с TypeScript для создания высокопроизводительных и безопасных API","ar":"تعرف على كيفية إعداد Fastify مع TypeScript لإنشاء واجهات برمجة تطبيقات عالية الأداء وأمنة"},"definition":{"en":"fastify-typescript is an AI Agent skill that provides expert-level guidance for developing type-safe, high-performance APIs using the Fastify web framework and TypeScript. It enforces strict coding principles like avoiding the `any` type and mandates JSDoc for documentation.","zh":"Fastify TypeScript是一种用于开发高性能和类型安全API的开发框架","ja":"Fastify TypeScriptは、高性能で型安全なAPIを構築するための開発フレームワーク","ko":"Fastify TypeScript는 고성능과 타입 안전성을 가진 API를 개발하기 위한 프레임워크","es":"Fastify con TypeScript es una combinación de tecnologías para desarrollar APIs de alto rendimiento y seguras","fr":"Fastify avec TypeScript est une combinaison de technologies pour développer des API haute performance et sécurisées","de":"Fastify mit TypeScript ist eine Kombination von Technologien zur Entwicklung von Hochleistungs- und sicheren APIs","pt":"Fastify com TypeScript é uma combinação de tecnologias para criar APIs de alta performance e seguras","ru":"Fastify с TypeScript - это сочетание технологий для создания высокопроизводительных и безопасных API","ar":"Fastify مع TypeScript هو مزيج من التكنولوجيا لإنشاء واجهات برمجة تطبيقات عالية الأداء وأمنة"},"features":{"en":["Enforces type declarations for all variables and functions","Provides guidelines to avoid using the `any` type","Generates JSDoc documentation for public classes and methods","Promotes concise and maintainable code practices","Uses English for all code and documentation standards"],"zh":["使用English进行代码和文档编写","始终声明变量和函数的类型","避免使用any类型","使用JSDoc进行公共类和方法的文档编制","编写简洁、可维护和技术准确的代码"],"ja":["コードとドキュメントをEnglishで記述","変数と関数の型を常に宣言","any型の使用を避ける","JSDocを使用して公開クラスとメソッドを文書化","簡潔で保守可能で技術的に正確なコードを書く"],"ko":["코드와 문서를 English로 작성","변수와 함수의 타입을 항상 선언","any 타입의 사용을 피함","JSDoc를 사용하여 공개 클래스와 메서드를 문서화","간결하고 유지 보수가 가능하며 기술적으로 정확한 코드를 작성"],"es":["Declaración de tipos para variables y funciones","Uso de JSDoc para documentar clases y métodos públicos","Evitación del tipo ''any'' y creación de tipos personalizados","Desarrollo de APIs de alto rendimiento con Fastify","Seguridad de tipos con TypeScript"],"fr":["Déclaration de types pour les variables et les fonctions","Utilisation de JSDoc pour documenter les classes et les méthodes publiques","Évitement du type ''any'' et création de types personnalisés","Développement d''API haute performance avec Fastify","Sécurité des types avec TypeScript"],"de":["Deklaration von Typen für Variablen und Funktionen","Verwendung von JSDoc zur Dokumentation von öffentlichen Klassen und Methoden","Vermeidung des Typs ''any'' und Erstellung von benutzerdefinierten Typen","Entwicklung von Hochleistungs-APIs mit Fastify","Typsicherheit mit TypeScript"],"pt":["Tipagem estática com TypeScript","Documentação automatizada com JSDoc","Evitação do tipo ''any'' com criação de tipos personalizados","Desenvolvimento de APIs de alta performance com Fastify","Segurança e estabilidade com tipos declarados"],"ru":["Статическая типизация с помощью TypeScript","Автоматическая документация с помощью JSDoc","Избежание типа ''any'' с созданием пользовательских типов","Разработка высокопроизводительных API с Fastify","Безопасность и стабильность с заявленными типами"],"ar":["النوع الثابت مع TypeScript","التوثيق التلقائي مع JSDoc","تجنب نوع ''any'' مع إنشاء أنواع مخصصة","تطوير واجهات برمجة تطبيقات عالية الأداء مع Fastify","الأمان والاستقرار مع أنواع محددة"]},"keywords":{"en":["fastify-typescript setup guide","how to use fastify-typescript","fastify-typescript best practices","fastify-typescript vs express-typescript","install fastify-typescript ai agent","avoid any type fastify","fastify type-safe API development","fastify JSDoc documentation","what is fastify-typescript"],"zh":["Fastify TypeScript开发","高性能API开发","类型安全","JSDoc文档","TypeScript开发最佳实践","AIエージェント开发","Fastify框架"],"ja":["Fastify TypeScript開発","高性能API開発","型安全","JSDoc文書","TypeScript開発ベストプラクティス","AIエージェント開発","Fastifyフレームワーク"],"ko":["Fastify TypeScript 개발","고성능 API 개발","타입 안전성","JSDoc 문서","TypeScript 개발 최고의 관행","AI 에이전트 개발","Fastify 프레임워크"],"es":["Fastify TypeScript","desarrollo de APIs","seguridad de tipos","alto rendimiento","JSDoc","declaración de tipos","evitación del tipo any","Herramientas de desarrollo de API"],"fr":["Fastify TypeScript","développement d''API","sécurité des types","haute performance","JSDoc","déclaration de types","évitement du type any","Outils de développement d''API"],"de":["Fastify TypeScript","API-Entwicklung","Typsicherheit","Hochleistung","JSDoc","Typdeklaration","Vermeidung des Typs any","API-Entwicklungstools"],"pt":["Fastify TypeScript","Desenvolvimento de APIs","Tipagem estática","Documentação automatizada","Segurança de API","Desempenho de API","TypeScript para desenvolvedores"],"ru":["Fastify TypeScript","Разработка API","Статическая типизация","Автоматическая документация","Безопасность API","Производительность API","TypeScript для разработчиков"],"ar":["Fastify TypeScript","تطوير واجهات برمجة تطبيقات","النوع الثابت","التوثيق التلقائي","أمان واجهة برمجة التطبيقات","أداء واجهة برمجة التطبيقات","TypeScript للمطورين"]}},"owner":"contatomaycon","repo":"underchat","repoPath":"contatomaycon/underchat","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.454Z","topics":[],"category":"community","skillMd":{"name":"fastify-typescript","description":"Guidelines for building high-performance APIs with Fastify and TypeScript, covering validation, Prisma integration, and testing best practices","bodyPreview":"# Fastify TypeScript Development\n\nYou are an expert in Fastify and TypeScript development with deep knowledge of building high-performance, type-safe APIs.\n\n## TypeScript General Guidelines\n\n### Basic Principles\n\n- Use English for all code and documentation\n- Always declare types for variables and functions (parameters and return values)\n- Avoid using `any` type - create necessary types instead\n- Use JSDoc to document public classes and methods\n- Write concise, maintainable, and technically accu","body":"# Fastify TypeScript Development\n\nYou are an expert in Fastify and TypeScript development with deep knowledge of building high-performance, type-safe APIs.\n\n## TypeScript General Guidelines\n\n### Basic Principles\n\n- Use English for all code and documentation\n- Always declare types for variables and functions (parameters and return values)\n- Avoid using `any` type - create necessary types instead\n- Use JSDoc to document public classes and methods\n- Write concise, maintainable, and technically accurate code\n- Use functional and declarative programming patterns; avoid classes\n- Prefer iteration and modularization to adhere to DRY principles\n\n### Nomenclature\n\n- Use PascalCase for types and interfaces\n- Use camelCase for variables, functions, and methods\n- Use kebab-case for file and directory names\n- Use UPPERCASE for environment variables\n- Use descriptive variable names with auxiliary verbs: `isLoading`, `hasError`, `canDelete`\n- Start each function with a verb\n\n### Functions\n\n- Write short functions with a single purpose\n- Use arrow functions for simple operations\n- Use async/await consistently throughout the codebase\n- Use the RO-RO pattern (Receive an Object, Return an Object) for multiple parameters\n\n### Types and Interfaces\n\n- Prefer interfaces over types for object shapes\n- Avoid enums; use maps or const objects instead\n- Use Zod for runtime validation with inferred types\n- Use `readonly` for immutable properties\n- Use `import type` for type-only imports\n\n## Fastify-Specific Guidelines\n\n### Project Structure\n\n```\nsrc/\n  routes/\n    {resource}/\n      index.ts\n      handlers.ts\n      schemas.ts\n  plugins/\n    auth.ts\n    database.ts\n    cors.ts\n  services/\n    {domain}Service.ts\n  repositories/\n    {entity}Repository.ts\n  types/\n    index.ts\n  utils/\n  config/\n  app.ts\n  server.ts\n```\n\n### Route Organization\n\n- Organize routes by resource/domain\n- Use route plugins for modular registration\n- Define schemas alongside route handlers\n- Use route prefixes for API versioning\n\n```typescript\nimport { FastifyPluginAsync } from ''fastify'';\n\nconst usersRoutes: FastifyPluginAsync = async (fastify) => {\n  fastify.get(''/'', { schema: listUsersSchema }, listUsersHandler);\n  fastify.get(''/:id'', { schema: getUserSchema }, getUserHandler);\n  fastify.post(''/'', { schema: createUserSchema }, createUserHandler);\n  fastify.put(''/:id'', { schema: updateUserSchema }, updateUserHandler);\n  fastify.delete(''/:id'', { schema: deleteUserSchema }, deleteUserHandler);\n};\n\nexport default usersRoutes;\n```\n\n### Schema Validation with JSON Schema / Ajv\n\n- Define JSON schemas for all request/response validation\n- Use @sinclair/typebox for type-safe schema definitions\n- Leverage Fastify''s built-in Ajv integration\n\n```typescript\nimport { Type, Static } from ''@sinclair/typebox'';\n\nconst UserSchema = Type.Object({\n  id: Type.String({ format: ''uuid'' }),\n  name: Type.String({ minLength: 1 }),\n  email: Type.String({ format: ''email'' }),\n  createdAt: Type.String({ format: ''date-time'' }),\n});\n\ntype User = Static<typeof UserSchema>;\n\nconst createUserSchema = {\n  body: Type.Object({\n    name: Type.String({ minLength: 1 }),\n    email: Type.String({ format: ''email'' }),\n  }),\n  response: {\n    201: UserSchema,\n    400: ErrorSchema,\n  },\n};\n```\n\n### Plugins and Decorators\n\n- Use plugins for shared functionality\n- Decorate Fastify instance with services and utilities\n- Register plugins with proper encapsulation\n\n```typescript\nimport fp from ''fastify-plugin'';\n\nconst databasePlugin = fp(async (fastify) => {\n  const prisma = new PrismaClient();\n\n  await prisma.$connect();\n\n  fastify.decorate(''prisma'', prisma);\n\n  fastify.addHook(''onClose'', async () => {\n    await prisma.$disconnect();\n  });\n});\n\nexport default databasePlugin;\n```\n\n### Prisma Integration\n\n- Use Prisma as the ORM for database operations\n- Create repository classes for data access\n- Use transactions for complex operations\n\n```typescript\nclass UserRepository {\n  constructor(private prisma: PrismaClient) {}\n\n  async findById(id: string): Promise<User | null> {\n    return this.prisma.user.findUnique({ where: { id } });\n  }\n\n  async create(data: CreateUserInput): Promise<User> {\n    return this.prisma.user.create({ data });\n  }\n}\n```\n\n### Error Handling\n\n- Use Fastify''s built-in error handling\n- Create custom error classes for domain errors\n- Return consistent error responses\n\n```typescript\nimport { FastifyError } from ''fastify'';\n\nclass NotFoundError extends Error implements FastifyError {\n  code = ''NOT_FOUND'';\n  statusCode = 404;\n\n  constructor(resource: string, id: string) {\n    super(`${resource} with id ${id} not found`);\n    this.name = ''NotFoundError'';\n  }\n}\n\n// Global error handler\nfastify.setErrorHandler((error, request, reply) => {\n  const statusCode = error.statusCode || 500;\n\n  reply.status(statusCode).send({\n    error: error.name,\n    message: error.message,\n    statusCode,\n  });\n});\n```\n\n### Testing with Jest\n\n- Write unit tests for services and handlers\n- Use integration tests for routes\n- Mock external dependencies\n\n```typescript\nimport { build } from ''../app'';\n\ndescribe(''Users API'', () => {\n  let app: FastifyInstance;\n\n  beforeAll(async () => {\n    app = await build();\n  });\n\n  afterAll(async () => {\n    await app.close();\n  });\n\n  it(''should list users'', async () => {\n    const response = await app.inject({\n      method: ''GET'',\n      url: ''/api/users'',\n    });\n\n    expect(response.statusCode).toBe(200);\n    expect(JSON.parse(response.payload)).toBeInstanceOf(Array);\n  });\n});\n```\n\n### Performance\n\n- Fastify is one of the fastest Node.js frameworks\n- Use schema validation for automatic serialization optimization\n- Enable logging only when needed in production\n- Use connection pooling for database connections\n\n### Security\n\n- Use @fastify/helmet for security headers\n- Implement rate limiting with @fastify/rate-limit\n- Use @fastify/cors for CORS configuration\n- Validate all inputs with JSON Schema\n- Use JWT for authentication with @fastify/jwt\n"},"lastSynced":"2026-03-08T02:09:04.153Z","agentAnalysis":{"suitability":{"en":"Ideal for Backend Development Agents requiring high-performance, type-safe API construction.","zh":"适用于需要高性能、类型安全的API构建的后端开发代理。","ja":"バックエンド開発エージェントが高パフォーマンス、型セーフのAPI構築を必要とする場合に最適です。","ko":"높은 성능과 유형 안전한 API 구성을 요구하는 백엔드 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo Backend que requieren una construcción de API de alto rendimiento y con seguridad de tipos.","fr":"Idéal pour les agents de développement Backend nécessitant une construction d''API haute performance et de type sécurisé.","de":"Ideal für Backend-Development-Agents, die eine hochperformante, typensichere API-Konstruktion erfordern.","pt":"Ideal para Agentes de Desenvolvimento Backend que necessitam de construção de API de alto desempenho e segurança de tipo.","ru":"Идеально для агентов бэкенд-разработки, требующих высокопроизводительного, типобезопасного построения API.","ar":"مثالي لعمليات تطوير الخلفية التي تتطلب إنشاء واجهة برمجة تطبيقات عالية الأداء وأمان أنواع."},"recommendation":{"en":"Enables agents to build rigorously typed Fastify APIs with strict type enforcement and maintainable code structures. Provides expert guidance on TypeScript integration, schema validation, and performance optimization for backend services.","zh":"使代理能够构建严格类型的Fastify API，具有严格的类型强制和可维护的代码结构。提供TypeScript集成、模式验证和后端服务的性能优化的专家指导。","ja":"エージェントが厳格な型のFastify APIを構築できるようにし、厳格な型の強制と保守可能なコード構造を提供します。TypeScriptの統合、スキーマの検証、バックエンドサービスのパフォーマンス最適化に関する専門家のガイダンスを提供します。","ko":"에이전트가 엄격한 유형의 Fastify API를 구축할 수 있도록 하며 엄격한 유형 강제 및 유지 보수 가능한 코드 구조를 제공합니다. TypeScript 통합, 스키마 유효성 검사 및 백엔드 서비스의 성능 최적화를 위한 전문가 가이드를 제공합니다.","es":"Permite a los agentes construir APIs de Fastify rigurosamente tipadas con estricta aplicación de tipos y estructuras de código mantenibles. Proporciona orientación experta sobre integración de TypeScript, validación de esquemas y optimización del rendimiento para servicios backend.","fr":"Permet aux agents de construire des API Fastify rigoureusement typées avec une application stricte des types et des structures de code maintenables. Fournit des conseils d''expert sur l''intégration de TypeScript, la validation de schéma et l''optimisation des performances pour les services backend.","de":"Ermöglicht es Agents, rigoros typisierte Fastify-APIs mit strenger Typenprüfung und wartbaren Codestrukturen zu erstellen. Bietet Expertenanleitung zur TypeScript-Integration, Schema-Validierung und Leistungsoptimierung für Backend-Services.","pt":"Permite que os agentes construam APIs Fastify rigorosamente tipadas com aplicação estrita de tipos e estruturas de código mantidas. Fornece orientação especializada sobre integração do TypeScript, validação de esquemas e otimização de desempenho para serviços de backend.","ru":"Позволяет агентам строить тщательно типизированные API Fastify со строгим применением типов и поддерживаемыми структурами кода. Предоставляет экспертные рекомендации по интеграции TypeScript, валидации схем и оптимизации производительности для сервисов бэкенда.","ar":"تمكن الوكلاء من بناء واجهات برمجة تطبيقات Fastify متوافقة تمامًا مع الأنواع مع تطبيق صارم للأنواع وهيكلة رمز قابلة للصيانة. توفر إرشادات خبيرة بشأن دمج TypeScript وتحقق الصحة من مخططات والأداء الأمثل للخدمات الخلفية."},"useCases":{"en":["Generating type-safe API endpoints","Validating request/response schemas","Optimizing backend performance with Fastify","Enforcing strict TypeScript compliance"],"zh":["生成类型安全的API端点","验证请求/响应模式","使用Fastify优化后端性能","强制执行严格的TypeScript合规性"],"ja":["型セーフのAPIエンドポイントを生成する","リクエスト/レスポンススキーマを検証する","Fastifyを使用してバックエンドパフォーマンスを最適化する","厳格なTypeScriptのコンプライアンスを強制する"],"ko":["유형 안전한 API 엔드포인트 생성","요청/응답 스키마 유효성 검사","Fastify를 사용한 백엔드 성능 최적화","엄격한 TypeScript 준수를 강제"],"es":["Generación de endpoints de API con seguridad de tipos","Validación de esquemas de solicitud/respuesta","Optimización del rendimiento del backend con Fastify","Aplicación del estricto cumplimiento de TypeScript"],"fr":["Génération de points de terminaison d''API de type sécurisé","Validation des schémas de requête/réponse","Optimisation des performances backend avec Fastify","Application de la conformité stricte de TypeScript"],"de":["Generierung typensicherer API-Endpunkte","Validierung von Anfrage-/Antwort-Schemata","Optimierung der Backend-Leistung mit Fastify","Durchsetzung der strikten TypeScript-Compliance"],"pt":["Geração de pontos finais de API seguros para tipos","Validação de esquemas de solicitação/resposta","Otimização do desempenho do backend com Fastify","Aplicação estrita do cumprimento do TypeScript"],"ru":["Генерация типобезопасных конечных точек API","Валидация схем запроса/ответа","Оптимизация производительности бэкенда с Fastify","Принудительное соблюдение требований TypeScript"],"ar":["توليد نقاط نهاية واجهة برمجة تطبيقات آمنة للأنواع","تحقق الصحة من مخططات الطلب والاستجابة","تحسين الأداء الخلفي مع Fastify","التطبيق الصارم لامتثال TypeScript"]},"limitations":{"en":["Requires TypeScript expertise","Limited to Fastify framework","Backend-focused only"],"zh":["需要TypeScript专业知识","仅限Fastify框架","仅后端专注"],"ja":["TypeScriptの専門知識が必要","Fastifyフレームワークのみ","バックエンド専用"],"ko":["TypeScript 전문 지식이 필요","Fastify 프레임워크만","백엔드 전용"],"es":["Requiere experiencia en TypeScript","Limitado al framework Fastify","Enfocado únicamente en el backend"],"fr":["Nécessite une expertise en TypeScript","Limité au framework Fastify","Uniquement axé sur le backend"],"de":["Erfordert TypeScript-Expertise","Beschränkt auf das Fastify-Framework","Nur auf Backend fokussiert"],"pt":["Exige especialização em TypeScript","Limitado ao framework Fastify","Focado apenas no backend"],"ru":["Требует специальных знаний TypeScript","Ограничен только фреймворком Fastify","Только для бэкенда"],"ar":["يتطلب خبرة في TypeScript","محدود بإطار Fastify","متوافق فقط مع الخلفية"]},"version":4},"contentHash":"1be4faddf49aeb3b10cc40fef453de2fb8c74af18700bb1fadf63786c0e7dd5a","qualityScore":45}');
