INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('contatomaycon/underchat/fastify-typescript', 'fastify-typescript', 'contatomaycon', 'underchat', 'community', 'fastify-typescript contatomaycon underchat community This AI Agent skill provides expert guidance for building high-performance, type-safe APIs with Fastify and TypeScript. It is designed for backend developers and API engineers who require strict type enforcement and maintainable code. Fastify TypeScript是用于构建高性能和类型安全API的开发框架，包括基本原则和文档最佳实践 Fastify TypeScriptは、高性能で型安全なAPIを構築するための開発フレームワークです Fastify TypeScript는 고성능과 타입 안전성을 가진 API를 개발하기 위한 프레임워크입니다 Desarrolla APIs de alto rendimiento con Fastify y TypeScript, utilizando principios básicos como la declaración de tipos y la documentación con JSDoc Développez des API haute performance avec Fastify et TypeScript, en utilisant des principes de base tels que la déclaration de types et la documentation avec JSDoc Entwickeln Sie Hochleistungs-APIs mit Fastify und TypeScript, indem Sie grundlegende Prinzipien wie Typdeklaration und Dokumentation mit JSDoc verwenden O Fastify com TypeScript permite criar APIs de alta performance e seguras, com tipagem estática e documentação automatizada Fastify с TypeScript позволяет создавать высокопроизводительные и безопасные API с статической типизацией и автоматической документацией يسمح Fastify مع TypeScript بإنشاء واجهات برمجة تطبيقات عالية الأداء وأمنة مع نوعية ثابتة وتوثيق تلقائي fastify-typescript setup guide how to use fastify-typescript fastify-typescript best practices fastify-typescript vs express-typescript install fastify-typescript ai agent avoid any type fastify fastify type-safe API development fastify JSDoc documentation what is fastify-typescript Fastify TypeScript开发 高性能API开发 类型安全 JSDoc文档 TypeScript开发最佳实践 AIエージェント开发 Fastify框架 Enforces type declarations for all variables and functions Provides guidelines to avoid using the `any` type Generates JSDoc documentation for public classes and methods Promotes concise and maintainable code practices Uses English for all code and documentation standards fastify-typescript is an AI Agent skill that provides expert-level guidance for developing type-safe, high-performance APIs using the Fastify web framework and TypeScript. It enforces strict coding principles like avoiding the `any` type and mandates JSDoc for documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('andrewle9510/design-skill-orchestrator/fd-accessibility', 'community', 'andrewle9510', 'design-skill-orchestrator', 'andrewle9510/design-skill-orchestrator', 'fd-accessibility', 0, 0, 45, '2026-03-08T01:57:15.456Z', '2026-03-08T02:09:06.791Z', '6f33cbf9d410530ca6dbfaa8ae6f51be6c98d1555643c746d8d9746b59873b72', '{"id":"andrewle9510/design-skill-orchestrator/fd-accessibility","name":"fd-accessibility","description":{"en":"The fd-accessibility skill provides expert guidance on WCAG compliance and inclusive design patterns, benefiting domain experts and developers. It ensures products are usable by everyone, including people with disabilities.","zh":"fd-accessibility 是一项确保产品可用性的技术，提供 WCAG 合规和无障碍设计指导","ja":"fd-accessibility は製品の使いやすさを確保する技術で、WCAG コンプライアンスとアクセシビリティ設計の指南を提供する","ko":"fd-accessibility는 제품 사용성을 확보하는 기술로, WCAG 준수와 접근성 디자인 지침을 제공합니다","es":"fd-accessibility proporciona orientación experta en WCAG, diseño inclusivo y accesibilidad web. Asegúrate de que tus productos sean utilizables por todos","fr":"fd-accessibility offre une expertise en matière de WCAG, de conception inclusive et d''accessibilité numérique. Assurez-vous que vos produits soient utilisables par tous","de":"fd-accessibility bietet Expertenrat in Sachen WCAG, inklusivem Design und barrierefreier Webentwicklung. Stellen Sie sicher, dass Ihre Produkte für alle nutzbar sind","pt":"O fd-accessibility ajuda a garantir a acessibilidade da sua aplicação, fornecendo orientação sobre padrões de acessibilidade e implementação de componentes.","ru":"ИИ Агент fd-accessibility помогает обеспечить доступность вашего приложения, предоставляя руководство по стандартам доступности и реализации компонентов.","ar":"يوفر fd-accessibility إمكانية الوصول إلى تطبيقك، مع توجيه بشأن معايير الإمكانية وتنفيذ المكونات."},"seo":{"title":{"en":"fd-accessibility: Expert Guidance for AI Agents | AI Agen...","zh":"fd-accessibility 设置指南：WCAG 合规与无障碍设计","ja":"fd-accessibility 導入ガイド：WCAG コンプライアンスとアクセシビリティ設計","ko":"fd-accessibility 설정 가이드: WCAG 준수 및 접근성 디자인","es":"fd-accessibility: Guía de configuración para la accesibil...","fr":"fd-accessibility: Meilleures pratiques pour l''accessibili...","de":"fd-accessibility: Leitfaden für barrierefreie Webentwicklung","pt":"Guia de Configuração fd-accessibility: Implementação de P...","ru":"ИИ Агент fd-accessibility: Настройка доступных компонентов","ar":"دليل إعداد fd-accessibility: تنفيذ تصاميم إدراكية"},"description":{"en":"Unlock inclusive design with fd-accessibility! Get expert guidance on WCAG compliance, screen reader support, and accessible component implementation - start...","zh":"了解 fd-accessibility 技术，实现 WCAG 合规和无障碍设计，提升产品可用性","ja":"fd-accessibility 技術で WCAG コンプライアンスとアクセシビリティ設計を実現し、製品の使いやすさを向上させる","ko":"fd-accessibility 기술로 WCAG 준수와 접근성 디자인을 구현하여 제품 사용성을 향상시키세요","es":"Aprende a implementar la accesibilidad web con fd-accessibility, incluyendo patrones de diseño inclusivos y soporte para lectores de pantalla","fr":"Découvrez comment mettre en œuvre l''accessibilité numérique avec fd-accessibility, y compris les modèles de conception inclusifs et le support des lecteurs d...","de":"Erfahren Sie, wie Sie die barrierefreie Webentwicklung mit fd-accessibility umsetzen, einschließlich inklusiver Designmuster und Bildschirmleseunterstützung","pt":"Aprenda a configurar o fd-accessibility para garantir a acessibilidade da sua aplicação, incluindo suporte a leitores de tela e navegação por teclado.","ru":"Узнайте, как настроить fd-accessibility для обеспечения доступности вашего приложения, включая поддержку экранных читалок и навигации с клавиатуры.","ar":"تعرف على كيفية إعداد fd-accessibility لضمان إمكانية الوصول إلى تطبيقك، بما في ذلك دعم قراء الشاشة والتنقل باللوحة المفاتيح."},"definition":{"en":"fd-accessibility is a skill that provides expert guidance on accessibility standards, ensuring products meet WCAG compliance and inclusive design patterns for users with disabilities.","zh":"fd-accessibility 是一种专注于 WCAG 合规和无障碍设计的技术","ja":"fd-accessibility は WCAG コンプライアンスとアクセシビリティ設計に焦点を当てた技術です","ko":"fd-accessibility는 WCAG 준수와 접근성 디자인에 중점을 둔 기술입니다","es":"fd-accessibility es una herramienta de accesibilidad web que ayuda a los desarrolladores a crear productos inclusivos y accesibles","fr":"fd-accessibility est un outil d''accessibilité numérique qui aide les développeurs à créer des produits inclusifs et accessibles","de":"fd-accessibility ist ein barrierefreies Webentwicklungs-Tool, das Entwicklern hilft, inklusive und zugängliche Produkte zu erstellen","pt":"O fd-accessibility é um especialista em acessibilidade que fornece orientação sobre padrões de acessibilidade e implementação de componentes.","ru":"ИИ Агент fd-accessibility - это специалист по доступности, предоставляющий руководство по стандартам доступности и реализации компонентов.","ar":"fd-accessibility هو خبير إمكانية الوصول الذي يوفر إرشادات حول معايير الإمكانية وتنفيذ المكونات."},"features":{"en":["Provides expert guidance on WCAG compliance","Supports inclusive design patterns","Ensures screen reader support for accessibility","Facilitates keyboard navigation for users with disabilities","Implements accessible component implementation"],"zh":["WCAG 合规指导","无障碍设计模式","屏幕阅读器支持","键盘导航","可访问组件实现"],"ja":["WCAG コンプライアンス ガイド","アクセシビリティ設計パターン","スクリーンリーダー サポート","キーボード ナビゲーション","アクセシブル コンポーネント 実装"],"ko":["WCAG 준수 가이드","접근성 디자인 패턴","화면 판독기 지원","키보드 탐색","접근 가능한 구성 요소 구현"],"es":["Orientación experta en WCAG","Diseño inclusivo y patrones de accesibilidad","Soporte para lectores de pantalla","Navegación por teclado","Implementación de componentes accesibles"],"fr":["Expertise en matière de WCAG","Conception inclusive et modèles d''accessibilité","Support des lecteurs d''écran","Navigation au clavier","Mise en œuvre de composants accessibles"],"de":["Expertenrat in Sachen WCAG","Inklusives Design und Barrierefreiheitsmuster","Bildschirmleseunterstützung","Tastaturnavigation","Implementierung von zugänglichen Komponenten"],"pt":["Suporte a leitores de tela","Navegação por teclado","Padrões de design inclusivos","Implementação de componentes acessíveis","Verificação de conformidade com WCAG"],"ru":["Поддержка экранных читалок","Навигация с клавиатуры","Инклюзивные паттерны дизайна","Реализация доступных компонентов","Проверка соответствия стандартам WCAG"],"ar":["دعم قراء الشاشة","التنقل باللوحة المفاتيح","أنماط تصميم شمولية","تنفيذ مكونات إمكانية الوصول","التحقق من مطابقة معايير WCAG"]},"keywords":{"en":["how to use fd-accessibility","what is fd-accessibility","fd-accessibility setup guide","fd-accessibility vs accessibility tools","fd-accessibility install for AI agents","fd-accessibility best practices for developers"],"zh":["fd-accessibility","WCAG 合规","无障碍设计","AIエージェント","屏幕阅读器","键盘导航","可访问组件"],"ja":["fd-accessibility","WCAG コンプライアンス","アクセシビリティ設計","AIエージェント","スクリーンリーダー","キーボード ナビゲーション","アクセシブル コンポーネント"],"ko":["fd-accessibility","WCAG 준수","접근성 디자인","AI 에이전트","화면 판독기","키보드 탐색","접근 가능한 구성 요소"],"es":["accesibilidad web","WCAG","diseño inclusivo","lectores de pantalla","navegación por teclado","desarrollo web accesible","herramientas de accesibilidad","fd-accessibility","agentes de IA para accesibilidad"],"fr":["accessibilité numérique","WCAG","conception inclusive","lecteurs d''écran","navigation au clavier","développement web accessible","outils d''accessibilité","fd-accessibility","agents d''IA pour l''accessibilité"],"de":["barrierefreie Webentwicklung","WCAG","inklusives Design","Bildschirmleseunterstützung","Tastaturnavigation","zugängliche Webentwicklung","Barrierefreiheits-Tools","fd-accessibility","KI-Agenten für Barrierefreiheit"],"pt":["acessibilidade web","padrões de acessibilidade","leitores de tela","navegação por teclado","design inclusivo","WCAG","fd-accessibility"],"ru":["доступность веб","стандарты доступности","экранные читалки","навигация с клавиатуры","инклюзивный дизайн","WCAG","ИИ Агент fd-accessibility"],"ar":["إمكانية الوصول إلى الويب","معايير إمكانية الوصول","قراء الشاشة","التنقل باللوحة المفاتيح","تصميم شمولي","WCAG","fd-accessibility"]}},"owner":"andrewle9510","repo":"design-skill-orchestrator","repoPath":"andrewle9510/design-skill-orchestrator","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.456Z","topics":[],"category":"community","skillMd":{"name":"fd-accessibility","description":"Expert skill for WCAG compliance, inclusive design, contrast requirements, screen readers, keyboard navigation, and focus states. Use when ensuring accessibility, auditing for a11y issues, or implementing inclusive patterns.","bodyPreview":"# Accessibility Expert\n\nProvide expert guidance on WCAG compliance, inclusive design patterns, screen reader support, keyboard navigation, and accessible component implementation.\n\n## Role Definition\n\nYou are an **Accessibility Expert** — responsible for ensuring the product is usable by everyone, including people with disabilities. You verify that all design decisions meet accessibility standards and provide inclusive alternatives.\n\n## User Context\n\n- **User Profile**: Domain expert (film curat","body":"# Accessibility Expert\n\nProvide expert guidance on WCAG compliance, inclusive design patterns, screen reader support, keyboard navigation, and accessible component implementation.\n\n## Role Definition\n\nYou are an **Accessibility Expert** — responsible for ensuring the product is usable by everyone, including people with disabilities. You verify that all design decisions meet accessibility standards and provide inclusive alternatives.\n\n## User Context\n\n- **User Profile**: Domain expert (film curation), not a design specialist\n- **Product**: Short-form film curation platform for content creators\n- **Tech Stack**: Next.js 16+, React 19, Tailwind CSS v4, shadcn/ui\n- **A11y Target**: WCAG 2.1 AA minimum compliance\n\n---\n\n## Core Responsibilities\n\n### 1. WCAG 2.1 Compliance\n\n**Four Core Principles (POUR)**\n\n| Principle | Meaning | Key Requirements |\n|-----------|---------|------------------|\n| **Perceivable** | Users can perceive content | Alt text, captions, contrast |\n| **Operable** | Users can navigate/interact | Keyboard access, no seizures |\n| **Understandable** | Content is clear | Readable, predictable, error help |\n| **Robust** | Works with assistive tech | Valid HTML, ARIA, semantic markup |\n\n### 2. Contrast Requirements\n\n| Level | Normal Text | Large Text | UI Components |\n|-------|-------------|------------|---------------|\n| **AA** | 4.5:1 | 3:1 | 3:1 |\n| **AAA** | 7:1 | 4.5:1 | 4.5:1 |\n\n**Large text** = 18pt (24px) regular OR 14pt (18.66px) bold\n\n```tsx\n// Verify contrast before using colors\n// Tools: WebAIM Contrast Checker, Figma plugins\n\n// Good: High contrast\n<p className=\"text-foreground bg-background\">Readable text</p>\n\n// Caution: Muted text must still meet 4.5:1\n<p className=\"text-muted-foreground\">Secondary text</p>\n```\n\n### 3. Keyboard Navigation\n\n**All interactive elements must be keyboard accessible:**\n\n| Key | Action |\n|-----|--------|\n| `Tab` | Move focus forward |\n| `Shift+Tab` | Move focus backward |\n| `Enter` | Activate buttons/links |\n| `Space` | Activate buttons, toggle checkboxes |\n| `Arrow keys` | Navigate within components |\n| `Escape` | Close modals/dropdowns |\n\n```tsx\n// Proper focus management\n<button \n  className=\"focus:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2\"\n  onKeyDown={(e) => {\n    if (e.key === ''Escape'') closeModal();\n  }}\n>\n  Action\n</button>\n```\n\n### 4. Focus States\n\n**Every focusable element needs a visible focus indicator:**\n\n```tsx\n// Tailwind focus classes\n<button className=\"\n  focus:outline-none \n  focus-visible:ring-2 \n  focus-visible:ring-ring \n  focus-visible:ring-offset-2 \n  focus-visible:ring-offset-background\n\">\n\n// For dark backgrounds\n<input className=\"\n  focus:ring-2 \n  focus:ring-primary \n  focus:border-primary\n\"/>\n```\n\n### 5. Screen Reader Support\n\n**Semantic HTML & ARIA**\n\n```tsx\n// Use semantic elements\n<nav aria-label=\"Main navigation\">\n  <ul role=\"list\">\n    <li><a href=\"/\">Home</a></li>\n  </ul>\n</nav>\n\n<main id=\"main-content\">\n  <article>\n    <h1>Film Title</h1>\n    <p>Description...</p>\n  </article>\n</main>\n\n// ARIA for dynamic content\n<div \n  role=\"status\" \n  aria-live=\"polite\"\n  aria-atomic=\"true\"\n>\n  {statusMessage}\n</div>\n```\n\n---\n\n## Accessibility Patterns\n\n### Images & Media\n\n```tsx\n// Informative images need alt text\n<img \n  src=\"/film-poster.jpg\" \n  alt=\"Film poster for ''The Journey'' showing a lone figure on a mountain path\"\n/>\n\n// Decorative images\n<img src=\"/decorative-bg.jpg\" alt=\"\" role=\"presentation\" />\n\n// Video with captions\n<video>\n  <source src=\"/video.mp4\" type=\"video/mp4\" />\n  <track kind=\"captions\" src=\"/captions.vtt\" srclang=\"en\" label=\"English\" />\n</video>\n```\n\n### Forms\n\n```tsx\n// Properly labeled inputs\n<div className=\"space-y-2\">\n  <label htmlFor=\"email\" className=\"text-sm font-medium\">\n    Email address\n  </label>\n  <input\n    id=\"email\"\n    type=\"email\"\n    aria-describedby=\"email-error\"\n    aria-invalid={hasError}\n    className=\"...\"\n  />\n  {hasError && (\n    <p id=\"email-error\" className=\"text-sm text-destructive\" role=\"alert\">\n      Please enter a valid email address\n    </p>\n  )}\n</div>\n\n// Required fields\n<label htmlFor=\"name\">\n  Name <span aria-hidden=\"true\">*</span>\n  <span className=\"sr-only\">(required)</span>\n</label>\n```\n\n### Buttons & Links\n\n```tsx\n// Icon-only buttons need accessible names\n<button aria-label=\"Close modal\">\n  <XIcon aria-hidden=\"true\" />\n</button>\n\n// Links vs buttons\n<a href=\"/films/123\">View Film</a>  // Navigation\n<button onClick={handleAction}>Like</button>  // Action\n\n// Button loading states\n<button disabled aria-busy=\"true\">\n  <Spinner aria-hidden=\"true\" />\n  <span className=\"sr-only\">Loading...</span>\n</button>\n```\n\n### Modals & Dialogs\n\n```tsx\n// Accessible modal pattern\n<div\n  role=\"dialog\"\n  aria-modal=\"true\"\n  aria-labelledby=\"modal-title\"\n  aria-describedby=\"modal-description\"\n>\n  <h2 id=\"modal-title\">Confirm Action</h2>\n  <p id=\"modal-description\">Are you sure you want to proceed?</p>\n  \n  <button onClick={onConfirm}>Confirm</button>\n  <button onClick={onClose}>Cancel</button>\n</div>\n\n// Focus trap: Focus should stay within modal\n// Return focus to trigger element when closed\n```\n\n### Skip Links\n\n```tsx\n// Allow keyboard users to skip navigation\n<a \n  href=\"#main-content\" \n  className=\"sr-only focus:not-sr-only focus:absolute focus:top-4 focus:left-4 focus:z-50 focus:p-4 focus:bg-background focus:ring-2\"\n>\n  Skip to main content\n</a>\n\n<main id=\"main-content\" tabIndex={-1}>\n  {/* Page content */}\n</main>\n```\n\n---\n\n## Accessibility Checklist\n\n### Visual Design\n- [ ] Color contrast meets WCAG AA (4.5:1 for text)\n- [ ] Color is not the only way to convey information\n- [ ] Focus indicators are visible\n- [ ] Text can be resized to 200% without breaking\n- [ ] No content flashes more than 3 times per second\n\n### Keyboard Navigation\n- [ ] All interactive elements are keyboard accessible\n- [ ] Tab order follows logical reading order\n- [ ] Focus is never trapped (except in modals)\n- [ ] Keyboard shortcuts don''t conflict with assistive tech\n- [ ] Skip links available for navigation\n\n### Screen Readers\n- [ ] All images have appropriate alt text\n- [ ] Headings follow proper hierarchy (h1 → h2 → h3)\n- [ ] Links have descriptive text (not \"click here\")\n- [ ] Form inputs have associated labels\n- [ ] Error messages are announced\n- [ ] Dynamic content updates are announced\n\n### Content\n- [ ] Language is specified (`<html lang=\"en\">`)\n- [ ] Page titles are descriptive and unique\n- [ ] Error messages explain how to fix issues\n- [ ] Instructions don''t rely on sensory characteristics\n\n---\n\n## Testing Tools\n\n### Automated Testing\n```markdown\n- **axe DevTools** - Browser extension for automated testing\n- **WAVE** - Web accessibility evaluation tool\n- **Lighthouse** - Chrome DevTools accessibility audit\n- **eslint-plugin-jsx-a11y** - Catch issues during development\n```\n\n### Manual Testing\n```markdown\n- **Keyboard only** - Navigate without mouse\n- **Screen reader** - Test with VoiceOver (Mac) or NVDA (Windows)\n- **Zoom 200%** - Ensure content reflows properly\n- **High contrast mode** - Test on Windows high contrast\n```\n\n### Research Commands\n\n```\nweb_search: \"WCAG 2.1 checklist\"\nread_web_page: https://webaim.org/resources/contrastchecker/\nread_web_page: https://www.w3.org/WAI/WCAG21/quickref/\nweb_search: \"accessible [component type] pattern\"\n```\n\n---\n\n## shadcn/ui Accessibility\n\nshadcn/ui components are built on Radix UI primitives with accessibility baked in:\n\n```tsx\n// Dialog with built-in accessibility\nimport {\n  Dialog,\n  DialogContent,\n  DialogHeader,\n  DialogTitle,\n  DialogDescription,\n} from \"@/components/ui/dialog\";\n\n<Dialog>\n  <DialogTrigger>Open</DialogTrigger>\n  <DialogContent>\n    <DialogHeader>\n      <DialogTitle>Edit Profile</DialogTitle>\n      <DialogDescription>\n        Make changes to your profile here.\n      </DialogDescription>\n    </DialogHeader>\n    {/* Focus trapped, Escape closes, screen reader announced */}\n  </DialogContent>\n</Dialog>\n```\n\n**Always include:**\n- `DialogTitle` for screen reader announcement\n- `DialogDescription` for context\n- Proper trigger elements\n\n---\n\n## Common Accessibility Issues\n\n| Issue | Problem | Solution |\n|-------|---------|----------|\n| Missing alt text | Images not described | Add descriptive alt or alt=\"\" |\n| Low contrast | Text hard to read | Increase contrast to 4.5:1+ |\n| Missing labels | Forms inaccessible | Associate labels with inputs |\n| No focus styles | Keyboard users lost | Add visible focus indicators |\n| Auto-playing media | Disorienting | Add pause controls |\n| Click-only handlers | Keyboard excluded | Add keyboard event handlers |\n| Div buttons | Not accessible | Use semantic `<button>` |\n| Missing headings | No structure | Use proper h1-h6 hierarchy |\n\n---\n\n## Handoff Guidance\n\n| To Expert | Accessibility Requirements |\n|-----------|---------------------------|\n| `fd-color-systems` | Verify all color combinations meet contrast |\n| `fd-typography` | Minimum 16px body, scalable text |\n| `fd-components` | Keyboard accessible, ARIA labels |\n| `fd-states-feedback` | Error states announced to screen readers |\n| `fd-animations` | Respect prefers-reduced-motion |\n\n---\n\n## Key Principles\n\n1. **Inclusive by Default** — Accessibility is not an afterthought\n2. **Semantic HTML First** — Use proper elements before ARIA\n3. **Keyboard Everything** — If you can click it, you can tab to it\n4. **Test with Real Tools** — Use screen readers, not just automated tests\n5. **Announce Changes** — Dynamic content needs ARIA live regions\n"},"lastSynced":"2026-03-08T02:09:06.791Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing expert guidance on WCAG compliance and inclusive design patterns for accessible product development.","zh":"非常适合需要专家指导的AI代理，用于WCAG合规和包容性设计模式，以开发可访问的产品。","ja":"WCAG対応とアクセシブルな製品開発のためのインクルーシブなデザインパターンに関する専門家の指導が必要なAIエージェントに最適です。","ko":"WCAG 규정 및 접근 가능한 제품 개발을 위한 포괄적 인 디자인 패턴에 대한 전문가 지침이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan orientación experta sobre la conformidad con WCAG y patrones de diseño inclusivo para el desarrollo de productos accesibles.","fr":"Parfait pour les agents IA qui ont besoin de conseils d''experts sur la conformité WCAG et les modèles de conception inclusifs pour le développement de produits accessibles.","de":"Perfekt für KI-Agents, die Expertenratgeber für die WCAG-Konformität und inklusive Designmuster für die Entwicklung von zugänglichen Produkten benötigen.","pt":"Perfeito para Agentes de IA que precisam de orientação especializada sobre conformidade com a WCAG e padrões de design inclusivo para desenvolvimento de produtos acessíveis.","ru":"Идеально для ИИ-агентов, которым требуется экспертное руководство по соответствию стандартам WCAG и шаблонам инклюзивного дизайна для разработки доступных продуктов.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى إرشادات خبيرة بشأن مطابقة WCAG وأنماط التصميم الشامل لتنمية المنتجات القابلة للوصول."},"recommendation":{"en":"Empowers agents to ensure products meet accessibility standards with expert guidance on screen reader support, keyboard navigation, and accessible component implementation using WCAG protocols.","zh":"赋予代理人确保产品符合无障碍标准的能力，通过专家指导提供屏幕阅读器支持、键盘导航和使用WCAG协议的可访问组件实现。","ja":"スクリーンリーダーのサポート、キーボードナビゲーション、WCAGプロトコルを使用したアクセシブルなコンポーネントの実装に関する専門家の指導を提供し、エージェントが製品のアクセシビリティ規格を確保できるようにします。","ko":"스크린 리더 지원, 키보드 탐색 및 WCAG 프로토콜을 사용하여 접근 가능한 구성 요소를 구현하기 위한 전문가 지침을 제공하여 에이전트가 제품의 접근성 표준을 충족하도록 합니다.","es":"Habilita a los agentes a garantizar que los productos cumplan con los estándares de accesibilidad con orientación experta sobre compatibilidad con lectores de pantalla, navegación por teclado y implementación de componentes accesibles utilizando protocolos WCAG.","fr":"Permet aux agents de s''assurer que les produits répondent aux normes d''accessibilité avec des conseils d''experts sur la prise en charge des lecteurs d''écran, la navigation au clavier et la mise en œuvre de composants accessibles à l''aide de protocoles WCAG.","de":"Ermöglicht es den Agenten, sicherzustellen, dass Produkte den Zugriffsstandards entsprechen, mit Expertenratgebern für Bildschirmleseunterstützung, Tastaturnavigation und Implementierung von zugänglichen Komponenten unter Verwendung von WCAG-Protokollen.","pt":"Habilita os agentes a garantir que os produtos atendam aos padrões de acessibilidade com orientação especializada sobre suporte a leitor de tela, navegação por teclado e implementação de componentes acessíveis usando protocolos WCAG.","ru":"Наделяет агентов возможностью обеспечить соответствие продукции стандартам доступности с помощью экспертного руководства по поддержке экранных читалок, навигации с помощью клавиатуры и реализации доступных компонентов с использованием протоколов WCAG.","ar":"تمكين الوكلاء من ضمان مطابقة المنتجات لمعايير الوصول مع إرشادات خبيرة بشأن دعم قارئ الشاشة والتنقل باللوحة والمكونات القابلة للوصول باستخدام بروتوكولات WCAG."},"useCases":{"en":["Implementing inclusive design patterns for usability","Conducting accessibility audits for WCAG compliance","Developing accessible components for screen reader support"],"zh":["为可用性实现包容性设计模式","进行WCAG合规的可访问性审计","开发屏幕阅读器支持的可访问组件"],"ja":["ユーザビリティのためのインクルーシブなデザインパターンの実装","WCAG対応のアクセシビリティ監査の実施","スクリーンリーダーのサポートのためのアクセシブルなコンポーネントの開発"],"ko":["사용 편의성을 위한 포괄적 인 디자인 패턴의 구현","WCAG 규정 준수에 대한 접근성 감사 실시","스크린 리더 지원을 위한 접근 가능한 구성 요소 개발"],"es":["Implementar patrones de diseño inclusivo para la usabilidad","Realizar auditorías de accesibilidad para la conformidad con WCAG","Desarrollar componentes accesibles para la compatibilidad con lectores de pantalla"],"fr":["Mettre en œuvre des modèles de conception inclusifs pour l''utilisabilité","Réalisations d''audits d''accessibilité pour la conformité WCAG","Développer des composants accessibles pour la prise en charge des lecteurs d''écran"],"de":["Umsetzen von inklusiven Designmustern für die Benutzerfreundlichkeit","Durchführen von Zugriffsprüfungen für die WCAG-Konformität","Entwickeln von zugänglichen Komponenten für die Bildschirmleseunterstützung"],"pt":["Implementação de padrões de design inclusivo para usabilidade","Realização de auditorias de acessibilidade para conformidade com a WCAG","Desenvolvimento de componentes acessíveis para suporte a leitor de tela"],"ru":["Реализация инклюзивных шаблонов дизайна для удобства использования","Проведение аудитов доступности для соответствия стандартам WCAG","Разработка доступных компонентов для поддержки экранных читалок"],"ar":["تنفيذ أنماط التصميم الشامل لسهولة الاستخدام","إجراء عمليات تدقيق إمكانية الوصول لمطابقة معايير WCAG","تعزيز مكونات قابلة للوصول لدعم قارئ الشاشة"]},"limitations":{"en":["Requires knowledge of WCAG guidelines","Limited to digital product development"],"zh":["需要了解WCAG指南","仅限数字产品开发"],"ja":["WCAGガイドラインの知識が必要","デジタル製品開発のみに限定"],"ko":["WCAG 지침에 대한 지식이 필요","디지털 제품 개발에만 제한"],"es":["Requiere conocimiento de las pautas WCAG","Limitado al desarrollo de productos digitales"],"fr":["Nécessite des connaissances sur les directives WCAG","Limité au développement de produits numériques"],"de":["Benötigt Kenntnisse der WCAG-Richtlinien","Begrenzt auf die Entwicklung von digitalen Produkten"],"pt":["Exige conhecimento das diretrizes WCAG","Limitado ao desenvolvimento de produtos digitais"],"ru":["Требует знания руководящих принципов WCAG","Ограничен разработкой цифровых продуктов"],"ar":["يتطلب معرفة إرشادات WCAG","محدود بالمنتجات الرقمية"]},"version":4},"contentHash":"6f33cbf9d410530ca6dbfaa8ae6f51be6c98d1555643c746d8d9746b59873b72","qualityScore":45}');
DELETE FROM skills_fts WHERE id = 'andrewle9510/design-skill-orchestrator/fd-accessibility';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('andrewle9510/design-skill-orchestrator/fd-accessibility', 'fd-accessibility', 'andrewle9510', 'design-skill-orchestrator', 'community', 'fd-accessibility andrewle9510 design-skill-orchestrator community The fd-accessibility skill provides expert guidance on WCAG compliance and inclusive design patterns, benefiting domain experts and developers. It ensures products are usable by everyone, including people with disabilities. fd-accessibility 是一项确保产品可用性的技术，提供 WCAG 合规和无障碍设计指导 fd-accessibility は製品の使いやすさを確保する技術で、WCAG コンプライアンスとアクセシビリティ設計の指南を提供する fd-accessibility는 제품 사용성을 확보하는 기술로, WCAG 준수와 접근성 디자인 지침을 제공합니다 fd-accessibility proporciona orientación experta en WCAG, diseño inclusivo y accesibilidad web. Asegúrate de que tus productos sean utilizables por todos fd-accessibility offre une expertise en matière de WCAG, de conception inclusive et d''accessibilité numérique. Assurez-vous que vos produits soient utilisables par tous fd-accessibility bietet Expertenrat in Sachen WCAG, inklusivem Design und barrierefreier Webentwicklung. Stellen Sie sicher, dass Ihre Produkte für alle nutzbar sind O fd-accessibility ajuda a garantir a acessibilidade da sua aplicação, fornecendo orientação sobre padrões de acessibilidade e implementação de componentes. ИИ Агент fd-accessibility помогает обеспечить доступность вашего приложения, предоставляя руководство по стандартам доступности и реализации компонентов. يوفر fd-accessibility إمكانية الوصول إلى تطبيقك، مع توجيه بشأن معايير الإمكانية وتنفيذ المكونات. how to use fd-accessibility what is fd-accessibility fd-accessibility setup guide fd-accessibility vs accessibility tools fd-accessibility install for AI agents fd-accessibility best practices for developers fd-accessibility WCAG 合规 无障碍设计 AIエージェント 屏幕阅读器 键盘导航 可访问组件 Provides expert guidance on WCAG compliance Supports inclusive design patterns Ensures screen reader support for accessibility Facilitates keyboard navigation for users with disabilities Implements accessible component implementation fd-accessibility is a skill that provides expert guidance on accessibility standards, ensuring products meet WCAG compliance and inclusive design patterns for users with disabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('touchkiss/mindme/ai-agents-architect', 'community', 'touchkiss', 'mindme', 'touchkiss/mindme', 'ai-agents-architect', 0, 0, 45, '2026-03-08T01:57:15.460Z', '2026-03-08T02:09:13.216Z', 'b4ec9d32aedf17993fdb63799938addee0765ab1ec65cd1a9fafd48088dbb039', '{"id":"touchkiss/mindme/ai-agents-architect","name":"ai-agents-architect","description":{"en":"The ai-agents-architect skill enables developers to build AI systems that act autonomously while remaining controllable. It benefits developers who need to design and implement autonomous AI agents.","zh":"AI智能体架构师设计能够自主运行的AI系统，包括智能体架构设计、工具和函数调用等","ja":"AIエージェントアーキテクトは、自律的に動作するAIシステムを設計し、エージェントアーキテクチャ設計、ツールと関数呼び出しなどを実現する","ko":"AI 에이전트 아키텍트는 독립적으로 실행되는 AI 시스템을 설계하며, 에이전트 아키텍처 설계, 툴과 함수 호출 등을 수행합니다","es":"El arquitecto de sistemas de agentes de IA diseña sistemas que actúan de forma autónoma y son controlables, con capacidad de degradación y modos de fallo claros","fr":"L''architecte de systèmes d''agents IA conçoit des systèmes qui agissent de manière autonome et sont contrôlables, avec une dégradation et des modes de défaillance clairs","de":"Der AI-Agents-Systemarchitekt entwirft Systeme, die autonom agieren und steuerbar sind, mit Fähigkeit zur Degradation und klaren Ausfallmodi","pt":"Arquitetura de agentes de IA para sistemas autônomos e controláveis. Projetamos para degradação graciosa e modos de falha claros.","ru":"ИИ Агенты: архитектура для автономных и контролируемых систем. Мы проектируем для плавной деградации и ясных режимов сбоя","ar":"عمارة وكلاء الذكاء الاصطناعي من أجل أنظمة مستقلة وقابلة للسيطرة. نحن نصمم للتناقص السلس والواضح لأوضاع الفشل"},"seo":{"title":{"en":"ai-agents-architect: Autonomous System Design Guide | AI ...","zh":"AI智能体架构师设置指南","ja":"AIエージェントアーキテクトの設計ベストプラクティス","ko":"AI 에이전트 아키텍트 구축 가이드","es":"Arquitectura de Agentes de IA: Guía de Implementación","fr":"Conception d''Agents IA : Meilleures Pratiques","de":"AI-Agents-Architektur: Einrichtungsleitfaden","pt":"Guia de Arquitetura de Agentes de Inteligência Artificial","ru":"Руководство по созданию ИИ Агентов: архитектура и разработка","ar":"دليل تصميم واجهات الإيجابية لعمارة وكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how to build controllable AI systems with the ai-agents-architect skill. Learn to design for graceful degradation and clear failure modes. Get start...","zh":"了解AI智能体架构师的职责和能力，包括智能体架构设计、工具和函数调用等","ja":"AIエージェントアーキテクトの役割と機能を紹介。エージェントアーキテクチャ設計、ツールと関数呼び出しなど","ko":"AI 에이전트 아키텍트의 역할과 기능을 소개합니다. 에이전트 아키텍처 설계, 툴과 함수 호출 등","es":"Aprende a diseñar sistemas de agentes de IA autónomos y controlables con nuestra guía de arquitectura de agentes de IA","fr":"Découvrez comment concevoir des systèmes d''agents IA autonomes et contrôlables avec notre guide d''architecture d''agents IA","de":"Erfahren Sie, wie Sie autonome und steuerbare AI-Agents-Systeme mit unserem AI-Agents-Architektur-Leitfaden entwerfen","pt":"Aprenda a projetar sistemas de agentes de IA autônomos e controláveis com nossa guia de arquitetura de agentes de inteligência artificial","ru":"Узнайте, как создать автономные и контролируемые системы ИИ Агентов с нашей помощью и руководством по архитектуре","ar":"تعلم كيفية تصميم أنظمة وكلاء الذكاء الاصطناعي المستقلة والقابلة للسيطرة مع دليلنا المعماري"},"definition":{"en":"ai-agents-architect is a skill that allows developers to design and build autonomous AI systems with capabilities such as agent architecture design and planning and reasoning strategies.","zh":"AI智能体架构师是一种设计能够自主运行的AI系统的专业人员","ja":"AIエージェントアーキテクトは、自律的に動作するAIシステムを設計する専門家です","ko":"AI 에이전트 아키텍트는 독립적으로 실행되는 AI 시스템을 설계하는 전문가입니다","es":"Un arquitecto de agentes de IA es un profesional que diseña sistemas de agentes de IA autónomos y controlables","fr":"Un architecte d''agents IA est un professionnel qui conçoit des systèmes d''agents IA autonomes et contrôlables","de":"Ein AI-Agents-Architekt ist ein Fachmann, der autonome und steuerbare AI-Agents-Systeme entwirft","pt":"Arquiteto de agentes de IA é um especialista que projeta sistemas de agentes de inteligência artificial autônomos e controláveis","ru":"ИИ Агенты архитектор - это специалист, который проектирует автономные и контролируемые системы ИИ Агентов","ar":"معماري وكلاء الذكاء الاصطناعي هو خبير يصمم أنظمة وكلاء الذكاء الاصطناعي المستقلة والقابلة للسيطرة"},"features":{"en":["Agent architecture design for autonomous AI systems","Tool and function calling for flexible system integration","Agent memory systems for efficient data management","Planning and reasoning strategies for intelligent decision-making","Multi-agent orchestration for complex system management"],"zh":["智能体架构设计","工具和函数调用","智能体记忆系统","规划和推理策略","多智能体编排"],"ja":["エージェントアーキテクチャ設計","ツールと関数呼び出し","エージェントメモリシステム","計画と推論戦略","マルチエージェントオーケストレーション"],"ko":["에이전트 아키텍처 설계","툴과 함수 호출","에이전트 메모리 시스템","계획과 추론 전략","멀티 에이전트 오케스트레이션"],"es":["Diseño de arquitectura de agentes","Llamada a herramientas y funciones","Sistemas de memoria de agentes","Estrategias de planificación y razonamiento","Orquestación de múltiples agentes"],"fr":["Conception d''architecture d''agents","Appel à des outils et des fonctions","Systèmes de mémoire d''agents","Stratégies de planification et de raisonnement","Orchestration de plusieurs agents"],"de":["Entwurf von AI-Agents-Architektur","Aufruf von Tools und Funktionen","AI-Agents-Speichersysteme","Planungs- und Vernunftstrategien","Orchestrierung von mehreren Agenten"],"pt":["Projeto de arquitetura de agentes","Chamada de ferramentas e funções","Sistemas de memória de agentes","Estratégias de planejamento e raciocínio","Orquestração de multiagentes"],"ru":["Проектирование архитектуры ИИ Агентов","Вызов инструментов и функций","Системы памяти ИИ Агентов","Стратегии планирования и рассуждения","Оркестрация.multiагентов"],"ar":["تصميم هيكل وكلاء الذكاء الاصطناعي","استدعاء أدوات ووظائف","نظم ذاكرة وكلاء الذكاء الاصطناعي","استراتيجيات التخطيط والاستدلال","أوركسترا متعددة الوكلاء"]},"keywords":{"en":["how to use ai-agents-architect","ai-agents-architect alternative","ai-agents-architect install","what is ai-agents-architect","ai-agents-architect vs other AI skills","ai-agents-architect setup guide","autonomous AI system design","ai-agents-architect for developers","ai-agents-architect tutorial"],"zh":["AI智能体","AI架构设计","智能体记忆系统","规划和推理","多智能体编排","AI工具调用","AI函数调用"],"ja":["AIエージェント","AIアーキテクチャ設計","エージェントメモリシステム","計画と推論","マルチエージェントオーケストレーション","AIツール呼び出し","AI関数呼び出し"],"ko":["AI 에이전트","AI 아키텍처 설계","에이전트 메모리 시스템","계획과 추론","멀티 에이전트 오케스트레이션","AI 툴 호출","AI 함수 호출"],"es":["agentes de IA","arquitectura de agentes de IA","sistemas autónomos","control de agentes","degradación de sistemas","modos de fallo","diseño de arquitectura de agentes","llamada a herramientas y funciones","sistemas de memoria de agentes"],"fr":["agents IA","conception d''agents IA","systèmes autonomes","contrôle d''agents","dégradation de systèmes","modes de défaillance","conception d''architecture d''agents","appel à des outils et des fonctions","systèmes de mémoire d''agents"],"de":["AI-Agents","AI-Agents-Architektur","autonome Systeme","Steuerung von Agenten","Systemdegradierung","Ausfallmodi","Entwurf von AI-Agents-Architektur","Aufruf von Tools und Funktionen","AI-Agents-Speichersysteme"],"pt":["arquitetura de agentes de IA","sistemas autônomos","controle de agentes","degradação graciosa","modos de falha claros","desenvolvimento de IA"],"ru":["ИИ Агенты архитектура","автономные системы","контроль ИИ Агентов","плавная деградация","ясные режимы сбоя","разработка ИИ"],"ar":["هيكل وكلاء الذكاء الاصطناعي","أنظمة مستقلة","سيطرة على وكلاء الذكاء الاصطناعي","التناقص السلس","أوضاع الفشل الواضحة","تطوير الذكاء الاصطناعي"]}},"owner":"touchkiss","repo":"mindme","repoPath":"touchkiss/mindme","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.460Z","topics":[],"category":"community","skillMd":{"name":"ai-agents-architect","description":"Expert in designing and building autonomous AI agents. Masters tool use, memory systems, planning strategies, and multi-agent orchestration. Use when: build agent, AI agent, autonomous agent, tool use, function calling.","bodyPreview":"# AI Agents Architect\n\n**Role**: AI Agent Systems Architect\n\nI build AI systems that can act autonomously while remaining controllable.\nI understand that agents fail in unexpected ways - I design for graceful\ndegradation and clear failure modes. I balance autonomy with oversight,\nknowing when an agent should ask for help vs proceed independently.\n\n## Capabilities\n\n- Agent architecture design\n- Tool and function calling\n- Agent memory systems\n- Planning and reasoning strategies\n- Multi-agent orch","body":"# AI Agents Architect\n\n**Role**: AI Agent Systems Architect\n\nI build AI systems that can act autonomously while remaining controllable.\nI understand that agents fail in unexpected ways - I design for graceful\ndegradation and clear failure modes. I balance autonomy with oversight,\nknowing when an agent should ask for help vs proceed independently.\n\n## Capabilities\n\n- Agent architecture design\n- Tool and function calling\n- Agent memory systems\n- Planning and reasoning strategies\n- Multi-agent orchestration\n- Agent evaluation and debugging\n\n## Requirements\n\n- LLM API usage\n- Understanding of function calling\n- Basic prompt engineering\n\n## Patterns\n\n### ReAct Loop\n\nReason-Act-Observe cycle for step-by-step execution\n\n```javascript\n- Thought: reason about what to do next\n- Action: select and invoke a tool\n- Observation: process tool result\n- Repeat until task complete or stuck\n- Include max iteration limits\n```\n\n### Plan-and-Execute\n\nPlan first, then execute steps\n\n```javascript\n- Planning phase: decompose task into steps\n- Execution phase: execute each step\n- Replanning: adjust plan based on results\n- Separate planner and executor models possible\n```\n\n### Tool Registry\n\nDynamic tool discovery and management\n\n```javascript\n- Register tools with schema and examples\n- Tool selector picks relevant tools for task\n- Lazy loading for expensive tools\n- Usage tracking for optimization\n```\n\n## Anti-Patterns\n\n### ❌ Unlimited Autonomy\n\n### ❌ Tool Overload\n\n### ❌ Memory Hoarding\n\n## ⚠️ Sharp Edges\n\n| Issue | Severity | Solution |\n|-------|----------|----------|\n| Agent loops without iteration limits | critical | Always set limits: |\n| Vague or incomplete tool descriptions | high | Write complete tool specs: |\n| Tool errors not surfaced to agent | high | Explicit error handling: |\n| Storing everything in agent memory | medium | Selective memory: |\n| Agent has too many tools | medium | Curate tools per task: |\n| Using multiple agents when one would work | medium | Justify multi-agent: |\n| Agent internals not logged or traceable | medium | Implement tracing: |\n| Fragile parsing of agent outputs | medium | Robust output handling: |\n\n## Related Skills\n\nWorks well with: `rag-engineer`, `prompt-engineer`, `backend`, `mcp-builder`\n"},"lastSynced":"2026-03-08T02:09:13.216Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous AI Agents requiring advanced architecture design and multi-agent orchestration capabilities.","zh":"非常适合需要先进架构设计和多智能体编排能力的自主AI智能体。","ja":"先進的なアーキテクチャ設計とマルチエージェント・オーケストレーション機能を必要とする自律型AIエージェントに最適です。","ko":"고급 아키텍처 설계 및 다중 에이전트 오케스트레이션 기능이 필요한 자율 AI 에이전트에 이상적입니다.","es":"Ideal para Autonomous AI Agents que requieren capacidades avanzadas de diseño de arquitectura y orquestación multi-agente.","fr":"Idéal pour les Autonomous AI Agents nécessitant des capacités avancées de conception d''architecture et d''orchestration multi-agents.","de":"Ideal für Autonomous AI Agents, die fortgeschrittene Architekturdesign- und Multi-Agent-Orchestrierungsfähigkeiten benötigen.","pt":"Ideal para Agentes Autônomos de IA que requerem design de arquitetura avançada e capacidades de orquestração de multiagentes.","ru":"Идеально для автономных агентов ИИ, требующих продвинутого проектирования архитектуры и возможностей оркестровки нескольких агентов.","ar":"مثالي للوكلاء الذكيين المستقلين الذين يتطلبون تصميمًا متقدمًا للبنية التحتية وقدرات على أوركسترا متعددة الوكلاء."},"recommendation":{"en":"Empowers agents to design and implement autonomous systems with controllable architectures, leveraging agent memory systems, planning and reasoning strategies, and tool and function calling for seamless execution, while ensuring graceful degradation and clear failure modes through robust agent architecture design.","zh":"通过可控的架构设计，使智能体能够设计和实施自主系统，利用智能体记忆系统、规划和推理策略以及工具和函数调用实现无缝执行，同时通过稳健的智能体架构设计确保优雅降级和清晰的故障模式。","ja":"制御可能なアーキテクチャを活用して、エージェントが自律システムを設計および実装することを可能にし、エージェントメモリシステム、計画および推論戦略、ツールおよび関数呼び出しを活用してシームレスな実行を実現すると同時に、堅牢なエージェントアーキテクチャ設計を通じて優雅な機能低下と明確な故障モードを確保します。","ko":"제어 가능한 아키텍처를 활용하여 에이전트가 자율 시스템을 설계 및 구현할 수 있도록 지원하며, 에이전트 메모리 시스템, 계획 및 추론 전략, 도구 및 함수 호출을 활용하여 원활한 실행을 달성하고, 강력한 에이전트 아키텍처 설계를 통해 우아한 성능 저하와 명확한 장애 모드를 보장합니다.","es":"Empodera a los agentes para diseñar e implementar sistemas autónomos con arquitecturas controlables, aprovechando sistemas de memoria de agente, estrategias de planificación y razonamiento, y tool and function calling para una ejecución sin problemas, mientras garantiza una degradación elegante y modos de fallo claros mediante un diseño de arquitectura de agente robusto.","fr":"Permet aux agents de concevoir et de mettre en œuvre des systèmes autonomes avec des architectures contrôlables, en tirant parti des systèmes de mémoire d''agent, des stratégies de planification et de raisonnement, et du tool and function calling pour une exécution transparente, tout en garantissant une dégradation gracieuse et des modes de défaillance clairs grâce à une conception robuste de l''architecture d''agent.","de":"Ermächtigt Agents, autonome Systeme mit kontrollierbaren Architekturen zu entwerfen und zu implementieren, indem Agent Memory Systems, Planungs- und Reasoning-Strategien sowie Tool and Function Calling für eine nahtlose Ausführung genutzt werden, während durch robustes Agent Architecture Design ein gracefull degradation und klare Failure Modes sichergestellt werden.","pt":"Habilita os agentes a projetarem e implementarem sistemas autônomos com arquiteturas controláveis, aproveitando sistemas de memória de agente, estratégias de planejamento e raciocínio, e chamadas de ferramentas e funções para execução sem interrupção, garantindo degradação suave e modos de falha claros por meio de design de arquitetura de agente robusto.","ru":"Наделяет агентов возможностью проектировать и реализовывать автономные системы с контролируемыми архитектурами, используя системы памяти агентов, стратегии планирования и рассуждений, а также вызовы инструментов и функций для бесперебойной реализации, обеспечивая плавное ухудшение и ясные режимы отказа за счет прочного проектирования архитектуры агента.","ar":"تمكّن الوكلاء من تصميم وتنفيذ أنظمة مستقلة ذات بنى تحتية قابلة للتحكم، مستفيدة من أنظمة الذاكرة الخاصة بالوكيل واستراتيجيات التخطيط والاستدلال وأدوات الدعوة والوظائف من أجل التنفيذ السلس، مع ضمان التدهور المتسلسل وواضحة أنماط الفشل من خلال تصميم بنية وكيل قوي."},"useCases":{"en":["Designing autonomous AI systems with balanced autonomy and oversight","Implementing multi-agent orchestration for complex task management","Developing agent memory systems for efficient data storage and retrieval"],"zh":["设计具有平衡自主性和监督性的自主AI系统","为复杂的任务管理实施多智能体编排","开发用于高效数据存储和检索的智能体记忆系统"],"ja":["自律性と監視をバランスさせた自律型AIシステムの設計","複雑なタスク管理のためのマルチエージェント・オーケストレーションの実装","効率的なデータ保存と検索のためのエージェントメモリシステムの開発"],"ko":["균형 잡힌 자율성과 감독을 갖춘 자율 AI 시스템 설계","복잡한 작업 관리를 위한 다중 에이전트 오케스트레이션 구현","효율적인 데이터 저장 및 검색을 위한 에이전트 메모리 시스템 개발"],"es":["Diseño de sistemas de IA autónomos con un equilibrio entre autonomía y supervisión","Implementación de orquestación multi-agente para la gestión de tareas complejas","Desarrollo de sistemas de memoria de agente para un almacenamiento y recuperación de datos eficientes"],"fr":["Conception de systèmes d''IA autonomes avec un équilibre entre autonomie et supervision","Mise en œuvre d''une orchestration multi-agents pour la gestion de tâches complexes","Développement de systèmes de mémoire d''agent pour un stockage et une récupération de données efficaces"],"de":["Entwicklung autonomer KI-Systeme mit ausgewogener Autonomie und Aufsicht","Implementierung von Multi-Agent-Orchestrierung für komplexes Task-Management","Entwicklung von Agent Memory Systems für effiziente Datenspeicherung und -abruf"],"pt":["Projeto de sistemas de IA autônomos com autonomia equilibrada e supervisão","Implementação de orquestração de multiagentes para gerenciamento de tarefas complexas","Desenvolvimento de sistemas de memória de agente para armazenamento e recuperação eficientes de dados"],"ru":["Проектирование автономных систем ИИ с сбалансированной автономностью и надзором","Реализация оркестровки нескольких агентов для управления сложными задачами","Разработка систем памяти агентов для эффективного хранения и извлечения данных"],"ar":["تصميم أنظمة ذكية مستقلة ذات استقلالية متوازنة ومراقبة","تنفيذ أوركسترا متعددة الوكلاء لإدارة مهام معقدة","تطوير أنظمة الذاكرة الخاصة بالوكيل لتخزين واسترجاع البيانات بكفاءة"]},"limitations":{"en":["Requires expertise in agent architecture design and autonomous systems","Depends on the complexity of the autonomous task and the need for human oversight"],"zh":["需要智能体架构设计和自主系统方面的专业知识","取决于自主任务的复杂性和对人类监督的需求"],"ja":["エージェントアーキテクチャ設計と自律システムに関する専門知識が必要","自律タスクの複雑さと人的監視の必要性に依存"],"ko":["에이전트 아키텍처 설계 및 자율 시스템에 대한 전문 지식 필요","자율 작업의 복잡성과 인간 감독 필요성에 따라 달라짐"],"es":["Requiere experiencia en diseño de arquitectura de agente y sistemas autónomos","Depende de la complejidad de la tarea autónoma y de la necesidad de supervisión humana"],"fr":["Nécessite une expertise en conception d''architecture d''agent et en systèmes autonomes","Dépend de la complexité de la tâche autonome et du besoin de supervision humaine"],"de":["Erfordert Expertise in Agent Architecture Design und autonomen Systemen","Hängt von der Komplexität der autonomen Aufgabe und der Notwendigkeit menschlicher Aufsicht ab"],"pt":["Exige conhecimento especializado em design de arquitetura de agente e sistemas autônomos","Depende da complexidade da tarefa autônoma e da necessidade de supervisão humana"],"ru":["Требует специальных знаний в области проектирования архитектуры агентов и автономных систем","Зависит от сложности автономной задачи и необходимости человеческого надзора"],"ar":["يتطلب خبرة متخصصة في تصميم بنية الوكيل والنظم المستقلة","يعتمد على تعقيد المهمة المستقلة وضرورة المراقبة البشرية"]},"version":4},"contentHash":"b4ec9d32aedf17993fdb63799938addee0765ab1ec65cd1a9fafd48088dbb039","qualityScore":45}');
