INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('touchkiss/mindme/ai-agents-architect', 'ai-agents-architect', 'touchkiss', 'mindme', 'community', 'ai-agents-architect touchkiss mindme community The ai-agents-architect skill enables developers to build AI systems that act autonomously while remaining controllable. It benefits developers who need to design and implement autonomous AI agents. AI智能体架构师设计能够自主运行的AI系统，包括智能体架构设计、工具和函数调用等 AIエージェントアーキテクトは、自律的に動作するAIシステムを設計し、エージェントアーキテクチャ設計、ツールと関数呼び出しなどを実現する AI 에이전트 아키텍트는 독립적으로 실행되는 AI 시스템을 설계하며, 에이전트 아키텍처 설계, 툴과 함수 호출 등을 수행합니다 El arquitecto de sistemas de agentes de IA diseña sistemas que actúan de forma autónoma y son controlables, con capacidad de degradación y modos de fallo claros L''architecte de systèmes d''agents IA conçoit des systèmes qui agissent de manière autonome et sont contrôlables, avec une dégradation et des modes de défaillance clairs Der AI-Agents-Systemarchitekt entwirft Systeme, die autonom agieren und steuerbar sind, mit Fähigkeit zur Degradation und klaren Ausfallmodi Arquitetura de agentes de IA para sistemas autônomos e controláveis. Projetamos para degradação graciosa e modos de falha claros. ИИ Агенты: архитектура для автономных и контролируемых систем. Мы проектируем для плавной деградации и ясных режимов сбоя عمارة وكلاء الذكاء الاصطناعي من أجل أنظمة مستقلة وقابلة للسيطرة. نحن نصمم للتناقص السلس والواضح لأوضاع الفشل how to use ai-agents-architect ai-agents-architect alternative ai-agents-architect install what is ai-agents-architect ai-agents-architect vs other AI skills ai-agents-architect setup guide autonomous AI system design ai-agents-architect for developers ai-agents-architect tutorial AI智能体 AI架构设计 智能体记忆系统 规划和推理 多智能体编排 AI工具调用 AI函数调用 Agent architecture design for autonomous AI systems Tool and function calling for flexible system integration Agent memory systems for efficient data management Planning and reasoning strategies for intelligent decision-making Multi-agent orchestration for complex system management ai-agents-architect is a skill that allows developers to design and build autonomous AI systems with capabilities such as agent architecture design and planning and reasoning strategies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('karstenheld3/OpenAI-BackendTools/windsurf-auto-model-switcher', 'community', 'karstenheld3', 'OpenAI-BackendTools', 'karstenheld3/OpenAI-BackendTools', 'windsurf-auto-model-switcher', 0, 0, 45, '2026-03-08T01:57:15.466Z', '2026-03-08T02:09:25.945Z', '3c7826ba875c581cca6263aa60aaee57a3cd1cf2f159020f7d8fabd6cbee05af', '{"id":"karstenheld3/OpenAI-BackendTools/windsurf-auto-model-switcher","name":"windsurf-auto-model-switcher","description":{"en":"The windsurf-auto-model-switcher skill enables developers to automate model switching for OpenAI backends, streamlining AI workflow operations. It benefits AI agents and developers working with OpenAI and AzureOpenAI.","zh":"Windsurf Auto Model Switcher是一套工具集合，用于测试、操作和维护OpenAI后端，包括OpenAI和AzureOpenAI","ja":"Windsurf Auto Model Switcherは、OpenAIのバックエンドをテスト、操作、およびメンテナンスするためのツールのコレクションです","ko":"Windsurf Auto Model Switcher는 오픈AI 백엔드를 테스트, 운영 및 유지 관리하는 데 사용되는 도구 모음입니다","es":"Windsurf-auto-model-switcher es una colección de herramientas para probar, operar y mantener backends de OpenAI, con capacidad de conmutación de modelos de AI de manera programática","fr":"Windsurf-auto-model-switcher est un ensemble d''outils pour tester, exploiter et maintenir les backends OpenAI, avec la possibilité de commutation de modèles d''IA de manière programmée","de":"Windsurf-auto-model-switcher ist eine Sammlung von Tools zum Testen, Betreiben und Warten von OpenAI-Backends, mit der Möglichkeit, KI-Modelle programmgesteuert umzuschalten","pt":"O Windsurf Auto Model Switcher é uma coleção de ferramentas para testar, operar e manter backends de IA da OpenAI e AzureOpenAI","ru":"Windsurf Auto Model Switcher - это коллекция инструментов для тестирования, эксплуатации и обслуживания бэкендов ИИ от OpenAI и AzureOpenAI","ar":"Windsurf Auto Model Switcher هو مجموعة من الأدوات لاختبار وتشغيل وضمان استمرار خلفيات الذكاء الاصطناعي من OpenAI و AzureOpenAI"},"seo":{"title":{"en":"windsurf-auto-model-switcher: Automated Model Switching f...","zh":"Windsurf Auto Model Switcher 设置指南 - 开源AI工具","ja":"Windsurf Auto Model Switcher のベストプラクティス - AIエージェント","ko":"Windsurf Auto Model Switcher 설치 가이드 - 인공지능 도구","es":"Configuración de windsurf-auto-model-switcher: Guía de co...","fr":"Configurer windsurf-auto-model-switcher: Guide de commuta...","de":"Einrichtung von windsurf-auto-model-switcher: Anleitung z...","pt":"Guia de Configuração do Windsurf Auto Model Switcher para...","ru":"Настройка Windsurf Auto Model Switcher для ИИ Агентов","ar":"دليل إعداد Windsurf Auto Model Switcher لأدوات الذكاء الا..."},"description":{"en":"Discover how to streamline your AI workflow with windsurf-auto-model-switcher. Learn to automate model switching and optimize your OpenAI backend operations ...","zh":"了解如何使用Windsurf Auto Model Switcher自动切换OpenAI后端模型，提高开发效率","ja":"Windsurf Auto Model Switcherを使用してOpenAIのバックエンドモデルを自動的に切り替える方法を学びましょう","ko":"Windsurf Auto Model Switcher로 오픈AI 백엔드 모델을 자동으로 전환하여 개발 효율성을 높이세요","es":"Descubre cómo configurar windsurf-auto-model-switcher para conmutar modelos de AI de manera programática con simulación de teclado","fr":"Découvrez comment configurer windsurf-auto-model-switcher pour commuter des modèles d''IA de manière programmée avec simulation de clavier","de":"Erfahren Sie, wie Sie windsurf-auto-model-switcher einrichten, um KI-Modelle programmgesteuert mit Tastensimulierung umzuschalten","pt":"Aprenda a configurar o Windsurf Auto Model Switcher para testar e operar backends de IA da OpenAI e AzureOpenAI","ru":"Узнайте, как настроить Windsurf Auto Model Switcher для тестирования и эксплуатации бэкендов ИИ от OpenAI и AzureOpenAI","ar":"تعرف على كيفية إعداد Windsurf Auto Model Switcher لاختبار وتشغيل خلفيات الذكاء الاصطناعي من OpenAI و AzureOpenAI"},"definition":{"en":"windsurf-auto-model-switcher is a collection of tools for testing, operating, and maintaining OpenAI backends, allowing for programmable model switching using keyboard simulation.","zh":"Windsurf Auto Model Switcher是一种自动切换OpenAI后端模型的工具","ja":"Windsurf Auto Model Switcherは、OpenAIのバックエンドモデルを自動的に切り替えるツールです","ko":"Windsurf Auto Model Switcher는 오픈AI 백엔드 모델을 자동으로 전환하는 도구입니다","es":"Windsurf-auto-model-switcher es una herramienta de conmutación de modelos de AI que permite cambiar entre modelos de manera programática","fr":"Windsurf-auto-model-switcher est un outil de commutation de modèles d''IA qui permet de changer entre les modèles de manière programmée","de":"Windsurf-auto-model-switcher ist ein Tool zur Umstellung von KI-Modellen, das das programmgesteuerte Umschalten zwischen Modellen ermöglicht","pt":"O Windsurf Auto Model Switcher é uma ferramenta de IA que permite a troca automática de modelos de IA","ru":"Windsurf Auto Model Switcher - это инструмент ИИ, позволяющий автоматически переключать модели ИИ","ar":"Windsurf Auto Model Switcher هو أداة ذكاء اصطناعي تمكن من تبديل النماذج الذكية تلقائيًا"},"features":{"en":["Switches Windsurf Cascade AI models programmatically using keyboard simulation","Requires custom keybindings for operation, as outlined in SETUP.md","Supports model hints in STRUT Strategy sections for optimized model selection","Ensures safety with screenshot verification for auto-switching","Compatible with German keyboards using F-keys instead of Ctrl+Alt due to AltGr conflict"],"zh":["支持OpenAI和AzureOpenAI后端","自动切换模型使用键盘模拟","需要自定义键绑定","支持STRUT策略","需要Windsurf窗口焦点","支持安全检查（截图验证）"],"ja":["OpenAIとAzureOpenAIのバックエンドをサポート","キーボードシミュレーションを使用した自動モデル切り替え","カスタムキーバインドが必要","STRUT戦略をサポート","Windsurfウィンドウの焦点が必要","安全性チェック（スクリーンショット検証）をサポート"],"ko":["오픈AI와 Azure 오픈AI 백엔드를 지원","키보드 시뮬레이션을 사용한 자동 모델 전환","사용자 정의 키 바인딩이 필요","STRUT 전략을 지원","윈드서프 창焦点이 필요","안전성 체크（스크린샷 검증）을 지원"],"es":["Conmutación de modelos de AI de manera programática","Simulación de teclado para cambiar entre modelos","Requiere enlaces de teclado personalizados","Compatible con teclados alemanes con teclas F","Requiere verificación de seguridad para la conmutación automática"],"fr":["Commutation de modèles d''IA de manière programmée","Simulation de clavier pour changer entre les modèles","Nécessite des raccourcis clavier personnalisés","Compatible avec les claviers allemands avec les touches F","Nécessite une vérification de sécurité pour la commutation automatique"],"de":["Umstellung von KI-Modellen in programmgesteuerter Weise","Tastensimulierung zum Umschalten zwischen Modellen","Benötigt benutzerdefinierte Tastenkombinationen","Kompatibel mit deutschen Tastaturen mit F-Tasten","Benötigt Sicherheitsüberprüfung für automatisches Umschalten"],"pt":["Troca automática de modelos de IA usando simulação de teclado","Requer configurações de atalhos personalizados","Suporta teclados alemães com uso de teclas F","Verificação de segurança por meio de verificação de tela"],"ru":["Автоматическое переключение моделей ИИ с помощью симуляции клавиатуры","Требует настройки пользовательских комбинаций клавиш","Поддерживает немецкие клавиатуры с использованием функциональных клавиш","Проверка безопасности путем проверки экрана"],"ar":["تبديل تلقائي للنماذج الذكية باستخدام محاكاة لوحة المفاتيح","يتطلب إعدادات اختصارات مخصصة","يدعم لوحات المفاتيح الألمانية باستخدام مفاتيح F","فحص أمان من خلال التحقق من الشاشة"]},"keywords":{"en":["how to use windsurf-auto-model-switcher","windsurf-auto-model-switcher setup guide","OpenAI backend automation","AzureOpenAI model switching","windsurf-auto-model-switcher alternative","windsurf-auto-model-switcher vs manual model switching","automated AI workflow optimization","windsurf-auto-model-switcher install","programmable keyboard simulation for AI agents"],"zh":["Windsurf Auto Model Switcher","OpenAI后端","AzureOpenAI","自动切换模型","键盘模拟","STRUT策略","安全检查","AI工具","开发效率"],"ja":["Windsurf Auto Model Switcher","OpenAIのバックエンド","AzureOpenAI","自動モデル切り替え","キーボードシミュレーション","STRUT戦略","安全性チェック","AIエージェント","開発効率"],"ko":["Windsurf Auto Model Switcher","오픈AI 백엔드","Azure 오픈AI","자동 모델 전환","키보드 시뮬레이션","STRUT 전략","안전성 체크","인공지능 도구","개발 효율성"],"es":["herramientas de AI","conmutación de modelos de AI","simulación de teclado","OpenAI","AzureOpenAI","desarrollo de AI","programación de AI","tecnologías de AI"],"fr":["outils d''IA","commutation de modèles d''IA","simulation de clavier","OpenAI","AzureOpenAI","développement d''IA","programmation d''IA","technologies d''IA"],"de":["KI-Tools","Umstellung von KI-Modellen","Tastensimulierung","OpenAI","AzureOpenAI","KI-Entwicklung","KI-Programmierung","KI-Technologien"],"pt":["Windsurf Auto Model Switcher","Ferramentas de IA","OpenAI","AzureOpenAI","Troca automática de modelos de IA","Simulação de teclado","Configuração de atalhos personalizados"],"ru":["Windsurf Auto Model Switcher","ИИ Агенты","OpenAI","AzureOpenAI","Автоматическое переключение моделей ИИ","Симуляция клавиатуры","Настройка пользовательских комбинаций клавиш"],"ar":["Windsurf Auto Model Switcher","أدوات الذكاء الاصطناعي","OpenAI","AzureOpenAI","تبديل تلقائي للنماذج الذكية","محاكاة لوحة المفاتيح","إعدادات اختصارات مخصصة"]}},"owner":"karstenheld3","repo":"OpenAI-BackendTools","repoPath":"karstenheld3/OpenAI-BackendTools","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.466Z","topics":[],"category":"community","skillMd":{"name":"windsurf-auto-model-switcher","description":"Switch Windsurf Cascade AI models programmatically. Apply when needing to change models from workflows or scripts.","bodyPreview":"# Windsurf Auto Model Switcher\n\nSwitch Windsurf Cascade AI models programmatically using keyboard simulation.\n\n## MUST-NOT-FORGET\n\n- Requires custom keybindings (see SETUP.md)\n- German keyboards: Use F-keys, not Ctrl+Alt (AltGr conflict)\n- Model selector requires Windsurf window focus\n- Auto-switching requires safety check (screenshot verification)\n\n## Model Hints in STRUT\n\nSTRUT Strategy sections may include model hints:\n```\n├─ Strategy: Analyze requirements, design solution\n│   - Opus for anal","body":"# Windsurf Auto Model Switcher\n\nSwitch Windsurf Cascade AI models programmatically using keyboard simulation.\n\n## MUST-NOT-FORGET\n\n- Requires custom keybindings (see SETUP.md)\n- German keyboards: Use F-keys, not Ctrl+Alt (AltGr conflict)\n- Model selector requires Windsurf window focus\n- Auto-switching requires safety check (screenshot verification)\n\n## Model Hints in STRUT\n\nSTRUT Strategy sections may include model hints:\n```\n├─ Strategy: Analyze requirements, design solution\n│   - Opus for analysis, Sonnet for implementation\n```\n\nModel hints are recommendations - agent decides based on actual task.\n\n## Prerequisites\n\n1. Run SETUP.md to install keybindings\n2. Restart Windsurf after setup\n\n## Files\n\n- `select-windsurf-model-in-ide.ps1` - Select a model by search query\n- `windsurf-model-registry.json` - All available models and costs\n- `update-model-registry/UPDATE_WINDSURF_MODEL_REGISTRY.md` - Workflow to update the registry\n\n## Usage\n\n```powershell\n# Select Claude Sonnet 4.5\n.\\select-windsurf-model-in-ide.ps1 -Query \"sonnet 4.5\"\n\n# Select Claude Opus 4.5 (Thinking)\n.\\select-windsurf-model-in-ide.ps1 -Query \"opus 4.5 thinking\"\n\n# Select GPT-5.2 Low Reasoning\n.\\select-windsurf-model-in-ide.ps1 -Query \"gpt-5.2 low\"\n```\n\n## Model Registry\n\nSee `windsurf-model-registry.json` for all available models and their credit costs.\n\nTo update the registry, see `update-model-registry/UPDATE_WINDSURF_MODEL_REGISTRY.md`.\n\n## Keybindings\n\nInstalled by SETUP.md:\n\n- `Ctrl+Shift+F9` - Open model selector\n- `Ctrl+Shift+F10` - Cycle to next model\n\n## Troubleshooting\n\n**Script types into editor**: Run SETUP.md and restart Windsurf.\n\n**Model doesn''t change**: Ensure Cascade panel is visible.\n\n**Special characters (German keyboard)**: Use F-keys, not Ctrl+Alt.\n"},"lastSynced":"2026-03-08T02:09:25.945Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing automated model switching for OpenAI backends, such as Cursor, Windsurf, and Claude Code, to streamline AI workflow operations.","zh":"非常适合需要为 OpenAI 后端（如 Cursor、Windsurf 和 Claude Code）实现自动模型切换的 AI 代理，从而简化 AI 工作流操作。","ja":"OpenAI バックエンド（Cursor、Windsurf、Claude Code など）で自動モデル切り替えが必要な AI エージェントに最適で、AI ワークフロー操作を簡素化します。","ko":"OpenAI 백엔드(Cursor, Windsurf, Claude Code 등)에 자동 모델 전환을 필요로 하는 AI 에이전트에게 적합하여 AI 워크플ロー 작업을 간소화합니다.","es":"Perfecto para agentes de IA que necesitan conmutación de modelo automática para backends de OpenAI, como Cursor, Windsurf y Claude Code, para optimizar las operaciones de flujo de trabajo de IA.","fr":"Parfait pour les agents IA nécessitant un commutateur de modèle automatisé pour les backends OpenAI, tels que Cursor, Windsurf et Claude Code, pour rationaliser les opérations de workflow IA.","de":"Perfekt für KI-Agents, die eine automatische Modellumschaltung für OpenAI-Backends wie Cursor, Windsurf und Claude Code benötigen, um KI-Workflow-Operationen zu optimieren.","pt":"Perfeito para Agentes de IA que necessitam de comutação de modelo automática para backends OpenAI, como Cursor, Windsurf e Claude Code, para otimizar as operações de workflow de IA.","ru":"Идеально подходит для агентов ИИ, которым требуется автоматическое переключение моделей для бэкендов OpenAI, таких как Cursor, Windsurf и Claude Code, для оптимизации операций рабочего процесса ИИ.","ar":"مثالي لعمليات وكيلات الذكاء الاصطناعي التي تحتاج إلى تبديل 모델 تلقائي لخلفيات OpenAI، مثل Cursor و Windsurf و Claude Code، لتحسين عمليات سير عمل الذكاء الاصطناعي."},"recommendation":{"en":"Empowers agents to programmatically switch Windsurf Cascade AI models using keyboard simulation, providing seamless integration with OpenAI and AzureOpenAI, and enabling advanced AI workflow automation through screenshot verification and custom keybindings.","zh":"赋予代理程序化切换 Windsurf Cascade AI 模型的能力，使用键盘模拟，并提供与 OpenAI 和 AzureOpenAI 的无缝集成，并通过截图验证和自定义快捷键启用高级 AI 工作流自动化。","ja":"エージェントに、キーボードシミュレーションを使用して Windsurf Cascade AI モデルをプログラムで切り替える機能を付与し、OpenAI および AzureOpenAI とシームレスに統合し、スクリーンショットの検証とカスタムキーバインドを介して高度な AI ワークフローの自動化を可能にします。","ko":"에이전트에게 키보드 시뮬레이션을 사용하여 Windsurf Cascade AI 모델을 프로그래밍 방식으로 전환할 수 있는 기능을 제공하며, OpenAI 및 AzureOpenAI와의无缝 통합을 제공하고, 스크린샷 확인 및 사용자 지정 키 바인딩을 통해 고급 AI 워크플로 자동화를 가능하게 합니다.","es":"Habilita a los agentes a conmutar programáticamente los modelos de AI Cascade de Windsurf mediante simulación de teclado, proporcionando una integración perfecta con OpenAI y AzureOpenAI, y permitiendo una automatización avanzada del flujo de trabajo de IA a través de la verificación de capturas de pantalla y enlaces de tecla personalizados.","fr":"Permet aux agents de commutater programmiquement les modèles d''IA Cascade de Windsurf à l''aide d''une simulation de clavier, offrant une intégration transparente avec OpenAI et AzureOpenAI, et permettant une automation avancée du flux de travail d''IA via la vérification d''écran et des liaisons de touche personnalisées.","de":"Ermöglicht es den Agents, die KI-Modelle von Windsurf Cascade programmgesteuert über eine Tastatursimulation umzuschalten, wodurch eine nahtlose Integration mit OpenAI und AzureOpenAI ermöglicht wird und eine erweiterte Automatisierung des KI-Workflows durch Screenshot-Verifizierung und benutzerdefinierte Tastenzuordnungen möglich ist.","pt":"Habilita os agentes a alternar programaticamente os modelos de IA do Windsurf Cascade usando simulação de teclado, fornecendo integração sem interrupções com OpenAI e AzureOpenAI, e permitindo automação avançada de workflow de IA por meio de verificação de tela e atalhos personalizados.","ru":"Позволяет агентам программно переключать модели ИИ Windsurf Cascade с помощью симуляции клавиатуры, обеспечивая бесшовную интеграцию с OpenAI и AzureOpenAI, и ermöglicht расширенную автоматизацию рабочего процесса ИИ с помощью проверки экрана и пользовательских горячих клавиш.","ar":"تمكّن الوكيلات من تبديل البرامج النصية لطراز Windsurf Cascade باستخدام محاكاة لوحة المفاتيح، وتوفير تكامل سلس مع OpenAI و AzureOpenAI، وتمكين آليّة متقدمة لسير عمليات الذكاء الاصطناعي من خلال التحقق من الشاشة والاختصارات المخصصة."},"useCases":{"en":["Automating model switching for AI workflows","Streamlining OpenAI backend operations","Debugging AI model interactions using screenshot verification"],"zh":["自动化 AI 工作流的模型切换","简化 OpenAI 后端操作","使用截图验证调试 AI 模型交互"],"ja":["AI ワークフローのモデル切り替えを自動化する","OpenAI バックエンド操作を簡素化する","スクリーンショットの検証を使用して AI モデル相互作用をデバッグする"],"ko":["AI 워크플로의 모델 전환을 자동화하는 것","OpenAI 백엔드 작업을 간소화하는 것","스크린샷 확인을 사용하여 AI 모델 상호작용을 디버깅하는 것"],"es":["Automatización de la conmutación de modelos para flujos de trabajo de IA","Optimización de las operaciones de backend de OpenAI","Depuración de las interacciones de los modelos de IA mediante verificación de capturas de pantalla"],"fr":["Automatisation du commutateur de modèles pour les flux de travail d''IA","Rationalisation des opérations de backend OpenAI","Débogage des interactions de modèles d''IA à l''aide de la vérification d''écran"],"de":["Automatisierung des Modellumschalters für KI-Workflows","Optimierung der OpenAI-Backend-Operationen","Fehlerbehebung der KI-Modellinteraktionen durch Screenshot-Verifizierung"],"pt":["Automatizar a comutação de modelo para fluxos de trabalho de IA","Otimizar operações de backend OpenAI","Depurar interações de modelo de IA usando verificação de tela"],"ru":["Автоматизировать переключение моделей для рабочих процессов ИИ","Оптимизировать операции бэкенда OpenAI","Отладить взаимодействия моделей ИИ с помощью проверки экрана"],"ar":["أتمتة تبديل الطراز لسير عمليات الذكاء الاصطناعي","تحسين عمليات خلفية OpenAI","تصحيح أخطاء تفاعلات النموذج باستخدام التحقق من الشاشة"]},"limitations":{"en":["Requires custom keybindings","Compatible with German keyboards using F-keys, not Ctrl+Alt","Model selector requires Windsurf window focus","Auto-switching requires safety check through screenshot verification"],"zh":["需要自定义快捷键","仅与使用 F 键的德语键盘兼容，不支持 Ctrl+Alt","模型选择器需要 Windsurf 窗口焦点","自动切换需要通过截图验证进行安全检查"],"ja":["カスタムキーバインドが必要","F キーを使用するドイツ語キーボードのみ対応、Ctrl+Alt はサポートされない","モデルセレクターには Windsurf ウィンドウのフォーカスが必要","自動切り替えにはスクリーンショットの検証を介したセーフティチェックが必要"],"ko":["사용자 지정 키 바인딩이 필요","F 키를 사용하는 독일어 키보드만 호환, Ctrl+Alt은 지원되지 않음","모델 선택기에는 Windsurf 창焦点이 필요","자동 전환에는 스크린샷 확인을 통해 안전 확인이 필요"],"es":["Requiere enlaces de tecla personalizados","Compatible con teclados alemanes que utilizan teclas F, no Ctrl+Alt","El selector de modelo requiere que la ventana de Windsurf esté en foco","La conmutación automática requiere una verificación de seguridad a través de la verificación de capturas de pantalla"],"fr":["Nécessite des liaisons de touche personnalisées","Compatible avec les claviers allemands utilisant les touches F, et non Ctrl+Alt","Le sélecteur de modèle nécessite que la fenêtre de Windsurf soit en focus","La commutation automatique nécessite une vérification de sécurité via la vérification d''écran"],"de":["Benötigt benutzerdefinierte Tastenzuordnungen","Kompatibel mit deutschen Tastaturen, die F-Tasten verwenden, nicht Ctrl+Alt","Der Modellauswahlerfordert, dass das Windsurf-Fenster im Fokus ist","Das automatische Umschalten erfordert eine Sicherheitsüberprüfung durch Screenshot-Verifizierung"],"pt":["Requer atalhos personalizados","Compatível com teclados alemães usando teclas F, não Ctrl+Alt","Seletor de modelo requer foco da janela do Windsurf","Comutação automática requer verificação de segurança por meio de verificação de tela"],"ru":["Требует пользовательских горячих клавиш","Совместимо с немецкими клавиатурами, используя клавиши F, не Ctrl+Alt","Выбор модели требует фокуса окна Windsurf","Автоматическое переключение требует проверки безопасности с помощью проверки экрана"],"ar":["يتطلب اختصارات مخصصة","متوافق مع لوحات المفاتيح الألمانية باستخدام مفاتيح F، وليس Ctrl+Alt","محدد الطراز يتطلب تركيز نافذة Windsurf","التبديل التلقائي يتطلب فحص أمان من خلال التحقق من الشاشة"]},"version":4},"contentHash":"3c7826ba875c581cca6263aa60aaee57a3cd1cf2f159020f7d8fabd6cbee05af","qualityScore":45}');
