INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('karstenheld3/OpenAI-BackendTools/windsurf-auto-model-switcher', 'windsurf-auto-model-switcher', 'karstenheld3', 'OpenAI-BackendTools', 'community', 'windsurf-auto-model-switcher karstenheld3 OpenAI-BackendTools community The windsurf-auto-model-switcher skill enables developers to automate model switching for OpenAI backends, streamlining AI workflow operations. It benefits AI agents and developers working with OpenAI and AzureOpenAI. Windsurf Auto Model Switcher是一套工具集合，用于测试、操作和维护OpenAI后端，包括OpenAI和AzureOpenAI Windsurf Auto Model Switcherは、OpenAIのバックエンドをテスト、操作、およびメンテナンスするためのツールのコレクションです Windsurf Auto Model Switcher는 오픈AI 백엔드를 테스트, 운영 및 유지 관리하는 데 사용되는 도구 모음입니다 Windsurf-auto-model-switcher es una colección de herramientas para probar, operar y mantener backends de OpenAI, con capacidad de conmutación de modelos de AI de manera programática Windsurf-auto-model-switcher est un ensemble d''outils pour tester, exploiter et maintenir les backends OpenAI, avec la possibilité de commutation de modèles d''IA de manière programmée Windsurf-auto-model-switcher ist eine Sammlung von Tools zum Testen, Betreiben und Warten von OpenAI-Backends, mit der Möglichkeit, KI-Modelle programmgesteuert umzuschalten O Windsurf Auto Model Switcher é uma coleção de ferramentas para testar, operar e manter backends de IA da OpenAI e AzureOpenAI Windsurf Auto Model Switcher - это коллекция инструментов для тестирования, эксплуатации и обслуживания бэкендов ИИ от OpenAI и AzureOpenAI Windsurf Auto Model Switcher هو مجموعة من الأدوات لاختبار وتشغيل وضمان استمرار خلفيات الذكاء الاصطناعي من OpenAI و AzureOpenAI how to use windsurf-auto-model-switcher windsurf-auto-model-switcher setup guide OpenAI backend automation AzureOpenAI model switching windsurf-auto-model-switcher alternative windsurf-auto-model-switcher vs manual model switching automated AI workflow optimization windsurf-auto-model-switcher install programmable keyboard simulation for AI agents Windsurf Auto Model Switcher OpenAI后端 AzureOpenAI 自动切换模型 键盘模拟 STRUT策略 安全检查 AI工具 开发效率 Switches Windsurf Cascade AI models programmatically using keyboard simulation Requires custom keybindings for operation, as outlined in SETUP.md Supports model hints in STRUT Strategy sections for optimized model selection Ensures safety with screenshot verification for auto-switching Compatible with German keyboards using F-keys instead of Ctrl+Alt due to AltGr conflict windsurf-auto-model-switcher is a collection of tools for testing, operating, and maintaining OpenAI backends, allowing for programmable model switching using keyboard simulation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AnasShahid/vimsy_lead_generation/gsd-templates', 'community', 'AnasShahid', 'vimsy_lead_generation', 'AnasShahid/vimsy_lead_generation', 'gsd-templates', 0, 0, 45, '2026-03-08T01:57:15.467Z', '2026-03-08T02:09:28.679Z', '9bd6bacfd25d9a38062a67d28a68834e1b9a8a11b4ce8b8bdc385144b1a553f5', '{"id":"AnasShahid/vimsy_lead_generation/gsd-templates","name":"gsd-templates","description":{"en":"The gsd-templates skill provides reference templates for GSD output files, benefiting developers and project managers by standardizing project documentation. It includes templates for PROJECT.md files with sections like vision, problem statement, and technical approach.","zh":"GSD 模板提供了 PROJECT.md 文件的参考模板，帮助开发者创建有效的项目文档","ja":"GSD テンプレートは、PROJECT.md ファイルのリファレンス テンプレートを提供し、開発者が有効なプロジェクト ドキュメントを作成するのに役立ちます","ko":"GSD 템플릿은 PROJECT.md 파일의 참조 템플릿을 제공하여 개발자가 효과적인 프로젝트 문서를 생성하도록 도와줍니다","es":"GSD Templates proporciona plantillas de referencia para archivos de salida, incluyendo PROJECT.md con secciones para visión, declaración de problemas y criterios de éxito","fr":"GSD Templates fournit des modèles de référence pour les fichiers de sortie, notamment PROJECT.md avec des sections pour la vision, la déclaration de problèmes et les critères de succès","de":"GSD Templates bietet Referenzvorlagen für Ausgabedateien, darunter PROJECT.md mit Abschnitten für Vision, Problemstellung und Erfolgskriterien","pt":"Os templates GSD fornecem uma estrutura para projetos e arquiteturas técnicas, incluindo visão, declaração de problemas e critérios de sucesso.","ru":"Шаблоны GSD предоставляют структуру для проектов и технических архитектур, включая видение, заявление проблемы и критерии успеха.","ar":"تقدم قوالب GSD هيكلاً لمشاريع والهياكل التقنية، بما في ذلك الرؤية وبيان المشكلة ومعايير النجاح."},"seo":{"title":{"en":"gsd-templates: Project Setup Guide for AI Agents","zh":"GSD 模板设置指南 - AIエージェント项目模板","ja":"GSD テンプレートのベストプラクティス - AIエージェントプロジェクトテンプレート","ko":"GSD 템플릿 설정 가이드 - AI 에이전트 프로젝트 템플릿","es":"GSD Templates: Guía de Configuración para Agentes de IA","fr":"GSD Templates: Guide de Mise en Place pour Outils d''IA","de":"GSD Templates: Einrichtungsleitfaden für KI-Tools","pt":"GSD Templates: Guia de Configuração para Ferramentas de IA","ru":"ИИ Агенты: GSD Templates Установка и Настройка","ar":"قوالب GSD: دليل الإعداد لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how gsd-templates streamlines project documentation with pre-built templates for PROJECT.md files, including vision, problem statement, and technica...","zh":"使用 GSD 模板简化项目开发，了解如何创建有效的 PROJECT.md 文件，包括项目愿景、问题陈述、目标用户和技术方法","ja":"GSD テンプレートを使用してプロジェクト開発を簡素化する、PROJECT.md ファイルの作成方法を学ぶ、プロジェクトのビジョン、問題ステートメント、ターゲットユーザー、技術アプローチを含む","ko":"GSD 템플릿을 사용하여 프로젝트 개발을 간소화하고 PROJECT.md 파일을 생성하는 방법을 알아보세요. 프로젝트 비전, 문제 진술, 타겟 사용자 및 기술 접근 방식 등을 포함합니다","es":"Descubre cómo configurar GSD Templates para mejorar tus proyectos de desarrollo con plantillas de referencia para archivos de salida","fr":"Découvrez comment configurer GSD Templates pour améliorer vos projets de développement avec des modèles de référence pour les fichiers de sortie","de":"Erfahren Sie, wie Sie GSD Templates einrichten, um Ihre Entwicklungsprojekte mit Referenzvorlagen für Ausgabedateien zu verbessern","pt":"Aprenda a configurar os modelos de saída do GSD com os templates de projeto e técnicos para melhorar a eficiência do seu trabalho com IA","ru":"Узнайте, как настроить выходные файлы GSD с помощью шаблонов проекта и технических шаблонов для улучшения эффективности вашей работы с ИИ Агентами","ar":"تعرف على كيفية ضبط نماذج الإخراج GSD باستخدام قوالب المشروع والتقنية لتحسين كفاءة عملك مع أدوات الذكاء الاصطناعي"},"definition":{"en":"gsd-templates is a collection of reference templates for GSD output files, including a PROJECT.md template with predefined sections for vision, problem statement, target user, success criteria, and technical approach","zh":"GSD 模板是一种用于创建 PROJECT.md 文件的参考模板，用于定义项目的愿景、问题陈述、目标用户和技术方法","ja":"GSD テンプレートは、PROJECT.md ファイルを作成するためのリファレンス テンプレートであり、プロジェクトのビジョン、問題ステートメント、ターゲットユーザー、技術アプローチを定義するために使用されます","ko":"GSD 템플릿은 PROJECT.md 파일을 생성하기 위한 참조 템플릿으로 프로젝트의 비전, 문제 진술, 타겟 사용자 및 기술 접근 방식을 정의하는 데 사용됩니다","es":"GSD Templates es un conjunto de plantillas de referencia para archivos de salida de proyectos de desarrollo","fr":"GSD Templates est un ensemble de modèles de référence pour les fichiers de sortie des projets de développement","de":"GSD Templates ist ein Satz von Referenzvorlagen für Ausgabedateien von Entwicklungsprojekten","pt":"GSD Templates são modelos de referência para arquivos de saída do GSD, incluindo projetos e arquiteturas técnicas.","ru":"Шаблоны GSD - это эталонные модели для выходных файлов GSD, включающих проекты и технические архитектуры.","ar":"قوالب GSD هي نماذج مرجعية لملفات الإخراج GSD، بما في ذلك المشاريع والهياكل التقنية."},"features":{"en":["Generates PROJECT.md templates with markdown formatting","Includes sections for vision, problem statement, target user, and success criteria","Supports technical approach documentation with stack and architecture details","Provides a structured format for observable outcome tracking","Enables standardized project documentation across teams and projects"],"zh":["PROJECT.md 文件模板","项目愿景和问题陈述","目标用户和成功标准","技术方法和栈","架构和高级别方法"],"ja":["PROJECT.md ファイル テンプレート","プロジェクトのビジョンと問題ステートメント","ターゲットユーザーと成功基準","技術アプローチとスタック","アーキテクチャと高水準方法"],"ko":["PROJECT.md 파일 템플릿","프로젝트 비전과 문제 진술","타겟 사용자와 성공 기준","기술 접근 방식과 스택","아키텍처와 고수준 방법"],"es":["Plantillas de referencia para archivos de salida","Secciones para visión, declaración de problemas y criterios de éxito en PROJECT.md","Soporte para tecnologías y arquitecturas específicas","Enfoque técnico para proyectos de desarrollo","Observable outcomes para medir el éxito del proyecto"],"fr":["Modèles de référence pour les fichiers de sortie","Sections pour la vision, la déclaration de problèmes et les critères de succès dans PROJECT.md","Prise en charge de technologies et d''architectures spécifiques","Approche technique pour les projets de développement","Résultats observables pour mesurer le succès du projet"],"de":["Referenzvorlagen für Ausgabedateien","Abschnitte für Vision, Problemstellung und Erfolgskriterien in PROJECT.md","Unterstützung für spezifische Technologien und Architekturen","Technischer Ansatz für Entwicklungsprojekte","Beobachtbare Ergebnisse zur Messung des Projekterfolgs"],"pt":["Modelos de projeto com visão e declaração de problemas","Arquiteturas técnicas com pilhas e abordagens de alto nível","Critérios de sucesso com resultados observáveis","Suporte a tecnologias e linguagens de programação diversas","Integração com ferramentas de IA e automação","Customização de templates para atender às necessidades específicas"],"ru":["Модели проектов с видением и заявлением проблемы","Технические архитектуры с технологическими стеками и высокоуровневыми подходами","Критерии успеха с наблюдаемыми результатами","Поддержка различных технологий и языков программирования","Интеграция с инструментами ИИ и автоматизации","Настройка шаблонов для удовлетворения конкретных потребностей"],"ar":["نماذج المشاريع مع الرؤية وبيان المشكلة","الهياكل التقنية مع تقنيات ونهج 높은 المستوى","معايير النجاح مع نتائج قابلة للملاحظة","دعم لتكنولوجيا ولغات برمجة متنوعة","التكامل مع أدوات الذكاء الاصطناعي والآلي","تخصيص القوالب لتناسب الاحتياجات المحددة"]},"keywords":{"en":["gsd-templates setup guide","how to use gsd-templates for project documentation","gsd-templates alternative to manual documentation","gsd-templates vs custom templates","installing gsd-templates for AI agents","gsd-templates tutorial for developers","what is gsd-templates and its benefits","gsd-templates best practices for project management"],"zh":["GSD 模板","PROJECT.md 文件","项目开发","AIエージェント","技术方法","栈和架构","PROJECT.md 文件创建","GSD 템플릿设置","PROJECT.md 文件模板"],"ja":["GSD テンプレート","PROJECT.md ファイル","プロジェクト開発","AIエージェント","技術アプローチ","スタックとアーキテクチャ","PROJECT.md ファイル作成","GSD テンプレート設定","PROJECT.md ファイルテンプレート"],"ko":["GSD 템플릿","PROJECT.md 파일","프로젝트 개발","AI 에이전트","기술 접근 방식","스택과 아키텍처","PROJECT.md 파일 생성","GSD 템플릿 설정","PROJECT.md 파일 템플릿"],"es":["GSD Templates","plantillas de referencia","archivos de salida","PROJECT.md","desarrollo de software","agentes de IA","herramientas de desarrollo","tecnologías de desarrollo","arquitecturas de desarrollo"],"fr":["GSD Templates","modèles de référence","fichiers de sortie","PROJECT.md","développement de logiciels","outils d''IA","outils de développement","technologies de développement","architectures de développement"],"de":["GSD Templates","Referenzvorlagen","Ausgabedateien","PROJECT.md","Softwareentwicklung","KI-Tools","EntwicklungsTools","Entwicklungstechnologien","Entwicklungsarchitekturen"],"pt":["GSD Templates","Ferramentas de IA","Projetos de IA","Arquiteturas técnicas","Visão e declaração de problemas","Critérios de sucesso","Tecnologias e linguagens de programação","Integração com ferramentas de IA","Customização de templates"],"ru":["ИИ Агенты","GSD Templates","Проекты ИИ","Технические архитектуры","Видение и заявление проблемы","Критерии успеха","Технологии и языки программирования","Интеграция с инструментами ИИ","Настройка шаблонов"],"ar":["أدوات الذكاء الاصطناعي","قوالب GSD","مشاريع الذكاء الاصطناعي","الهياكل التقنية","الرؤية وبيان المشكلة","معايير النجاح","التكنولوجيا ولغات البرمجة","التكامل مع أدوات الذكاء الاصطناعي","تخصيص القوالب"]}},"owner":"AnasShahid","repo":"vimsy_lead_generation","repoPath":"AnasShahid/vimsy_lead_generation","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.467Z","topics":[],"category":"community","skillMd":{"name":"gsd-templates","description":"Output templates for GSD artifacts - PROJECT.md, ROADMAP.md, PLAN.md, SUMMARY.md, STATE.md. Invoke when creating GSD documents.","bodyPreview":"# GSD Templates\n\nReference templates for all GSD output files.\n\n## PROJECT.md Template\n\n```markdown\n# [Project Name]\n\n## Vision\n\n[2-3 sentences capturing the core idea and why it matters]\n\n## Problem Statement\n\n[What problem this solves, for whom]\n\n## Target User\n\n[Who uses this, what they care about]\n\n## Success Criteria\n\n- [Observable outcome 1]\n- [Observable outcome 2]\n- [Observable outcome 3]\n\n## Technical Approach\n\n**Stack:** [Technologies and why]\n**Architecture:** [High-level approach]\n**","body":"# GSD Templates\n\nReference templates for all GSD output files.\n\n## PROJECT.md Template\n\n```markdown\n# [Project Name]\n\n## Vision\n\n[2-3 sentences capturing the core idea and why it matters]\n\n## Problem Statement\n\n[What problem this solves, for whom]\n\n## Target User\n\n[Who uses this, what they care about]\n\n## Success Criteria\n\n- [Observable outcome 1]\n- [Observable outcome 2]\n- [Observable outcome 3]\n\n## Technical Approach\n\n**Stack:** [Technologies and why]\n**Architecture:** [High-level approach]\n**Constraints:** [Limitations or requirements]\n\n## Requirements\n\n### Validated\n(None yet — ship to validate)\n\n### Active\n- [ ] [Requirement 1]\n- [ ] [Requirement 2]\n\n### Out of Scope\n- [Exclusion] — [why]\n\n## Key Decisions\n\n| Decision | Rationale | Outcome |\n|----------|-----------|---------|\n| [Choice] | [Why] | Pending |\n\n---\n*Last updated: [date]*\n```\n\n## REQUIREMENTS.md Template\n\n```markdown\n# Requirements\n\n## Overview\n\n**Project:** [name]\n**Defined:** [date]\n**Total:** [count] requirements\n\n## v1 Requirements (MVP)\n\n| ID | Requirement | Priority | Phase |\n|----|-------------|----------|-------|\n| REQ-001 | [Description] | Must | TBD |\n\n## v2 Requirements\n\n| ID | Requirement | Rationale for v2 |\n|----|-------------|------------------|\n| REQ-101 | [Description] | [Why not v1] |\n\n## Out of Scope\n\n| Item | Reason |\n|------|--------|\n| [Feature] | [Why] |\n\n## Traceability\n\n| Requirement | Phase | Plan | Status |\n|-------------|-------|------|--------|\n| REQ-001 | TBD | TBD | Pending |\n\n---\n*Last updated: [date]*\n```\n\n## ROADMAP.md Template\n\n```markdown\n# Roadmap\n\n## Overview\n\n**Project:** [name]\n**Milestone:** v1.0\n**Phases:** [count]\n\n## Progress\n\n```\nPhase 1  ░░░░░░░░░░  0%\nPhase 2  ░░░░░░░░░░  0%\n```\n\n## Phases\n\n### Phase 1: [Name]\n\n**Goal:** [Observable outcome]\n**Requirements:** REQ-001, REQ-002\n**Success Criteria:**\n- [ ] [Testable behavior 1]\n- [ ] [Testable behavior 2]\n\n---\n\n### Phase 2: [Name]\n\n**Goal:** [Outcome]\n**Requirements:** REQ-003\n**Depends on:** Phase 1\n**Success Criteria:**\n- [ ] [Behavior]\n\n---\n\n## Requirement Coverage\n\n| Requirement | Phase | Status |\n|-------------|-------|--------|\n| REQ-001 | 1 | Pending |\n\n---\n*Last updated: [date]*\n```\n\n## STATE.md Template\n\n```markdown\n# Project State\n\n## Current Position\n\n**Milestone:** v1.0\n**Phase:** 1 of [total] ([Name])\n**Plan:** Not started\n**Status:** Ready to plan\n\n**Progress:**\n```\n░░░░░░░░░░░░░░░░░░░░ 0%\n```\n\n**Last activity:** [date] - [description]\n\n## Session Continuity\n\n**Last session:** [date]\n**Stopped at:** [description]\n**Resume file:** None\n\n## Decisions\n\n| Decision | Rationale | Date | Phase |\n|----------|-----------|------|-------|\n| [Choice] | [Why] | [date] | — |\n\n## Blockers & Concerns\n\nNone yet.\n\n## Context Notes\n\n[Important context for future sessions]\n\n---\n*Auto-updated by GSD workflows*\n```\n\n## PLAN.md Template\n\n```markdown\n---\nphase: [N]\nplan: [M]\nname: [Name]\nwave: [1|2|3]\ndepends_on: [plans or \"none\"]\nautonomous: true\n---\n\n# Phase [N] Plan [M]: [Name]\n\n## Objective\n\n[What this plan accomplishes]\n\n## Context\n\n**Requirements:** REQ-XXX\n**Phase goal contribution:** [How this advances the goal]\n\n## Tasks\n\n### Task 1: [Action-oriented name]\n\n**Files:** `src/path/file.ts`\n\n**Action:**\n[Specific instructions]\n\n**Verify:**\n```bash\n[verification command]\n```\n\n**Done when:**\n- [Outcome]\n\n---\n\n### Task 2: [Name]\n\n[Same structure]\n\n---\n\n## Verification\n\n```bash\n[Overall verification]\n```\n\n## Success Criteria\n\n- [ ] [Testable outcome]\n```\n\n## SUMMARY.md Template\n\n```markdown\n---\nphase: [N]\nplan: [M]\ncompleted: [date]\nduration: [time]\n---\n\n# Phase [N] Plan [M]: [Name] — Summary\n\n## One-liner\n\n[Substantive: \"JWT auth with refresh rotation using jose\"]\n\n## What Was Built\n\n[2-3 paragraphs]\n\n## Tasks Completed\n\n| Task | Description | Commit | Files |\n|------|-------------|--------|-------|\n| 1 | [Name] | [hash] | [files] |\n\n## Key Files\n\n**Created:**\n- `path` — [purpose]\n\n**Modified:**\n- `path` — [changes]\n\n## Decisions Made\n\n| Decision | Rationale |\n|----------|-----------|\n| [Choice] | [Why] |\n\n## Deviations from Plan\n\n[Auto-fixes or \"None\"]\n\n## Verification Results\n\n```\n[Output]\n```\n\n---\n*Completed: [timestamp]*\n```\n\n## VERIFICATION.md Template\n\n```markdown\n---\nphase: [N]-[name]\nverified: [timestamp]\nstatus: [passed | gaps_found | human_needed]\nscore: N/M verified\n---\n\n# Phase [N] Verification Report\n\n**Goal:** [from ROADMAP]\n**Status:** [status]\n\n## Observable Truths\n\n| # | Truth | Status | Evidence |\n|---|-------|--------|----------|\n| 1 | [truth] | ✓/✗ | [evidence] |\n\n## Required Artifacts\n\n| Artifact | Exists | Substantive | Wired |\n|----------|--------|-------------|-------|\n| `path` | ✓ | ✓ | ✓ |\n\n## Key Links\n\n| From | To | Status |\n|------|----|--------|\n| [component] | [api] | [status] |\n\n## Gaps\n\n[If any]\n\n## Human Verification\n\n[If needed]\n```\n"},"lastSynced":"2026-03-08T02:09:28.679Z","agentAnalysis":{"suitability":{"en":"Perfect for Project Management Agents needing standardized GSD output file templates.","zh":"非常适合需要标准化GSD输出文件模板的项目管理代理。","ja":"標準化されたGSD出力ファイルテンプレートを必要とするプロジェクト管理エージェントに最適です。","ko":"표준화된 GSD 출력 파일 템플릿이 필요한 프로젝트 관리 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Gestión de Proyectos que necesitan plantillas de archivos de salida de GSD estandarizadas.","fr":"Parfait pour les agents de gestion de projet nécessitant des modèles de fichiers de sortie GSD standardisés.","de":"Perfekt für Projektmanagement-Agenten, die standardisierte GSD-Ausgabedateivordrucke benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Projetos que precisam de modelos de arquivos de saída GSD padrão.","ru":"Идеально подходит для агентов по управлению проектами, которым необходимы стандартизированные шаблоны выходных файлов GSD.","ar":"مثالي لعمليات إدارة المشاريع التي تحتاج إلى قوالب ملفات إخراج GSD معيارية."},"recommendation":{"en":"Empowers agents to generate consistent PROJECT.md files with sections like vision, problem statement, and technical approach, utilizing Markdown formatting and including essential project details like target user and success criteria.","zh":"赋予代理生成具有vision、问题陈述和技术方法等部分的consistent PROJECT.md文件的能力，利用Markdown格式，并包含目标用户和成功标准等必要的项目详细信息。","ja":"ビジョン、問題ステートメント、技術アプローチなどのセクションを含む一貫性のあるPROJECT.mdファイルを生成するエージェントの能力を付与します。Markdown形式を利用し、ターゲットユーザーと成功基準などの必要なプロジェクト詳細情報を含みます。","ko":"비전, 문제 진술, 기술 접근 방식 등과 같은 섹션을 포함하는 일관된 PROJECT.md 파일을 생성하는 에이전트의 능력을 부여합니다. Markdown 형식을 사용하며, 대상 사용자 및 성공 기준 등과 같은 필요한 프로젝트 세부 정보를 포함합니다.","es":"Permite a los agentes generar archivos PROJECT.md consistentes con secciones como visión, declaración del problema y enfoque técnico, utilizando formato Markdown e incluyendo detalles esenciales del proyecto como usuario objetivo y criterios de éxito.","fr":"Permet aux agents de générer des fichiers PROJECT.md cohérents avec des sections comme vision, énoncé du problème et approche technique, en utilisant le format Markdown et en incluant des détails essentiels du projet comme l''utilisateur cible et les critères de succès.","de":"Ermöglicht es Agenten, konsistente PROJECT.md-Dateien mit Abschnitten wie Vision, Problembeschreibung und technischer Ansatz zu generieren, unter Verwendung von Markdown-Formatierung und unter Einbeziehung wesentlicher Projektdetails wie Zielbenutzer und Erfolgskriterien.","pt":"Habilita os agentes a gerar arquivos PROJECT.md consistentes com seções como visão, declaração de problema e abordagem técnica, utilizando formatação Markdown e incluindo detalhes essenciais do projeto como usuário-alvo e critérios de sucesso.","ru":"Наделяет агентов возможностью генерировать последовательные файлы PROJECT.md с разделами, такими как видение, формулировка проблемы и технический подход, используя форматирование Markdown и включая важные подробности проекта, такие как целевой пользователь и критерии успеха.","ar":"يمنح الوكلاء القدرة على生成 ملفات PROJECT.md متسقة مع أقسام مثل الرؤية وبيان المشكلة والمنهج الفني، باستخدام تنسيق Markdown وإدراج تفاصيل أساسية للمشروع مثل المستخدم المستهدف ومعايير النجاح."},"useCases":{"en":["Automating project documentation templates","Generating standardized PROJECT.md files","Streamlining technical approach descriptions"],"zh":["自动化项目文档模板","生成标准化的PROJECT.md文件","简化技术方法描述"],"ja":["プロジェクト文書テンプレートの自動化","標準化されたPROJECT.mdファイルの生成","技術アプローチの説明の簡素化"],"ko":["프로젝트 문서 템플릿 자동화","표준화된 PROJECT.md 파일 생성","기술 접근 방식 설명 단순화"],"es":["Automatización de plantillas de documentación de proyectos","Generación de archivos PROJECT.md estandarizados","Optimización de las descripciones del enfoque técnico"],"fr":["Automatisation des modèles de documentation de projet","Génération de fichiers PROJECT.md standardisés","Optimisation des descriptions de l''approche technique"],"de":["Automatisierung von Projektdokumentationsvorlagen","Generierung von standardisierten PROJECT.md-Dateien","Optimierung der Beschreibungen des technischen Ansatzes"],"pt":["Automar modelos de documentação de projetos","Gerar arquivos PROJECT.md padrão","Otimizar descrições de abordagem técnica"],"ru":["Автоматизация шаблонов документации проектов","Генерация стандартизированных файлов PROJECT.md","Оптимизация описаний технического подхода"],"ar":["توفير قوالب وثائق المشروع","جعل ملفات PROJECT.md معيارية","تبسيط وصف المنهج الفني"]},"limitations":{"en":["Requires Markdown compatibility","Limited to GSD output file templates"],"zh":["需要Markdown兼容性","仅限GSD输出文件模板"],"ja":["Markdownの互換性が必要","GSD出力ファイルテンプレートに限定される"],"ko":["Markdown 호환성이 필요","GSD 출력 파일 템플릿으로 제한"],"es":["Requiere compatibilidad con Markdown","Limitado a plantillas de archivos de salida de GSD"],"fr":["Nécessite la compatibilité avec Markdown","Limité aux modèles de fichiers de sortie GSD"],"de":["Benötigt Markdown-Kompatibilität","Begrenzt auf GSD-Ausgabedateivordrucke"],"pt":["Exige compatibilidade com Markdown","Limitado a modelos de arquivos de saída GSD"],"ru":["Требует совместимости с Markdown","Ограничен шаблонами выходных файлов GSD"],"ar":["يتطلب توافقًا مع Markdown","محدود بقوالب ملفات إخراج GSD"]},"version":4},"contentHash":"9bd6bacfd25d9a38062a67d28a68834e1b9a8a11b4ce8b8bdc385144b1a553f5","qualityScore":45}');
