INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AnasShahid/vimsy_lead_generation/gsd-templates', 'gsd-templates', 'AnasShahid', 'vimsy_lead_generation', 'community', 'gsd-templates AnasShahid vimsy_lead_generation community The gsd-templates skill provides reference templates for GSD output files, benefiting developers and project managers by standardizing project documentation. It includes templates for PROJECT.md files with sections like vision, problem statement, and technical approach. GSD 模板提供了 PROJECT.md 文件的参考模板，帮助开发者创建有效的项目文档 GSD テンプレートは、PROJECT.md ファイルのリファレンス テンプレートを提供し、開発者が有効なプロジェクト ドキュメントを作成するのに役立ちます GSD 템플릿은 PROJECT.md 파일의 참조 템플릿을 제공하여 개발자가 효과적인 프로젝트 문서를 생성하도록 도와줍니다 GSD Templates proporciona plantillas de referencia para archivos de salida, incluyendo PROJECT.md con secciones para visión, declaración de problemas y criterios de éxito GSD Templates fournit des modèles de référence pour les fichiers de sortie, notamment PROJECT.md avec des sections pour la vision, la déclaration de problèmes et les critères de succès GSD Templates bietet Referenzvorlagen für Ausgabedateien, darunter PROJECT.md mit Abschnitten für Vision, Problemstellung und Erfolgskriterien Os templates GSD fornecem uma estrutura para projetos e arquiteturas técnicas, incluindo visão, declaração de problemas e critérios de sucesso. Шаблоны GSD предоставляют структуру для проектов и технических архитектур, включая видение, заявление проблемы и критерии успеха. تقدم قوالب GSD هيكلاً لمشاريع والهياكل التقنية، بما في ذلك الرؤية وبيان المشكلة ومعايير النجاح. gsd-templates setup guide how to use gsd-templates for project documentation gsd-templates alternative to manual documentation gsd-templates vs custom templates installing gsd-templates for AI agents gsd-templates tutorial for developers what is gsd-templates and its benefits gsd-templates best practices for project management GSD 模板 PROJECT.md 文件 项目开发 AIエージェント 技术方法 栈和架构 PROJECT.md 文件创建 GSD 템플릿设置 PROJECT.md 文件模板 Generates PROJECT.md templates with markdown formatting Includes sections for vision, problem statement, target user, and success criteria Supports technical approach documentation with stack and architecture details Provides a structured format for observable outcome tracking Enables standardized project documentation across teams and projects gsd-templates is a collection of reference templates for GSD output files, including a PROJECT.md template with predefined sections for vision, problem statement, target user, success criteria, and technical approach');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('allthingslinux/portal/frontend-testing', 'community', 'allthingslinux', 'portal', 'allthingslinux/portal', 'frontend-testing', 0, 0, 45, '2026-03-08T01:57:15.472Z', '2026-03-08T02:09:35.832Z', 'f5bcf1878cbd646b6428b07d061545177c8ab2051da65855f1a393478b913568', '{"id":"allthingslinux/portal/frontend-testing","name":"frontend-testing","description":{"en":"The frontend-testing skill enables Claude to generate comprehensive frontend tests following established conventions and best practices, benefiting developers working on the Dify project.","zh":"Dify前端测试技能能够生成高质量的自动化测试，支持Vitest mock/timer APIs，提高代码可靠性和稳定性。","ja":"Difyフロントエンドテストスキルは、高品質の自動テストを生成し、Vitest mock/timer APIsをサポートして、コードの信頼性と安定性を向上させます。","ko":"Dify 프런트엔드 테스트 스킬은 고품질의 자동화 테스트를 생성하며 Vitest mock/timer APIs를 지원하여 코드의 신뢰성과 안정성을 향상시킵니다.","es":"El skill de pruebas frontend permite generar pruebas comprehensivas para el proyecto Dify utilizando Vitest y siguiendo convenciones establecidas","fr":"Le skill de tests frontend permet de générer des tests complets pour le projet Dify en utilisant Vitest et en suivant les conventions établies","de":"Das Frontend-Test-Skill ermöglicht die Erstellung umfassender Tests für das Dify-Projekt unter Verwendung von Vitest und etablierten Konventionen","pt":"O teste frontend é uma habilidade que gera testes abrangentes para o projeto Dify com Vitest e convenções estabelecidas","ru":"Фронтенд-тестирование - это навык, который генерирует всесторонние тесты для проекта Dify с Vitest и установленными конвенциями","ar":"اختبار الواجهة الأمامية هو مهارة تنتج اختبارات شاملة لمشروع Dify مع Vitest والاتفاقيات المعمول بها"},"seo":{"title":{"en":"Frontend-Testing: Comprehensive Test Generation for AI Ag...","zh":"前端测试设置指南 - 使用Vitest进行自动化测试","ja":"フロントエンドテストのベストプラクティス - Vitestを使用した自動テスト","ko":"프런트엔드 테스트 설정 가이드 - Vitest를 이용한 자동화 테스트","